"use client"

import React from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import type { AiBalancerKeyHealth } from "@/modules/api/graphql/queries/types/ai-balancer-health"
import { AiBalancerKeyStatus } from "@/modules/api/graphql/queries/enums/ai-balancer-key-status"
import { KeyStatusChip } from "@/components/blocks/learn/AiBalancer/KeyStatusChip"
import { formatBalancerTimestamp } from "@/modules/utils/format-balancer-timestamp"

interface KeyRowProps {
    /** Key health row from GraphQL. */
    keyHealth: AiBalancerKeyHealth
}

/**
 * Table row for one API key suffix in the admin balancer dashboard.
 *
 * List item: keeps its own `keyHealth` payload but reads locale + status labels
 * itself from the i18n hooks (no prop-drilled label resolvers).
 * @param props.keyHealth - Per-key health payload.
 */
export const KeyRow = ({
    keyHealth,
}: KeyRowProps) => {
    const locale = useLocale()
    const t = useTranslations("admin.aiBalancer")

    /** Maps a status enum value to its translated label. */
    const statusLabel = (status: string) => {
        if (status === AiBalancerKeyStatus.Active) {
            return t("status.active")
        }
        if (status === AiBalancerKeyStatus.Disabled) {
            return t("status.disabled")
        }
        if (status === AiBalancerKeyStatus.Probing) {
            return t("status.probing")
        }
        return status
    }

    return (
        <tr className="border-t border-separator text-sm text-foreground">
            <td data-principle="ps-admin-4" className="px-4 py-2 font-mono text-foreground">
                …{keyHealth.keySuffix}
            </td>
            <td data-principle="ps-admin-4" className="px-4 py-2">
                <KeyStatusChip
                    status={keyHealth.status}
                    label={statusLabel(keyHealth.status)}
                />
            </td>
            <td data-principle="ps-admin-4" className="px-4 py-2 text-center tabular-nums">
                {keyHealth.failCount}
            </td>
            <td data-principle="ps-admin-4" className="px-4 py-2 text-muted">
                {formatBalancerTimestamp(keyHealth.lastHealthCheckAt, locale)}
            </td>
            <td data-principle="ps-admin-4" className="px-4 py-2 text-muted">
                {formatBalancerTimestamp(keyHealth.lastUsedAt, locale)}
            </td>
        </tr>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    Card,
    CardContent,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    KeyRow,
} from "./KeyRow"
import type { AiBalancerProviderHealth } from "@/modules/api/graphql/queries/types/ai-balancer-health"
import { ModelProvider } from "@/modules/api/graphql/queries/query-my-ai-settings"
import { StackH, StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

interface ProviderSectionProps {
    /** Provider aggregate from GraphQL. */
    providerHealth: AiBalancerProviderHealth
}

/**
 * Card listing all keys for one AI provider in the balancer pool.
 *
 * List item: keeps its own `providerHealth` payload but reads all display
 * labels itself from the i18n hook (no prop-drilled label maps).
 * @param props.providerHealth - Provider snapshot from GraphQL.
 */
export const ProviderSection = ({
    providerHealth,
}: ProviderSectionProps) => {
    const t = useTranslations("admin.aiBalancer")

    /** Localized provider display name, falling back to the raw provider id. */
    const providerLabel = useMemo(
        (): string => {
            const labelByProvider: Record<string, string> = {
                [ModelProvider.Gemini]: t("providers.gemini"),
                [ModelProvider.OpenAI]: t("providers.openai"),
            }
            return labelByProvider[providerHealth.provider] ?? providerHealth.provider
        },
        [
            t,
            providerHealth.provider,
        ],
    )

    /** Column header labels for the keys table. */
    const columnLabels = useMemo(
        () => ({
            suffix: t("columns.suffix"),
            status: t("columns.status"),
            failCount: t("columns.failCount"),
            lastPing: t("columns.lastPing"),
            lastUsed: t("columns.lastUsed"),
        }),
        [
            t,
        ],
    )

    /** Summary pill labels (active / disabled / total). */
    const summaryLabels = useMemo(
        () => ({
            active: t("summary.active"),
            disabled: t("summary.disabled"),
            total: t("summary.total"),
        }),
        [
            t,
        ],
    )

    const sortedKeys = useMemo(
        () => [
            ...providerHealth.keys,
        ].sort((left, right) => left.keySuffix.localeCompare(right.keySuffix)),
        [
            providerHealth.keys,
        ],
    )

    return (
        <Card className="border border-white/10 bg-white/5 backdrop-blur-xl">
            {/* ps-admin-1: p-5 has no house token (dropped from padding scale) — teacher-hold */}
            <CardContent data-principle="ps-admin-1" className="p-5">
                <StackV principle="card-caption"
                    explain="Holds caption text under card media so the caption stays attached to the image above it."
                    items={[
                        () => (
                            <StackH principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    () => (
                                        <div>
                                            <h2 className="text-lg font-semibold text-white">
                                                {providerLabel}
                                            </h2>
                                            <p className="mt-1 font-mono text-xs text-slate-500">
                                                {providerHealth.keysFilePath}
                                            </p>
                                        </div>
                                    ),
                                    () => (
                                        <Box principle="chip-row" className="flex flex-wrap gap-2 text-xs"
                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column.">
                                            {/* ps-admin-3: span px-3 py-1 — py-1 not control-pad (needs py-2) — teacher-hold */}
                                            <span data-principle="ps-admin-3" className="rounded-full bg-emerald-500/10 px-3 py-1 text-emerald-300">
                                                {summaryLabels.active}: {providerHealth.activeKeys}
                                            </span>
                                            <span data-principle="ps-admin-3" className="rounded-full bg-rose-500/10 px-3 py-1 text-rose-300">
                                                {summaryLabels.disabled}: {providerHealth.disabledKeys}
                                            </span>
                                            <span data-principle="ps-admin-3" className="rounded-full bg-slate-500/10 px-3 py-1 text-slate-300">
                                                {summaryLabels.total}: {providerHealth.totalKeys}
                                            </span>
                                        </Box>
                                    ),
                                ]} />
                        ),
                        () => (
                            <div className="overflow-x-auto rounded-lg border border-white/5">
                                <table className="min-w-full text-left">
                                    <thead className="bg-white/5 text-xs uppercase tracking-wide text-slate-400">
                                        <tr>
                                            {/* ps-admin-4: th px-4 py-2 — HTML table cell, genuine foreign mount — teacher-hold */}
                                            <th data-principle="ps-admin-4" className="px-4 py-2 font-medium">
                                                {columnLabels.suffix}
                                            </th>
                                            <th data-principle="ps-admin-4" className="px-4 py-2 font-medium">
                                                {columnLabels.status}
                                            </th>
                                            <th data-principle="ps-admin-4" className="px-4 py-2 font-medium text-center">
                                                {columnLabels.failCount}
                                            </th>
                                            <th data-principle="ps-admin-4" className="px-4 py-2 font-medium">
                                                {columnLabels.lastPing}
                                            </th>
                                            <th data-principle="ps-admin-4" className="px-4 py-2 font-medium">
                                                {columnLabels.lastUsed}
                                            </th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {sortedKeys.map((keyHealth) => (
                                            <KeyRow
                                                key={`${providerHealth.provider}-${keyHealth.keySuffix}`}
                                                keyHealth={keyHealth}
                                            />
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        ),
                    ]} />
            </CardContent>
        </Card>
    )
}

"use client"

import { ArrowLeftIcon, FilmStripIcon } from "@phosphor-icons/react"
import React, {
    useCallback,
} from "react"
import {
    Button,
} from "@heroui/react"
import { StackH } from "@/components/frames/Stack"

import {
    useRouter,
} from "next/navigation"
import {

    useTranslations,
} from "next-intl"

/**
 * Admin tool navigation for the AI balancer health page.
 */
export const TopBar = () => {
    const router = useRouter()
    const t = useTranslations("admin.aiBalancer")

    const onBack = useCallback(
        () => {
            router.push("../../admin")
        },
        [
            router,
        ],
    )

    const onOpenUploadVideo = useCallback(
        () => {
            router.push("../upload-video")
        },
        [
            router,
        ],
    )

    return (
        <div className="pt-4">
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center" items={[
                    () => (
                        <Button
                            variant="ghost"
                            size="sm"
                            className="text-slate-400 hover:text-white"
                            onPress={onBack}
                        >
                            <ArrowLeftIcon className="h-5 w-5" />
                            {t("backToAdmin")}
                        </Button>
                    ),
                    () => (
                        <Button
                            variant="ghost"
                            size="sm"
                            className="text-slate-400 hover:text-white"
                            onPress={onOpenUploadVideo}
                        >
                            <FilmStripIcon className="h-5 w-5" />
                            {t("uploadVideoTool")}
                        </Button>
                    ),
                ]} />
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
} from "react"
import {
    Button,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    TopBar,
} from "./TopBar"
import {
    ProviderSection,
} from "./ProviderSection"
import {
    AdminAiBalancerSkeleton,
} from "./AdminAiBalancerSkeleton"
import { useQueryAiBalancerHealthSwr } from "@/hooks/swr/api/graphql/queries/useQueryAiBalancerHealthSwr"
import { useAppSelector } from "@/redux/hooks"
import { Box } from "@/components/frames/Box"

/**
 * Admin dashboard for live AI balancer API key health (Redis ping cache + pool).
 *
 * Requires admin API key in Redux (same gate as other admin tools) and an
 * authenticated session for the GraphQL query. Polls every 10s.
 */
export const AdminAiBalancerPage = () => {
    const apiKey = useAppSelector((state) => state.admin.apiKey)
    const router = useRouter()
    const t = useTranslations("admin.aiBalancer")
    const {
        data,
        error,
        isLoading,
        isValidating,
        mutate,
    } = useQueryAiBalancerHealthSwr()

    useEffect(() => {
        if (!apiKey) {
            router.replace("../../admin")
        }
    }, [
        apiKey,
        router,
    ])

    const sortedProviders = useMemo(
        () => [
            ...(data?.providers ?? []),
        ].sort((left, right) => left.provider.localeCompare(right.provider)),
        [
            data?.providers,
        ],
    )

    const onRefresh = useCallback(
        () => {
            void mutate()
        },
        [
            mutate,
        ],
    )

    const ready = !isLoading && !!data && !error

    return (
        <Box identity={{ tier: "page", component: "AdminAiBalancerPage" }} principle="card-padding" className="min-h-screen bg-gradient-to-br from-slate-950 via-indigo-950 to-slate-900 p-4 pb-12"
            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
            <Box principle="center-measure" className="mx-auto max-w-5xl"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                <Box principle="block-boundary" className="flex flex-col gap-6"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups.">
                    <TopBar />
                    <div className="space-y-2">
                        <h1 className="text-2xl font-bold text-white">
                            {t("title")}
                        </h1>
                        <p className="text-sm text-slate-400">
                            {t("subtitle")}
                        </p>
                        {isValidating ? (
                            <p className="text-xs text-indigo-300">
                                {t("refreshing")}
                            </p>
                        ) : null}
                    </div>
                    {!ready ? (
                        <AdminAiBalancerSkeleton />
                    ) : (
                        <Box principle="block-boundary" className="flex flex-col gap-6"
                            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups.">
                            {sortedProviders.map((providerHealth) => (
                                <ProviderSection
                                    key={providerHealth.provider}
                                    providerHealth={providerHealth}
                                />
                            ))}
                            {sortedProviders.length === 0 ? (
                                <p className="text-center text-sm text-slate-400">
                                    {t("empty")}
                                </p>
                            ) : null}
                        </Box>
                    )}
                    {error ? (
                        <p className="text-center text-sm text-rose-300">
                            {t("error")}
                        </p>
                    ) : null}
                    <Box principle="center-measure" className="mx-auto"
                        explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                        <Button
                            variant="ghost"
                            size="sm"
                            className="text-indigo-300"
                            onPress={onRefresh}
                        >
                            {t("refreshNow")}
                        </Button>
                    </Box>
                </Box>
            </Box>
        </Box>
    )
}

"use client"

import React from "react"
import { cn } from "@heroui/react"
import { useCallback } from "react"
import type { RendererTypeOption } from "@/modules/types/admin-mpeg-dash-test"
import type { VideoRendererType } from "@/modules/types/enums/video-renderer-type"

/** Props for {@link RendererTypeButton}. */
export interface RendererTypeButtonProps {
    /** Option metadata to render. */
    option: RendererTypeOption
    /** Whether this option is currently selected. */
    isActive: boolean
    /** Selects this option's renderer type. */
    onSelect: (type: VideoRendererType) => void
}

/**
 * Single renderer-type selector button (icon + label + description).
 * @param props.option - Option metadata to render.
 * @param props.isActive - Whether this option is the active renderer type.
 * @param props.onSelect - Called with this option's type when pressed.
 */
export const RendererTypeButton = ({
    option,
    isActive,
    onSelect}: RendererTypeButtonProps) => {
    const onPress = useCallback(
        () => onSelect(option.type),
        [onSelect, option.type],
    )

    return (
        <button
            onClick={onPress}
            className={cn(
                "flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-medium transition-all",
                isActive
                    ? `bg-gradient-to-r ${option.color} text-white shadow-lg`
                    : "bg-slate-700/50 text-slate-300 hover:bg-slate-700",
            )}
        >
            {option.icon}
            <div className="text-left">
                <div>{option.label}</div>
                <div className="text-[10px] opacity-70">
                    {option.description}
                </div>
            </div>
        </button>
    )
}

"use client"

import React from "react"
import { Card, CardContent, Input } from "@heroui/react"
import { RENDERER_TYPE_OPTIONS } from "@/modules/utils/admin-mpeg-dash-map"
import { RendererTypeButton } from "./RendererTypeButton"
import type { VideoRendererType } from "@/modules/types/enums/video-renderer-type"
import { Box } from "@/components/frames/Box"

/** Props for {@link ConfigCard}. */
export interface ConfigCardProps {
    /** Current URL value. */
    url: string
    /** Currently selected renderer type. */
    activeType: VideoRendererType
    /** Updates the URL value. */
    onChangeUrl: (value: string) => void
    /** Selects a renderer type. */
    onSelectType: (type: VideoRendererType) => void
}

/**
 * Configuration card: URL input + renderer-type selector buttons.
 * @param props.url - Current URL value.
 * @param props.activeType - Currently selected renderer type.
 * @param props.onChangeUrl - Updates the URL value.
 * @param props.onSelectType - Selects a renderer type.
 */
export const ConfigCard = ({
    url,
    activeType,
    onChangeUrl,
    onSelectType}: ConfigCardProps) => (
    <Card className={"border-slate-700/50 bg-slate-800/50 backdrop-blur-xl"}>
        <CardContent>
            <Box principle="page-pad" className="space-y-3 p-6"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                <h2 className="text-lg font-semibold text-white">
                    Configuration
                </h2>

                <Input
                    id="mpegdash-url-input"
                    placeholder="https://example.com/stream/manifest.mpd"
                    value={url}
                    onChange={(e) => onChangeUrl(e.target.value)}
                    className="text-white"
                />

                <Box principle="chip-row" className="flex flex-wrap gap-2"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column.">
                    {RENDERER_TYPE_OPTIONS.map((option) => (
                        <RendererTypeButton
                            key={option.type}
                            option={option}
                            isActive={activeType === option.type}
                            onSelect={onSelectType}
                        />
                    ))}
                </Box>
            </Box>
        </CardContent>
    </Card>
)

"use client"

import React from "react"
import { Card, CardContent } from "@heroui/react"
import { useMemo } from "react"
import { RENDERER_TYPE_OPTION_MAP } from "@/modules/utils/admin-mpeg-dash-map"
import { VideoRenderer } from "@/components/blocks/media/VideoRenderer"
import type { VideoRendererType } from "@/modules/types/enums/video-renderer-type"
import { Box } from "@/components/frames/Box"

/** Props for {@link PreviewCard}. */
export interface PreviewCardProps {
    /** URL to preview. */
    url: string
    /** Renderer type used to preview the URL. */
    activeType: VideoRendererType
}

/**
 * Preview card: renders the {@link VideoRenderer} for the entered URL,
 * or a placeholder when no URL is provided.
 * @param props.url - URL to preview.
 * @param props.activeType - Renderer type used to preview the URL.
 */
export const PreviewCard = ({ url, activeType}: PreviewCardProps) => {
    const activeLabel = useMemo(
        () => RENDERER_TYPE_OPTION_MAP[activeType]?.label,
        [activeType],
    )
    const hasUrl = url.trim().length > 0

    return (
        <Card className={"border-separator bg-surface backdrop-blur-xl"}>
            <CardContent>
                <Box principle="cell-pad" className="space-y-3 p-3"
                    explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                    {/* ps-admin-6: h2 gap-2 — block element inside heading invalid; foreign mount — teacher-hold */}
                    <h2 data-principle="ps-admin-6" className="text-lg font-semibold text-foreground flex items-center gap-2">
                    Preview
                        <span className="text-xs font-normal text-muted">
                        ({activeLabel})
                        </span>
                    </h2>

                    {hasUrl ? (
                        <VideoRenderer
                            url={url}
                            rendererType={activeType}
                            title="Test video"
                        />
                    ) : (
                        <div className="flex aspect-video items-center justify-center rounded-large border border-dashed border-separator text-sm text-muted">
                        Enter a URL above to preview
                        </div>
                    )}
                </Box>
            </CardContent>
        </Card>
    )
}

"use client"

import React, { useCallback } from "react"
import type { QuickTestUrl } from "@/modules/types/admin-mpeg-dash-test"

/** Props for {@link QuickTestUrlButton}. */
export interface QuickTestUrlButtonProps {
    /** Preset to render. */
    item: QuickTestUrl
    /** Loads the preset's URL + renderer type into the tool. */
    onSelect: (item: QuickTestUrl) => void
}

/**
 * Single quick-test preset row; loads its URL + type when pressed.
 * @param props.item - Preset to render.
 * @param props.onSelect - Called with the preset when pressed.
 */
export const QuickTestUrlButton = ({ item, onSelect}: QuickTestUrlButtonProps) => {
    const onPress = useCallback(
        () => onSelect(item),
        [onSelect, item],
    )

    return (
        <button
            onClick={onPress}
            className={"w-full rounded-lg bg-slate-700/30 px-3 py-2 text-left text-xs text-slate-300 transition-colors hover:bg-slate-700/60"}
        >
            <span className="font-medium text-white">
                {item.label}
            </span>
            <br />
            <span className="text-slate-500 break-all">
                {item.url}
            </span>
        </button>
    )
}

"use client"

import React from "react"
import { Card, CardContent } from "@heroui/react"
import { QUICK_TEST_URLS } from "@/modules/utils/admin-mpeg-dash-quick-urls"
import { QuickTestUrlButton } from "./QuickTestUrlButton"
import type { QuickTestUrl } from "@/modules/types/admin-mpeg-dash-test"
import { Box } from "@/components/frames/Box"

/** Props for {@link QuickTestUrls}. */
export interface QuickTestUrlsProps {
    /** Loads a preset's URL + renderer type into the tool. */
    onSelect: (item: QuickTestUrl) => void
}

/**
 * Quick test URLs card: preset buttons that load a URL + renderer type.
 * @param props.onSelect - Called with the chosen preset.
 */
export const QuickTestUrls = ({ onSelect}: QuickTestUrlsProps) => (
    <Card className={"border-slate-700/50 bg-slate-800/50 backdrop-blur-xl"}>
        <CardContent>
            <Box principle="page-pad" className="space-y-3 p-6"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                <h2 className="text-sm font-medium text-slate-400">
                    Quick Test URLs
                </h2>
                <div className="space-y-2">
                    {QUICK_TEST_URLS.map((item) => (
                        <QuickTestUrlButton
                            key={item.url}
                            item={item}
                            onSelect={onSelect}
                        />
                    ))}
                </div>
            </Box>
        </CardContent>
    </Card>
)

"use client"

import React, { useCallback, useState } from "react"
import { AdminMpegDashTestHeader } from "./Header"
import { ConfigCard } from "./ConfigCard"
import { PreviewCard } from "./PreviewCard"
import { QuickTestUrls } from "./QuickTestUrls"
import type { QuickTestUrl } from "@/modules/types/admin-mpeg-dash-test"
import { VideoRendererType } from "@/modules/types/enums/video-renderer-type"
import { Box } from "@/components/frames/Box"

/**
 * Admin tool page for testing the VideoRenderer with all 3 renderer types.
 * Owns the URL + active-type state and action handlers; renders presentational cards.
 * Enter a URL and pick Standard / MpegDash / Youtube to preview.
 */
export const AdminMpegDashTestPage = () => {
    const [url, setUrl] = useState("")
    const [activeType, setActiveType] = useState<VideoRendererType>(
        VideoRendererType.MpegDash,
    )

    const onChangeUrl = useCallback(
        (value: string) => setUrl(value),
        [],
    )

    const onSelectType = useCallback(
        (type: VideoRendererType) => setActiveType(type),
        [],
    )

    /** Load a preset: set both its URL and renderer type. */
    const onSelectQuickTestUrl = useCallback(
        (item: QuickTestUrl) => {
            setUrl(item.url)
            setActiveType(item.type)
        },
        [],
    )

    return (
        <div className={"min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 p-4 @app-md:p-8"}>
            <Box principle="center-measure" className="mx-auto max-w-4xl space-y-6"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                <AdminMpegDashTestHeader />

                <ConfigCard
                    url={url}
                    activeType={activeType}
                    onChangeUrl={onChangeUrl}
                    onSelectType={onSelectType}
                />

                <PreviewCard
                    url={url}
                    activeType={activeType}
                />

                <QuickTestUrls onSelect={onSelectQuickTestUrl} />
            </Box>
        </div>
    )
}

"use client"

import { UploadSimpleIcon as UploadIcon, VideoCameraIcon as VideoIcon } from "@phosphor-icons/react"
import React from "react"
import {
    Chip,
} from "@heroui/react"
import { formatSize } from "@/modules/utils/format-size"
import { StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/** Props for {@link DropZone}. */
export interface DropZoneProps {
    /** Currently selected file, or null when none is chosen. */
    file: File | null
    /** Ref to the hidden file input, used to open the native picker. */
    fileInputRef: React.RefObject<HTMLInputElement | null>
    /** Fired when the drop zone is clicked (opens the native file picker). */
