"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    useRef,
    useState,
} from "react"
import { toast } from "@/modules/toast/toast"
import {
    useRouter,
} from "next/navigation"
import {
    UploadStatus,
} from "@/modules/types/enums/upload-status"
import type {
    ProcessResult,
    ProviderUploadStatus,
} from "@/modules/types/admin-upload-video"
import {
    LoadingScreen,
} from "./LoadingScreen"
import {
    TopBar,
} from "./TopBar"
import {
    AdminUploadVideoHeader,
} from "./Header"
import {
    FileSelectionCard,
} from "./FileSelectionCard"
import {
    UploadProgressCard,
} from "./UploadProgressCard"
import { usePostAdminPresignedUrlSwr } from "@/hooks/swr/api/rest/mutations/usePostAdminPresignedUrlSwr"
import { usePostAdminProcessVideoSwr } from "@/hooks/swr/api/rest/mutations/usePostAdminProcessVideoSwr"
import { useRestWithToast } from "@/modules/toast/hooks"
import { useAppSelector } from "@/redux/hooks"
import type { AdminPresignedUrlItem } from "@/modules/api/rest/admin-presigned-url/types"
import { Box } from "@/components/frames/Box"

/** Props for {@link AdminUploadVideoPage}. */
export type AdminUploadVideoPageProps = Record<string, never>
/**
 * Admin video upload tool container.
 *
 * Owns the API key gate, file/upload/process state, the presigned-URL +
 * process-video SWR triggers, and the upload orchestration; renders the
 * presentational cards. "use client" because it relies on browser APIs
 * (XMLHttpRequest, clipboard, drag/drop) and local state.
 * @param props - optional className forwarded to the wrapper div
 */
export const AdminUploadVideoPage = () => {
    const apiKey = useAppSelector((state) => state.admin.apiKey)
    const router = useRouter()

    /** Redirect to admin page if no API key is set */
    useEffect(() => {
        if (!apiKey) {
            router.replace("../../admin")
        }
    }, [apiKey, router])

    /** Selected file to upload */
    const [file, setFile] = useState<File | null>(null)
    /** Custom S3 key (path) */
    const [objectKey, setObjectKey] = useState("")
    /** Per-provider upload status */
    const [uploads, setUploads] = useState<Array<ProviderUploadStatus>>([])
    /** Is the presigned URL request in flight */
    const [isRequesting, setIsRequesting] = useState(false)
    /** Track whether upload has been performed */
    const [uploadDone, setUploadDone] = useState(false)
    /** Track whether process-video is in flight */
    const [isProcessing, setIsProcessing] = useState(false)
    /** The uploaded video URL (first provider) to pass to process-video */
    const [uploadedVideoUrl, setUploadedVideoUrl] = useState<string | null>(null)
    /** Result from the process-video API */
    const [processResult, setProcessResult] = useState<ProcessResult | null>(null)

    const fileInputRef = useRef<HTMLInputElement>(null)
    const { trigger: triggerPresignedUrl } = usePostAdminPresignedUrlSwr()
    const { trigger: triggerProcessVideo } = usePostAdminProcessVideoSwr()
    const runRest = useRestWithToast()

    /** Handle file selection */
    const onFileChange = useCallback(
        (e: React.ChangeEvent<HTMLInputElement>) => {
            const selected = e.target.files?.[0]
            if (!selected) return
            setFile(selected)
            setUploads([])
            setUploadDone(false)
            if (!objectKey) {
                const ts = Date.now()
                const safeName = selected.name.replace(/\s+/g, "-")
                setObjectKey(`videos/${ts}-${safeName}`)
            }
        },
        [objectKey],
    )

    /** Handle file drop */
    const onDrop = useCallback(
        (e: React.DragEvent) => {
            e.preventDefault()
            e.stopPropagation()
            const dropped = e.dataTransfer.files?.[0]
            if (dropped) {
                setFile(dropped)
                setUploads([])
                setUploadDone(false)
                if (!objectKey) {
                    const ts = Date.now()
                    const safeName = dropped.name.replace(/\s+/g, "-")
                    setObjectKey(`videos/${ts}-${safeName}`)
                }
            }
        },
        [objectKey],
    )

    /** Allow dropping by preventing the browser's default dragover behavior. */
    const onDragOver = useCallback(
        (e: React.DragEvent) => {
            e.preventDefault()
            e.stopPropagation()
        },
        [],
    )

    /** Open the native file picker when the drop zone is clicked. */
    const onClickZone = useCallback(
        () => {
            fileInputRef.current?.click()
        },
        [],
    )

    /** Update the S3 object key from the input. */
    const onChangeObjectKey = useCallback(
        (value: string) => setObjectKey(value),
        [],
    )

    /** Upload file to a single presigned URL */
    const uploadToProvider = useCallback(
        async (
            presigned: AdminPresignedUrlItem,
            fileToUpload: File,
            idx: number,
        ) => {
            return new Promise<void>((resolve) => {
                const xhr = new XMLHttpRequest()

                xhr.upload.addEventListener("progress", (e) => {
                    if (e.lengthComputable) {
                        const pct = Math.round((e.loaded / e.total) * 100)
                        setUploads((prev) =>
                            prev.map((u, i) =>
                                i === idx ? { ...u, progress: pct } : u,
                            ),
                        )
                    }
                })

                xhr.addEventListener("load", () => {
                    if (xhr.status >= 200 && xhr.status < 300) {
                        setUploads((prev) =>
                            prev.map((u, i) =>
                                i === idx
                                    ? { ...u, status: UploadStatus.Success, progress: 100 }
                                    : u,
                            ),
                        )
                    } else {
                        setUploads((prev) =>
                            prev.map((u, i) =>
                                i === idx
                                    ? {
                                        ...u,
                                        status: UploadStatus.Error,
                                        error: `HTTP ${xhr.status}`,
                                    }
                                    : u,
                            ),
                        )
                    }
                    resolve()
                })

                xhr.addEventListener("error", () => {
                    setUploads((prev) =>
                        prev.map((u, i) =>
                            i === idx
                                ? {
                                    ...u,
                                    status: UploadStatus.Error,
                                    error: "Network error",
                                }
                                : u,
                        ),
                    )
                    resolve()
                })

                xhr.open("PUT", presigned.url)
                xhr.setRequestHeader(
                    "Content-Type",
                    fileToUpload.type || "application/octet-stream",
                )
                setUploads((prev) =>
                    prev.map((u, i) =>
                        i === idx ? { ...u, status: UploadStatus.Uploading } : u,
                    ),
                )
                xhr.send(fileToUpload)
            })
        },
        [],
    )

    /** Full upload flow: get presigned URLs → upload to each provider */
    const onUpload = useCallback(async () => {
        if (!file || !objectKey) {
            toast.warning("Missing fields", {
                description: "Please select a file and set an object key.",
            })
            return
        }

        setIsRequesting(true)
        setUploadDone(false)

        // Request the presigned URLs (REST write). `runRest` toasts on failure.
        const presignedResult = await runRest(
            () =>
                triggerPresignedUrl({
                    request: {
                        key: objectKey,
                        contentType: file.type || "video/mp4",
                    },
                    apiKey,
                }),
            { showSuccessToast: false },
        )
        if (!presignedResult) {
            setIsRequesting(false)
            return
        }

        const items: Array<AdminPresignedUrlItem> = presignedResult.data ?? []
        if (items.length === 0) {
            toast.danger("No presigned URLs", {
                description: "The server returned an empty list.",
            })
            setIsRequesting(false)
            return
        }

        // Initialize per-provider statuses
        const initial: Array<ProviderUploadStatus> = items.map((item) => ({
            provider: item.provider,
            url: item.url,
            status: UploadStatus.Idle,
            progress: 0,
        }))
        setUploads(initial)
        setIsRequesting(false)

        // Upload to all providers concurrently (REST writes via XHR PUT).
        await runRest(
            () =>
                Promise.all(
                    items.map((item, idx) => uploadToProvider(item, file, idx)),
                ),
            { successMessage: "Video has been uploaded to all providers." },
        )

        setUploadDone(true)
        // Save first provider URL for process-video
        setUploadedVideoUrl(items[0].url.split("?")[0])
    }, [file, objectKey, apiKey, triggerPresignedUrl, uploadToProvider, runRest])

    /** Trigger video processing (FFmpeg encode + MPEG-DASH) on the backend */
    const onProcess = useCallback(async () => {
        if (!uploadedVideoUrl) {
            toast.warning("No video URL", {
                description: "Please upload a video first.",
            })
            return
        }
        setIsProcessing(true)
        setProcessResult(null)
        // Trigger backend video processing (REST write). `runRest` toasts the result.
        const result = await runRest(
            () =>
                triggerProcessVideo({
                    request: { url: uploadedVideoUrl },
                    apiKey,
                }),
            { showSuccessToast: false },
        )
        if (result) {
            setProcessResult({ jobId: result.jobId, message: result.message })
            toast.success("Processing started", {
                description: `Job ${result.jobId} enqueued.`,
            })
        }
        setIsProcessing(false)
    }, [uploadedVideoUrl, apiKey, triggerProcessVideo, runRest])

    /** Copy URL to clipboard */
    const onCopyUrl = useCallback((url: string) => {
        navigator.clipboard.writeText(url)
        toast.success("Copied!", {
            description: "Presigned URL copied to clipboard.",
        })
    }, [])

    /** Whether any provider upload is currently in progress. */
    const isUploading = useMemo(
        () => uploads.some((u) => u.status === UploadStatus.Uploading),
        [uploads],
    )

    if (!apiKey) {
        return <LoadingScreen />
    }

    return (
        <div className={"min-h-screen bg-gradient-to-br from-slate-950 via-indigo-950 to-slate-900 p-4 @app-md:p-8"}>
            <Box principle="center-measure" className="mx-auto max-w-3xl space-y-6"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                <TopBar />

                <AdminUploadVideoHeader />

                <FileSelectionCard
                    file={file}
                    fileInputRef={fileInputRef}
                    objectKey={objectKey}
                    isRequesting={isRequesting}
                    isUploading={isUploading}
                    uploadDone={uploadDone}
                    isProcessing={isProcessing}
                    processResult={processResult}
                    onClickZone={onClickZone}
                    onDragOver={onDragOver}
                    onDrop={onDrop}
                    onFileChange={onFileChange}
                    onChangeObjectKey={onChangeObjectKey}
                    onUpload={onUpload}
                    onProcess={onProcess}
                />

                {uploads.length > 0 && (
                    <UploadProgressCard
                        uploads={uploads}
                        uploadDone={uploadDone}
                        onCopyUrl={onCopyUrl}
                    />
                )}
            </Box>
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Label,
    Link,
    Skeleton,
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import { SettingsBreadcrumb } from "@/components/blocks/settings/SettingsBreadcrumb"
import { pathConfig } from "@/resources/path"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Callout } from "@/components/composites/feedback/Callout"
import { useQueryMyAiQuotaSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiQuotaSwr"
import { useMutateSetAiCeilSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSetAiCeilSwr"
import { AiModelCategory } from "@/modules/api/graphql/queries/query-ai-models"
import { AiCeilSurface } from "@/modules/api/graphql/mutations/types/set-ai-ceil"
import { StackH, StackV } from "@/components/frames/Stack"

/** Category ladder cheapest → strongest (mirrors backend CATEGORY_LADDER). */
const LADDER: Array<AiModelCategory> = [
    AiModelCategory.Low,
    AiModelCategory.Medium,
    AiModelCategory.High,
]

/** Per-surface override sentinel = follow the global default. */
const INHERIT = "__inherit__"

/** Surfaces the user can override (mirrors backend AiCeilSurface). */
const SURFACES: Array<AiCeilSurface> = [
    AiCeilSurface.Chatbot,
    AiCeilSurface.Grading,
    AiCeilSurface.Interview,
]

/**
 * AI settings page — set the model CEILING (the "cap") the Auto router may climb to,
 * for cost control. BYOK was removed from the main flow; grading + the lesson
 * tutor run only on the StarCi System pool (the system auto-picks a model by
 * task difficulty + the user's plan). Here the user sets a *lower* ceiling: a
 * global default + per-surface overrides. The Auto chain climbs to the ceiling,
 * then stops (hard cap). Caps above the plan max are disabled (need an upgrade).
 */
export const AiSettingsPage = () => {
    const t = useTranslations()
    const router = useRouter()
    const locale = useLocale()

    const quota = useQueryMyAiQuotaSwr()
    const { trigger, isMutating } = useMutateSetAiCeilSwr()

    const data = quota.data

    /** Categories the plan unlocks (the ceiling); default to the free allowance. */
    const allowed = data?.allowedCategories ?? [
        AiModelCategory.Low,
        AiModelCategory.Medium,
    ]
    /** Highest category the plan allows = the cap ceiling. */
    const planMax = LADDER[
        Math.max(...allowed.map((category) => LADDER.indexOf(category)), 0)
    ]
    const planMaxIndex = LADDER.indexOf(planMax)
    /** Free (no paid tier) caps at Economy → little to cap → show the upsell. */
    const isPaid = planMaxIndex > LADDER.indexOf(AiModelCategory.Low)

    /** Human label for a category. */
    const label = useCallback(
        (category: AiModelCategory) => t(`aiSettings.categories.${category}`),
        [t],
    )

    /** Persist a ceiling then revalidate the quota snapshot. */
    const setCeil = useCallback(
        async (
            surface: AiCeilSurface | null,
            category: AiModelCategory | null,
        ) => {
            await trigger({
                surface,
                category,
            })
            await quota.mutate()
        },
        [trigger, quota],
    )

    /** Ladder buttons (above the plan max are disabled). */
    const ladderItems = useMemo(
        () => LADDER.map((category) => ({
            value: category,
            content: label(category),
            isDisabled: LADDER.indexOf(category) > planMaxIndex,
        })),
        [label, planMaxIndex],
    )

    /** Per-surface ladder = "follow default" + the ladder. */
    const surfaceItems = useMemo(
        () => [
            {
                value: INHERIT,
                content: t("aiSettings.ceil.inherit"),
            },
            ...ladderItems,
        ],
        [ladderItems, t],
    )

    const onNavigateSubscription = useCallback(
        () => router.push(`${pathConfig().locale(locale).profile().build()}/ai-subscription`),
        [router, locale],
    )

    return (
        <StackV identity={{ tier: "page", component: "AiSettingsPage" }} gap={7} principle="layout-split"
            explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
            items={[
                () => (
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("aiSettings.title")} />}
                        title={t("aiSettings.title")}
                        description={t("aiSettings.ceil.description")}
                    />
                ),

                () => (
                    <AsyncContent
                        isLoading={quota.isLoading}
                        skeleton={(
                            <StackV gap={6} principle="block-boundary"
                                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                items={[
                                    () => <Skeleton className="h-16 w-full rounded-2xl" />,
                                    () => (
                                        <StackV gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={[
                                                () => <Skeleton className="h-4 w-32 rounded-lg" />,
                                                () => <Skeleton className="h-9 w-full rounded-xl" />,
                                            ]} />
                                    ),
                                    () => (
                                        <StackV gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={[
                                                () => <Skeleton className="h-4 w-40 rounded-lg" />,
                                                ...SURFACES.map((surface) => () => (
                                                    <Skeleton
                                                        key={surface}
                                                        className="h-9 w-full rounded-xl"
                                                    />
                                                )),
                                            ]} />
                                    ),
                                ]} />
                        )}
                        error={quota.error}
                        errorContent={{
                            title: t("aiSettings.ceil.error"),
                            onRetry: () => { void quota.mutate() },
                            retryLabel: t("common.retry"),
                        }}
                    >
                        <StackV gap={6} principle="block-boundary"
                            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                            items={[
                                () => (
                                    <Callout
                                        title={data?.tier
                                            ? t("aiSettings.ceil.plan", {
                                                tier: data.tier,
                                                max: label(planMax),
                                            })
                                            : t("aiSettings.ceil.planFree", {
                                                max: label(planMax),
                                            })}
                                        description={data
                                            ? t("aiSettings.ceil.creditLine", {
                                                used5h: data.credit.used5h,
                                                limit5h: data.credit.limit5h,
                                                usedWeek: data.credit.usedWeek,
                                                limitWeek: data.credit.limitWeek,
                                            })
                                            : undefined}
                                    />
                                ),

                                () => (
                                    <StackV gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={[
                                            () => <Label>{t("aiSettings.ceil.defaultLabel")}</Label>,
                                            () => (
                                                <FlexWrapButtonRadio
                                                    ariaLabel={t("aiSettings.ceil.defaultLabel")}
                                                    items={ladderItems}
                                                    value={data?.ceil.default ?? planMax}
                                                    onChange={(category) =>
                                                        setCeil(
                                                            null,
                                                            category === planMax
                                                                ? null
                                                                : (category as AiModelCategory),
                                                        )}
                                                />
                                            ),
                                            () => (
                                                <Typography type="body-xs" color="muted">
                                                    {t("aiSettings.ceil.creditCaption")}
                                                    {" · "}
                                                    {t("aiSettings.ceil.hardStop")}
                                                </Typography>
                                            ),
                                        ]} />
                                ),

                                () => (
                                    <StackV gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={[
                                            () => <Label>{t("aiSettings.ceil.surfacesLabel")}</Label>,
                                            ...SURFACES.map((surface) => () => (
                                                <StackV
                                                    key={surface}
                                                    gap={3}
                                                    principle="sibling-stack"
                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                    items={[
                                                        () => (
                                                            <Typography type="body-sm">
                                                                {t(`aiSettings.ceil.surface.${surface}`)}
                                                            </Typography>
                                                        ),
                                                        () => (
                                                            <FlexWrapButtonRadio
                                                                ariaLabel={t(`aiSettings.ceil.surface.${surface}`)}
                                                                items={surfaceItems}
                                                                value={data?.ceil[surface] ?? INHERIT}
                                                                onChange={(value) =>
                                                                    setCeil(
                                                                        surface,
                                                                        value === INHERIT
                                                                            ? null
                                                                            : (value as AiModelCategory),
                                                                    )}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            )),
                                        ]} />
                                ),

                                () => (!isPaid
                                    ? (
                                        <StackH gap={3} principle="identity"
                                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                            at="sm" align="center" items={[
                                                () => (
                                                    <Typography type="body-sm" color="muted">
                                                        {t("aiSettings.upgradePrompt")}
                                                    </Typography>
                                                ),
                                                () => (
                                                    <Link onPress={onNavigateSubscription}>
                                                        {t("aiSettings.byok.upsellCta")}
                                                    </Link>
                                                ),
                                            ]} />
                                    )
                                    : null),

                                () => (isMutating
                                    ? (
                                        <Typography type="body-xs" color="muted">
                                            {t("aiSettings.ceil.saving")}
                                        </Typography>
                                    )
                                    : null),
                            ]} />
                    </AsyncContent>
                ),
            ]} />
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import { Chip, ScrollShadow } from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import dayjs from "dayjs"
import {
    BarChart,
    Bar,
    CartesianGrid,
    ResponsiveContainer,
    Tooltip,
    XAxis,
    YAxis,
} from "recharts"
import { useQueryMyCreditUsageHistoryInfiniteSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCreditUsageHistoryInfiniteSwr"
import { AiCeilSurface } from "@/modules/api/graphql/mutations/types/set-ai-ceil"
import type { QueryMyCreditUsageHistoryItem } from "@/modules/api/graphql/queries/types/my-credit-usage-history"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { InfiniteScrollSentinel } from "@/components/blocks/async/InfiniteScrollSentinel"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackV } from "@/components/frames/Stack"

/** Days shown in the per-day spend chart (matches the chart title copy). */
const CHART_DAYS = 14

/** Display label per provider key; null = the free Auto lane. */
const PROVIDER_LABELS: Record<string, string> = {
    openai: "OpenAI",
    gemini: "Gemini",
}

/**
 * Human label for what a charge row was for. `surface` distinguishes an
 * interview-grading / chatbot charge from a challenge-grading one — rows
 * predating the `surface` column (or from a surface not yet passing it
 * through) fall back to the "Grade challenge" label.
 */
const purposeLabel = (
    item: QueryMyCreditUsageHistoryItem,
    t: ReturnType<typeof useTranslations>,
): string => {
    switch (item.surface) {
    case AiCeilSurface.Interview:
        return t("aiQuota.history.purposeInterview")
    case AiCeilSurface.Chatbot:
        return t("aiQuota.history.purposeChatbot")
    default:
        return t("aiQuota.history.purposeGrade")
    }
}

/** Props for {@link AiUsageHistory}. */
export type AiUsageHistoryProps = Record<string, never>
/**
 * AI usage insight for the `/profile/ai-usage` page: a per-day spend chart, a
 * "by provider" {@link SegmentBar} breakdown, and the charge history as an
 * infinite-scroll list. Self-contained: drives its own `useSWRInfinite` over
 * `myCreditUsageHistory` (offset paginated). Chart/breakdown are computed
 * client-side from the loaded rows.
 *
 * NOTE: linking a charge back to its challenge needs the backend to expose
 * `attemptId` on the history item — not surfaced yet, so rows are read-only.
 *
 * @param props - optional className (placement only).
 */
export const AiUsageHistory = () => {
    const t = useTranslations()

    const {
        data,
        isLoading,
        isValidating,
        error,
        size,
        setSize,
        mutate,
    } = useQueryMyCreditUsageHistoryInfiniteSwr()

    const pages = useMemo(() => data ?? [], [data])
    const items = useMemo(() => pages.flatMap((page) => page.items), [pages])
    const total = pages[0]?.total ?? 0
    const hasMore = items.length < total
    const isLoadingMore = isValidating && size > 0

    // per-day spend buckets (last CHART_DAYS days), from all loaded rows
    const chartData = useMemo(() => {
        const today = dayjs().startOf("day")
        const buckets = new Map<string, number>()
        for (let offset = CHART_DAYS - 1; offset >= 0; offset--) {
            buckets.set(today.subtract(offset, "day").format("DD/MM"), 0)
        }
        for (const item of items) {
            const key = dayjs(item.createdAt).startOf("day").format("DD/MM")
            if (buckets.has(key)) {
                buckets.set(key, (buckets.get(key) ?? 0) + item.credits)
            }
        }
        return [...buckets.entries()].map(([day, credits]) => ({ day, credits }))
    }, [items])

    // credits spent per provider (null provider = free Auto lane)
    const providerSegments = useMemo(() => {
        const byProvider = new Map<string, number>()
        for (const item of items) {
            const key = item.provider ?? "free"
            byProvider.set(key, (byProvider.get(key) ?? 0) + item.credits)
        }
        return [...byProvider.entries()]
            .filter(([, credits]) => credits > 0)
            .sort((a, b) => b[1] - a[1])
            .map(([key, credits]) => ({
                key,
                label: key === "free" ? t("aiQuota.freeTier") : PROVIDER_LABELS[key] ?? key,
                value: credits,
            }))
    }, [items, t])

    const historyItems: Array<SurfaceCardListItem> = items.map((item) => ({
        key: item.id,
        title: item.model ?? t("aiQuota.history.autoModel"),
        subtitle: `${purposeLabel(item, t)} · ${dayjs(item.createdAt).format("HH:mm DD/MM")}`,
        trailing: () => (
            <Chip
                size="sm"
                variant="soft"
                color={item.credits > 0 ? "warning" : "success"}
            >
                <Chip.Label>
                    {`${item.credits} ${t("aiQuota.history.creditsUnit")}`}
                </Chip.Label>
            </Chip>
        ),
    }))

    return (
        <AsyncContent
            isLoading={isLoading && items.length === 0}
            skeleton={(
                <StackV
                    gap={6}
                    items={[
                        () => (
                            <LabeledCard label={t("aiQuota.history.chartTitle")}>
                                <Skeleton className="h-44 w-full rounded-xl" />
                            </LabeledCard>
                        ),
                        () => (
                            <LabeledCard label={t("aiQuota.history.breakdownTitle")}>
                                <Skeleton.SegmentBar legendItems={3} />
                            </LabeledCard>
                        ),
                        () => (
                            <LabeledCard label={t("aiQuota.history.title")}>
                                <StackV
                                    gap={3}
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={[0, 1, 2, 3].map((row) => () => (
                                        <Skeleton key={row} className="h-12 w-full rounded-xl" />
                                    ))}
                                />
                            </LabeledCard>
                        ),
                    ]}
                />
            )}
            isEmpty={items.length === 0}
            emptyContent={{ title: t("aiQuota.history.empty") }}
            error={error}
            errorContent={{
                title: t("aiQuota.history.title"),
                onRetry: () => { void mutate() },
                retryLabel: t("dashboard.retry"),
            }}
        >
            <div className={""}>
                <StackV
                    gap={6}
                    items={[
                        () => (
                            <LabeledCard label={t("aiQuota.history.chartTitle")}>
                                <div className="h-44 w-full text-accent-soft-foreground">
                                    <ResponsiveContainer width="100%" height="100%">
                                        <BarChart data={chartData} margin={{ top: 8, right: 8, bottom: 0, left: -16 }}>
                                            <CartesianGrid
                                                strokeDasharray="3 3"
                                                stroke="currentColor"
                                                className="text-divider"
                                                vertical={false}
                                            />
                                            <XAxis dataKey="day" tick={{ fontSize: 10 }} interval={1} tickLine={false} axisLine={false} />
                                            <YAxis allowDecimals={false} tick={{ fontSize: 10 }} tickLine={false} axisLine={false} width={28} />
                                            <Tooltip
                                                cursor={{ fill: "currentColor", opacity: 0.08 }}
                                                formatter={(value) => [`${value} ${t("aiQuota.history.creditsUnit")}`, ""]}
                                            />
                                            <Bar dataKey="credits" fill="currentColor" radius={[4, 4, 0, 0]} />
                                        </BarChart>
                                    </ResponsiveContainer>
                                </div>
                            </LabeledCard>
                        ),
                        ...(providerSegments.length > 0
                            ? [() => (
                                <LabeledCard label={t("aiQuota.history.breakdownTitle")}>
                                    <SegmentBar
                                        ariaLabel={t("aiQuota.history.breakdownTitle")}
                                        segments={providerSegments}
                                    />
                                </LabeledCard>
                            )]
                            : []),
                        () => (
                            <ScrollShadow className="max-h-96">
                                <SurfaceCardList
                                    label={t("aiQuota.history.title")}
                                    items={historyItems}
                                />
                                <InfiniteScrollSentinel
                                    onReach={() => setSize((current) => current + 1)}
                                    disabled={!hasMore || isLoadingMore}
                                />
                            </ScrollShadow>
                        ),
                    ]}
                />
            </div>
        </AsyncContent>
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useRef,
    useState,
} from "react"
import {
    Button,
    ColorArea,
    ColorPicker,
    ColorSlider,
    ColorSwatch,
    ColorSwatchPicker,
    Label,
    cn,
    parseColor,
} from "@heroui/react"
import type {
    Color,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    PageHeader,
} from "@/components/blocks/layout/PageHeader"
import {
    SurfaceCard,
} from "@/components/composites/cards/SurfaceCard"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    useAppDispatch,
    useAppSelector,
} from "@/redux/hooks"
import {
    setUser,
} from "@/redux/slices/user"
import {
    useMutateUpdateProfileSwr,
} from "@/hooks/swr/api/graphql/mutations/useMutateUpdateProfileSwr"
import {
    BackgroundEffect,
} from "@/modules/types/enums/background-effect"
import {
    AmbientBackground,
} from "@/components/blocks/layout/AmbientBackground"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Fallback accent (matches the default brand `--accent` token) when the user has never set one. */
const DEFAULT_ACCENT_HEX = "#e84393"

/** 10 named preset accents (hex, curated to stay legible with the default white `--accent-foreground`). */
const ACCENT_PRESETS: ReadonlyArray<{ hex: string, labelKey: string }> = [
    { hex: "#e84393", labelKey: "pink" },
    { hex: "#7c5cfc", labelKey: "purple" },
    { hex: "#2f86eb", labelKey: "blue" },
    { hex: "#16b5c4", labelKey: "teal" },
    { hex: "#25b56a", labelKey: "emerald" },
    { hex: "#84cc16", labelKey: "lime" },
    { hex: "#f39c12", labelKey: "amber" },
    { hex: "#e74c3c", labelKey: "red" },
    { hex: "#d946ef", labelKey: "fuchsia" },
    { hex: "#64748b", labelKey: "slate" },
]

/** The 10 selectable ambient background effects (including "off"). */
const EFFECT_OPTIONS: ReadonlyArray<BackgroundEffect> = [
    BackgroundEffect.None,
    BackgroundEffect.Ember,
    BackgroundEffect.Wave,
    BackgroundEffect.Snow,
    BackgroundEffect.Rain,
    BackgroundEffect.Bubbles,
    BackgroundEffect.Fireflies,
    BackgroundEffect.Stars,
    BackgroundEffect.Aurora,
    BackgroundEffect.Circuit,
]

/** How long to wait after the last color change before persisting (avoids spamming the mutation while dragging). */
const ACCENT_PERSIST_DEBOUNCE_MS = 500

/**
 * Settings → "AppearancePage": pick an accent color (10 presets or a free-form
 * `ColorPicker`) and an ambient background effect (10 options, tinted by the
 * chosen accent) — independent of light/dark mode, which stays on the navbar
 * toggle. Both persist to `UserEntity` via `updateProfile` (server is the
 * source of truth; `useAccentOverride` / `useBackgroundEffect` mirror them
 * app-wide + into localStorage for the no-flash fast path).
 */
export const AppearancePage = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const user = useAppSelector((state) => state.user.user)
    const updateProfileSwr = useMutateUpdateProfileSwr()

    const [color, setColor] = useState<Color>(
        () => parseColor(user?.accentColor ?? DEFAULT_ACCENT_HEX),
    )
    const persistTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

    // instant preview while dragging — independent of the debounced persistence below
    useEffect(() => {
        document.documentElement.style.setProperty("--accent", color.toString("hex"))
    }, [
        color,
    ])

    const persistAccent = useCallback((hex: string | null) => {
        if (persistTimeoutRef.current) {
            clearTimeout(persistTimeoutRef.current)
        }
        persistTimeoutRef.current = setTimeout(() => {
            void updateProfileSwr.trigger({ accentColor: hex }).then((result) => {
                const updated = result?.data?.updateProfile?.data
                if (updated) {
                    dispatch(setUser(updated))
                }
            })
        }, ACCENT_PERSIST_DEBOUNCE_MS)
    }, [
        updateProfileSwr,
        dispatch,
    ])

    const onColorChange = useCallback((next: Color) => {
        setColor(next)
        persistAccent(next.toString("hex"))
    }, [
        persistAccent,
    ])

    const onResetAccent = useCallback(() => {
        setColor(parseColor(DEFAULT_ACCENT_HEX))
        document.documentElement.style.removeProperty("--accent")
        document.documentElement.style.removeProperty("--accent-foreground")
        persistAccent(null)
    }, [
        persistAccent,
    ])

    const effect = user?.backgroundEffect ?? BackgroundEffect.None

    const onSelectEffect = useCallback((next: BackgroundEffect) => {
        if (!user || next === effect) {
            return
        }
        // optimistic — the real confirmation comes back from the mutation below
        dispatch(setUser({ ...user, backgroundEffect: next }))
        void updateProfileSwr.trigger({ backgroundEffect: next }).then((result) => {
            const updated = result?.data?.updateProfile?.data
            if (updated) {
                dispatch(setUser(updated))
            }
        })
    }, [
        user,
        effect,
        dispatch,
        updateProfileSwr,
    ])

    return (
        <StackV
            identity={{ tier: "page", component: "AppearancePage" }}
            gap={7}
            principle="layout-split"
            explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
            items={[
                () => (
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("appearance.title")} />}
                        title={t("appearance.title")}
                        description={t("appearance.description")}
                    />
                ),
                () => (
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => (
                                <SurfaceCard
                                    label={t("appearance.accentLabel")}
                                    body={() => (
                                        <StackV gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={[
                                                () => (
                                                    <ColorSwatchPicker value={color} onChange={onColorChange} size="lg">
                                                        {ACCENT_PRESETS.map((preset) => (
                                                            <ColorSwatchPicker.Item key={preset.hex} color={preset.hex}>
                                                                <ColorSwatchPicker.Swatch />
                                                                <ColorSwatchPicker.Indicator />
                                                            </ColorSwatchPicker.Item>
                                                        ))}
                                                    </ColorSwatchPicker>
                                                ),
                                                () => (
                                                    <StackH gap={4} principle="content-row" at="sm" align="center"
                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                        items={[
                                                            () => (
                                                                <ColorPicker value={color} onChange={onColorChange}>
                                                                    <ColorPicker.Trigger>
                                                                        <ColorSwatch size="lg" />
                                                                        <Label>{t("appearance.customColor")}</Label>
                                                                    </ColorPicker.Trigger>
                                                                    <ColorPicker.Popover>
                                                                        <ColorArea
                                                                            aria-label={t("appearance.customColor")}
                                                                            className="max-w-full"
                                                                            colorSpace="hsb"
                                                                            xChannel="saturation"
                                                                            yChannel="brightness"
                                                                        >
                                                                            <ColorArea.Thumb />
                                                                        </ColorArea>
                                                                        <ColorSlider channel="hue" colorSpace="hsb">
                                                                            <ColorSlider.Track>
                                                                                <ColorSlider.Thumb />
                                                                            </ColorSlider.Track>
                                                                        </ColorSlider>
                                                                    </ColorPicker.Popover>
                                                                </ColorPicker>
                                                            ),
                                                            () => (
                                                                <Button variant="tertiary" size="sm" onPress={onResetAccent}>
                                                                    {t("appearance.resetAccent")}
                                                                </Button>
                                                            ),
                                                        ]} />
                                                ),
                                            ]} />
                                    )}
                                />
                            ),

                            () => (
                                <SurfaceCard
                                    label={t("appearance.effectLabel")}
                                    body={() => (
                                        <Box principle="content-row" className="grid grid-cols-2 gap-3 @app-sm:grid-cols-3 @app-md:grid-cols-5"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title.">
                                            {EFFECT_OPTIONS.map((option) => (
                                                <button
                                                    key={option}
                                                    type="button"
                                                    onClick={() => onSelectEffect(option)}
                                                    className={cn(
                                                        "relative flex h-24 flex-col justify-end overflow-hidden rounded-2xl border p-2 text-left transition-colors",
                                                        effect === option
                                                            ? "border-accent ring-2 ring-accent"
                                                            : "border-default hover:bg-default",
                                                    )}
                                                >
                                                    <AmbientBackground effect={option} className="absolute inset-0 -z-0" />
                                                    <span className="relative z-10 text-xs font-medium text-foreground">
                                                        {t(`appearance.effects.${option}`)}
                                                    </span>
                                                </button>
                                            ))}
                                        </Box>
                                    )}
                                />
                            ),
                        ]} />
                ),
            ]} />
    )
}

"use client"

import React, { useMemo } from "react"
import dynamic from "next/dynamic"
import { Chip, Skeleton } from "@heroui/react"
import { useTranslations } from "next-intl"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import type { HealthByName } from "@/hooks/useSystemHealthPoll"
import { ARCHITECTURE_MODULE_MAP } from "@/modules/utils/architecture-modules"
import { buildLiveScene } from "@/modules/utils/architecture-live-scene"
import { buildFutureScene } from "@/modules/utils/architecture-future-scene"

/** The R3F canvas is heavy + client-only — lazy so it never ships in the RSC
 *  bundle and never mounts during SSR. */
const ArchitectureScene = dynamic(
    () => import("@/components/blocks/marketing/ArchitectureScene").then((mod) => mod.ArchitectureScene),
    {
        ssr: false,
        loading: () => <Skeleton className="h-[440px] w-full rounded-3xl @app-sm:h-[560px]" />,
    },
)

/** Which era the map shows: today's live system, or the future roadmap. */
export type ArchitectureEra = "present" | "future"

/** Props for {@link ArchitectureMap}. */
export interface ArchitectureMapProps {
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
    /** Currently selected node id — highlighted with a ring on the map. */
    selectedId: string
    /** Click-to-select a node — kept in sync with the rail via `?node=`. */
    onSelectNode: (id: string) => void
}

/**
 * The live 3D architecture ATLAS — one flat isometric board, no pods, no drill.
 * Two eras via a single toggle:
 *
 *  - **Present** (default): the live atlas — all 17 infra/external components
 *    (live status dot) PLUS the 10 feature modules the Core API splits into
 *    (neutral, no dot — no health probe exists for them). Selecting a module
 *    brightens the infra it runs on ({@link buildLiveScene}); selecting infra
 *    highlights it. Everything on one grid, one tile per node.
 *  - **Future**: the microservices roadmap (Coming soon — no live status).
 *
 * The `?node=` selection is shared with the rail + dissection panel. Every scene
 * builder is a pure data function fed i18n'd labels here.
 *
 * @param props - {@link ArchitectureMapProps}
 */
export const ArchitectureMap = ({ healthByName, selectedId, onSelectNode}: ArchitectureMapProps) => {
    const t = useTranslations("architecture")

    const [era, setEra] = React.useState<ArchitectureEra>("present")

    // stable per-scene i18n label bags (memoised on t so scene builders stay pure)
    const flatLabels = useMemo(
        () => ({
            checking: t("status.checking"),
            unknown: t("status.unknown"),
            degraded: t("status.degraded"),
            down: t("status.down"),
            client: t("map.client"),
            clientSub: t("map.clientSub"),
            gateway: t("map.gateway"),
            gatewaySub: t("map.gatewaySub"),
            moduleName: (id: string) => t(`module.${id}.name`),
            moduleSub: (id: string) => {
                const value = t(`module.${id}.sub`)
                return value || undefined
            },
        }),
        [t],
    )
    const futureLabels = useMemo(
        () => ({
            bus: t("future.bus"),
            busSub: t("future.busSub"),
            service: (key: string) => t(`future.${key}`),
        }),
        [t],
    )

    const data = useMemo(
        () => (era === "future" ? buildFutureScene(futureLabels) : buildLiveScene(healthByName, flatLabels, selectedId)),
        [era, healthByName, flatLabels, futureLabels, selectedId],
    )

    // nothing is selectable in the future (roadmap) scene
    const onSelect = (id: string) => {
        if (era === "future") return
        onSelectNode(id)
    }

    const highlightId = era === "future" ? undefined : selectedId

    const caption = era === "future"
        ? t("future.caption")
        : ARCHITECTURE_MODULE_MAP[selectedId]
            ? t("map.moduleHint")
            : t("map.atlasHint")

    return (
        <div className={"flex flex-col gap-3"}>
            {/* era switch (present ⇄ future) — no pod/layout toggle anymore */}
            <div data-principle="content-row" className="flex flex-wrap items-center justify-between gap-3">
                <TabsCard
                    variant="primary"
                    className="w-full max-w-xs"
                    leftTabs={{
                        selectedKey: era,
                        ariaLabel: t("view.eraAria"),
                        onSelectionChange: (key) => setEra(String(key) as typeof era),
                        items: [
                            { key: "present", label: t("view.present") },
                            { key: "future", label: t("view.future") },
                        ],
                    }}
                />
                {era === "future" ? (
                    <Chip size="sm" className="bg-accent-soft text-accent-soft-foreground">
                        <Chip.Label>{t("future.comingSoon")}</Chip.Label>
                    </Chip>
                ) : null}
            </div>

            <ArchitectureScene
                data={data}
                selectedId={highlightId}
                onSelectNode={onSelect}
                caption={caption}
            />
        </div>
    )
}

"use client"

import React from "react"
import { ScrollShadow, Typography, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { ARCHITECTURE_COMPONENTS } from "@/modules/utils/architecture-catalog"
import { ARCHITECTURE_MODULES } from "@/modules/utils/architecture-modules"
import type { HealthByName } from "@/hooks/useSystemHealthPoll"
import { getArchitectureStatusVisual, resolveArchitectureStatus } from "@/modules/utils/architecture-status-visual"
import { StackH } from "@/components/frames/Stack"

/** Props for {@link ArchitectureMobileNav}. */
export interface ArchitectureMobileNavProps {
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
    /** Selected node id, mirrored to `?node=`. */
    selectedId: string
    /** Selects a node — shares state with {@link import("..").ArchitectureRail}. */
    onSelect: (id: string) => void
}

/** One selectable chip: icon + name + status dot. */
const NodeChip = ({
    name,
    icon: Icon,
    healthByName,
    selected,
    onSelect,
}: NodeChipProps) => {
    const state = resolveArchitectureStatus(name, healthByName)
    const visual = getArchitectureStatusVisual(state)
    return (
        <button
            type="button"
            aria-pressed={selected}
            onClick={onSelect}
            className={cn(
                "flex shrink-0 cursor-pointer items-center gap-2 rounded-full border px-3 py-2 text-sm transition-colors",
                selected ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
            )}
        >
            <Icon aria-hidden className="size-4 shrink-0" />
            <Typography type="body-sm" className={selected ? "text-accent-soft-foreground" : undefined}>{name}</Typography>
            <span className={cn("size-2 shrink-0 rounded-full", visual.dotClassName, visual.pulse && "animate-pulse")} aria-hidden />
        </button>
    )
}

/** One module chip: icon + name, NO status dot (modules have no health probe). */
const ModuleChip = ({
    id,
    icon: Icon,
    selected,
    onSelect,
}: ModuleChipProps) => {
    const t = useTranslations("architecture")
    return (
        <button
            type="button"
            aria-pressed={selected}
            onClick={onSelect}
            className={cn(
                "flex shrink-0 cursor-pointer items-center gap-2 rounded-full border px-3 py-2 text-sm transition-colors",
                selected ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
            )}
        >
            <Icon aria-hidden className="size-4 shrink-0" />
            <Typography type="body-sm" className={selected ? "text-accent-soft-foreground" : undefined}>{t(`module.${id}.name`)}</Typography>
        </button>
    )
}

/**
 * Mobile counterpart of {@link import("..").ArchitectureRail}: below `lg` the
 * docs-style rail hides, so the component list folds into two horizontally
 * scrollable chip rows (own system, then external dependencies) above the map
 * — the master-detail mobile pattern (mirrors `PracticeMobileNav`). Reads/
 * writes the same `?node=` state as the rail, so the two stay in lockstep.
 *
 * @param props - {@link ArchitectureMobileNavProps}
 */
export const ArchitectureMobileNav = ({ healthByName, selectedId, onSelect}: ArchitectureMobileNavProps) => {
    const t = useTranslations("architecture")
    const ownComponents = ARCHITECTURE_COMPONENTS.filter((c) => c.group === "own")
    const externalComponents = ARCHITECTURE_COMPONENTS.filter((c) => c.group === "external")

    return (
        <div className={"flex flex-col gap-3 @app-lg:hidden"}>
            <div data-principle="sibling-stack" className="flex flex-col gap-2">
                <Typography type="body-xs" color="muted">{t("rail.ownGroup")}</Typography>
                <ScrollShadow orientation="horizontal" hideScrollBar className="overflow-x-auto pb-1">
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={ownComponents.map((component) => (
                            () => (
                                <NodeChip
                                    name={component.name}
                                    icon={component.icon}
                                    healthByName={healthByName}
                                    selected={selectedId === component.name}
                                    onSelect={() => onSelect(component.name)}
                                />
                            )
                        ))}
                    />
                </ScrollShadow>
            </div>
            <div data-principle="sibling-stack" className="flex flex-col gap-2">
                <Typography type="body-xs" color="muted">{t("rail.externalGroup")}</Typography>
                <ScrollShadow orientation="horizontal" hideScrollBar className="overflow-x-auto pb-1">
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={externalComponents.map((component) => (
                            () => (
                                <NodeChip
                                    name={component.name}
                                    icon={component.icon}
                                    healthByName={healthByName}
                                    selected={selectedId === component.name}
                                    onSelect={() => onSelect(component.name)}
                                />
                            )
                        ))}
                    />
                </ScrollShadow>
            </div>
            <div data-principle="sibling-stack" className="flex flex-col gap-2">
                <Typography type="body-xs" color="muted">{t("rail.moduleGroup", { count: ARCHITECTURE_MODULES.length })}</Typography>
                <ScrollShadow orientation="horizontal" hideScrollBar className="overflow-x-auto pb-1">
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={ARCHITECTURE_MODULES.map((module) => (
                            () => (
                                <ModuleChip
                                    id={module.id}
                                    icon={module.icon}
                                    selected={selectedId === module.id}
                                    onSelect={() => onSelect(module.id)}
                                />
                            )
                        ))}
                    />
                </ScrollShadow>
            </div>
        </div>
    )
}

type NodeChipProps = {
    name: string
    icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
    healthByName: HealthByName | null
    selected: boolean
    onSelect: () => void
}
type ModuleChipProps = {
    id: string
    icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
    selected: boolean
    onSelect: () => void
}

"use client"

import React, { useMemo } from "react"
import { Label, ListBox, ScrollShadow, Typography, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { ARCHITECTURE_COMPONENTS } from "@/modules/utils/architecture-catalog"
import { ARCHITECTURE_MODULES } from "@/modules/utils/architecture-modules"
import type { HealthByName } from "@/hooks/useSystemHealthPoll"
import { MetricsInline } from "../MetricsInline"
import { getArchitectureStatusVisual, resolveArchitectureStatus } from "@/modules/utils/architecture-status-visual"

/** Props for {@link ArchitectureRail}. */
export interface ArchitectureRailProps {
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
    /** Selected node id, mirrored to `?node=`. */
    selectedId: string
    /** Selects a node (rail row, map click, or mobile chip all call this). */
    onSelect: (id: string) => void
}

/** One rail row: icon + name/tagline + a live status dot WITH a text label —
 *  never color-only (a11y: dot + text, ≥3:1 contrast). Shared by both the
 *  "own" and "external" groups below. */
const ComponentRow = ({
    name,
    icon: Icon,
    healthByName,
}: ComponentRowProps) => {
    const t = useTranslations("architecture")
    const state = resolveArchitectureStatus(name, healthByName)
    const visual = getArchitectureStatusVisual(state)
    const metrics = healthByName?.[name]?.metrics
    return (
        <span data-principle="identity" className="flex w-full min-w-0 items-center gap-2">
            <Icon aria-hidden className="size-4 shrink-0 text-muted" />
            <span className="flex min-w-0 flex-1 flex-col">
                <Typography type="body-sm" weight="medium" className="min-w-0 truncate">
                    {name}
                </Typography>
                <Typography type="body-xs" color="muted" className="min-w-0 truncate">
                    {t(`rail.tagline.${name}`)}
                </Typography>
                {/* only components with a local Docker container carry metrics — a
                    row with none (judge0, ollama, mail, aiBalancer, external SaaS)
                    simply stays 2 lines, no fake placeholder line */}
                <MetricsInline metrics={metrics} className="text-xs text-muted" />
            </span>
            <span className={cn("flex shrink-0 items-center gap-2 rounded-full px-2 py-0", visual.chipClassName)}>
                <span className={cn("size-1.5 shrink-0 rounded-full", visual.dotClassName, visual.pulse && "animate-pulse")} aria-hidden />
                <Typography type="body-xs" className="whitespace-nowrap">
                    {t(`status.${state}`)}
                </Typography>
