}

/**
 * "More in {pillar}" strip at the end of an article. Reuses the existing
 * `blogPosts(category)` query (no new backend) to keep readers in the same
 * editorial pillar. Self-hiding: renders nothing when there are no other posts.
 */
export const RelatedPosts = ({ category, currentSlug }: RelatedPostsProps) => {
    const t = useTranslations("blog")
    const locale = useLocale()

    const { data } = useSWR(
        ["blog-related", category, currentSlug],
        async () => {
            const response = await queryBlogPosts({
                request: { category, limit: MAX_RELATED + 1, offset: 0 },
            })
            return response.data?.blogPosts.data ?? []
        },
    )

    const related = (data ?? [])
        .filter((post) => post.slug !== currentSlug)
        .slice(0, MAX_RELATED)

    // self-hiding section — nothing to show when this is the only post in the pillar
    if (related.length === 0) {
        return null
    }

    const formatDate = (iso: string) =>
        new Date(iso).toLocaleDateString(locale, {
            year: "numeric",
            month: "short",
            day: "numeric",
        })

    return (
        <section className="border-t border-default pt-6">
            <StackV
                principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <h2 className="text-lg font-semibold text-foreground">
                            {t("relatedTitle", { category: t(`categories.${category}`) })}
                        </h2>
                    ),
                    ...related.map((post) => () => (
                        <PostRow
                            post={post}
                            formattedDate={formatDate(post.publishedAt)}
                        />
                    )),
                ]}
            />
        </section>
    )
}

import React from "react"
import { ArrowLeftIcon, ArticleIcon } from "@phosphor-icons/react"
import { Link } from "@/i18n/navigation"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Callout } from "@/components/composites/feedback/Callout"
import { Typography } from "@/components/atoms/text/Typography"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Button } from "@/components/atoms/buttons/Button"
import { Image } from "@/components/atoms/media/Image"
import { Container } from "@/components/frames/Container"
import { StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { BlogCategory } from "@/modules/api/graphql/queries/types/blog"
import { ReadingProgress } from "./ReadingProgress"
import { RelatedPosts } from "./RelatedPosts"

/** How many placeholder body lines the co-located skeleton mirrors (matches the old 6-full + 1-partial rhythm). */
const SKELETON_BODY_LINES = 7

/** All display text, already localized by the connected `BlogPostPage`; a story passes i18n keys. */
export interface BlogPostLabels {
    back: string
    errorTitle: string
    errorHint: string
    retry: string
    notFound: string
    /** Editorial pillar chip label — only meaningful once a post is loaded. */
    category: string
    premium: string
    /** Already-formatted publish date — only meaningful once a post is loaded. */
    publishedAt: string
    /** Already-interpolated "X min read" — omitted when the post carries no estimate. */
    readingMinutes?: string
    lockedTitle: string
    lockedBody: string
    viewSource: string
    /** Funnel CTA label — the post's own `ctaLabel`, or the generic fallback. */
    cta: string
}

/** Props for {@link _BlogPostPage} — presentational; all data resolved, no fetch/store/i18n. */
export interface BlogPostPageProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no matching post → the "not found" message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its fetch error. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry?: () => void

    title?: string
    category?: BlogCategory
    /** Chip tone for {@link BlogPostPageProps.category} — the connected file resolves it from `CATEGORY_COLOR`. */
    categoryTone?: ChipTone
    isPremium?: boolean
    coverImageUrl?: string | null
    /** Article body (markdown). */
    body?: string
    /** `true` when the body was truncated server-side for a non-member viewer. */
    isLocked?: boolean
    /** "View on GitHub" source link — omitted → the button is skipped. */
    sourceUrl?: string | null
    /** Funnel CTA destination — omitted → the button is skipped. */
    ctaUrl?: string | null
    /** Current post's slug — excluded from the "more in this pillar" strip. */
    slug?: string

    labels: BlogPostLabels
}

/**
 * Public `/blog/[slug]` article — the presentational half of {@link BlogPostPage}. Renders a reading-progress
 * bar (once real content is showing), a persistent "back to blog" link, and — error → not-found → content,
 * in that fixed priority — the serif header, the markdown body, the members-only gate, the GitHub source +
 * funnel CTAs, and a "More in {pillar}" strip. The content region threads `isSkeleton` to every leaf so the
 * shimmer mirrors the loaded shape (loading-and-skeleton.md); `MarkdownContent` has no `isSkeleton` of its
 * own, so its slot swaps to a co-located `Skeleton.Paragraph` mirror while shimmering instead.
 *
 * @param props - {@link BlogPostPageProps}
 */
export const _BlogPostPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    title,
    category,
    categoryTone = "default",
    isPremium = false,
    coverImageUrl,
    body,
    isLocked = false,
    sourceUrl,
    ctaUrl,
    slug,
    labels,
}: BlogPostPageProps) => {
    // Always-visible chrome — present in every branch (error/not-found/content alike), unlike the
    // async region below it.
    const backLink: ComponentTypeWithSkeleton = () => (
        <Link href="/blog">
            <Typography size="sm" color="muted" prefixIcon={ArrowLeftIcon} text={labels.back} />
        </Link>
    )

    const shell = (region: React.ReactNode) => (
        <Container
            size="md"
            padding={6}
            identity={{ tier: "block", component: "BlogPostPage" }}
            body={() => (
                <StackV gap={6} items={[backLink, () => region]} />
            )}
        />
    )

    // error beats a stale loading flag; not-found only once settled
    if (error) {
        return shell(
            <AsyncContentError
                title={labels.errorTitle}
                description={labels.errorHint}
                onRetry={onRetry}
                retryLabel={labels.retry}
            />,
        )
    }
    if (!isSkeleton && isEmpty) {
        return shell(<AsyncContentEmpty icon={ArticleIcon} title={labels.notFound} />)
    }

    // header chip row: category pillar + optional premium badge; one shimmering pill while loading
    const chipItems: Array<ComponentTypeWithSkeleton> = isSkeleton
        ? [() => <Chip isSkeleton />]
        : [
            () => <Chip tone={categoryTone} text={labels.category} />,
            ...(isPremium ? [() => <Chip tone="warning" text={labels.premium} />] : []),
        ]

    // header meta row: publish date + optional reading time, separated by a middle dot
    const metaItems: Array<ComponentTypeWithSkeleton> = isSkeleton
        ? [() => <Typography size="sm" color="muted" isSkeleton />]
        : [
            () => <Typography size="sm" color="muted" text={labels.publishedAt} />,
            ...(labels.readingMinutes ? [() => <Typography size="sm" color="muted" text={labels.readingMinutes as string} />] : []),
        ]

    // The ONE real tree — the same shape shimmers while loading and renders once the post arrives.
    // Cover image, the locked gate, the CTA row, and the related strip only ever existed post-load
    // (the legacy skeleton never mirrored them either), so they're skipped entirely while shimmering.
    const articleTree = (
        <StackV gap={6} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            isSkeleton={isSkeleton} items={[
                () => (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        isSkeleton={isSkeleton} items={[
                            () => <Cluster gap={2} principle="chip-row"
                                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                items={chipItems} />,
                            () => <Typography size="h1" text={title ?? ""} isSkeleton={isSkeleton} />,
                            () => <Cluster gap={2} principle="separator-dot"
                                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                                separator items={metaItems} />,
                        ]} />
                ),
                ...(!isSkeleton && coverImageUrl ? [() => <Image src={coverImageUrl} alt="" ratio="video" />] : []),
                () => (isSkeleton
                    ? <Skeleton.Paragraph lines={SKELETON_BODY_LINES} />
                    : <MarkdownContent markdown={body ?? ""} />),
                ...(!isSkeleton && isLocked ? [() => (
                    <Callout status="warning" title={labels.lockedTitle} description={labels.lockedBody} />
                )] : []),
                ...(!isSkeleton && (sourceUrl || ctaUrl) ? [() => (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            ...(sourceUrl ? [() => (
                                <a href={sourceUrl} target="_blank" rel="noopener noreferrer">
                                    <Button variant="outline" size="lg" label={labels.viewSource} classNames={["w-full"]} />
                                </a>
                            )] : []),
                            ...(ctaUrl ? [() => (
                                <Link href={ctaUrl}>
                                    <Button variant="primary" size="lg" label={labels.cta} classNames={["w-full"]} />
                                </Link>
                            )] : []),
                        ]} />
                )] : []),
                ...(!isSkeleton && category != null && slug != null ? [() => (
                    <RelatedPosts category={category} currentSlug={slug} />
                )] : []),
            ]} />
    )

    return (
        <>
            {!isSkeleton && <ReadingProgress />}
            <Container
                size="md"
                padding={6}
                isSkeleton={isSkeleton}
                identity={{ tier: "block", component: "BlogPostPage" }}
                body={() => (
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[backLink, () => articleTree]}  />
                )}
            />
        </>
    )
}

"use client"

import React, {
    useCallback,
} from "react"
import {
    Chip,
    Typography,
} from "@heroui/react"
import {
    FileTextIcon,
    ClockIcon,
    FlameIcon,
} from "@phosphor-icons/react"
import {
    useRouter,
} from "next/navigation"
import {
    useTranslations,
} from "next-intl"
import {
    pathConfig,
} from "@/resources/path"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SurfaceListCardRow } from "@/components/blocks/cards/SurfaceListCard"
import { StackH } from "@/components/frames/Stack"
import { type ContentEntity, getContentChallengeCount } from "@/modules/types/entities/content"

/** Props for {@link BookmarkCard} (list item — per-item content data only). */
export interface BookmarkCardProps {
    /** Saved content entity rendered by this row. */
    content: ContentEntity
}

/**
 * One saved-content row inside the bookmark {@link SurfaceListCard}: a file icon,
 * the lesson title (the link — underlines on hover), the owning course as a
 * subtitle, and read-time / premium / challenge meta. The whole row navigates to
 * the content page (the title IS the link, so hover underlines it rather than
 * filling the row).
 *
 * List item: receives its own content entity and self-navigates via the router.
 * @param props - {@link BookmarkCardProps}
 */
export const BookmarkCard = ({
    content,
}: BookmarkCardProps) => {
    const t = useTranslations()
    const router = useRouter()
    const challengeCount = getContentChallengeCount(content)

    const onPress = useCallback(
        () => {
            if (content.displayId) {
                router.push(pathConfig().locale().publicContent(content.displayId).build())
            }
        },
        [
            content.displayId,
            router,
        ],
    )

    return (
        <SurfaceListCardRow
            hover="underline"
            onPress={onPress}
            leading={() => (
                <IconTile
                    size="sm"
                    tone="neutral"
                    src={content.module?.course?.coverImageUrl}
                    icon={<FileTextIcon />}
                    alt={content.title ?? ""}
                />
            )}
            title={content.title}
            subtitle={content.module?.course?.title}
            meta={() => (
                <>
                    {content.isPremium ? (
                        <Chip size="sm" variant="soft" color="warning">
                            <Chip.Label>{t("bookmarks.premium")}</Chip.Label>
                        </Chip>
                    ) : null}
                    <StackH
                        as="span"
                        inline
                        gap={2}
                        align="center"
                        principle="icon-text"
                        explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                        items={[
                            () => <ClockIcon aria-hidden className="size-4 text-muted" />,
                            () => (
                                <Typography type="body-xs" color="muted">
                                    {t("content.minutesRead", { minutes: content.minutesRead })}
                                </Typography>
                            ),
                        ]}
                    />
                    {challengeCount > 0 ? (
                        <StackH
                            as="span"
                            inline
                            gap={2}
                            align="center"
                            principle="icon-text"
                            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                            items={[
                                () => <FlameIcon aria-hidden className="size-4 text-muted" />,
                                () => (
                                    <Typography type="body-xs" color="muted">
                                        {challengeCount}
                                    </Typography>
                                ),
                            ]}
                        />
                    ) : null}
                </>
            )}
        />
    )
}

"use client"

import React, {
    useEffect,
    useState,
} from "react"
import {
    Button,
    Input,
    Pagination,
    TextField,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    BookmarkCard,
} from "./BookmarkCard"
import { pathConfig } from "@/resources/path"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { SAVED_CONTENTS_PAGE_SIZE, useQuerySavedContentsSwr } from "@/hooks/swr/api/graphql/queries/useQuerySavedContentsSwr"

/**
 * Bookmark page — a searchable, paginated library of the viewer's saved contents.
 * Follows the list-surface anatomy: a primary search input balanced by the result
 * count, one {@link SurfaceListCard} of saved-lesson rows, and a left-aligned
 * {@link Pagination} (hidden on a single page). Search + paging are resolved
 * server-side (`savedContents(skip, take, search)`); typing snaps back to page 1.
 * Data states go through {@link AsyncContent}. A truly-empty library (never
 * bookmarked, no active search) renders {@link EmptyState} with a "browse
 * courses" CTA instead of a dead end; a zero-match search stays inline with
 * {@link AsyncContentEmpty} so the search box remains reachable. Mounted by
 * `/profile/bookmarks`.
 */
export const BookmarksPage = () => {
    const t = useTranslations()
    const router = useRouter()

    // search input (debounced → server-side title filter) + 1-based page
    const [search, setSearch] = useState("")
    const [debounced, setDebounced] = useState("")
    const [page, setPage] = useState(1)

    // debounce keystrokes before hitting the server
    useEffect(() => {
        const timer = setTimeout(() => setDebounced(search.trim()), 300)
        return () => clearTimeout(timer)
    }, [search])

    // a new search shrinks the list — snap back to the first page
    useEffect(() => {
        setPage(1)
    }, [debounced])

    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQuerySavedContentsSwr(page, debounced)

    const contents = data?.contents ?? []
    const count = data?.count ?? 0
    const totalPages = Math.ceil(count / SAVED_CONTENTS_PAGE_SIZE)
    const pageNumbers = Array.from({ length: totalPages }, (_unused, index) => index + 1)

    const skeletonRows = [0, 1, 2, 3, 4].map((row) => () => (
        <Box key={row} principle="card-padding" className="p-4"
            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
            <StackH
                gap={4}
                align="center"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                    () => (
                        <StackV
                            gap={3}
                            principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            classNames={["flex-1"]}
                            items={[
                                () => <Skeleton className="h-4 w-1/2 rounded-medium" />,
                                () => <Skeleton className="h-3 w-1/3 rounded-medium" />,
                            ]}
                        />
                    ),
                ]}
            />
        </Box>
    ))

    const listBodyItems = [
        () => (
            <Cluster
                gap={4}
                justify="between"
                align="center"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <TextField className="w-full @app-sm:max-w-sm">
                            <Input
                                type="search"
                                aria-label={t("bookmarks.searchPlaceholder")}
                                placeholder={t("bookmarks.searchPlaceholder")}
                                value={search}
                                onChange={(event) => setSearch(event.target.value)}
                            />
                        </TextField>
                    ),
                    () => (
                        <Typography type="body-sm" color="muted" className="shrink-0">
                            {t("bookmarks.found", { count })}
                        </Typography>
                    ),
                ]}
            />
        ),
        () => (
            contents.length === 0 ? (
                <AsyncContentEmpty title={t("bookmarks.noMatch")} />
            ) : (
                <>
                    <SurfaceListCard>
                        {contents.map((content) => (
                            <BookmarkCard key={content.id} content={content} />
                        ))}
                    </SurfaceListCard>

                    {totalPages > 1 ? (
                        <Pagination
                            aria-label={t("common.pagination.navAria")}
                            className="justify-start"
                            size="sm"
                        >
                            <Pagination.Content className="flex flex-wrap justify-start gap-2" data-principle="flex-action">
                                <Pagination.Item>
                                    <Pagination.Previous
                                        aria-label={t("common.pagination.previous")}
                                        isDisabled={page <= 1}
                                        className="cursor-pointer rounded-medium transition-colors hover:bg-default"
                                        onPress={() => setPage((current) => Math.max(1, current - 1))}
                                    >
                                        <Pagination.PreviousIcon />
                                    </Pagination.Previous>
                                </Pagination.Item>
                                {pageNumbers.map((pageNumber) => (
                                    <Pagination.Item key={pageNumber}>
                                        <Pagination.Link
                                            isActive={pageNumber === page}
                                            className="cursor-pointer rounded-medium transition-colors hover:bg-default data-[active=true]:hover:bg-accent"
                                            onPress={() => setPage(pageNumber)}
                                        >
                                            {pageNumber}
                                        </Pagination.Link>
                                    </Pagination.Item>
                                ))}
                                <Pagination.Item>
                                    <Pagination.Next
                                        aria-label={t("common.pagination.next")}
                                        isDisabled={page >= totalPages}
                                        className="cursor-pointer rounded-medium transition-colors hover:bg-default"
                                        onPress={() => setPage((current) => Math.min(totalPages, current + 1))}
                                    >
                                        <Pagination.NextIcon />
                                    </Pagination.Next>
                                </Pagination.Item>
                            </Pagination.Content>
                        </Pagination>
                    ) : null}
                </>
            )
        ),
    ]

    return (
        <Box identity={{ tier: "page", component: "BookmarksPage" }} principle="center-measure" className="mx-auto max-w-4xl"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
            <Box principle="page-pad" className="p-6"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                <div className="flex flex-col gap-10">
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("bookmarks.heading")} />}
                        title={t("bookmarks.heading")}
                        description={t("bookmarks.subtitle")}
                    />
                    <AsyncContent
                        isLoading={isLoading && !data}
                        skeleton={(
                            <SurfaceListCard>
                                {skeletonRows.map((Row, index) => (
                                    <Row key={index} />
                                ))}
                            </SurfaceListCard>
                        )}
                        error={error}
                        errorContent={{
                            title: t("bookmarks.errorTitle"),
                            onRetry: () => { void mutate() },
                            retryLabel: t("dashboard.retry"),
                        }}
                    >
                        {!debounced && count === 0 ? (
                            <EmptyState
                                title={t("bookmarks.empty")}
                                description={t("bookmarks.emptyHint")}
                                action={() => (
                                    <Button
                                        variant="primary"
                                        onPress={() => router.push(pathConfig().locale().course().build())}
                                    >
                                        {`${t("dashboard.browseCourses")} →`}
                                    </Button>
                                )}
                            />
                        ) : (
                            <StackV gap={4} items={listBodyItems} />
                        )}
                    </AsyncContent>
                </div>
            </Box>
        </Box>
    )
}

import React, { useEffect, useMemo, useState } from "react"
import { ArrowRightIcon, ShoppingCartIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { Container } from "@/components/frames/Container"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { CartLine } from "@/components/blocks/commerce/CartLine"
import { publicEnv } from "@/resources/env/public"
import type { CartItemEntity } from "@/modules/api/graphql/queries/types/my-cart"
import type { CoursesCheckoutPreviewLine } from "@/modules/api/graphql/queries/types/courses-checkout-preview"
import type { CourseEntity } from "@/modules/types/entities/course"

/** How many placeholder rows the co-located skeleton shows for the cart-line list. */
const SKELETON_ROW_COUNT = 3

/** Format an integer VND amount as "1.275.000₫". */
export const formatVnd = (amount: number): string => `${amount.toLocaleString("vi-VN")}₫`

/**
 * A course's DISPLAY list VND price from its entity (active-phase price, falling
 * back to the list price, ÷ non-prod test divisor). Used only as the FALLBACK
 * total when the checkout preview fails — the real charged total comes from the
 * preview, whose amounts are already display-ready.
 */
const displayPriceVnd = (course: CourseEntity): number => {
    const divisor = publicEnv().pricing.testDivisor
    const toVnd = (amount: number): number =>
        divisor === 1 ? amount : Math.max(1, Math.round(amount / divisor))
    const phasePrice = course.pricingPhases?.find(
        (phase) => phase.phase === course.currentPhase,
    )?.price
    return toVnd(phasePrice ?? course.originalPrice ?? 0)
}

/**
 * One row's minimal shimmer standing in for {@link CartLine} while the cart's
 * first load is in flight. `CartLine` takes no `isSkeleton` prop, so this mirrors
 * its leading-tile + title/price + trailing-button shape as a `content` slot
 * inside {@link SurfaceCardList} (Decision C — same tree, no parallel list).
 */
const CartLineSkeletonBody = () => (
    <StackH gap={4} items={[
        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
        () => (
            <StackV gap={3} classNames={["min-w-0", "flex-1"]} items={[
                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                () => <Skeleton className="h-4 w-24 rounded-lg" />,
            ]} />
        ),
        () => <Skeleton className="size-9 shrink-0 rounded-lg" />,
    ]} />
)

/** Props for the private {@link ClearCartButton} helper. */
interface ClearCartButtonProps {
    isDisabled: boolean
    onClear: () => void
    /** Already-translated resting label ("Clear cart"). */
    clearLabel: string
    /** Already-translated armed-state label ("Press again to confirm"). */
    confirmLabel: string
}

/**
 * "Clear cart" with a lightweight inline 2-step confirm (no modal): first press
 * arms a danger-soft "confirm" state that auto-disarms after 3s; second press
 * within the window actually clears — so a destroy-all action can't fire on one
 * stray click. (canon: destructive action needs confirmation.)
 */
const ClearCartButton = ({ isDisabled, onClear, clearLabel, confirmLabel }: ClearCartButtonProps) => {
    const [confirming, setConfirming] = useState(false)
    useEffect(() => {
        if (!confirming) return
        const timer = setTimeout(() => setConfirming(false), 3000)
        return () => clearTimeout(timer)
    }, [confirming])
    return (
        <Button
            variant={confirming ? "danger-soft" : "tertiary"}
            isDisabled={isDisabled}
            label={confirming ? confirmLabel : clearLabel}
            classNames={["w-full"]}
            onPress={() => {
                if (confirming) {
                    onClear()
                    setConfirming(false)
                } else {
                    setConfirming(true)
                }
            }}
        />
    )
}

/** All display text, already localized by the connected `CartPage`; a story passes i18n keys. */
export interface CartPageLabels {
    title: string
    description: string
    empty: string
    emptyHint: string
    browseCourses: string
    error: string
    retry: string
    total: string
    /** Full "Checkout (N)" sentence — the connected file interpolates the count. */
    checkoutCount: string
    clear: string
    clearConfirm: string
    /** Present only when the preview reports a real saving over the list total. */
    savings?: string
    /** Present only when the preview also reports a multi-course bundle bonus. */
    bundleBonus?: string
    /** Present only when an installment plan exists for this cart. */
    installmentHint?: string
    /** "Add one more to unlock the next tier" nudge — present only at cart size 1 or 2. */
    addMoreHint?: string
}

/** Props for {@link _CartPage} — presentational; all data resolved, no fetch/store/i18n. */
export interface CartPageProps {
    /** Every cart row with its full course. */
    items: Array<CartItemEntity>
    /** The checkout preview's per-course lines, for per-line pricing inside {@link CartLine}. */
    previewLines: Array<CoursesCheckoutPreviewLine>
    /** Real charged total from the checkout preview; undefined while it's pending or on error. */
    totalChargedVnd?: number
    /** Real list (pre-discount) total from the checkout preview. */
    totalListVnd?: number
    /** Disables the remove/checkout/clear affordances while a cart write is in flight. */
    isMutating: boolean
    /** First load, nothing in hand yet → the cart-line list + footer shimmer in place. */
    isSkeleton?: boolean
    /** Settled with zero rows → the empty message (offers browsing courses). */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file's settled cart-fetch error. */
    error?: unknown
    /**
     * The cart itself has resolved but the checkout-preview query (a separate SWR
     * key) is still pending — only the footer total/savings block shimmers.
     */
    isPreviewSkeleton?: boolean
    /** Retry handler for the error branch — re-fetches the cart. */
    onRetry: () => void
    /** Remove one course from the cart. */
    onRemove: (courseId: string) => void
    /** Opens the payment overlay for the current cart. */
    onCheckout: () => void
    /** Empties the cart (after the inline 2-step confirm). */
    onClearCart: () => void
    /** Jumps to course browsing — the empty state's action. */
    onBrowseCourses: () => void
    labels: CartPageLabels
}

/**
 * Shopping-cart page — the presentational half of {@link import("./index").CartPage}.
 * Header (always shown) → error/empty/content in that order (`error` beats a stale
 * `isSkeleton`; `isEmpty` only once settled) → cart lines in one `SurfaceCardList` →
 * a footer with the REAL discounted total (progressive loyalty + multi-course bundle
 * bonus), the saving, a bundle chip, an "add more to save more" nudge, a primary
 * "Checkout" CTA (opens the payment modal), and a tertiary "Clear cart". The cart-line
 * list and the footer's preview total shimmer independently (two separate SWR keys —
 * `isSkeleton` for the cart itself, `isPreviewSkeleton` for the checkout preview),
 * both threaded co-located rather than built as a parallel skeleton tree. See
 * `tiers/split.md` — the connected `./index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link CartPageProps}
 */
export const _CartPage = ({
    items,
    previewLines,
    totalChargedVnd,
    totalListVnd,
    isMutating,
    isSkeleton = false,
    isEmpty = false,
    error,
    isPreviewSkeleton = false,
    onRetry,
    onRemove,
    onCheckout,
    onClearCart,
    onBrowseCourses,
    labels,
}: CartPageProps) => {
    const { savings: savingsLabel, bundleBonus: bundleBonusLabel, installmentHint: installmentHintLabel, addMoreHint: addMoreHintLabel } = labels

    // courseId → preview line, for per-line pricing.
    const previewByCourse = useMemo(() => {
        const map = new Map<string, CoursesCheckoutPreviewLine>()
        previewLines.forEach((line) => map.set(line.courseId, line))
        return map
    }, [previewLines])

    // plain summed list total from the cart entities — the fallback shown when the
    // preview total hasn't arrived (still pending, or errored).
    const fallbackTotalVnd = useMemo(
        () => items.reduce((sum, item) => sum + displayPriceVnd(item.course), 0),
        [items],
    )

    // the footer summary block: total (real charged) + savings + bundle chip + nudge.
    // While the preview itself is pending it shimmers independently of the cart list.
    const summaryItems = isPreviewSkeleton
        ? [() => <Skeleton className="h-4 w-40 rounded-lg" />]
        : [
            ...(savingsLabel ? [() => (
                <StackH gap={3} principle="flex-action" justify="between"
                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                    items={[
                        () => <Typography size="sm" color="success-soft" text={savingsLabel} />,
                        () => (bundleBonusLabel ? <Chip tone="accent" text={bundleBonusLabel} /> : null),
                    ]} />
            )] : []),
            ...(installmentHintLabel ? [() => <Typography size="xs" color="muted" text={installmentHintLabel} />] : []),
            ...(addMoreHintLabel ? [() => <Typography size="xs" color="muted" text={addMoreHintLabel} />] : []),
        ]

    // error beats a stale isSkeleton flag; empty only once settled (BLOCK-8) — the
    // two message branches are the shared `AsyncContent*` frames, not hand-written JSX.
    const contentBody = () => {
        if (error) {
            return <AsyncContentError title={labels.error} onRetry={onRetry} retryLabel={labels.retry} />
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    icon={ShoppingCartIcon}
                    title={labels.empty}
                    description={labels.emptyHint}
                    onRetry={onBrowseCourses}
                    retryLabel={labels.browseCourses}
                />
            )
        }
        return (
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => {
                        const listItems: Array<SurfaceCardListItem> = isSkeleton
                            ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
                                key: `skeleton-${index}`,
                                content: () => <CartLineSkeletonBody />,
                            }))
                            : items.map((item) => ({
                                key: item.id,
                                content: () => (
                                    <CartLine
                                        item={item}
                                        previewLine={previewByCourse.get(item.courseId)}
                                        onRemove={onRemove}
                                        isMutating={isMutating}
                                    />
                                ),
                            }))
                        return (
                            <SurfaceCardList
                                items={listItems}
                                isSkeleton={isSkeleton}
                            />
                        )
                    },
                    () => {
                    // Items hoisted so this gap-only column is not scanned as owning nested
                    // justify/principle from its children (check-pattern-coverage opens to `>`).
                        const footerColumnItems = isSkeleton
                            ? [() => <Skeleton className="h-12 w-full rounded-2xl" />]
                            : [
                                () => (
                                    <StackV gap={3} principle="sibling-stack" isSkeleton={isPreviewSkeleton}
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => (
                                                <StackH gap={4} principle="content-row" justify="between"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => <Typography size="base" weight="semibold" text={labels.total} isSkeleton={isPreviewSkeleton} />,
                                                        () => (isPreviewSkeleton
                                                            ? <Skeleton className="h-7 w-32 rounded-lg" />
                                                            : (totalChargedVnd != null
                                                                ? (
                                                                    <PriceTagInline
                                                                        discounted={totalChargedVnd}
                                                                        original={totalListVnd}
                                                                        currency="VND"
                                                                    />
                                                                )
                                                                : <Typography size="h4" weight="bold" text={formatVnd(fallbackTotalVnd)} />)),
                                                    ]} />
                                            ),
                                            ...summaryItems,
                                        ]} />
                                ),
                                () => (
                                    <Button
                                        variant="primary"
                                        size="lg"
                                        isDisabled={isMutating}
                                        onPress={onCheckout}
                                        label={labels.checkoutCount}
                                        suffixIcon={ArrowRightIcon}
                                        classNames={["w-full"]}
                                    />
                                ),
                                () => (
                                    <ClearCartButton
                                        isDisabled={isMutating}
                                        onClear={onClearCart}
                                        clearLabel={labels.clear}
                                        confirmLabel={labels.clearConfirm}
                                    />
                                ),
                            ]
                        return <StackV gap={4} items={footerColumnItems} />
                    },
                ]} />
        )
    }

    return (
        <Container
            size="md"
            padding={6}
            identity={{ tier: "block", component: "CartPage" }}
            body={() => (
                <StackV gap={7} items={[
                    () => <PageHeader title={labels.title} description={labels.description} />,
                    contentBody,
                ]} />
            )}
        />
    )
}

import { InputTextarea } from "@/components/atoms/forms"
import React, { useCallback, useState } from "react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"

import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { StackH, StackV } from "@/components/frames/Stack"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import type { ChatMessageNode } from "@/modules/api/graphql/queries/types/chat"

/** How many placeholder rows the co-located skeleton shows for the message list. */
const SKELETON_ROW_COUNT = 3

/** All display text, already localized by the connected `ChatPane`; a story passes i18n keys. */
export interface ChatPaneLabels {
    /** Empty-state title — no messages yet. */
    empty: string
    /** Error-state title — the message list failed to load. */
    error: string
    /** Retry-button label paired with {@link ChatPaneProps.onRetry}. */
    retry: string
    /** Composer placeholder / accessible name. */
    placeholder: string
    /** Send-button label. */
    send: string
}

/** Props for {@link _ChatPane} — presentational; all data resolved, no fetch/store/i18n. */
export interface ChatPaneProps {
    /** First load, nothing in hand → the message list shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero messages → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry?: () => void
    /** Messages, oldest→newest, already resolved by the connected file. */
    messages?: Array<ChatMessageNode>
    /** `true` while a send is in flight — locks the send button and shows its spinner. */
    isSending?: boolean
    /** Sends the composed body; resolves `true` on success (the composer clears itself), `false` otherwise. */
    onSend: (body: string) => Promise<boolean>
    /** Already-translated copy — see {@link ChatPaneLabels}. */
    labels: ChatPaneLabels
}

/**
 * `_ChatPane` — the presentational half of {@link import(".").ChatPane}: one
 * chat conversation's message list + composer. Three states in the fixed
 * order error → empty → content (`loading-and-skeleton.md`): `error` falls
 * to the shared `AsyncContentError` frame, a settled `isEmpty` to
 * `AsyncContentEmpty`, and otherwise the message list renders with
 * `isSkeleton` threaded down to every leaf that supports it — placeholder
 * rows keep the SAME `ChatBubble` shape as the loaded state, alternating
 * `isMine` the way real messages do so the sender row shows/hides in the
 * same pattern. `UserCell` itself has no `isSkeleton`, so that one sender
 * row is mirrored in place with `Skeleton.UserCell` instead (still
 * co-located, not a parallel tree). Only the message-list zone branches —
 * the composer stays mounted underneath regardless, so a member can still
 * write while the history is loading or failed to load. See
 * `tiers/split.md` — the connected `index.tsx` owns the fetch, the socket
 * subscription, and i18n.
 *
 * @param props - {@link ChatPaneProps}
 */
export const _ChatPane = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    messages = [],
    isSending = false,
    onSend,
    labels,
}: ChatPaneProps) => {
    const [body, setBody] = useState("")

    /** Trim + guard, hand off to the connected sender, clear the composer on success. */
    const onSendPress = useCallback(async () => {
        const trimmed = body.trim()
        if (!trimmed) {
            return
        }
        const ok = await onSend(trimmed)
        if (ok) {
            setBody("")
        }
    }, [body, onSend])

    // Row shape shared by both states: while shimmering, placeholder rows alternate
    // `isMine` the same way real messages do, so the sender row (UserCell) shows/hides
    // in the SAME pattern the loaded list will settle into — nothing collapses or jumps.
    const rows = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
            isMine: index % 2 === 1,
            body: undefined as string | undefined,
            author: undefined as ChatMessageNode["author"] | undefined,
            isFounderAuthor: false,
        }))
        : messages.map((message) => ({
            isMine: message.isMine,
            body: message.body as string | undefined,
            author: message.author as ChatMessageNode["author"] | undefined,
            isFounderAuthor: message.isFounderAuthor,
        }))

    const messageRows: Array<ComponentTypeWithSkeleton> = rows.map((row) => () => (
        <StackV gap={2} items={[
            ...(!row.isMine ? [() => (
                isSkeleton || !row.author ? (
                    <Skeleton.UserCell withHandle={false} />
                ) : (
                    <UserCell
                        username={row.author!.username}
                        displayName={row.author!.displayName ?? undefined}
                        avatar={row.author!.avatar ?? undefined}
                        size="sm"
                        trailing={row.isFounderAuthor
                            ? () => <SealCheckIcon weight="fill" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                            : undefined}
                    />
                )
            )] : []),
            () => (
                <ChatBubble role={row.isMine ? "user" : "assistant"}>
                    <Typography size="sm" text={row.body ?? ""} isSkeleton={isSkeleton} />
                </ChatBubble>
            ),
        ]} />
    ))

    return (
        <StackV
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            identity={{ tier: "block", component: "ChatPane" }}
            items={[
                () => (
                    error ? (
                        <AsyncContentError title={labels.error} onRetry={onRetry} retryLabel={labels.retry} />
                    ) : !isSkeleton && isEmpty ? (
                        <AsyncContentEmpty title={labels.empty} />
                    ) : (
                        // NEW-VOCABULARY GAP: no frame owns "cap this region's height and scroll
                        // it locally" — `ScrollArea`'s `classNames` is a closed, positioning-only
                        // enum (no height values) — so the height cap goes through `Box` (the
                        // sanctioned raw-appearance escape hatch), same shape as `FollowListModal`.
                        <Box className="max-h-[60vh]">
                            <ScrollArea axis="y" body={() => <StackV gap={4} isSkeleton={isSkeleton} items={messageRows} />} />
                        </Box>
                    )
                ),
                () => (
                    <StackV gap={3} principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => (
                                <InputTextarea
                                    variant="secondary"
                                    rows={2}
                                    value={body}
                                    onValueChange={setBody}
                                    placeholder={labels.placeholder}
                                    ariaLabel={labels.placeholder}
                                />
                            ),
                            () => (
                                <StackH gap={1} principle="name-handle"
                                    explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                    justify="end" items={[
                                        () => (
                                            <Button
                                                variant="primary"
                                                size="sm"
                                                label={labels.send}
                                                isPending={isSending}
                                                isDisabled={!body.trim()}
                                                onPress={() => void onSendPress()}
                                            />
                                        ),
                                    ]} />
                            ),
                        ]} />
                ),
            ]}
        />
    )
}

"use client"

import React, { useCallback, useEffect, useMemo } from "react"
import { useTranslations } from "next-intl"
import { _ChatPane } from "./component"
import { PublicationEvent } from "@/hooks/socketio/enums/publication-event"
import { SubscriptionEvent } from "@/hooks/socketio/enums/subscription-event"
import { communityChatSocketIoEventEmitter } from "@/hooks/socketio/useCommunityChatSocketIoLifecycle"
import { useCommunityChatSocketIo } from "@/hooks/socketio/useCommunityChatSocketIo"
import { useMutateSendChatMessageSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSendChatMessageSwr"
import { useQueryChatMessagesSwr } from "@/hooks/swr/api/graphql/queries/useQueryChatMessagesSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"

/** Props for {@link ChatPane}. */
export interface ChatPaneProps {
    /**
     * Conversation whose messages are shown + sent to. Omitted/null → shimmer
     * mirror of the pane (message list + composer) while the active id resolves.
     */
    conversationId?: string | null
}

type ChatPaneLiveProps = {
    conversationId: string
}

/**
 * Live connected pane — hooks only run when a conversation id is known.
 */
const ChatPaneLive = ({ conversationId }: ChatPaneLiveProps) => {
    const t = useTranslations()
    const runGraphQL = useGraphQLWithToast()
    const socket = useCommunityChatSocketIo()

    const { data, isLoading, error, mutate } = useQueryChatMessagesSwr(conversationId)
    const { trigger: sendMessage, isMutating } = useMutateSendChatMessageSwr()

    // server returns newest-first; render oldest→newest so the latest sits at the bottom
    const messages = useMemo(
        () => [...(data?.items ?? [])].reverse(),
        [data],
    )

    // join the conversation room (and re-join on reconnect)
    useEffect(() => {
        const subscribe = () => {
            socket.emit(PublicationEvent.SubscribeCommunityChat, {
                data: {
                    conversationId,
                },
            })
        }
        if (socket.connected) {
            subscribe()
        }
        socket.on("connect", subscribe)
        return () => {
            socket.off("connect", subscribe)
        }
    }, [socket, conversationId])

    // refetch whenever a realtime message arrives for THIS conversation
    useEffect(() => {
        const handler = (message: { data?: { conversationId?: string } }) => {
            // ignore events for other conversations sharing the same socket
            if (message?.data?.conversationId !== conversationId) {
                return
            }
            void mutate()
        }
        communityChatSocketIoEventEmitter.on(SubscriptionEvent.ChatMessageCreated, handler)
        return () => {
            communityChatSocketIoEventEmitter.off(SubscriptionEvent.ChatMessageCreated, handler)
        }
    }, [conversationId, mutate])

    /** Send one message (toast-wrapped), then refresh the list on success. */
    const onSend = useCallback(async (trimmedBody: string) => {
        const ok = await runGraphQL(async () => {
            const result = await sendMessage({
                conversationId,
                body: trimmedBody,
            })
            return result.data!.sendChatMessage
        })
        if (ok) {
            await mutate()
        }
        return ok
    }, [conversationId, sendMessage, runGraphQL, mutate])

    return (
        <_ChatPane
            // first load, nothing in hand → shimmer (loading-and-skeleton.md)
            isSkeleton={isLoading && messages.length === 0}
            isEmpty={messages.length === 0}
            // only a settled fetch error with nothing cached to show reaches the block
            error={messages.length === 0 ? error : undefined}
            onRetry={() => void mutate()}
            messages={messages}
            isSending={isMutating}
            onSend={onSend}
            labels={{
                empty: t("community.chat.empty"),
                error: t("community.chat.error"),
                retry: t("community.retry"),
                placeholder: t("community.chat.placeholder"),
                send: t("community.chat.send"),
            }}
        />
    )
}

/**
 * `ChatPane` — the connected half (see `tiers/split.md`) of one chat
 * conversation pane: fetches the conversation's messages, joins its
 * Socket.IO room and refetches on every new message (so messages from
 * others appear in real time), and resolves every label before handing
 * them to the presentational {@link _ChatPane}.
 *
 * @param props - {@link ChatPaneProps}
 */
export const ChatPane = ({ conversationId }: ChatPaneProps) => {
    const t = useTranslations()

    // Wait for an active conversation id — same shape as the live pane via
    // intrinsic `isSkeleton` (no parallel public skeleton export).
    if (!conversationId) {
        return (
            <_ChatPane
                isSkeleton
                isEmpty={false}
                messages={[]}
                isSending={false}
                onSend={async () => false}
                labels={{
                    empty: t("community.chat.empty"),
                    error: t("community.chat.error"),
                    retry: t("community.retry"),
                    placeholder: t("community.chat.placeholder"),
                    send: t("community.chat.send"),
                }}
            />
        )
    }
    return <ChatPaneLive conversationId={conversationId} />
}

"use client"

import React, { useMemo, useState } from "react"
import { Button } from "@heroui/react"
import { UsersThreeIcon } from "@phosphor-icons/react"
import type { Key } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { ChatPane } from "./ChatPane"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { PageContainer } from "@/components/blocks/layout/PageContainer"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { useAuthenticationOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useQueryCommunityChatConversationSwr } from "@/hooks/swr/api/graphql/queries/useQueryCommunityChatConversationSwr"
import { useQueryMyFounderConversationSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFounderConversationSwr"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"
import { StackV } from "@/components/frames/Stack"

/** Which conversation the chat surface is showing. */
type ChatTab = "community" | "founder"

/**
 * Community chat surface: a toggle between the global community room and the
 * private founder DM, with the active conversation's message pane below. Member-
 * only — signed-out users see a prompt; the server enforces the membership gate.
 */
export const CommunityChatPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const authentication = useAuthenticationOverlayState()
    const [tab, setTab] = useState<ChatTab>("community")

    const communityConversationSwr = useQueryCommunityChatConversationSwr()
    const founderConversationSwr = useQueryMyFounderConversationSwr()

    // the SWR handle for the active tab — chat reads are member-only, so a
    // signed-in non-member either errors (membership gate) or resolves to null.
    const activeConversationSwr = tab === "community"
        ? communityConversationSwr
        : founderConversationSwr

    // the conversation id for the active tab (undefined until resolved)
    const conversationId = activeConversationSwr.data?.id
    // still resolving: only the initial load, before either an id or a terminal
    // (error / null) is known — this is what the skeleton is allowed to cover.
    const isResolving = activeConversationSwr.isLoading && !activeConversationSwr.data
    // the query settled but yielded no conversation for the active tab: the
    // membership gate rejected a signed-in non-member (or the read failed).
    const membersOnly = !isResolving && !conversationId

    const tabs = useMemo(
        () => [
            { key: "community", label: t("community.chat.communityRoom") },
            { key: "founder", label: t("community.chat.founderDm") },
        ],
        [t],
    )

    return (
        <PageContainer>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <PageHeader
                            title={t("community.chat.title")}
                            description={t("community.chat.description")}
                        />
                    ),
                    () => (authenticated ? (
                        <StackV gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <TabsCard
                                        leftTabs={{
                                            items: tabs,
                                            selectedKey: tab,
                                            ariaLabel: t("community.chat.tabsAria"),
                                            onSelectionChange: (key: Key) => setTab(String(key) as ChatTab),
                                        }}
                                    />
                                ),
                                () => (conversationId ? (
                                    <ChatPane key={conversationId} conversationId={conversationId} />
                                ) : membersOnly ? (
                                // Signed-in but the membership gate rejected this read (or it
                                // failed): a non-member must not sit on a perpetual skeleton —
                                // surface a members-only terminal with an upsell to membership.
                                    <EmptyState
                                        icon={UsersThreeIcon}
                                        title={t("community.chat.membersOnly")}
                                        description={t("community.chat.membersOnlyDescription")}
                                        action={() => (
                                            <Button
                                                variant="primary"
                                                size="sm"
                                                onPress={() => router.push(
                                                    pathConfig().locale(locale).profile().membership().build(),
                                                )}
                                            >
                                                {t("community.chat.viewMembership")}
                                            </Button>
                                        )}
                                    />
                                ) : (
                                // 2026-07-12: was a bare "loading…" caption while the active
                                // conversation id resolves — mirror the real pane's shape
                                // (message list + composer) so the tab switch/first load
                                // doesn't jump into a differently-shaped panel afterward.
                                    <ChatPane />
                                )),
                            ]} />
                    ) : (
                        <EmptyState
                            title={t("community.chat.signInRequired")}
                            action={() => (
                                <Button
                                    variant="primary"
                                    size="sm"
                                    onPress={() => authentication.open()}
                                >
                                    {t("nav.signIn")}
                                </Button>
                            )}
                        />
                    )),
                ]} />
        </PageContainer>
    )
}

"use client"

import React, { useCallback, useState } from "react"
import { StackV } from "@/components/frames/Stack"
import {
    Button,
    Card,
    CardContent,
    TextArea,
    TextField,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import { CommunityChannel } from "@/modules/api/graphql/queries/types/community-feed"
import { useMutateCreateCommunityPostSwr } from "@/hooks/swr/api/graphql/mutations/useMutateCreateCommunityPostSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"

/** Props for the {@link CommunityComposer} sub-component. */
export interface CommunityComposerProps {
    /** Channel new posts are published to (the "all" tab posts to General). */
    channel: CommunityChannel
    /** Called after a post is created so the feature can refetch the feed. */
    onPosted: () => void
}

/**
 * Compose box for a new community post: a body textarea + a post button. Creation
 * goes through the toast-wrapped mutation, so the server-side quota error (for
 * non-members over their limit) surfaces as a toast automatically. On success the
 * box clears and `onPosted` refetches the feed.
 *
 * @param props - {@link CommunityComposerProps}
 */
export const CommunityComposer = ({
    channel,
    onPosted,
}: CommunityComposerProps) => {
    const t = useTranslations()
    const [body, setBody] = useState("")
    const runGraphQL = useGraphQLWithToast()
    const { trigger: createPost, isMutating } = useMutateCreateCommunityPostSwr()

    /** Validate, submit, then clear + refetch on success. */
    const onSubmit = useCallback(async () => {
        // ignore empty/whitespace-only bodies
        const trimmed = body.trim()
        if (!trimmed) {
            return
        }
        // create via the toast wrapper so quota/auth errors surface as a toast;
        // the action returns the inner GraphQLResponse the toast wrapper inspects
        const ok = await runGraphQL(
            async () => {
                const result = await createPost({
                    channel,
                    body: trimmed,
                })
                return result.data!.createCommunityPost
            },
            { showSuccessToast: true },
        )
        // only clear + refetch when the create actually succeeded
        if (ok) {
            setBody("")
            onPosted()
        }
    }, [body, channel, createPost, runGraphQL, onPosted])

    return (
        <Card>
            <CardContent>
                <StackV gap={4} principle="label-field"
                    explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                    items={[
                        () => (
                            <TextField variant="secondary">
                                <TextArea
                                    rows={3}
                                    value={body}
                                    onChange={(event) => setBody(event.target.value)}
                                    placeholder={t("community.composerPlaceholder")}
                                    aria-label={t("community.composerPlaceholder")}
                                    className="resize-none"
                                />
                            </TextField>
                        ),
                        () => (
                            <div className="flex justify-end">
                                <Button
                                    variant="primary"
                                    isPending={isMutating}
                                    isDisabled={!body.trim()}
                                    onPress={() => void onSubmit()}
                                >
                                    {t("community.post")}
                                </Button>
                            </div>
                        ),
                    ]} />
            </CardContent>
        </Card>
    )
}

import React from "react"
import type { Key } from "react"
import { ChatCircleIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Button } from "@/components/atoms/buttons/Button"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { PageContainer } from "@/components/blocks/layout/PageContainer"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { TabsCard, type TabsCardItem } from "@/components/blocks/navigation/TabsCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { CommunityComposer } from "./CommunityComposer"
import { CommunityPost } from "@/components/blocks/community/CommunityPost"
import { CommunityChannel } from "@/modules/api/graphql/queries/types/community-feed"
import type { QueryCommunityFeedItemData } from "@/modules/api/graphql/queries/types/community-feed"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"

/** How many placeholder rows the co-located skeleton shows for the feed list. */
const SKELETON_ROW_COUNT = 3

/**
 * One placeholder feed row. `CommunityPost` (and the `CommunityPostCard` it wraps)
 * take a required `post` and carry no `isSkeleton` of their own, so this hand-mirrors
 * the card face right where it sits — author row, body block, reaction footer —
 * instead of pulling in a separate skeleton tree (loading-and-skeleton.md).
 */
const CommunityFeedSkeletonRow = () => (
    <SurfaceCard body={() => (
        <StackV gap={4} principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => (
                    <StackH gap={4} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={[
                            () => <Avatar isSkeleton size="md" />,
                            () => (
                                <StackV gap={3} principle="identity"
                                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                    classNames={["min-w-0", "flex-1"]} items={[
                                        () => <Typography size="sm" isSkeleton />,
                                        () => <Typography size="xs" isSkeleton classNames={["w-3/4"]} />,
                                    ]} />
                            ),
                        ]} />
                ),
                () => <Skeleton className="h-16 w-full rounded-xl" />,
                () => (
                    <StackH gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => <Skeleton className="h-7 w-24 rounded-full" />,
                            () => <Skeleton className="h-7 w-14 rounded-full" />,
                        ]} />
                ),
            ]} />
    )} />
)

/** All display text, already localized by the connected `CommunityFeedPage`; a story passes i18n keys. */
export interface CommunityFeedLabels {
    /** Page title. */
    title: string
    /** Page description under the title. */
    description: string
    /** Label on the "Chat" header action button. */
    chatLabel: string
    /** Accessible name for the channel tab strip. */
    channelTabsAriaLabel: string
    /** Error-branch title (feed failed to load). */
    errorTitle: string
    /** Retry button label, shared by the error branch. */
    retryLabel: string
    /** Empty-branch title when a channel filter has no posts. */
    emptyFilteredTitle: string
    /** Action label that clears the channel filter back to "all". */
    viewAllChannelsLabel: string
    /** Empty-branch title when the whole platform has no posts yet. */
    emptyTitle: string
    /** Action label that sends an empty-feed visitor into the course catalog. */
    browseCoursesLabel: string
    /** "Load more" button label under the feed. */
    loadMoreLabel: string
}

/** Props for {@link _CommunityFeedPage} — presentational; all data resolved, no fetch/store/i18n. */
export interface CommunityFeedPageProps {
    /** First load, nothing in hand → the feed region shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with a resolved page that carries zero posts → the empty branch. */
    isEmpty?: boolean
    /** Truthy → the error branch (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — refetches the feed. Paired with `labels.retryLabel`. */
    onRetry?: () => void
    /** `true` while a channel filter is active — picks which of the two empty messages shows. */
    isFilteredEmpty?: boolean
    /** Channel tab strip, already resolved (i18n'd labels). */
    channelTabs: Array<TabsCardItem>
    /** Currently selected channel tab key ("all" or a {@link CommunityChannel}). */
    selectedChannelKey: string
    /** Fired with the newly selected tab key. */
    onChannelChange: (key: Key) => void
    /** `true` (signed-in) → renders the composer above the feed. */
    showComposer: boolean
    /** Channel the composer posts to (the "all" tab defaults to General). */
    composerChannel: CommunityChannel
    /** Called after a post is created so the feature can refetch the feed. */
    onPosted: () => void
    /** Clears the active channel filter back to "all channels". */
    onViewAllChannels: () => void
    /** Sends a platform-empty visitor into the course catalog. */
    onBrowseCourses: () => void
    /** Opens the community chat route. */
    onChatClick: () => void
    /** The flattened, newest-first feed page. */
    items: Array<QueryCommunityFeedItemData>
    /** Whether the viewer is signed in — gates reactions + the comment composer on each post. */
    authenticated: boolean
    /** React handler forwarded to each post — reacts, then refetches. */
    onReact: (postId: string, type: ReactionType | null) => void
    /** Called when a post's thread changes (new comment) so the feed can refresh. */
    onChanged: () => void
    /** `true` iff the last loaded page still carries a next cursor. */
    hasMore: boolean
    /** `true` while a "load more" page is in flight. */
    isLoadingMore: boolean
    /** Requests the next page. */
    onLoadMore: () => void
    labels: CommunityFeedLabels
}

/**
 * Community feed page (Facebook/Twitter-style) — the presentational half of
 * {@link CommunityFeedPage}, composed on the tier-correct vocabulary (`PageContainer` /
 * `PageHeader` / `TabsCard` / `SurfaceCard`). The header, channel tabs, and composer
 * always render; only the feed region itself runs the fixed order
 * error → loading → empty → content: `error` falls to the shared `AsyncContentError`
 * frame, `isEmpty` to `AsyncContentEmpty` (filtered vs platform-wide), and otherwise
 * the post list renders with `isSkeleton` threaded to every leaf that supports it so
 * the shimmer mirrors the loaded shape (loading-and-skeleton.md). See `tiers/split.md`
 * — the connected `index.tsx` owns the fetch, the channel filter, and i18n.
 *
 * @param props - {@link CommunityFeedPageProps}
 */
export const _CommunityFeedPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    isFilteredEmpty = false,
    channelTabs,
    selectedChannelKey,
    onChannelChange,
    showComposer,
    composerChannel,
    onPosted,
    onViewAllChannels,
    onBrowseCourses,
    onChatClick,
    items,
    authenticated,
    onReact,
    onChanged,
    hasMore,
    isLoadingMore,
    onLoadMore,
    labels,
}: CommunityFeedPageProps) => {
    return (
        <PageContainer>
            <StackV gap={7} principle="layout-split"
                explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                items={[
                    () => (
                        <PageHeader
                            title={labels.title}
                            description={labels.description}
                            actions={(
                                <Button
                                    variant="secondary"
                                    size="sm"
                                    prefixIcon={ChatCircleIcon}
                                    label={labels.chatLabel}
                                    onPress={onChatClick}
                                />
                            )}
                        />
                    ),
                    () => (
                        <StackV gap={6} principle="block-boundary"
                            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                            items={[
                                () => (
                                    <TabsCard
                                        leftTabs={{
                                            items: channelTabs,
                                            selectedKey: selectedChannelKey,
                                            ariaLabel: labels.channelTabsAriaLabel,
                                            onSelectionChange: onChannelChange,
                                        }}
                                    />
                                ),
                                ...(showComposer ? [() => (
                                    <CommunityComposer channel={composerChannel} onPosted={onPosted} />
                                )] : []),
                                () => {
                                    // error beats a stale loading flag; empty only once settled
                                    if (error) {
                                        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retryLabel} />
                                    }
                                    if (!isSkeleton && isEmpty) {
                                        // empty feed is still a conversion surface. Two distinct reasons need
                                        // two distinct empties (§State-matrix): filtered-empty offers a way
                                        // back to "all channels"; platform-empty invites into courses.
                                        return isFilteredEmpty ? (
                                            <AsyncContentEmpty
                                                title={labels.emptyFilteredTitle}
                                                action={() => (
                                                    <Button variant="secondary" size="sm" label={labels.viewAllChannelsLabel} onPress={onViewAllChannels} />
                                                )}
                                            />
                                        ) : (
                                            <AsyncContentEmpty
                                                title={labels.emptyTitle}
                                                action={() => (
                                                    <Button variant="secondary" size="sm" label={labels.browseCoursesLabel} onPress={onBrowseCourses} />
                                                )}
                                            />
                                        )
                                    }

                                    // ROWS — while shimmering, placeholder rows keep the SAME count shape as the
                                    // real list; `CommunityPost` has no `isSkeleton` of its own (missingSkeletonSupport).
                                    const rowItems = isSkeleton
                                        ? Array.from({ length: SKELETON_ROW_COUNT }, () => () => <CommunityFeedSkeletonRow />)
                                        : items.map((post) => () => (
                                            <CommunityPost
                                                post={post}
                                                authenticated={authenticated}
                                                onReact={authenticated ? onReact : undefined}
                                                onChanged={onChanged}
                                            />
                                        ))

                                    return (
                                        <StackV gap={6} principle="block-boundary"
                                            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                            items={[
                                                ...rowItems,
                                                ...(!isSkeleton && hasMore ? [() => (
                                                    <div className="flex justify-center">
                                                        <Button
                                                            variant="secondary"
                                                            size="sm"
                                                            isPending={isLoadingMore}
                                                            label={labels.loadMoreLabel}
                                                            onPress={onLoadMore}
                                                        />
                                                    </div>
                                                )] : []),
                                            ]} />
                                    )
                                },
                            ]} />
                    ),
                ]} />
        </PageContainer>
    )
}

