    /** Already-formatted absolute date, in the viewer's locale. */
    dateLabel: string
    /** Course page to navigate to on press. */
    href: string
}

/** All display text, already localized by the connected `UpcomingLivestreamCard`. */
export interface UpcomingLivestreamCardLabels {
    /** Card header title. */
    title: string
    /** Error-branch title. */
    errorTitle: string
    /** Error-branch retry button label. */
    retry: string
}

/** Props for {@link _UpcomingLivestreamCard} — presentational; all data resolved, no fetch/store/i18n. */
export interface UpcomingLivestreamCardProps {
    /** First load, nothing in hand → the whole row list shimmers in place. Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with nothing upcoming → the card hides itself entirely (no emptyContent — matches the sibling right-rail widgets, e.g. `WhoToFollow`). */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** The soonest few sessions, already sorted, capped, and formatted. */
    sessions?: Array<UpcomingLivestreamCardSession>
    labels: UpcomingLivestreamCardLabels
}

/**
 * Right-rail card surfacing the viewer's next live sessions across enrolled courses
 * (soonest first), so a scheduled stream is visible from the home surface instead of
 * buried in a course page — the presentational half of `UpcomingLivestreamCard`. The
 * soonest session leads with a relative countdown ("in Nd Nh"); a short list of the
 * next few follows. Three states in the fixed order error → loading → empty →
 * content (BLOCK-8): `error` falls to the shared `AsyncContentError` frame, `isEmpty`
 * hides the card (no emptyContent, matching the sibling right-rail widgets that
 * self-hide rather than render an empty state), and otherwise the row list renders —
 * while shimmering, `Skeleton.ListRow` placeholders keep the SAME `SectionCard` +
 * `SurfaceCardList` shape so the box neither shrinks nor jumps when data arrives
 * (loading-and-skeleton.md). See `tiers/split.md` — the connected `index.tsx` owns
 * the fetch and i18n.
 *
 * @param props - {@link UpcomingLivestreamCardProps}
 */
export const _UpcomingLivestreamCard = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    sessions = [],
    labels,
}: UpcomingLivestreamCardProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return null
    }

    const skeletonItems: Array<SurfaceCardListItem> = Array.from(
        { length: MAX_ROWS },
        (_unused, index) => ({
            key: `skeleton-${index}`,
            content: () => (
                <Box
                    principle="row-pad"
                    explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell."
                >
                    <Skeleton.ListRow withSubtitle />
                </Box>
            ),
        }),
    )

    const sessionItems: Array<SurfaceCardListItem> = sessions.map((session) => ({
        key: session.key,
        leading: () => <IconTile icon={<VideoCameraIcon />} tone="accent" size="sm" />,
        title: session.title,
        subtitle: session.subtitle,
        meta: () => (
            <Typography
                size="xs"
                weight="medium"
                color="accent-soft"
                text={`${session.relativeLabel} · ${session.dateLabel}`}
            />
        ),
        href: session.href,
    }))

    return (
        <SectionCard
            icon={() => <VideoCameraIcon className="size-5 text-accent-soft-foreground" />}
            title={labels.title}
        >
            <SurfaceCardList
                variant="nested"
                items={isSkeleton ? skeletonItems : sessionItems}
            />
        </SectionCard>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    pathConfig,
} from "@/resources/path"
import { useQueryMyUpcomingLivestreamsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyUpcomingLivestreamsSwr"
import {
    _UpcomingLivestreamCard,
    MAX_ROWS,
    type UpcomingLivestreamCardSession,
} from "./component"

/**
 * Right-rail card surfacing the viewer's next live sessions across enrolled
 * courses (soonest first) — the CONNECTED half. Self-fetches its own leaf query,
 * resolves the relative countdown + locale date for each row, and hands the
 * result to the presentational `_UpcomingLivestreamCard`. See `tiers/split.md`.
 */
export const UpcomingLivestreamCard = () => {
    const t = useTranslations()
    const locale = useLocale()
    const { data, isLoading, error, mutate } = useQueryMyUpcomingLivestreamsSwr()

    /** The soonest few sessions, sorted defensively by start time. */
    const sessions = useMemo(
        () => {
            return [...(data ?? [])]
                .sort(
                    (a, b) => new Date(a.nextStartAt).getTime()
                        - new Date(b.nextStartAt).getTime(),
                )
                .slice(0, MAX_ROWS)
        },
        [
            data,
        ],
    )

    /**
     * A short relative label until `iso` ("in Nd Nh" / "in Nh Nm" / "now"). Past
     * timestamps collapse to "now" since the list only holds upcoming sessions.
     */
    const relativeLabel = (iso: string) => {
        const remaining = new Date(iso).getTime() - Date.now()
        if (remaining <= 0) {
            return t("DashboardPage.upcomingLive.now")
        }
        const days = Math.floor(remaining / 86_400_000)
        const hours = Math.floor((remaining % 86_400_000) / 3_600_000)
        const minutes = Math.floor((remaining % 3_600_000) / 60_000)
        if (days > 0) {
            return t("DashboardPage.upcomingLive.inDays", {
                days,
                hours,
            })
        }
        if (hours > 0) {
            return t("DashboardPage.upcomingLive.inHours", {
                hours,
                minutes,
            })
        }
        return t("DashboardPage.upcomingLive.inMinutes", {
            minutes,
        })
    }

    /** Sessions resolved into the presentational row shape (relative + absolute labels, course link). */
    const sessionRows: Array<UpcomingLivestreamCardSession> = sessions.map((session) => ({
        key: `${session.courseGlobalId}-${session.nextStartAt}`,
        title: session.sessionTitle ?? session.courseTitle,
        subtitle: session.sessionTitle ? session.courseTitle : undefined,
        relativeLabel: relativeLabel(session.nextStartAt),
        dateLabel: new Date(session.nextStartAt).toLocaleDateString(locale),
        href: pathConfig().locale(locale).course(session.courseDisplayId).build(),
    }))

    return (
        <_UpcomingLivestreamCard
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={data === undefined && isLoading}
            isEmpty={sessions.length === 0}
            // only a settled fetch error (nothing in hand) reaches the block
            error={data === undefined ? error : undefined}
            onRetry={() => { void mutate() }}
            sessions={sessionRows}
            labels={{
                title: t("DashboardPage.upcomingLive.title"),
                errorTitle: t("DashboardPage.loadError"),
                retry: t("DashboardPage.retry"),
            }}
        />
    )
}

