/**
 * "This week's challenge" section — the presentational half of {@link import("./index").WeeklyChallengeCard}:
 * title (routable), a live countdown, the viewer's pass status, total pass count, and a short
 * leaderboard of recent finishers. Owns its own `LabeledCard` frame (label outside), which STAYS
 * MOUNTED across every state — the error and empty messages render INSIDE it instead of the section
 * self-hiding, so the DashboardPage slot never disappears entirely. Three states in the fixed order
 * error → loading → empty → content: `error` falls to the shared `AsyncContentError` frame, `isEmpty`
 * to `AsyncContentEmpty`, and otherwise the real tree renders with `isSkeleton` threaded to every leaf
 * that supports it (loading-and-skeleton.md). `EntityToken`/`UserAvatar`/`SurfaceListCardRow` take no
 * `isSkeleton` of their own, so the leaderboard rows are mirrored with `Skeleton.*` pieces in place
 * while shimmering instead (see `missingSkeletonSupport`). See `tiers/split.md` — the connected
 * `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link WeeklyChallengeCardProps}
 */
export const _WeeklyChallengeCard = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    challengeGlobalId,
    challengeTitle,
    viewerPassed = false,
    claimed = false,
    isClaiming = false,
    onClaim,
    leaderboard = [],
    labels,
}: WeeklyChallengeCardProps) => {
    /** The card's body — error beats a stale loading flag; empty only once settled (BLOCK-8). */
    const body = () => {
        if (error) {
            return (
                <AsyncContentError
                    title={labels.errorTitle}
                    onRetry={onRetry}
                    retryLabel={labels.retry}
                />
            )
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    title={labels.emptyTitle}
                    description={labels.emptyDescription}
                />
            )
        }

        // ROWS — while shimmering, placeholder rows keep the SAME count shape (loading-and-skeleton.md
        // §1). `SurfaceListCardRow` wraps a plain (non-skeleton-aware) `Typography` internally and
        // `UserAvatar` takes no `isSkeleton` either, so the placeholder rows are built from
        // `SurfaceListCardItem` + `Skeleton.*` pieces sized to match the real row instead.
        const showLeaderboard = isSkeleton || leaderboard.length > 0

        // Hoisted so outer sibling-stack is not scanned as owning nested justify.
        const challengeItems = [
            () => (isSkeleton
                ? <Skeleton.Typography type="body-sm" width="2/3" />
                : <EntityToken globalId={challengeGlobalId} label={challengeTitle ?? ""} />),
            () => (
                <StackH gap={3} principle="flex-action"
                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                    justify="between" items={[
                        () => (
                            <Typography
                                size="xs"
                                color="muted"
                                text={labels.endsIn ?? ""}
                                isSkeleton={isSkeleton}
                                classNames={isSkeleton ? ["w-1/3"] : undefined}
                            />
                        ),
                        () => (isSkeleton
                            ? <Skeleton className="h-6 w-16 shrink-0 rounded-full" />
                            : viewerPassed
                                ? (claimed
                                    ? <Chip tone="success" text={labels.passed} />
                                    : (
                                        <Button
                                            variant="primary"
                                            size="sm"
                                            isPending={isClaiming}
                                            onPress={onClaim}
                                            label={labels.claimReward}
                                        />
                                    ))
                                : <EntityToken globalId={challengeGlobalId} label={labels.tryNow} />),
                    ]} />
            ),
            () => (
                <Typography
                    size="xs"
                    color="muted"
                    text={labels.passedCount}
                    isSkeleton={isSkeleton}
                    classNames={isSkeleton ? ["w-1/4"] : undefined}
                />
            ),
            ...(showLeaderboard ? [() => (
                <SurfaceListCard bordered>
                    {isSkeleton
                        ? Array.from({ length: SKELETON_ROW_COUNT }, (_row, index) => (
                            <SurfaceListCardItem key={index}>
                                <StackH gap={3} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => <Skeleton className="size-6 shrink-0 rounded-full" />,
                                        () => <Skeleton.Typography type="body-sm" width="1/2" className="min-w-0 flex-1" />,
                                        () => <Skeleton className="h-3 w-12 shrink-0 rounded-sm" />,
                                    ]} />
                            </SurfaceListCardItem>
                        ))
                        : leaderboard.map((entry) => (
                            <SurfaceListCardRow
                                key={entry.username}
                                leading={() => (
                                    <UserAvatar
                                        className="size-6 shrink-0"
                                        username={entry.username}
                                        avatar={entry.avatar}
                                        seed={entry.username}
                                    />
                                )}
                                title={entry.username}
                                trailing={() => (
                                    <Typography
                                        size="xs"
                                        color="muted"
                                        text={entry.relativeLabel}
                                        classNames={["shrink-0"]}
                                    />
                                )}
                            />
                        ))}
                </SurfaceListCard>
            )] : []),
        ]

        return (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={challengeItems}  />
        )
    }

    return (
        <LabeledCard
            identity={{ tier: "block", component: "WeeklyChallengeCard" }}
            label={labels.title}

        >
            {body()}
        </LabeledCard>
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import { useQueryWeeklyChallengeSwr } from "@/hooks/swr/api/graphql/queries/useQueryWeeklyChallengeSwr"
import { useMutateClaimWeeklyChallengeRewardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateClaimWeeklyChallengeRewardSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { _WeeklyChallengeCard } from "./component"

/** How many leaderboard rows to show before truncating. */
const TOP_ROWS = 5

/** Props for {@link WeeklyChallengeCard}. */
export type WeeklyChallengeCardProps = Record<string, never>
/**
 * "This week's challenge" section — the CONNECTED half: it self-fetches the featured
 * weekly-challenge event, computes the countdown/claim state and every "x ago" label, resolves
 * every display string (incl. interpolation), and hands them to the presentational
 * {@link _WeeklyChallengeCard}. See `design/storybook/architecture/split.md`.
 *
 * @param props - optional className for the root element.
 */
export const WeeklyChallengeCard = () => {
    const t = useTranslations()
    const locale = useLocale()
    const challengeSwr = useQueryWeeklyChallengeSwr()
    const { data } = challengeSwr
    const { trigger: triggerClaimReward } = useMutateClaimWeeklyChallengeRewardSwr()
    const runGraphQL = useGraphQLWithToast()
    const [isClaiming, setIsClaiming] = useState(false)

    /** Claim the weekly-challenge coin reward, then revalidate. */
    const onClaim = async () => {
        setIsClaiming(true)
        try {
            const ok = await runGraphQL(async () => {
                const result = await triggerClaimReward()
                const env = result?.data?.claimWeeklyChallengeReward
                if (!env) {
                    throw new Error(t("weeklyChallenge.claimError"))
                }
                return env
            })
            if (ok) {
                await challengeSwr.mutate()
            }
        } finally {
            setIsClaiming(false)
        }
    }

    /** Days/hours left until the event closes (computed from `weekEndAt`). */
    const countdown = useMemo(
        () => {
            if (!data) {
                return null
            }
            const remaining = Math.max(
                0,
                new Date(data.weekEndAt).getTime() - Date.now(),
            )
            return {
                days: Math.floor(remaining / 86_400_000),
                hours: Math.floor((remaining % 86_400_000) / 3_600_000),
            }
        },
        [
            data,
        ],
    )

    /** Locale-aware relative-time formatter for the "passed N ago" labels. */
    const relativeFormatter = useMemo(
        () => new Intl.RelativeTimeFormat(locale, { numeric: "auto" }),
        [
            locale,
        ],
    )

    /** Render a coarse "x ago" label for an ISO timestamp. */
    const formatRelative = (iso: string) => {
        const diffMs = new Date(iso).getTime() - Date.now()
        const minutes = Math.round(diffMs / 60_000)
        if (Math.abs(minutes) < 60) {
            return relativeFormatter.format(minutes, "minute")
        }
        const hours = Math.round(minutes / 60)
        if (Math.abs(hours) < 24) {
            return relativeFormatter.format(hours, "hour")
        }
        return relativeFormatter.format(Math.round(hours / 24), "day")
    }

    // recent finishers — sliced + localized here, so the presentational half never resolves i18n
    const leaderboard = (data?.leaderboard.slice(0, TOP_ROWS) ?? []).map((entry) => ({
        username: entry.username,
        avatar: entry.avatar,
        relativeLabel: formatRelative(entry.passedAt),
    }))

    return (
        <_WeeklyChallengeCard
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={challengeSwr.isLoading && !data}
            // error beats loading + empty; only a settled fetch error (nothing in hand) reaches the block
            error={!data ? challengeSwr.error : undefined}
            onRetry={() => { void challengeSwr.mutate() }}
            // settled with no active event
            isEmpty={!data}
            challengeGlobalId={data?.challengeGlobalId}
            challengeTitle={data?.title}
            viewerPassed={data?.viewerPassed}
            claimed={data?.claimed}
            isClaiming={isClaiming}
            onClaim={() => { void onClaim() }}
            leaderboard={leaderboard}
            labels={{
                title: t("weeklyChallenge.title"),
                errorTitle: t("weeklyChallenge.errorTitle"),
                retry: t("weeklyChallenge.retry"),
                emptyTitle: t("weeklyChallenge.emptyTitle"),
                emptyDescription: t("weeklyChallenge.emptyDescription"),
                endsIn: countdown ? t("weeklyChallenge.endsIn", {
                    days: countdown.days,
                    hours: countdown.hours,
                }) : undefined,
                passed: t("weeklyChallenge.passed"),
                claimReward: t("weeklyChallenge.claimReward", {
                    count: data?.coinReward ?? 0,
                }),
                tryNow: t("weeklyChallenge.tryNow"),
                passedCount: t("weeklyChallenge.passedCount", {
                    count: data?.passedCount ?? 0,
                }),
            }}
        />
    )
}

