    // avatar-upload modal (dropzone) open-state — shared zustand overlay
    const { open: openAvatarUpload } = useAvatarUploadOverlayState()

    // controlled bindings read straight from the form state (no component useState)
    const displayName = watch("displayName")
    const bio = watch("bio")
    const openToWork = watch("openToWork")
    const roleTitle = watch("roleTitle")
    const location = watch("location")
    const workMode = watch("workMode")
    const linkedinUrl = watch("linkedinUrl")
    const websiteUrl = watch("websiteUrl")

    // signed-out guard
    if (!user) {
        return (
            <div className="py-12">
                <StackV gap={3} principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    align="center" items={[
                        () => (
                            <Typography type="h5" weight="semibold" align="center">
                                {t("profile.signedOut.title")}
                            </Typography>
                        ),
                        () => (
                            <Typography type="body-sm" color="muted" align="center">
                                {t("profile.signedOut.desc")}
                            </Typography>
                        ),
                    ]} />
            </div>
        )
    }

    return (
        <div className="flex flex-col gap-10">
            <PageHeader
                breadcrumb={<SettingsBreadcrumb current={t("profileEdit.title")} />}
                title={t("profileEdit.title")}
                description={t("profileEdit.subtitle")}
            />
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <StackH gap={4} principle="identity"
                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                            items={[
                                () => (
                                    <AvatarUploadButton
                                        avatar={shownAvatar}
                                        displayName={user.displayName ?? user.username}
                                        seed={user.email ?? user.username}
                                        label={t("profileEdit.changeAvatar")}
                                        onPress={openAvatarUpload}
                                    />
                                ),
                                () => (
                                    <StackV gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => (
                                                <Button
                                                    variant="secondary"
                                                    size="sm"
                                                    onPress={openAvatarUpload}
                                                >
                                                    {t("profileEdit.changeAvatar")}
                                                </Button>
                                            ),
                                            () => (
                                                <Typography type="body-xs" color="muted">
                                                    {t("profileEdit.avatarHint")}
                                                </Typography>
                                            ),
                                        ]} />
                                ),
                            ]} />
                    ),
                    () => <AvatarUploadModal onFile={onAvatarFile} />,
                    () => (
                        <TextField variant="secondary">
                            <Label htmlFor="profile-display-name">{t("profileEdit.displayName")}</Label>
                            <Input
                                id="profile-display-name"
                                placeholder={user.username}
                                maxLength={DISPLAY_NAME_MAX}
                                value={displayName}
                                onChange={(event) => setValue("displayName", event.target.value)}
                            />
                        </TextField>
                    ),
                    () => (
                        <TextField variant="secondary">
                            <Label htmlFor="profile-bio">{t("profileEdit.bio")}</Label>
                            <TextArea
                                id="profile-bio"
                                rows={3}
                                placeholder={t("profileEdit.bioPlaceholder")}
                                maxLength={BIO_MAX}
                                value={bio}
                                onChange={(event) => setValue("bio", event.target.value)}
                                className="resize-none"
                            />
                            <Typography slot="description" type="body-xs" color="muted" className="self-end">
                                {`${bio.length}/${BIO_MAX}`}
                            </Typography>
                        </TextField>
                    ),
                    () => (
                        <TextField variant="secondary">
                            <Label htmlFor="profile-role-title">{t("profileEdit.roleTitle")}</Label>
                            <Input
                                id="profile-role-title"
                                placeholder={t("profileEdit.roleTitlePlaceholder")}
                                maxLength={ROLE_TITLE_MAX}
                                value={roleTitle}
                                onChange={(event) => setValue("roleTitle", event.target.value)}
                            />
                        </TextField>
                    ),
                    () => (
                        <TextField variant="secondary">
                            <Label htmlFor="profile-location">{t("profileEdit.location")}</Label>
                            <Input
                                id="profile-location"
                                placeholder={t("profileEdit.locationPlaceholder")}
                                maxLength={LOCATION_MAX}
                                value={location}
                                onChange={(event) => setValue("location", event.target.value)}
                            />
                        </TextField>
                    ),
                    () => (
                        <StackV gap={4} principle="label-field"
                            explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                            items={[
                                () => <Label htmlFor="profile-work-mode">{t("profileEdit.workMode")}</Label>,
                                () => (
                                    <TabsCard
                                        variant="primary"
                                        leftTabs={{
                                            selectedKey: workMode === "" ? WORK_MODE_NONE : workMode,
                                            ariaLabel: t("profileEdit.workMode"),
                                            onSelectionChange: (key) => {
                                                const value = String(key)
                                                setValue("workMode", value === WORK_MODE_NONE ? "" : (value as WorkMode))
                                            },
                                            items: [
                                                { key: WORK_MODE_NONE, label: t("profileEdit.workModeNone") },
                                                ...WORK_MODE_OPTIONS.map((option) => ({
                                                    key: option.value as string,
                                                    label: t(option.labelKey),
                                                })),
                                            ],
                                        }}
                                    />
                                ),
                            ]} />
                    ),
                    () => (
                        <TextField variant="secondary">
                            <Label htmlFor="profile-linkedin">{t("profileEdit.linkedinUrl")}</Label>
                            <Input
                                id="profile-linkedin"
                                type="url"
                                inputMode="url"
                                placeholder={t("profileEdit.linkedinUrlPlaceholder")}
                                maxLength={URL_MAX}
                                value={linkedinUrl}
                                onChange={(event) => setValue("linkedinUrl", event.target.value)}
                            />
                            {errors.linkedinUrl ? (
                                <Typography slot="description" type="body-xs" className="text-danger-soft-foreground">
                                    {t("profileEdit.invalidUrl")}
                                </Typography>
                            ) : null}
                        </TextField>
                    ),
                    () => (
                        <TextField variant="secondary">
                            <Label htmlFor="profile-website">{t("profileEdit.websiteUrl")}</Label>
                            <Input
                                id="profile-website"
                                type="url"
                                inputMode="url"
                                placeholder={t("profileEdit.websiteUrlPlaceholder")}
                                maxLength={URL_MAX}
                                value={websiteUrl}
                                onChange={(event) => setValue("websiteUrl", event.target.value)}
                            />
                            {errors.websiteUrl ? (
                                <Typography slot="description" type="body-xs" className="text-danger-soft-foreground">
                                    {t("profileEdit.invalidUrl")}
                                </Typography>
                            ) : null}
                        </TextField>
                    ),
                    () => (
                        <StackH gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            align="start" justify="between" items={[
                                () => (
                                    <StackV gap={1} items={[
                                        () => <Label htmlFor="profile-open-to-work">{t("profileEdit.openToWork")}</Label>,
                                        () => (
                                            <Typography type="body-xs" color="muted">
                                                {t("profileEdit.openToWorkHint")}
                                            </Typography>
                                        ),
                                    ]} />
                                ),
                                () => (
                                    <Checkbox
                                        id="profile-open-to-work"
                                        className="shrink-0"
                                        isSelected={openToWork}
                                        onChange={(selected) => setValue("openToWork", selected)}
                                        aria-label={t("profileEdit.openToWork")}
                                    >
                                        <Checkbox.Content>
                                            <Checkbox.Control>
                                                <Checkbox.Indicator />
                                            </Checkbox.Control>
                                        </Checkbox.Content>
                                    </Checkbox>
                                ),
                            ]} />
                    ),
                    () => (
                        <Button
                            variant="primary"
                            size="lg"
                            className="h-12 self-end text-base"
                            isDisabled={isSubmitting || !isValid}
                            isPending={isSubmitting}
                            onPress={() => onSubmit()}
                        >
                            {({ isPending }) => (
                                <>
                                    {isPending ? (
                                        <Spinner
                                            color="current"
                                            size="sm"
                                        />
                                    ) : null}
                                    {t("profileEdit.save")}
                                </>
                            )}
                        </Button>
                    ),
                ]} />
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    StackIcon,
    CheckCircleIcon,
} from "@phosphor-icons/react"
import {
    pathConfig,
} from "@/resources/path"
import { useMutateReviewFlashcardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateReviewFlashcardSwr"
import { useQueryMyDueFlashcardsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyDueFlashcardsSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import type { GraphQLResponse } from "@/modules/api/graphql/types"
import type { ReviewFlashcardData } from "@/modules/api/graphql/mutations/types/review-flashcard"
import type { QueryFlashcardNextIntervals } from "@/modules/api/graphql/queries/types/my-due-flashcards"
import { Button } from "@/components/atoms/buttons/Button"
import { Card, CardContent } from "@/components/atoms/display/Card"
import { Divider } from "@/components/atoms/display/Divider"
import { Spinner } from "@/components/atoms/display/Spinner"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** SM-2 grade buttons (value + i18n key + tone), ordered worst → best. */
const GRADES: Array<{
    grade: number
    /** i18n key AND the `nextIntervals` field this grade previews. */
    key: keyof QueryFlashcardNextIntervals
    variant: "danger" | "danger-soft" | "secondary" | "primary"
}> = [
    { grade: 0, key: "again", variant: "danger" },
    { grade: 1, key: "hard", variant: "danger-soft" },
    { grade: 2, key: "good", variant: "secondary" },
    { grade: 3, key: "easy", variant: "primary" },
]

/**
 * The `/review` flashcard-review session (SM-2). Fetches the viewer's due cards,
 * then walks them one at a time: shows the front, a "flip" button reveals the
 * back, and four grade buttons record the recall quality (`reviewFlashcard`) and
 * advance. When the queue is exhausted it shows a "done" state with a link back
 * to the dashboard. Current index + flipped state are local (presentational); the
 * grade mutation is owned here.
 */
export const FlashcardReviewPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { data, isLoading, error, mutate } = useQueryMyDueFlashcardsSwr()
    const { trigger: triggerReview } = useMutateReviewFlashcardSwr()
    const runGraphQL = useGraphQLWithToast()

    // index of the card currently shown
    const [index, setIndex] = useState(0)
    // whether the back of the current card is revealed
    const [flipped, setFlipped] = useState(false)
    // the grade being saved, or null when idle
    const [savingGrade, setSavingGrade] = useState<number | null>(null)

    const cards = data?.cards ?? []
    const current = cards[index]

    /** Grade the current card, then advance to the next one. */
    const onGrade = useCallback(
        async (grade: number) => {
            if (!current) {
                return
            }
            setSavingGrade(grade)
            try {
                const ok = await runGraphQL(
                    async (): Promise<GraphQLResponse<ReviewFlashcardData>> => {
                        const result = await triggerReview({
                            cardId: current.cardId,
                            grade,
                        })
                        const env = result?.data?.reviewFlashcard
                        // surface a non-success envelope as an error so the toast
                        // hook reports failure and we don't advance the queue
                        if (!env?.success) {
                            throw new Error(env?.message)
                        }
                        return env
                    },
                )
                // advance only when the grade was recorded
                if (ok) {
                    setIndex((value) => value + 1)
                    setFlipped(false)
                }
            } finally {
                setSavingGrade(null)
            }
        },
        [
            current,
            triggerReview,
            runGraphQL,
        ],
    )

    // query failed with no cached data → error state with retry (never spin
    // forever: `isLoading` is already false and `data` is undefined here)
    if (error && !data) {
        return (
            <Box identity={{ tier: "page", component: "FlashcardReviewPage" }} principle="center-measure" className="flex min-h-[60vh] items-center justify-center"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            >
                <AsyncContentError
                    title={t("flashcardReview.loadError")}
                    onRetry={() => { void mutate() }}
                    retryLabel={t("common.retry")}
                />
            </Box>
        )
    }

    // still loading the queue → centred spinner
    if (isLoading || !data) {
        return (
            <Box identity={{ tier: "page", component: "FlashcardReviewPage" }} principle="center-measure" className="flex min-h-[60vh] items-center justify-center"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            >
                <Spinner size="lg" />
            </Box>
        )
    }

    // queue exhausted (or empty from the start) → done / empty state
    if (!current) {
        const empty = cards.length === 0
        return (
            <Box identity={{ tier: "page", component: "FlashcardReviewPage" }} principle="center-measure" className="mx-auto min-h-[60vh] w-full max-w-xl p-3"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            >
                <StackV gap={6} principle="block-boundary" align="center" justify="center"
                    explain="Block-to-block spacing — not group-boundary, because these blocks are distinct groups rather than same-kind peers."
                    items={[
                        () => <CheckCircleIcon className="size-12 text-success-soft-foreground" />,
                        () => (
                            <Typography
                                size="lg"
                                weight="semibold"
                                align="center"
                                text={empty
                                    ? t("flashcardReview.empty")
                                    : t("flashcardReview.done")}
                            />
                        ),
                        () => (
                            <Button
                                variant="primary"
                                label={t("flashcardReview.backToDashboard")}
                                onPress={() => router.push(
                                    pathConfig().locale(locale).dashboard().build(),
                                )}
                            />
                        ),
                    ]} />
            </Box>
        )
    }

    return (
        <Box identity={{ tier: "page", component: "FlashcardReviewPage" }} principle="center-measure" className="mx-auto w-full max-w-xl p-3"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
        >
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because these blocks are distinct groups rather than same-kind peers."
                items={[
                // progress header: deck context + position in the queue
                    () => (
                        <StackH gap={4} principle="content-row" justify="between" align="center"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <StackH gap={3} principle="identity" classNames={["min-w-0"]} align="center"
                                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                        items={[
                                            () => <StackIcon className="size-5 shrink-0 text-foreground" />,
                                            () => (
                                                <Typography
                                                    size="sm"
                                                    weight="medium"
                                                    truncate
                                                    text={current.deckTitle}
                                                />
                                            ),
                                        ]} />
                                ),
                                () => (
                                    <Typography
                                        size="sm"
                                        color="muted"
                                        classNames={["shrink-0"]}
                                        text={t("flashcardReview.progress", {
                                            current: index + 1,
                                            total: cards.length,
                                        })}
                                    />
                                ),
                            ]} />
                    ),

                    // the card: front always, back after flip
                    () => (
                        <Card>
                            <Box principle="card-padding" className="p-6 @app-sm:p-7"
                                explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                <CardContent>
                                    <StackV gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={[
                                            () => (
                                                <Typography
                                                    size="lg"
                                                    weight="semibold"
                                                    text={current.front}
                                                />
                                            ),
                                            () => (flipped ? (
                                                <StackV gap={4} principle="sibling-stack"
                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                    items={[
                                                        () => <Divider />,
                                                        () => (
                                                            <Typography size="lg" text={current.back} />
                                                        ),
                                                    ]} />
                                            ) : null),
                                        ]} />
                                </CardContent>
                            </Box>
                        </Card>
                    ),

                    // flip → reveal; revealed → grade buttons
                    () => (flipped ? (
                        <Box principle="sibling-stack" className="grid grid-cols-2 gap-2 @app-sm:grid-cols-4"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups.">
                            {GRADES.map((item) => (
                                <Button
                                    key={item.grade}
                                    variant={item.variant}
                                    isDisabled={savingGrade !== null}
                                    isPending={savingGrade === item.grade}
                                    onPress={() => void onGrade(item.grade)}
                                    label={(
                                        <StackV gap={1} principle="title-subtitle" align="center"
                                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                                            items={[
                                                () => <Typography size="sm" text={t(`flashcardReview.${item.key}`)} />,
                                                () => (
                                                    <Typography
                                                        size="xs"
                                                        color="muted"
                                                        text={t("flashcardReview.intervalDays", {
                                                            days: current.nextIntervals[item.key],
                                                        })}
                                                    />
                                                ),
                                            ]} />
                                    )}
                                />
                            ))}
                        </Box>
                    ) : (
                        <Button
                            variant="primary"
                            label={t("flashcardReview.flip")}
                            onPress={() => setFlipped(true)}
                        />
                    )),
                ]} />
        </Box>
    )
}

import React from "react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { ContinueCard } from "@/components/blocks/cards/ContinueCard"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Resolved resume-card data for {@link _DueReviewHero} — only present when a "Due today"
 * run is in progress. Already-translated text and interpolated numbers; the interpolation
 * itself lives in the connected `DueReviewHero` (`tiers/split.md`).
 */
export interface DueReviewHeroResume {
    /** Card title ("Review in progress"). */
    title: string
    /** Card subtitle, already interpolated ("Card {current}/{total}"). */
    subtitle: string
    /** Current position for the progress meter. */
    value: number
    /** Total cards in the run, for the progress meter. */
    max: number
    /** "Continue" CTA label. */
    ctaLabel: string
    /** Fired when the resume card's CTA is pressed. */
    onPress: () => void
}

/** All display text, already localized by the connected `DueReviewHero`; a story passes i18n keys. */
export interface DueReviewHeroLabels {
    /** Section label above the card ("Due today"). */
    sectionLabel: string
    /** Error-branch title. */
    errorTitle: string
    /** Empty-branch title ("All caught up"). */
    allCaughtTitle: string
    /** Empty-branch description. */
    allCaughtHint: string
    /** Primary stat line, already interpolated with the due count. */
    count: string
    /** Secondary "overdue + new" breakdown line — omitted when the queue isn't a mix of the two. */
    countBreakdown?: string
    /** "Review N cards" button label, already interpolated with the due count. */
    start: string
}

/** Props for {@link _DueReviewHero} — presentational; all data resolved, no fetch/store/i18n. */
export interface DueReviewHeroProps {
    /** First load, nothing in hand → the whole due-today row shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero cards due → the caught-up empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats empty + content). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry?: () => void
    /** `true` while a fresh review session is being created — the start button goes pending. */
    starting?: boolean
    /** Fired when the "Review N cards" button is pressed. */
    onPressStart: () => void
    /** The resumable cross-deck run, when one exists — renders a `ContinueCard` above the due-today card. */
    resume?: DueReviewHeroResume
    /** Every translated string this block renders. */
    labels: DueReviewHeroLabels
}

/**
 * The flashcards home hero — the presentational half of {@link import("./index").DueReviewHero}.
 * Two independent sections stacked `gap-6` (different function, `foundations/gap.md`): an
 * optional resume card for an in-progress cross-deck run, and the "Due today" card, whose
 * body follows the fixed order error → skeleton → empty → content
 * (`loading-and-skeleton.md`), with `isSkeleton` threaded to every leaf so the shimmer
 * mirrors the loaded shape. See `tiers/split.md` — the connected `index.tsx` owns the fetch
 * and i18n.
 *
 * @param props - {@link DueReviewHeroProps}
 */
export const _DueReviewHero = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    starting = false,
    onPressStart,
    resume,
    labels,
}: DueReviewHeroProps) => {
    // error beats a stale loading flag; empty only once settled (loading-and-skeleton.md §1) —
    // both message branches come from the shared `AsyncContent*` frames, never hand-written JSX.
    const dueBody = () => {
        if (error) {
            return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} />
        }
        if (!isSkeleton && isEmpty) {
            return <AsyncContentEmpty title={labels.allCaughtTitle} description={labels.allCaughtHint} />
        }
        return (
            <StackH gap={4} principle="flex-action" justify="between" at="sm" isSkeleton={isSkeleton}
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                items={[
                    () => (
                        <StackV gap={1} isSkeleton={isSkeleton} items={[
                            () => <Typography size="sm" text={labels.count} isSkeleton={isSkeleton} />,
                            // breaks the (possibly confusing) total down into its 2 parts — only when
                            // it's actually a mix, so a pure-overdue or pure-new queue doesn't show a
                            // redundant "X + 0" (dueCount = overdue reviews + today's capped new batch).
                            ...(labels.countBreakdown ? [() => (
                                <Typography size="xs" color="muted" text={labels.countBreakdown ?? ""} isSkeleton={isSkeleton} />
                            )] : []),
                        ]} />
                    ),
                    () => (
                        <Button
                            variant="primary"
                            label={labels.start}
                            isPending={starting}
                            isSkeleton={isSkeleton}
                            onPress={onPressStart}
                        />
                    ),
                ]} />
        )
    }

    return (
        <StackV gap={6} identity={{ tier: "block", component: "DueReviewHero" }} items={[
            ...(resume ? [() => (
                <ContinueCard
                    variant="hero"
                    title={resume.title}
                    subtitle={resume.subtitle}
                    value={resume.value}
                    max={resume.max}
                    ctaLabel={resume.ctaLabel}
                    onPress={resume.onPress}
                />
            )] : []),
            () => <LabeledCard label={labels.sectionLabel}>{dueBody()}</LabeledCard>,
        ]} />
    )
}

"use client"

import React from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { DUE_REVIEW_LIMIT } from "@/modules/utils/flashcards"
import { useStartFlashcardDueReviewSession } from "@/hooks/useStartFlashcardDueReviewSession"
import { queryMyDueFlashcards } from "@/modules/api/graphql/queries/query-my-due-flashcards"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyInProgressFlashcardDueReviewSessionSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyInProgressFlashcardDueReviewSessionSwr"
import { pathConfig } from "@/resources/path"
import { _DueReviewHero } from "./component"

/**
 * The flashcards home hero: the spaced-repetition queue. Shows how many cards are due today
 * across every enrolled course and offers the page's PRIMARY action — starting a review
 * session. When nothing is due it collapses to a caught-up empty state. This is the
 * CONNECTED half — it fetches the due queue (and the resumable cross-deck run) directly from
 * the shared `myDueFlashcards` SWR key, resolves every label, and hands them to the
 * presentational {@link _DueReviewHero}. See `tiers/split.md`.
 *
 * Takes no props: the previous `className` was never used by its one call site
 * (`FlashcardsPage/index.tsx`, `<DueReviewHero />`) and a block hands out no `className` escape
 * hatch once it composes entirely through frames (`ContinueCard`'s own doc makes the same
 * call) — see `apiChanged` in this migration's report.
 */
export const DueReviewHero = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // scope the due queue to THIS course (the count must reflect this course's
    // decks, not every deck system-wide); shared SWR key with {@link DueReview}.
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const displayId = useAppSelector((state) => state.course.displayId)

    const { data, error, mutate } = useSWR(
        ["my-due-flashcards", courseId ?? null, DUE_REVIEW_LIMIT],
        async () => {
            const response = await queryMyDueFlashcards({ request: { courseId, limit: DUE_REVIEW_LIMIT } })
            return response.data?.myDueFlashcards.data ?? null
        },
    )

    // eager resolve-or-start right from the CTA (per the teacher's note, 2026-07-11:
    // "pressing the learn button should show isPending right on that button, reviewing
    // 55 cards is also isPending, and once the session is created it routes into the
    // same page as quick-learn") — the button stays
    // ON this screen, pending, until a real sessionId comes back; no more
    // instant navigation to the bare `?session=due` shim + full-page skeleton.
    const { start: startDueReview, starting } = useStartFlashcardDueReviewSession(courseId)
    const onPressStart = async () => {
        if (!displayId) {
            return
        }
        const cardIds = (data?.cards ?? []).map((dueCard) => dueCard.cardId)
        const sessionId = await startDueReview(cardIds)
        if (sessionId) {
            router.push(pathConfig().locale(locale).course(displayId).learn().flashcards().due(sessionId).build())
        }
    }

    // resumable cross-deck "Due today" run — mirrors QuizSession's own "Zone 0" resume
    // card. Renders like the mock-interview resume card (per the teacher's note, 2026-07-17:
    // "render exactly like Mock Interview"): a progress meter (`value`), NO clock watermark —
    // the `card {current}/{total}` progress carries "in progress".
    const resumeSwr = useQueryMyInProgressFlashcardDueReviewSessionSwr(courseId)
    const resumeData = resumeSwr.data

    const dueCount = data?.dueCount ?? 0
    const dueReviewCount = data?.dueReviewCount ?? 0
    const newCount = data?.newCount ?? 0

    return (
        <_DueReviewHero
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={!data && !error}
            isEmpty={dueCount === 0}
            error={error}
            onRetry={() => { void mutate() }}
            starting={starting}
            onPressStart={() => { void onPressStart() }}
            resume={resumeData && displayId ? {
                title: t("flashcard.due.resumeTitle"),
                subtitle: t("flashcard.due.resumeSubtitle", {
                    current: resumeData.currentIndex + 1,
                    total: resumeData.cardIds.length,
                }),
                value: resumeData.currentIndex + 1,
                max: resumeData.cardIds.length,
                ctaLabel: t("flashcard.due.resumeCta"),
                onPress: () => router.push(
                    pathConfig().locale(locale).course(displayId).learn().flashcards().due(resumeData.sessionId).build(),
                ),
            } : undefined}
            labels={{
                sectionLabel: t("flashcard.due.label"),
                // NOTE: reuses the "no flashcards for this course" copy for the error title —
                // carried over verbatim from the pre-migration code, which had no dedicated
                // `flashcard.due.error` key either; not this migration's call to fix.
                errorTitle: t("flashcard.empty"),
                allCaughtTitle: t("flashcard.due.allCaught"),
                allCaughtHint: t("flashcard.due.allCaughtHint"),
                count: t("flashcard.due.count", { count: dueCount }),
                countBreakdown: dueReviewCount > 0 && newCount > 0
                    ? t("flashcard.due.countBreakdown", { overdue: dueReviewCount, newCapped: newCount })
                    : undefined,
                start: t("flashcard.due.start", { count: dueCount }),
            }}
        />
    )
}

