import React from "react"
import type { ReactNode } from "react"
import { CheckCircleIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Section } from "@/components/composites/layout/Section"
import { MetricCard } from "@/components/composites/stats/MetricCard"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { Container } from "@/components/frames/Container"
import type { SkeletonProps } from "@/components/frames/_slot"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"

/** How many placeholder rows the co-located skeleton shows for the weak-tags list. */
const SKELETON_WEAK_TAG_COUNT = 3

/**
 * One SM-2 grade bucket in the HERO distribution: its data key, i18n label key, and the
 * semantic meter tone (a low-recall grade must READ low; `good`/`easy` both share the
 * success tone). Kept here (not the connected file) because ORDER + TONE is a display
 * decision — only the label/count STRINGS need `t()`, resolved by the connected
 * `FlashcardSessionStats` (`tiers/split.md`).
 */
export const GRADE_ROW_DEFS = [
    { key: "again", labelKey: "flashcard.review.again", color: "danger" },
    { key: "hard", labelKey: "flashcard.review.hard", color: "warning" },
    { key: "good", labelKey: "flashcard.review.good", color: "success" },
    { key: "easy", labelKey: "flashcard.review.easy", color: "success" },
] as const

/** One resolved HERO grade row — label/count-percent already translated by the connected file. */
export interface FlashcardSessionStatsGradeRow {
    /** The SM-2 grade this row reports. */
    key: string
    /** Meter tone — a low-recall grade must read low. */
    color: "accent" | "success" | "warning" | "danger"
    /** Already-translated grade name ("Again", "Hard", …). */
    label: string
    /** Raw count — the meters' shared `max` is {@link FlashcardSessionStatsProps.gradeTotal}. */
    count: number
    /** Already-translated "N (P%)" readout. */
    countPercentLabel: string
}

/** One resolved "most forgotten" tag row. */
export interface FlashcardSessionStatsWeakTag {
    /** The tag text itself (not translated — content, not UI copy). */
    tag: string
    /** Already-translated "forgotten N times" readout. */
    forgotLabel: string
}

/** All display text, already localized by the connected `FlashcardSessionStats`; a story passes i18n keys. */
export interface FlashcardSessionStatsLabels {
    backLabel: string
    headerTitle: string
    headerDescription: string
    errorTitle: string
    retryLabel: string
    emptyTitle: string
    emptyDescription: string
    backToReviewLabel: string
    rollupLabel: string
    metricsLabel: string
    metricTotalLabel: string
    metricDurationLabel: string
    metricNextDueLabel: string
    metricXpLabel: string
    weakTagsHeading: string
    studyHeading: string
}

/** Props for {@link _FlashcardSessionStats} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardSessionStatsProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no honest per-grade breakdown (not found, or a legacy count-only session) → the fallback message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retryLabel` on the error branch. */
    onRetry?: () => void
    /** Returns to the flashcards study overview — the single onward path, never a dead end. */
    onBack: () => void
    /** The 4 SM-2 grade rows, in display order, already localized. */
    gradeRows: ReadonlyArray<FlashcardSessionStatsGradeRow>
    /** Sum of every grade row's count — the meters' shared `max`. */
    gradeTotal: number
    /** Already-formatted "reviewed" metric value. */
    metricTotalValue: string
    /** Already-formatted duration metric value ("45 seconds" / "6 minutes" / "—"). */
    metricDurationValue: string
    /** Already-formatted next-due-date metric value ("—" when nothing scheduled). */
    metricNextDueValue: string
    /** Already-formatted, already-translated XP metric value. */
    metricXpValue: string
    /** Every tag the learner forgot at least once, worst-first, already localized. */
    weakTags: ReadonlyArray<FlashcardSessionStatsWeakTag>
    /** Course id for the RAG study-suggestions child. */
    courseId: string
    /** Course display id — needed to build the study list's deep links. */
    courseDisplayId: string
    /** Weak-tag terms joined into one query string, driving the RAG "study this" list. */
    relatedQuery: string
    labels: FlashcardSessionStatsLabels
}

/**
 * The end-of-session STATS surface for a "Study cards" review run (deck-review or cross-deck
 * due-review) — the presentational half of {@link FlashcardSessionStats}: the completion screen
 * AND the render for revisiting a finished session by URL. A centered column of canonical blocks —
 * HERO = the 4-grade SM-2 distribution (NOT a binary remembered/forgot ring), then session metric
 * tiles, the most-forgotten tags, and a self-hiding RAG "study this" list keyed off those weak tags.
 *
 * Four states in the fixed order error → loading → empty → content (`loading-and-skeleton.md`):
 * `error` falls to the shared `AsyncContentError` frame; a settled `isEmpty` (not found, or a
 * legacy/degraded session with no per-grade data) falls to `AsyncContentEmpty` — never an error;
 * otherwise the ONE real tree renders, with `isSkeleton` threaded to every leaf so the shimmer
 * mirrors the loaded shape and cannot drift. The page header stays outside this switch — it is the
 * route's own chrome, not part of the async region. See `tiers/split.md` — the connected
 * `index.tsx` owns the fetch and every `t()` call.
 *
 * @param props - {@link FlashcardSessionStatsProps}
 */
export const _FlashcardSessionStats = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onBack,
    gradeRows,
    gradeTotal,
    metricTotalValue,
    metricDurationValue,
    metricNextDueValue,
    metricXpValue,
    weakTags,
    courseId,
    courseDisplayId,
    relatedQuery,
    labels,
}: FlashcardSessionStatsProps) => {
    // reached via the "Study cards"/"Review due cards" LIVE session route AND the
    // revisit-by-URL result route — the header is the route's own chrome, unaffected
    // by the stats fetch below, so it renders unconditionally.
    const header = (
        <PageHeader
            breadcrumb={<BackLink label={labels.backLabel} onPress={onBack} />}
            title={labels.headerTitle}
            description={labels.headerDescription}
        />
    )

    let contentNode: ReactNode
    // error beats a stale loading flag; empty only once settled (BLOCK-8) — the empty and
    // error surfaces are the shared `AsyncContent*` frames, not hand-written JSX (loading-and-skeleton.md §6).
    if (error) {
        contentNode = <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retryLabel} />
    } else if (!isSkeleton && isEmpty) {
        contentNode = (
            <AsyncContentEmpty
                icon={CheckCircleIcon}
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                action={() => <Button label={labels.backToReviewLabel} variant="secondary" size="sm" onPress={onBack} />}
            />
        )
    } else {
        // most-forgotten tags — self-hiding: while shimmering, placeholder rows keep the
        // SAME list shape; otherwise only when there is at least one real tag.
        const showWeakTags = isSkeleton || weakTags.length > 0
        const weakTagItems: Array<SurfaceCardListItem> = isSkeleton
            ? Array.from({ length: SKELETON_WEAK_TAG_COUNT }, (_unused, index) => ({
                key: `pending-${index}`,
                title: "Tag",
                leadingIcon: WarningCircleIcon,
                leadingIconColor: "warning" as const,
                trailing: () => <Chip isSkeleton />,
            }))
            : weakTags.map((weak) => ({
                key: weak.tag,
                title: weak.tag,
                leadingIcon: WarningCircleIcon,
                leadingIconColor: "warning" as const,
                trailing: () => <Chip tone="danger" text={weak.forgotLabel} />,
            }))

        // session metric tiles — same 4-cell grid shape while shimmering (MetricCard's own
        // isSkeleton branch has no real value/label to check yet).
        const metricItems: Array<GridItem> = [
            {
                key: "total",
                content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (cellSkeleton
                    ? <MetricCard isSkeleton />
                    : <MetricCard value={metricTotalValue} label={labels.metricTotalLabel} />),
            },
            {
                key: "duration",
                content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (cellSkeleton
                    ? <MetricCard isSkeleton />
                    : <MetricCard value={metricDurationValue} label={labels.metricDurationLabel} />),
            },
            {
                key: "next-due",
                content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (cellSkeleton
                    ? <MetricCard isSkeleton />
                    : <MetricCard value={metricNextDueValue} label={labels.metricNextDueLabel} />),
            },
            {
                key: "xp",
                content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (cellSkeleton
                    ? <MetricCard isSkeleton />
                    : <MetricCard value={metricXpValue} label={labels.metricXpLabel} />),
            },
        ]

        contentNode = (
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                isSkeleton={isSkeleton} items={[
                // HERO — the 4-grade SM-2 distribution (outcome first).
                    () => (
                        <SurfaceCard isSkeleton={isSkeleton} body={() => (
                            <StackV gap={5} principle="group-boundary"
                                explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                isSkeleton={isSkeleton} items={[
                                    () => (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            isSkeleton={isSkeleton} items={gradeRows.map((row) => () => (
                                                <StackH gap={3} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    isSkeleton={isSkeleton} items={[
                                                        () => <Typography size="sm" classNames={["shrink-0"]} isSkeleton={isSkeleton} text={row.label} />,
                                                        () => (
                                                            <FillAvailable
                                                                at="base"
                                                                isSkeleton={isSkeleton}
                                                                body={() => (isSkeleton
                                                                    ? <ProgressMeter isSkeleton color={row.color} />
                                                                    : <ProgressMeter value={row.count} max={gradeTotal} color={row.color} />)}
                                                            />
                                                        ),
                                                        () => <Typography size="sm" color="muted" classNames={["shrink-0"]} isSkeleton={isSkeleton} text={row.countPercentLabel} />,
                                                    ]} />
                                            ))} />
                                    ),
                                    // subtle secondary rollup — never replaces the 4 grades above
                                    () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.rollupLabel} />,
                                ]} />
                        )} />
                    ),

                    // session metric tiles
                    () => (
                    // teacher-hold: flashcards-remain-session-stats-metric-grid-gap4-no-token —
                    // four metric tiles at preserved step 4; no card-grid token.
                        <Section
                            header={{ title: labels.metricsLabel, level: 3 }}
                            isSkeleton={isSkeleton}
                            body={() => <Grid columns={{ base: 2, md: 4 }} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                isSkeleton={isSkeleton} items={metricItems} />}
                        />
                    ),

                    // most-forgotten tags — grouped from grade-0 cards
                    ...(showWeakTags ? [() => (
                        <SurfaceCardList label={labels.weakTagsHeading} isSkeleton={isSkeleton} items={weakTagItems} />
                    )] : []),

                    // PRIMARY payoff — self-hiding RAG "study your weak spot" list, keyed off the
                    // weak tags. RelatedContentList is a real block (self-fetching) — a presentational
                    // component may render a connected child (split.md). Hidden while shimmering (it
                    // fetches its own state).
                    ...(!isSkeleton ? [() => (
                        <RelatedContentList
                            courseId={courseId}
                            courseDisplayId={courseDisplayId}
                            query={relatedQuery}
                            label={labels.studyHeading}
                        />
                    )] : []),

                    // onward path — never a dead end, even with no weak tags
                    ...(!isSkeleton ? [() => (
                        <Button variant="tertiary" label={labels.backToReviewLabel} onPress={onBack} classNames={["self-center"]} />
                    )] : []),
                ]} />
        )
    }

    return (
        <StackV identity={{ tier: "page", component: "FlashcardSessionStats" }} gap={1} padding={{ base: { x: 5, y: 6 }, sm: { x: 6 } }} items={[
            () => (
                <Container size="md" padding={1} body={() => (
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[() => header, () => contentNode]}  />
                )} />
            ),
        ]} />
    )
}

"use client"

import React, { useMemo } from "react"
import { useLocale, useTranslations } from "next-intl"
import {
    _FlashcardSessionStats,
    GRADE_ROW_DEFS,
    type FlashcardSessionStatsGradeRow,
    type FlashcardSessionStatsWeakTag,
} from "./component"
import { useQueryMyFlashcardReviewSessionStatsBySessionIdSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFlashcardReviewSessionStatsBySessionIdSwr"
import { useQueryMyFlashcardReviewSessionBySessionIdSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFlashcardReviewSessionBySessionIdSwr"

/** Props for {@link FlashcardSessionStats}. */
export interface FlashcardSessionStatsProps {
    /** The finished (or in-progress) review session to recap. */
    sessionId: string
    /** Owning course id (uuid) — enrollment-guard header + RAG search scope. */
    courseId: string
    /** Owning course slug — needed to build deep links from the study list. */
    courseDisplayId: string
    /** Returns to the flashcards study overview (the single onward path — no dead end). */
    onBack: () => void
}

/**
 * The end-of-session STATS surface for a "Study cards" review run — the CONNECTED half: fetches
 * the session's stats + its context (which kind of run this was), computes `isSkeleton` from the
 * first-load formula and `isEmpty` from the resolved data, and resolves every label (including
 * per-row interpolation) before handing them to the presentational {@link _FlashcardSessionStats}.
 * See `tiers/split.md`.
 *
 * @param props - {@link FlashcardSessionStatsProps}
 */
export const FlashcardSessionStats = ({
    sessionId,
    courseId,
    courseDisplayId,
    onBack,
}: FlashcardSessionStatsProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const statsSwr = useQueryMyFlashcardReviewSessionStatsBySessionIdSwr(sessionId, courseId)
    const stats = statsSwr.data
    // which kind of run this was (single deck vs cross-deck "Due") + the deck identity when
    // applicable — resolved purely from the sessionId (teacher 2026-07-13: "re-render which review
    // session it was, due or deck"), same query the LIVE session already uses to pick its chrome.
    const sessionContextSwr = useQueryMyFlashcardReviewSessionBySessionIdSwr(sessionId, courseId)
    const sessionContext = sessionContextSwr.data

    // next-due date — short "DD Mon" per locale; "—" when nothing scheduled.
    const dueDateFormatter = useMemo(
        () => new Intl.DateTimeFormat(locale, { day: "2-digit", month: "short" }),
        [locale],
    )

    // seconds → a compact localized duration ("45 seconds" / "6 minutes"); em-dash when unknown.
    const formatDuration = (seconds: number | null): string => {
        if (seconds === null || seconds <= 0) {
            return "—"
        }
        return seconds < 60
            ? t("flashcard.review.stats.durationSeconds", { count: seconds })
            : t("flashcard.review.stats.durationMinutes", { count: Math.round(seconds / 60) })
    }

    // which run this was, folded straight into the TITLE text (not a separate chip — teacher
    // 2026-07-13: "that kind of label, drop the chip") — falls back to the generic caption while
    // resolving/absent (legacy session with no matching row).
    const headerCaption = !sessionContext
        ? t("flashcard.review.stats.headerCaption")
        : sessionContext.kind === "due"
            ? t("flashcard.review.stats.headerCaptionDue")
            : sessionContext.deckTitle
                ? t("flashcard.review.stats.headerCaptionDeck", { deckTitle: sessionContext.deckTitle })
                : t("flashcard.review.stats.headerCaption")

    // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
    const isSkeleton = statsSwr.isLoading && !stats
    // settled with no honest per-grade breakdown: not found/not owned, or a legacy (pre-sessionId)
    // count-only session — a bare, honest fallback with the onward path, never an error.
    const gradeCounts = stats?.gradeCounts
    const gradeTotal = gradeCounts ? gradeCounts.again + gradeCounts.hard + gradeCounts.good + gradeCounts.easy : 0
    const isEmpty = !stats || gradeTotal === 0
    const fallbackCount = stats?.reviewedCount ?? 0

    const gradeRows: Array<FlashcardSessionStatsGradeRow> = GRADE_ROW_DEFS.map((def) => {
        const count = gradeCounts ? gradeCounts[def.key] : 0
        const percent = gradeTotal > 0 ? Math.round((count / gradeTotal) * 100) : 0
        return {
            key: def.key,
            color: def.color,
            label: t(def.labelKey),
            count,
            countPercentLabel: t("flashcard.review.stats.gradeCountPercent", { count, percent }),
        }
    })

    // subtle secondary rollup — never replaces the 4 grades above
    const solid = gradeCounts ? gradeCounts.good + gradeCounts.easy : 0
    const needsWork = gradeCounts ? gradeCounts.again + gradeCounts.hard : 0

    // most-forgotten tags — grouped from grade-0 cards
    const weakTags: Array<FlashcardSessionStatsWeakTag> = (stats?.weakTags ?? []).map((weak) => ({
        tag: weak.tag,
        forgotLabel: t("flashcard.review.stats.forgotCount", { count: weak.forgotCount }),
    }))
    // weak-tag terms drive the RAG "study this" query — the learner types nothing.
    const relatedQuery = (stats?.weakTags ?? []).map((weak) => weak.tag).join(" ")

    return (
        <_FlashcardSessionStats
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            // error beats loading + empty; only a settled fetch error (nothing in hand) reaches the block
            error={!stats ? statsSwr.error : undefined}
            onRetry={() => { void statsSwr.mutate() }}
            onBack={onBack}
            gradeRows={gradeRows}
            gradeTotal={gradeTotal}
            metricTotalValue={String(fallbackCount)}
            metricDurationValue={formatDuration(stats?.durationSeconds ?? null)}
            metricNextDueValue={stats?.nextDueAt ? dueDateFormatter.format(new Date(stats.nextDueAt)) : "—"}
            metricXpValue={t("flashcard.review.stats.xpValue", { count: stats?.xpEarned ?? 0 })}
            weakTags={weakTags}
            courseId={courseId}
            courseDisplayId={courseDisplayId}
            relatedQuery={relatedQuery}
            labels={{
                backLabel: t("flashcard.title"),
                headerTitle: headerCaption,
                headerDescription: t("flashcard.review.stats.heroSubtitle"),
                errorTitle: t("flashcard.review.statsError"),
                retryLabel: t("flashcard.review.stats.retry"),
                emptyTitle: t("flashcard.review.stats.fallbackTitle", { count: fallbackCount }),
                emptyDescription: t("flashcard.review.stats.fallbackNote"),
                backToReviewLabel: t("flashcard.review.stats.backToReview"),
                rollupLabel: t("flashcard.review.stats.rollup", { solid, needsWork }),
                metricsLabel: t("flashcard.review.stats.metricsLabel"),
                metricTotalLabel: t("flashcard.review.stats.metricTotal"),
                metricDurationLabel: t("flashcard.review.stats.metricDuration"),
                metricNextDueLabel: t("flashcard.review.stats.metricNextDue"),
                metricXpLabel: t("flashcard.review.stats.metricXp"),
                weakTagsHeading: t("flashcard.review.stats.weakTagsHeading"),
                studyHeading: t("flashcard.review.stats.studyHeading"),
            }}
        />
    )
}

import React from "react"
import { FlameIcon } from "@phosphor-icons/react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import type { CallerIdentity } from "@/components/frames/_identity"

/** Below this many lifetime reviews, the retention % is noise (e.g. 100% off one
 * review), so the caption is hidden. */
export const RETENTION_MIN_REVIEWS = 5

/** This block's own identity (BLOCK-2/split.md) — handed down to whichever frame stands as the root. */
const IDENTITY: CallerIdentity = { tier: "block", component: "FlashcardStatsStrip" }

/** All display text, already localized by the connected `FlashcardStatsStrip`; a story passes i18n keys. */
export interface FlashcardStatsStripLabels {
    /** Section label above the card. */
    label: string
    /** Error-branch title (the deck-list fetch failed). */
    errorTitle: string
    /** Headline sentence — mastered/total already interpolated, the — · N%" tail already appended. */
    masteredLine: string
    /** Streak chip label, already interpolated with the day count. Only shown once `streak > 0`. */
    streakChip: string
    /** Accessible summary of the maturity bar, already interpolated. */
    barAria: string
    /** Maturity-bar segment label — cards fully mastered. */
    mastered: string
    /** Maturity-bar segment label — cards seen but not yet mastered. */
    learning: string
    /** Maturity-bar segment label — cards never reviewed. */
    new: string
    /** Retention caption, already interpolated with the percent. Shown once `totalReviewed` clears the floor. */
    retentionCaption: string
    /** Nudge shown instead of the retention caption before the learner's first review. */
    firstReviewHint: string
}

/** Props for {@link _FlashcardStatsStrip} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardStatsStripProps {
    /** First load, nothing in hand → the whole strip shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero cards in the course at all → the section renders nothing (matches the legacy
     * `AsyncContent` call, which passed no `emptyContent` for this branch). */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled deck-list fetch error. */
    error?: unknown
    /** Retry handler for the error branch — the connected file re-fetches the deck list. */
    onRetry?: () => void
    /** Cards fully mastered across the course's decks. */
    mastered?: number
    /** Total cards across the course's decks. */
    total?: number
    /** Cards seen but not yet mastered. */
    learning?: number
    /** Cards never reviewed. */
    newCount?: number
    /** Current daily-study streak, in days. */
    streak?: number
    /** Lifetime review count — decides which caption (if any) shows. */
    totalReviewed?: number
    labels: FlashcardStatsStripLabels
}

/**
 * The flashcards home progress block — mastery-first. Leads with how much of the
 * course's deck set the viewer has MASTERED (the quantity that actually grows):
 * a maturity bar (mastered · learning · new) over the total card count, with the
 * review streak as a momentum chip and retention as a quiet caption.
 *
 * The presentational half of {@link import("./index").FlashcardStatsStrip}. Two
 * states in the fixed order error → skeleton/content (BLOCK-8): `error` falls to
 * the shared `AsyncContentError` frame; a settled empty course renders nothing
 * (no message ever existed for it); otherwise the ONE real tree renders, with
 * `isSkeleton` threaded to every leaf so the shimmer mirrors the loaded shape
 * (loading-and-skeleton.md). `SegmentBar` carries no `isSkeleton` of its own, so
 * its slot swaps to a co-located `Skeleton.SegmentBar` mirror while shimmering.
 * See `tiers/split.md` — the connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link FlashcardStatsStripProps}
 */
export const _FlashcardStatsStrip = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    mastered = 0,
    total = 0,
    learning = 0,
    newCount = 0,
    streak = 0,
    totalReviewed = 0,
    labels,
}: FlashcardStatsStripProps) => {
    // error beats a stale loading flag; empty only once settled
    if (error) {
        return <AsyncContentError identity={IDENTITY} title={labels.errorTitle} onRetry={onRetry} />
    }
    if (!isSkeleton && isEmpty) {
        return null
    }

    // caption: retention once it's meaningful, else a first-review nudge, else nothing. With the
    // isSkeleton defaults above (totalReviewed=0, mastered=0) this resolves to the nudge, matching
    // the loaded first-visit shape so the shimmer mirrors it (loading-and-skeleton.md §3).
    const showRetention = totalReviewed >= RETENTION_MIN_REVIEWS
    const showFirstReviewHint = !showRetention && mastered === 0

    return (
        <LabeledCard identity={IDENTITY} label={labels.label}>
            <StackV gap={3} principle="sibling-stack" isSkeleton={isSkeleton}
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={[
                    () => (
                        <StackH gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            justify="between" isSkeleton={isSkeleton} items={[
                                () => (
                                    <Typography
                                        size="sm"
                                        isSkeleton={isSkeleton}
                                        truncate
                                        classNames={["min-w-0"]}
                                        text={labels.masteredLine}
                                    />
                                ),
                                ...(streak > 0 ? [() => (
                                    <Chip
                                        isSkeleton={isSkeleton}
                                        tone="warning"
                                        icon={FlameIcon}
                                        text={labels.streakChip}
                                        classNames={["shrink-0"]}
                                    />
                                )] : []),
                            ]} />
                    ),
                    // maturity bar: mastered · learning · new, filling toward total. No `isSkeleton` of its
                    // own, so the mirror sits right here (co-located), not in a parallel tree.
                    () => (isSkeleton
                        ? <Skeleton.SegmentBar />
                        : (
                            <SegmentBar
                                max={total}
                                ariaLabel={labels.barAria}
                                segments={[
                                    { key: "mastered", label: labels.mastered, value: mastered, color: "var(--success)" },
                                    { key: "learning", label: labels.learning, value: learning, color: "var(--warning)" },
                                    // light track tone (same as a ProgressBar's empty track) — "untouched",
                                    // NOT a heavy grey slice
                                    { key: "new", label: labels.new, value: newCount, color: "var(--default)" },
                                ]}
                            />
                        )),
                    // retention only once it's meaningful; else a first-review nudge
                    ...(showRetention || showFirstReviewHint ? [() => (
                        <Typography
                            size="xs"
                            color="muted"
                            isSkeleton={isSkeleton}
                            text={showRetention ? labels.retentionCaption : labels.firstReviewHint}
                        />
                    )] : []),
                ]} />
        </LabeledCard>
    )
}

"use client"

import React from "react"
import useSWR from "swr"
import { useTranslations } from "next-intl"
import { DUE_REVIEW_LIMIT } from "@/modules/utils/flashcards"
import { queryFlashcardDecksByCourse } from "@/modules/api/graphql/queries/query-flashcard-decks-by-course"
import { queryMyDueFlashcards } from "@/modules/api/graphql/queries/query-my-due-flashcards"
import { queryMyFlashcardStats } from "@/modules/api/graphql/queries/query-my-flashcard-stats"
import { useAppSelector } from "@/redux/hooks"
import { _FlashcardStatsStrip } from "./component"

/** Connected flashcards home progress block — no public props. */
export const FlashcardStatsStrip = () => {
    const t = useTranslations()
    // scope mastery + new-backlog to THIS course (shared keys with the siblings)
    const courseId = useAppSelector((state) => state.course.entity?.id)

    // streak / retention / lifetime reviews
    const stats = useSWR(["my-flashcard-stats"], async () => {
        const response = await queryMyFlashcardStats({})
        return response.data?.myFlashcardStats.data ?? null
    })
    // decks → mastered + total cards (same key as FlashcardDeckList → cache shared)
    const decks = useSWR(
        courseId ? ["flashcard-decks-by-course", courseId] : null,
        async () => {
            const response = await queryFlashcardDecksByCourse({
                request: { courseId: courseId as string },
            })
            return response.data?.flashcardDecksByCourse.data ?? null
        },
    )
    // new (never-reviewed) backlog (same key as DueReviewHero → cache shared)
    const due = useSWR(
        ["my-due-flashcards", courseId ?? null, DUE_REVIEW_LIMIT],
        async () => {
            const response = await queryMyDueFlashcards({
                request: { courseId, limit: DUE_REVIEW_LIMIT },
            })
            return response.data?.myDueFlashcards.data ?? null
        },
    )

    // mastery split across the course's decks (all derived from existing data)
    const deckList = decks.data ?? []
    const total = deckList.reduce((sum, deck) => sum + (deck.cards?.length ?? 0), 0)
    const mastered = deckList.reduce((sum, deck) => sum + (deck.masteredCount ?? 0), 0)
    const newCount = Math.min(due.data?.newTotalCount ?? 0, total)
    const learning = Math.max(0, total - mastered - newCount)

    const streak = stats.data?.currentStreak ?? 0
    const retention = stats.data?.retentionRate ?? 0
    const totalReviewed = stats.data?.totalReviewed ?? 0
    const percent = total > 0 ? Math.round((mastered / total) * 100) : 0

    // still hydrating when no facet has resolved yet
    const isSkeleton =
        (stats.isLoading || decks.isLoading || due.isLoading) &&
        !stats.data && !decks.data && !due.data

    return (
        <_FlashcardStatsStrip
            isSkeleton={isSkeleton}
            // nothing to show only when the course has no cards at all
            isEmpty={total === 0}
            // only the deck-list fetch is watched here (unchanged from the legacy call)
            error={decks.error}
            onRetry={() => { void decks.mutate() }}
            mastered={mastered}
            total={total}
            learning={learning}
            newCount={newCount}
            streak={streak}
            totalReviewed={totalReviewed}
            labels={{
                label: t("flashcard.stats.label"),
                errorTitle: t("flashcard.empty"),
                masteredLine: `${t("flashcard.stats.masteredLine", { mastered, total })} · ${percent}%`,
                streakChip: t("flashcard.stats.streakChip", { count: streak }),
                barAria: t("flashcard.stats.barAria", { mastered, learning, newCount, total }),
                mastered: t("flashcard.stats.mastered"),
                learning: t("flashcard.stats.learning"),
                new: t("flashcard.stats.new"),
                retentionCaption: t("flashcard.stats.retentionCaption", { percent: retention }),
                firstReviewHint: t("flashcard.stats.firstReviewHint"),
            }}
        />
    )
}

import { InputSearch } from "@/components/atoms/forms"
import React from "react"
import { ListBox, ScrollShadow } from "@heroui/react"
import { CardsThreeIcon, MicrophoneStageIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"

import { StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { Box } from "@/components/frames/Box"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Placeholder row count the deck list shows while the first load is in flight. */
const SKELETON_ROW_COUNT = 5

/** Study mode vs quiz mode — the top mode switch. */
export type FlashcardStudyRailMode = "study" | "quiz"

/** One deck row, already resolved (sorted + search-filtered) by the connected `FlashcardStudyRail`. */
export interface FlashcardStudyRailDeck {
    id: string
    title: string
    dueCount?: number
}

/** All display text, already localized by the connected `FlashcardStudyRail`; a story passes i18n keys. */
export interface FlashcardStudyRailLabels {
    /** Accessible name for the mode-switch tab list. */
    modeAria: string
    modeStudy: string
    modeQuiz: string
    /** Visible caption above the deck search box, and the deck list's accessible name. */
    decksLabel: string
    /** Accessible name for the search box (falls back to the placeholder, matching the pre-split behaviour). */
    searchAria: string
    searchPlaceholder: string
    /** Empty-state title — the connected file already picks between the generic and the "no match for <query>" phrasing. */
    emptyTitle: string
    errorTitle: string
}

/** Props for {@link _FlashcardStudyRail} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardStudyRailProps extends WithClassNames<undefined> {
    /** First load, nothing in hand → the deck list shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no deck to show (search narrowed the list to nothing, or the course has none). */
    isEmpty?: boolean
    /** Truthy → the error message (beats a stale loading flag). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler for the error branch — the connected file's SWR `mutate`. */
    onRetry?: () => void
    mode: FlashcardStudyRailMode
    onModeChange: (mode: FlashcardStudyRailMode) => void
    /** Deck-search box value — study mode only. */
    query: string
    onQueryChange: (query: string) => void
    /** The deck highlighted in the rail (none during the cross-deck due session). */
    activeDeckId: string | null
    /** Already sorted + search-filtered decks. */
    decks: Array<FlashcardStudyRailDeck>
    onSelectDeck: (deckId: string) => void
    labels: FlashcardStudyRailLabels
}

/**
 * The flashcards LEFT RAIL — the same docs-style sidebar as the content-map rail
 * (pinned header + scroll region, full rail height). A mode switch (Study / Quiz)
 * + the course's decks as a searchable nav list; all selection drives the URL
 * (owned by the connected file), so the rail (layout) and the work pane (page)
 * share one source of truth. Presentational half of {@link FlashcardStudyRail}
 * (`tiers/split.md`): the deck list threads `isSkeleton` to every leaf so the
 * shimmer mirrors the loaded shape (loading-and-skeleton.md) instead of a
 * separate hand-kept skeleton tree — `error` beats a stale loading flag,
 * `isEmpty` is only read once settled.
 *
 * The deck list still composes HeroUI's `ListBox`/`ScrollShadow` directly: no
 * design-system atom wraps a selectable nav list or a shadowed scroll region
 * yet (the same gap the sibling `PracticeRail`/`ArchitectureRail` rails carry),
 * so this is a genuine vocabulary gap rather than a shape to invent here.
 *
 * @param props - {@link FlashcardStudyRailProps}
 */
export const _FlashcardStudyRail = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    mode,
    onModeChange,
    query,
    onQueryChange,
    activeDeckId,
    decks,
    onSelectDeck,
    labels,
    className,
}: FlashcardStudyRailProps) => {
    // placeholder rows while shimmering keep the SAME ListBox + row shape as the real decks —
    // only the leaves (Typography/Chip) switch to their own shimmer (loading-and-skeleton.md).
    const rows: Array<FlashcardStudyRailDeck> = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({ id: `skeleton-${index}`, title: "" }))
        : decks

    /** error → skeleton/content → empty, in priority order (loading-and-skeleton.md). */
    const renderDeckRegion = () => {
        if (error) {
            return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} />
        }
        if (!isSkeleton && isEmpty) {
            return <AsyncContentEmpty title={labels.emptyTitle} />
        }
        return (
            <ListBox
                aria-label={labels.decksLabel}
                selectionMode="single"
                selectedKeys={activeDeckId ? [activeDeckId] : []}
                onSelectionChange={(keys) => {
                    // rows are placeholders while shimmering — nothing real to select onto
                    if (isSkeleton) return
                    const key = [...keys][0]
                    if (typeof key === "string") {
                        onSelectDeck(key)
                    }
                }}
                className="p-0"
            >
                {rows.map((deck) => (
                    <ListBox.Item
                        key={deck.id}
                        id={deck.id}
                        textValue={deck.title}
                        className="cursor-pointer rounded-2xl data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft"
                    >
                        <Box principle="control-pad" className="px-3 py-2"
                            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                            <Cluster gap={3} principle="value-row"
                                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                justify="between" align="center" classNames={["w-full", "min-w-0"]} items={[
                                    () => (
                                        <Typography
                                            size="sm"
                                            truncate
                                            isSkeleton={isSkeleton}
                                            classNames={["min-w-0", "flex-1"]}
                                            text={deck.title}
                                        />
                                    ),
                                    () => (isSkeleton || deck.dueCount ? (
                                        <Chip
                                            isSkeleton={isSkeleton}
                                            tone="warning"
                                            text={deck.dueCount}
                                            classNames={["shrink-0"]}
                                        />
                                    ) : null),
                                ]} />
                        </Box>
                    </ListBox.Item>
                ))}
            </ListBox>
        )
    }

    return (
        <Box
            identity={{ tier: "block", component: "FlashcardStudyRail" }}
            principle="page-pad"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
            className={`relative flex min-h-0 min-w-0 flex-col p-6${className ? ` ${className}` : ""}`}
        >
            <StackV gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                classNames={["min-h-0", "min-w-0", "flex-1"]} items={[
                    () => (
                        <StackV gap={4} items={[
                            () => (
                                <TabsCard
                                    variant="primary"
                                    leftTabs={{
                                        selectedKey: mode,
                                        ariaLabel: labels.modeAria,
                                        onSelectionChange: (key) => {
                                            if (key === "study" || key === "quiz") {
                                                onModeChange(key)
                                            }
                                        },
                                        items: [
                                            {
                                                key: "study",
                                                icon: <CardsThreeIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                                label: labels.modeStudy,
                                            },
                                            {
                                                key: "quiz",
                                                icon: <MicrophoneStageIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                                label: labels.modeQuiz,
                                            },
                                        ],
                                    }}
                                />
                            ),
                            ...(mode === "study" ? [() => (
                                <InputSearch
                                    label={labels.decksLabel}
                                    ariaLabel={labels.searchAria}
                                    placeholder={labels.searchPlaceholder}
                                    value={query}
                                    onValueChange={onQueryChange}
                                />
                            )] : []),
                        ]} />
                    ),
                    ...(mode === "study" ? [() => (
                        <ScrollShadow hideScrollBar className="min-h-0 min-w-0 flex-1 overflow-y-auto">
                            {renderDeckRegion()}
                        </ScrollShadow>
                    )] : []),
                ]} />
        </Box>
    )
}

"use client"

import React, { useMemo, useState } from "react"
import useSWR from "swr"
import { useTranslations } from "next-intl"
import { useFlashcardNav } from "@/hooks/useFlashcardNav"
import { queryFlashcardDecksByCourse } from "@/modules/api/graphql/queries/query-flashcard-decks-by-course"
import { useAppSelector } from "@/redux/hooks"
import { _FlashcardStudyRail } from "./component"
import type { FlashcardStudyRailDeck } from "./component"
import type { FlashcardDeckEntity } from "@/modules/types/entities/flashcard-deck"

/** Props for {@link FlashcardStudyRail}. */
export type FlashcardStudyRailProps = Record<string, never>
/**
 * The flashcards LEFT RAIL — CONNECTED half of {@link _FlashcardStudyRail}
 * (`tiers/split.md`): fetches the course's decks, owns the mode/deck/search
 * URL state (via `useFlashcardNav`), computes `isSkeleton` from the first-load
 * formula and `isEmpty` from the resolved (sorted + filtered) decks, and
 * resolves every label — handing all of it down as already-resolved props.
 * Reads the owning course id from the store; shares the deck SWR key with the
 * page.
 *
 * @param props - {@link FlashcardStudyRailProps}
 */
export const FlashcardStudyRail = () => {
    const t = useTranslations()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const { mode, deckId, session, goMode, goDeck } = useFlashcardNav()
    const [query, setQuery] = useState("")

    // the deck highlighted in the rail = the open deck (none during the due session)
    const activeDeckId = session === "due" ? null : deckId

    const { data, isLoading, error, mutate } = useSWR(
        courseId ? ["flashcard-decks-by-course", courseId] : null,
        async () => {
            const response = await queryFlashcardDecksByCourse({
                request: { courseId: courseId as string },
            })
            return response.data?.flashcardDecksByCourse.data ?? null
        },
    )

    const decks = useMemo<Array<FlashcardDeckEntity>>(() => {
        const sorted = [...(data ?? [])].sort((prev, next) => prev.sortIndex - next.sortIndex)
        const normalized = query.trim().toLowerCase()
        if (!normalized) {
            return sorted
        }
        return sorted.filter((deck) =>
            `${deck.title ?? ""} ${deck.description ?? ""}`.toLowerCase().includes(normalized),
        )
    }, [data, query])

    // first load, nothing in hand → shimmer (loading-and-skeleton.md) — same condition the
    // pre-split `AsyncContent.isLoading` used.
    const isSkeleton = (isLoading || !courseId) && (data ?? []).length === 0
    // settled (after loading + search) with nothing to show
    const isEmpty = decks.length === 0
    // settled fetch error with nothing cached to fall back to
    const settledError = (data ?? []).length === 0 ? error : undefined

    const rows: Array<FlashcardStudyRailDeck> = decks.map((deck) => ({
        id: deck.id,
        title: deck.title,
        dueCount: deck.dueCount,
    }))

    return (
        <_FlashcardStudyRail
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            error={settledError}
            onRetry={() => { void mutate() }}
            mode={mode}
            onModeChange={goMode}
            query={query}
            onQueryChange={setQuery}
            activeDeckId={activeDeckId}
            decks={rows}
            onSelectDeck={goDeck}
            labels={{
                modeAria: t("flashcard.title"),
                modeStudy: t("flashcard.mode.study"),
                modeQuiz: t("flashcard.mode.quiz"),
                decksLabel: t("flashcard.decksLabel"),
                searchAria: t("flashcard.searchPlaceholder"),
                searchPlaceholder: t("flashcard.searchPlaceholder"),
                emptyTitle: query.trim()
                    ? t("flashcard.searchEmpty", { query: query.trim() })
                    : t("flashcard.empty"),
                errorTitle: t("flashcard.empty"),
            }}
        />
    )
}

"use client"

import React, { useMemo, useState } from "react"
import { Badge, Button, Card, CardContent, Chip, Popover, Typography, cn } from "@heroui/react"
import { CaretDownIcon, ClockCounterClockwiseIcon, FunnelIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Button as PrimitiveButton } from "@/components/atoms/buttons/Button"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackH, StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"
import { groupByTimeBucket, type TimeBucketKey } from "@/modules/utils/history-buckets"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** How many placeholder rows the co-located skeleton shows while shimmering. */
const SKELETON_ROW_COUNT = 4

/** Score (correctCount/cardCount) → color. */
const scoreColorOf = (ratio: number): "success" | "warning" | "danger" =>
    ratio >= 0.8 ? "success" : ratio >= 0.6 ? "warning" : "danger"

/** Chip color domain for a run's level badge — mirrors `LEVEL_COLOR` plus its "no level" fallback. */
export type FlashcardQuizHistoryLevelColor = "success" | "warning" | "danger" | "accent" | "default"

/** One weak tag on a resolved row — already localized, with its deep-link `href` resolved. */
export interface FlashcardQuizHistoryWeakTag {
    /** The tag/topic label (raw — also matched against the search box). */
    tag: string
    /** Already-translated "NN% coverage" text. */
    coverageLabel: string
    /** Deep link into the module/content the tag maps to, or the generic module fallback. */
    href: string
}

/** One completed quiz run, fully resolved for render: text translated, filter fields kept raw. */
export interface FlashcardQuizHistoryRow {
    /** Session id — React key + expand-toggle identity. */
    id: string
    /** ISO timestamp — feeds {@link groupByTimeBucket} (not itself rendered). */
    updatedAt: string
    /** The learner's own session name, or its time-based fallback (`sessionDisplayName`). */
    displayName: string
    /** Raw quiz mode ("deep" | "quick" | …) — filtered against, not rendered directly. */
    mode: string
    /** Already-translated "mode · N cards" subtitle line. */
    subtitle: string
    /** Raw difficulty level, or `null` — filtered against, not rendered directly. */
    level: string | null
    /** Already-translated level chip text; omitted when `level` is `null`. */
    levelLabel?: string
    /** Level chip color (`LEVEL_COLOR` lookup, `"default"` when no level). */
    levelColor: FlashcardQuizHistoryLevelColor
    /** Already-translated "NN% coverage" chip text; omitted when the session has no coverage. */
    coverageLabel?: string
    /** Already-translated "+N XP" chip text; omitted when no XP was earned. */
    xpLabel?: string
    /** Cards answered fully correct. */
    correctCount: number
    /** Cards drawn for this session. */
    cardCount: number
    /** Weakest tags this session, ranked worst-first. */
    weakTags: Array<FlashcardQuizHistoryWeakTag>
}

/** All display text, already localized by the connected `FlashcardQuizHistory`; a story passes i18n keys. */
export interface FlashcardQuizHistoryLabels {
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
    emptyAction: string
    searchPlaceholder: string
    filterButtonAria: string
    modeHeading: string
    modeFilterAria: string
    levelHeading: string
    levelFilterAria: string
    filterAll: string
    clearFilters: string
    filterEmptyMessage: string
    weakTagsEmpty: string
    loadMore: string
}

/** Props for {@link _FlashcardQuizHistory} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardQuizHistoryProps extends WithClassNames<undefined> {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero runs → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Jumps the setup tab strip back to "Start" — the empty state's action, when the caller wired one. */
    onStartQuiz?: () => void
    /** Every run loaded so far (all pages accumulated), fully resolved. */
    rows: Array<FlashcardQuizHistoryRow>
    /** Total runs matching the query (for the "load more" affordance). */
    totalCount: number
    /** `rows.length < totalCount` — whether another page is available. */
    hasMore: boolean
    /** True while a page fetch (initial or "load more") is in flight — disables the load-more button. */
    isLoadingMore?: boolean
    /** Fired when "load more" is pressed. */
    onLoadMore: () => void
    /** Fired with a weak tag's resolved `href` when its row is pressed. */
    onTagPress: (href: string) => void
    /** Raw mode value → already-translated label, for the mode facet's options. */
    modeLabelOf: Record<string, string>
    /** Raw level value → already-translated label, for the level facet's options. */
    levelLabelOf: Record<string, string>
    /** Time-bucket key → already-translated label (all six buckets, translated once). */
    timeBucketLabelOf: Record<TimeBucketKey, string>
    /** Formats a run count into its already-translated "N runs" sentence — the count itself is a presentational (filtered) aggregate, so the string can't be pre-baked per row. */
    formatRunCount: (count: number) => string
    labels: FlashcardQuizHistoryLabels
}

/**
 * "Quick Quiz" run history — the presentational half of {@link FlashcardQuizHistory}, composed on
 * `SurfaceCardList`/`SearchInput`/`FlexWrapButtonRadio`. Four states in the fixed order
 * error → loading → empty → content: `error` falls to the shared `AsyncContentError` frame, `isEmpty`
 * to `AsyncContentEmpty` (wrapped in the same bounded `Card` shape as the populated list, per
 * `components/card.md` "frameless-section-empty-state-needs-card"), and otherwise the toolbar + row
 * tree renders with `isSkeleton` threaded so the shimmer mirrors the loaded shape
 * (loading-and-skeleton.md). Time buckets collapse into `SurfaceCardList` (label / labelEnd /
 * subtleLabel) with free-form data `items` — no parallel skeleton tree. Expandable rows keep
 * nested weak-tag buttons inside `content` (no item-level `onPress`, which would wrap the row in
 * a button). None of `SearchInput`/`Popover`/`FlexWrapButtonRadio` carry their own `isSkeleton`,
 * so the toolbar's shimmer is a co-located `Skeleton.*` swap at the same leaf position. Client-side
 * search/facet filtering, row expansion, and the funnel popover are pure UI state owned here. See
 * `tiers/split.md` — the connected `index.tsx` owns the fetch, i18n, and navigation.
 *
 * @param props - {@link FlashcardQuizHistoryProps}
 */
export const _FlashcardQuizHistory = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onStartQuiz,
    rows,
    totalCount,
    hasMore,
    isLoadingMore = false,
    onLoadMore,
    onTagPress,
    modeLabelOf,
    levelLabelOf,
    timeBucketLabelOf,
    formatRunCount,
    labels,
    className,
}: FlashcardQuizHistoryProps) => {
    const [expandedId, setExpandedId] = useState<string | null>(null)
    // client-side filters over already-fetched `rows` — "all" sentinel instead of `null`
    // since `FlexWrapButtonRadio<T>` requires a non-nullable string value.
    const [modeFilter, setModeFilter] = useState<"all" | string>("all")
    const [levelFilter, setLevelFilter] = useState<"all" | string>("all")
    // free-text search over each run's WEAK TAGS (the only searchable text a run carries).
    const [search, setSearch] = useState("")
    const [filterOpen, setFilterOpen] = useState(false)

    const presentModes = useMemo(() => Array.from(new Set(rows.map((row) => row.mode))), [rows])
    const presentLevels = useMemo(
        () => Array.from(new Set(rows.flatMap((row) => (row.level ? [row.level] : [])))),
        [rows],
    )
    const filteredRows = useMemo(() => {
        const needle = search.trim().toLowerCase()
        return rows.filter((row) =>
            (modeFilter === "all" || row.mode === modeFilter)
            && (levelFilter === "all" || row.level === levelFilter)
            && (!needle || row.weakTags.some((tag) => tag.tag.toLowerCase().includes(needle))),
        )
    }, [rows, modeFilter, levelFilter, search])

    // group the filtered runs by time window — quiz sessions have no deck, so time
    // is the meaningful grouping axis. Buckets come already ordered/non-empty.
    const timeBuckets = useMemo(
        () => groupByTimeBucket(filteredRows, (row) => row.updatedAt),
        [filteredRows],
    )

    const hasModeFacet = presentModes.length > 1
    const hasLevelFacet = presentLevels.length > 1
    const hasFacets = hasModeFacet || hasLevelFacet
    const activeFacetCount = (modeFilter !== "all" ? 1 : 0) + (levelFilter !== "all" ? 1 : 0)
    const clearFacets = () => {
        setModeFilter("all")
        setLevelFilter("all")
    }
    const shownCount = search.trim() || activeFacetCount > 0 ? filteredRows.length : totalCount

    /** One run row body — press toggles its weak-tag panel. Nested tag buttons live inside
     *  free-form `content` (not item `onPress`) so they are not illegally nested in a row button. */
    const renderRowContent = (row: FlashcardQuizHistoryRow) => {
        const expanded = expandedId === row.id
        const scoreRatio = row.cardCount > 0 ? row.correctCount / row.cardCount : 0
        return (
            <>
                <button
                    type="button"
                    onClick={() => setExpandedId(expanded ? null : row.id)}
                    className="w-full text-left"
                >
                    <StackH gap={4} principle="content-row" align="center" items={[
                        () => (
                            <StackV gap={1} classNames={["min-w-0", "flex-1"]} items={[
                                () => (
                                    <Typography type="body-sm" weight="medium" truncate>
                                        {row.displayName}
                                    </Typography>
                                ),
                                () => (
                                    <Typography type="body-xs" color="muted" truncate>
                                        {row.subtitle}
                                    </Typography>
                                ),
                            ]} />
                        ),
                        () => (
                            <StackH gap={3} principle="chip-row" align="center" classNames={["shrink-0"]} items={[
                                ...(row.levelLabel ? [() => (
                                    <Chip key="level" size="sm" variant="soft" color={row.levelColor}>
                                        {row.levelLabel}
                                    </Chip>
                                )] : []),
                                ...(row.coverageLabel ? [() => (
                                    <Chip key="coverage" size="sm" variant="soft" color="default">
                                        {row.coverageLabel}
                                    </Chip>
                                )] : []),
                                ...(row.xpLabel ? [() => (
                                    <Chip key="xp" size="sm" variant="soft" color="warning">
                                        {row.xpLabel}
                                    </Chip>
                                )] : []),
                                () => (
                                    <Chip size="sm" variant="soft" color={scoreColorOf(scoreRatio)}>
                                        {`${row.correctCount}/${row.cardCount}`}
                                    </Chip>
                                ),
                                () => (
                                    <CaretDownIcon
                                        className={cn("size-4 text-muted transition-transform", expanded && "rotate-180")}
                                        weight="bold"
                                        aria-hidden
                                        focusable="false"
                                    />
                                ),
                            ]} />
                        ),
                    ]} />
                </button>
                {expanded ? (
                    <Box className="mt-3 border-t border-divider pt-3">
                        <StackV
                            gap={3}
                            principle="sibling-stack"
                            items={row.weakTags.length === 0 ? [
                                () => (
                                    <Typography type="body-xs" color="muted">
                                        {labels.weakTagsEmpty}
                                    </Typography>
                                ),
                            ] : row.weakTags.map((tag) => () => (
                                <button
                                    key={tag.tag}
                                    type="button"
                                    onClick={() => onTagPress(tag.href)}
                                    className="group w-full rounded-xl border border-default bg-default text-left"
                                >
                                    <StackH gap={4} principle="control-pad" padding={{ x: 4, y: 3 }} justify="between" align="center" items={[
                                        () => (
                                            <Typography type="body-xs" weight="medium" className="truncate underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                                                {tag.tag}
                                            </Typography>
                                        ),
                                        () => (
                                            <Typography type="body-xs" color="muted" className="shrink-0">
                                                {tag.coverageLabel}
                                            </Typography>
                                        ),
                                    ]} />
                                </button>
                            ))}
                        />
                    </Box>
                ) : null}
            </>
        )
    }

    const skeletonItems: Array<SurfaceCardListItem> = Array.from(
        { length: SKELETON_ROW_COUNT },
        (_unused, index) => ({
            key: `skeleton-${index}`,
            content: () => (
                <StackH gap={4} principle="content-row" align="center" items={[
                    () => (
                        <StackV gap={2} classNames={["min-w-0", "flex-1"]} items={[
                            () => <Skeleton.Typography type="body-sm" width="1/2" />,
                            () => <Skeleton.Typography type="body-xs" width="1/3" />,
                        ]} />
                    ),
                    () => <Skeleton className="h-6 w-12 shrink-0 rounded-full" />,
                    () => <Skeleton className="size-4 shrink-0 rounded" />,
                ]} />
            ),
        }),
    )

    // error beats a stale loading flag; empty only once settled (BLOCK-8, loading-and-skeleton.md).
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        // `AsyncContentEmpty` omits its own frame (composites/feedback/EmptyState) — the populated
        // sibling below is a real bounded list surface, so the empty state needs the same
        // card shape to match (`components/card.md` "frameless-section-empty-state-needs-card").
        return (
            <Card className={className}>
                <CardContent>
                    <AsyncContentEmpty
                        icon={ClockCounterClockwiseIcon}
                        title={labels.emptyTitle}
                        description={labels.emptyDescription}
                        action={onStartQuiz ? () => (
                            <PrimitiveButton label={labels.emptyAction} variant="secondary" size="sm" onPress={onStartQuiz} />
                        ) : undefined}
                    />
                </CardContent>
            </Card>
        )
    }

    // filter/search excluded everything — a DIFFERENT (secondary) empty state than the block's own
    // `isEmpty` above: there IS history, the active filters just hide all of it.
    const filteredEmpty = !isSkeleton && filteredRows.length === 0

    return (
        <Box className={className}>
            <StackV gap={4} items={[
                () => (
                    <StackH gap={4} principle="content-row" justify="between" at="sm" align="center" items={[
                        () => (
                            <StackH gap={4} principle="flex-action" align="center" classNames={["min-w-0", "flex-1"]} items={[
                                ...(isSkeleton ? [
                                    () => <Skeleton className="h-9 min-w-0 flex-1 rounded-medium" />,
                                    () => <Skeleton className="size-9 shrink-0 rounded-medium" />,
                                ] : [
                                    () => (
                                        <SearchInput
                                            className="min-w-0 flex-1"
                                            value={search}
                                            onValueChange={setSearch}
                                            placeholder={labels.searchPlaceholder}
                                        />
                                    ),
                                    ...(hasFacets ? [() => (
                                        <Popover isOpen={filterOpen} onOpenChange={setFilterOpen}>
                                            <Button
                                                isIconOnly
                                                variant="ghost"
                                                aria-label={labels.filterButtonAria}
                                                className="shrink-0"
                                            >
                                                {activeFacetCount > 0 ? (
                                                    <Badge.Anchor>
                                                        <FunnelIcon className="size-5" />
                                                        <Badge size="sm" color="accent" placement="top-left">{activeFacetCount}</Badge>
                                                    </Badge.Anchor>
                                                ) : (
                                                    <FunnelIcon className="size-5" />
                                                )}
                                            </Button>
                                            <Popover.Content className="w-72">
                                                <StackV gap={1} principle="cell-pad" padding={4} items={[() => (
                                                    <StackV gap={4} items={[
                                                        ...(hasModeFacet ? [() => (
                                                            <StackV gap={3} principle="label-field" items={[
                                                                () => <Typography type="body-xs" color="muted">{labels.modeHeading}</Typography>,
                                                                () => (
                                                                    <FlexWrapButtonRadio
                                                                        ariaLabel={labels.modeFilterAria}
                                                                        value={modeFilter}
                                                                        onChange={setModeFilter}
                                                                        items={[
                                                                            { value: "all", content: labels.filterAll },
                                                                            ...presentModes.map((mode) => ({
                                                                                value: mode,
                                                                                content: modeLabelOf[mode] ?? mode,
                                                                            })),
                                                                        ]}
                                                                    />
                                                                ),
                                                            ]} />
                                                        )] : []),
                                                        ...(hasLevelFacet ? [() => (
                                                            <StackV gap={3} principle="label-field" items={[
                                                                () => <Typography type="body-xs" color="muted">{labels.levelHeading}</Typography>,
                                                                () => (
                                                                    <FlexWrapButtonRadio
                                                                        ariaLabel={labels.levelFilterAria}
                                                                        value={levelFilter}
                                                                        onChange={setLevelFilter}
                                                                        items={[
                                                                            { value: "all", content: labels.filterAll },
                                                                            ...presentLevels.map((level) => ({
                                                                                value: level,
                                                                                content: levelLabelOf[level] ?? level,
                                                                            })),
                                                                        ]}
                                                                    />
                                                                ),
                                                            ]} />
                                                        )] : []),
                                                        ...(activeFacetCount > 0 ? [() => (
                                                            <Button variant="danger-soft" size="sm" className="self-start" onPress={clearFacets}>
                                                                {labels.clearFilters}
                                                            </Button>
                                                        )] : []),
                                                    ]} />
                                                )]} />
                                            </Popover.Content>
                                        </Popover>
                                    )] : []),
                                ]),
                            ]} />
                        ),
                        ...(isSkeleton ? [() => <Skeleton className="h-[14px] w-16 shrink-0 rounded" />] : [() => (
                            <Typography type="body-sm" color="muted" className="shrink-0">
                                {formatRunCount(shownCount)}
                            </Typography>
                        )]),
                    ]} />
                ),
                () => (
                    isSkeleton ? (
                        <SurfaceCardList isSkeleton items={skeletonItems} />
                    ) : filteredEmpty ? (
                        <Card>
                            <CardContent>
                                <Box principle="page-pad" className="py-6">
                                    <Typography type="body-sm" color="muted" align="center">
                                        {labels.filterEmptyMessage}
                                    </Typography>
                                </Box>
                            </CardContent>
                        </Card>
                    ) : (
                        <StackV gap={4} items={timeBuckets.map((bucket) => () => (
                            <SurfaceCardList
                                key={bucket.key}
                                subtleLabel
                                label={timeBucketLabelOf[bucket.key]}
                                labelEnd={formatRunCount(bucket.items.length)}
                                items={bucket.items.map((row) => ({
                                    key: row.id,
                                    content: () => renderRowContent(row),
                                }))}
                            />
                        ))} />
                    )
                ),
                ...(!isSkeleton && hasMore ? [() => (
                    <Button
                        variant="secondary"
                        size="sm"
                        className="self-center"
                        isDisabled={isLoadingMore}
                        onPress={onLoadMore}
                    >
                        {labels.loadMore}
                    </Button>
                )] : []),
            ]} />
        </Box>
    )
}

"use client"

import React, { useEffect, useMemo, useRef, useState } from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { queryMyFlashcardQuizHistory } from "@/modules/api/graphql/queries/query-my-flashcard-quiz-history"
import type { QueryFlashcardQuizHistoryItem, QueryFlashcardQuizWeakTag } from "@/modules/api/graphql/queries/types/my-flashcard-quiz-history"
import { sessionDisplayName } from "@/modules/utils/session-display-name"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"
import { LEVEL_COLOR } from "@/modules/utils/flashcards"
import type { TimeBucketKey } from "@/modules/utils/history-buckets"
import { _FlashcardQuizHistory, type FlashcardQuizHistoryRow } from "./component"

/** Props for {@link FlashcardQuizHistory}. */
export interface FlashcardQuizHistoryProps extends WithClassNames<undefined> {
    /** Course whose quick-quiz ("Quick Quiz") history to list. */
    courseId: string
    /** Jumps the setup tab strip back to "Start" — wired from `InterviewSession`
     *  so the empty state's action can start a fresh run without this component
     *  owning the tab switcher itself. */
    onStartQuiz?: () => void
}

/** History items fetched per "load more" page. */
const PAGE_SIZE = 10

/** Every time-bucket key, in the order {@link groupByTimeBucket} can emit them — translated once. */
const TIME_BUCKET_KEYS: ReadonlyArray<TimeBucketKey> = ["day", "days3", "week", "month", "year", "older"]

/**
 * "Quick Quiz" run history — the CONNECTED half: it owns the offset-paginated
 * fetch (accumulating pages as "load more" advances), reads the course slug +
 * locale + router, resolves every run into a fully-localized
 * {@link FlashcardQuizHistoryRow}, and hands them to the presentational
 * {@link _FlashcardQuizHistory}. See `design/storybook/architecture/tiers/split.md`.
 *
 * @param props - {@link FlashcardQuizHistoryProps}
 */
export const FlashcardQuizHistory = ({ courseId, onStartQuiz, className }: FlashcardQuizHistoryProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const displayId = useAppSelector((state) => state.course.displayId)
    const learn = pathConfig().locale(locale).course(displayId).learn()
    const genericHref = learn.module().build()

    const [offset, setOffset] = useState(0)
    const [items, setItems] = useState<Array<QueryFlashcardQuizHistoryItem>>([])
    const [totalCount, setTotalCount] = useState(0)

    const historySwr = useSWR(
        ["flashcard-quiz-history", courseId, offset],
        async () => {
            const response = await queryMyFlashcardQuizHistory({
                request: { courseId, limit: PAGE_SIZE, offset },
            })
            return response.data?.myFlashcardQuizHistory.data ?? null
        },
    )

    // accumulate pages as `offset` advances ("load more"); a fresh `courseId`
    // resets the accumulator (guarded by the effect below).
    useEffect(() => {
        const data = historySwr.data
        if (!data) {
            return
        }
        setItems((previous) => (offset === 0 ? data.items : [...previous, ...data.items]))
        setTotalCount(data.totalCount)
    }, [historySwr.data, offset])

    // course changed → start the accumulator over. Guarded against firing on
    // mere MOUNT (this tab is unmounted/remounted by the parent's tab switch;
    // an unguarded version fires on every remount too since `courseId` is
    // "new" to a fresh effect subscription, wiping the `items` this same
    // render's data-effect had JUST populated from SWR's still-warm cache —
    // see FlashcardReviewHistory for the same fix).
    const previousCourseIdRef = useRef(courseId)
    useEffect(() => {
        if (previousCourseIdRef.current === courseId) {
            return
        }
        previousCourseIdRef.current = courseId
        setOffset(0)
        setItems([])
    }, [courseId])

    /** A weak tag's deep link: content-level → module-level → the generic module fallback. */
    const resolveHref = (tag: QueryFlashcardQuizWeakTag): string =>
        (tag.moduleId && tag.contentId
            ? learn.module(tag.moduleId).content(tag.contentId).build()
            : tag.moduleId
                ? learn.module(tag.moduleId).build()
                : null) ?? genericHref

    // fully resolve every fetched item into render-ready text + the raw fields the
    // presentational half still filters/groups by (mode, level, updatedAt, tag).
    const rows: Array<FlashcardQuizHistoryRow> = useMemo(() => items.map((item) => ({
        id: item.id,
        updatedAt: item.updatedAt,
        displayName: sessionDisplayName(item.name, item.updatedAt, t, locale),
        mode: item.mode,
        subtitle: `${t(item.mode === "deep" ? "flashcard.quiz.modeDeep" : "flashcard.quiz.modeQuick")} · ${t("flashcard.quiz.quizHistoryCardCount", { count: item.cardCount })}`,
        level: item.level,
        levelLabel: item.level ? t(`flashcard.level.${item.level}`) : undefined,
        levelColor: item.level ? (LEVEL_COLOR[item.level] ?? "default") : "default",
        coverageLabel: item.coverage !== null
            ? t("flashcard.quiz.weakTagCoverage", { percent: Math.round(item.coverage * 100) })
            : undefined,
        xpLabel: item.xpEarned > 0 ? t("flashcard.quiz.xpToast", { xp: item.xpEarned }) : undefined,
        correctCount: item.correctCount,
        cardCount: item.cardCount,
        weakTags: item.weakTags.map((tag) => ({
            tag: tag.tag,
            coverageLabel: t("flashcard.quiz.weakTagCoverage", { percent: Math.round(tag.coverage * 100) }),
            href: resolveHref(tag),
        })),
    })), [items, t, locale, learn, genericHref])

    // mode has exactly two known labels (mirrors the presentational's own ternary,
    // `mode === "deep"` else "quick") — translate each raw value seen ONCE.
    const modeLabelOf = useMemo(() => {
        const map: Record<string, string> = {}
        for (const item of items) {
            if (!(item.mode in map)) {
                map[item.mode] = t(item.mode === "deep" ? "flashcard.quiz.modeDeep" : "flashcard.quiz.modeQuick")
            }
        }
        return map
    }, [items, t])

    const levelLabelOf = useMemo(() => {
        const map: Record<string, string> = {}
        for (const item of items) {
            if (item.level && !(item.level in map)) {
                map[item.level] = t(`flashcard.level.${item.level}`)
            }
        }
        return map
    }, [items, t])

    // fixed six-key enum — translate once regardless of which buckets end up populated.
    const timeBucketLabelOf = useMemo(() => {
        const map = {} as Record<TimeBucketKey, string>
        for (const key of TIME_BUCKET_KEYS) {
            map[key] = t(`flashcard.timeBucket.${key}`)
        }
        return map
    }, [t])

    return (
        <_FlashcardQuizHistory
            className={className}
            // first load, nothing in hand → shimmer; matches the pre-split `isLoading && items.length === 0`
            isSkeleton={historySwr.isLoading && items.length === 0}
            isEmpty={items.length === 0}
            // only a settled fetch error (nothing cached to fall back to) reaches the block
            error={items.length === 0 ? historySwr.error : undefined}
            onRetry={() => { void historySwr.mutate() }}
            onStartQuiz={onStartQuiz}
            rows={rows}
            totalCount={totalCount}
            hasMore={items.length < totalCount}
            isLoadingMore={historySwr.isLoading}
            onLoadMore={() => setOffset((previous) => previous + PAGE_SIZE)}
            onTagPress={(href) => router.push(href)}
            modeLabelOf={modeLabelOf}
            levelLabelOf={levelLabelOf}
            timeBucketLabelOf={timeBucketLabelOf}
            formatRunCount={(count) => t("flashcard.runCount", { count })}
            labels={{
                errorTitle: t("flashcard.quiz.quizHistoryError"),
                retry: t("flashcard.quiz.retry"),
                emptyTitle: t("flashcard.quiz.quizHistoryEmptyTitle"),
                emptyDescription: t("flashcard.quiz.quizHistoryEmptyDescription"),
                emptyAction: t("flashcard.quiz.quizHistoryEmptyAction"),
                searchPlaceholder: t("flashcard.quiz.quizHistorySearchPlaceholder"),
                filterButtonAria: t("flashcard.quiz.quizHistoryFilterButton"),
                modeHeading: t("flashcard.quiz.quizHistoryModeHeading"),
                modeFilterAria: t("flashcard.quiz.quizHistoryFilterMode"),
                levelHeading: t("flashcard.quiz.quizHistoryLevelHeading"),
                levelFilterAria: t("flashcard.quiz.quizHistoryFilterLevel"),
                filterAll: t("flashcard.quiz.quizHistoryFilterAll"),
                clearFilters: t("flashcard.quiz.quizHistoryClearFilters"),
                filterEmptyMessage: t("flashcard.quiz.quizHistoryFilterEmpty"),
                weakTagsEmpty: t("flashcard.quiz.weakTagsEmpty"),
                loadMore: t("flashcard.quiz.quizHistoryLoadMore"),
            }}
        />
    )
}

import React from "react"
import { ArrowRightIcon, ChartLineUpIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Section } from "@/components/composites/layout/Section"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { ScoreValue } from "@/components/composites/text/ScoreValue"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"

/** Coverage-vs-target verdict floor (teacher's ruling per proposal §C — "an 80% target counts as knowing the module"). FE-only, no server field (contract). */
export const COVERAGE_TARGET = 80

/** Chip/meter severity BY coverage value (0..100). */
const coverageTone = (percent: number): "success" | "warning" | "danger" =>
    percent < 50 ? "danger" : percent < 70 ? "warning" : "success"

/** How many placeholder rows the co-located skeleton shows for zone 2. */
const SKELETON_ROW_COUNT = 4

/** One attempted tag with its coverage fraction (0..1) — the block turns it into a %. */
export interface FlashcardQuizStatsTag {
    tag: string
    coverage: number
}

/** All display text, already localized by the connected `FlashcardQuizStats`; a story passes i18n keys. */
export interface FlashcardQuizStatsLabels {
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
    emptyAction: string
    coverageZone: string
    /** Full sentence — the connected file interpolates coverage/remaining/total. */
    coverageVerdict: string
    /** Caption under the meter — the connected file interpolates the target. */
    coverageSub: string
    /** Drill CTA — the connected file interpolates the untouched count. */
    coverageDrillCta: string
    gapZone: string
    topicOftenWrong: string
    topicNeverTried: string
    /** Suffix printed after the untouched-topic number in its chip. */
    topicEmptyChip: string
    studyHeading: string
}

/** Props for {@link _FlashcardQuizStats} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardQuizStatsProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no honest aggregate (insufficient data / no stats) → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Coverage % vs the target; `null` on a course with zero tag data → zone 1 skipped. */
    coveragePercent?: number | null
    /** Attempted topics that were never covered — one honest aggregate row. */
    untouchedTopicCount?: number
    /** Every attempted tag, already ranked worst-first. */
    tags?: Array<FlashcardQuizStatsTag>
    /** Course id for the RAG study-suggestions child. */
    courseId: string
    /** Course display id — omitted (as in a story) → the self-fetching study zone is skipped. */
    displayId?: string
    onStartQuiz?: () => void
    labels: FlashcardQuizStatsLabels
}

/**
 * "Quick quiz" aggregate stats — the presentational half of {@link FlashcardQuizStats}, composed on the
 * tier-correct vocabulary (`Section` / `SurfaceCard` / `SurfaceCardList` / `ProgressMeter` / `ScoreValue`).
 * Four states in the fixed order error → loading → empty → content: `error` falls to the shared
 * `AsyncContentError` frame, `isEmpty` to `AsyncContentEmpty`, and otherwise the two-zone tree renders
 * with `isSkeleton` threaded to every leaf so the shimmer mirrors the loaded shape (loading-and-skeleton.md).
 * See `tiers/split.md` — the connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link FlashcardQuizStatsProps}
 */
export const _FlashcardQuizStats = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    coveragePercent = null,
    untouchedTopicCount = 0,
    tags = [],
    courseId,
    displayId,
    onStartQuiz,
    labels,
}: FlashcardQuizStatsProps) => {
    // error → skeleton → empty → content (BLOCK-8): error beats a stale loading flag; the empty and
    // error surfaces are the shared `AsyncContent*` frames, not hand-written JSX (loading-and-skeleton.md §6).
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                icon={ChartLineUpIcon}
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                action={onStartQuiz ? () => (
                    <Button label={labels.emptyAction} variant="secondary" size="sm" onPress={onStartQuiz} />
                ) : undefined}
            />
        )
    }

    // ZONE 2 rows — while shimmering, placeholder rows keep the SAME `SurfaceCardList` shape; otherwise
    // every attempted tag worst-first, then one honest aggregate row for the never-tried topics.
    const gapRows: Array<SurfaceCardListItem> = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
            key: `pending-${index}`,
            title: "Topic",
            meta: () => <Chip isSkeleton />,
        }))
        : [
            ...tags.map((tagStat, index) => {
                const percent = Math.round(tagStat.coverage * 100)
                return {
                    key: tagStat.tag,
                    title: tagStat.tag,
                    // only flag the single worst tag — the ranked chips already speak for the rest
                    subtitle: index === 0 && percent < 70 ? labels.topicOftenWrong : undefined,
                    meta: () => <Chip tone={coverageTone(percent)} text={`${percent}%`} />,
                }
            }),
            ...(untouchedTopicCount > 0
                ? [{
                    key: "__never-tried",
                    title: labels.topicNeverTried,
                    meta: () => <Chip text={`${untouchedTopicCount} ${labels.topicEmptyChip}`} />,
                }]
                : []),
        ]

    // Zones render while shimmering too (placeholder values) so the skeleton mirrors the loaded shape.
    const showCoverage = isSkeleton || coveragePercent !== null
    const showGap = isSkeleton || gapRows.length > 0

    return (
        <StackV gap={6} principle="block-boundary" items={[
            // ZONE 1 — HERO "Coverage vs target": coverage judged against COVERAGE_TARGET (not a bare %).
            ...(showCoverage ? [() => (
                <Section header={{ title: labels.coverageZone, level: 3 }} isSkeleton={isSkeleton} body={() => (
                    <SurfaceCard isSkeleton={isSkeleton} body={() => (
                        <StackV gap={3} principle="sibling-stack" items={[
                            () => <ScoreValue points={coveragePercent ?? 0} unit="%" isSkeleton={isSkeleton} />,
                            () => <Typography text={labels.coverageVerdict} isSkeleton={isSkeleton} classNames={isSkeleton ? ["w-3/4"] : undefined} />,
                            () => <Typography size="sm" color="muted" text={labels.coverageSub} isSkeleton={isSkeleton} classNames={isSkeleton ? ["w-1/2"] : undefined} />,
                            () => (isSkeleton
                                ? <ProgressMeter isSkeleton />
                                : <ProgressMeter value={coveragePercent ?? 0} max={100} target={COVERAGE_TARGET} color={coverageTone(coveragePercent ?? 0)} />),
                            ...(!isSkeleton && untouchedTopicCount > 0 && onStartQuiz ? [() => (
                                <Button label={labels.coverageDrillCta} variant="primary" size="sm" suffixIcon={ArrowRightIcon} onPress={onStartQuiz} />
                            )] : []),
                        ]} />
                    )} />
                )} />
            )] : []),

            // ZONE 2 — "Weak topics": attempted tags ranked worst-first + one honest never-tried row.
            ...(showGap ? [() => (
                <Section header={{ title: labels.gapZone, level: 3 }} isSkeleton={isSkeleton} body={() => (
                    <SurfaceCardList variant="nested" isSkeleton={isSkeleton} items={gapRows} />
                )} />
            )] : []),

            // ZONE 3 — passive RAG "Study suggestions": weakest-coverage tags → course-wide content search.
            // Waits on the slug for deep links, so a story that omits `displayId` renders backend-free.
            // RelatedContentList is a real block (self-fetching) — a presentational component may render a
            // connected child (split.md). Hidden while shimmering (it fetches its own state).
            ...(!isSkeleton && displayId ? [() => (
                <RelatedContentList
                    courseId={courseId}
                    courseDisplayId={displayId}
                    query={tags.map((tagStat) => tagStat.tag).join(" ")}
                    label={labels.studyHeading}
                />
            )] : []),
        ]} />
    )
}

"use client"

import React, { useMemo } from "react"
import useSWR from "swr"
import { useTranslations } from "next-intl"
import { queryMyFlashcardQuizStats } from "@/modules/api/graphql/queries/query-my-flashcard-quiz-stats"
import { useAppSelector } from "@/redux/hooks"
import { _FlashcardQuizStats, COVERAGE_TARGET } from "./component"

/** Props for {@link FlashcardQuizStats}. */
export interface FlashcardQuizStatsProps {
    /** Course whose aggregate quick-quiz ("Quick quiz") stats to show. */
    courseId: string
    /** Jumps the setup tab strip back to "Start" (empty-state + coverage-gap CTA action). */
    onStartQuiz?: () => void
}

/**
 * "Quick quiz" aggregate stats — the CONNECTED half: it fetches the stats, reads the course slug,
 * resolves every label (incl. interpolation), and hands them to the presentational
 * {@link _FlashcardQuizStats}. See `design/storybook/architecture/split.md`.
 *
 * @param props - {@link FlashcardQuizStatsProps}
 */
export const FlashcardQuizStats = ({ courseId, onStartQuiz }: FlashcardQuizStatsProps) => {
    const t = useTranslations()
    // slug for the RAG "Study suggestions" deep links (this surface is course-scoped but only carries the id).
    const displayId = useAppSelector((state) => state.course.displayId)

    const statsSwr = useSWR(
        ["flashcard-quiz-stats", courseId],
        async () => {
            const response = await queryMyFlashcardQuizStats({ request: { courseId } })
            return response.data?.myFlashcardQuizStats.data ?? null
        },
    )

    const stats = statsSwr.data
    const conceptCoverage = stats?.conceptCoverage ?? null

    // ZONE 1 evidence: coverage% vs the local target — `conceptCoverage` is
    // null only when the course itself has zero tag data (guards divide-by-zero,
    // see BE contract), in which case there is nothing honest to judge.
    const coveragePercent = conceptCoverage && conceptCoverage.total > 0
        ? Math.round((conceptCoverage.covered / conceptCoverage.total) * 100)
        : null
    const untouchedTopicCount = conceptCoverage ? Math.max(0, conceptCoverage.total - conceptCoverage.covered) : 0

    // ZONE 2 evidence: every attempted tag, worst-first.
    const tags = useMemo(
        () => [...(stats?.byTag ?? [])].sort((a, b) => a.coverage - b.coverage),
        [stats?.byTag],
    )

    return (
        <_FlashcardQuizStats
            // first load, nothing in hand → shimmer; settled (data OR error) stops it (loading-and-skeleton.md)
            isSkeleton={!statsSwr.data && !statsSwr.error}
            // error beats loading + empty; only a settled fetch error (nothing in hand) reaches the block
            error={!stats ? statsSwr.error : undefined}
            onRetry={() => { void statsSwr.mutate() }}
            // settled with no honest aggregate
            isEmpty={!stats || stats.insufficientData}
            coveragePercent={coveragePercent}
            untouchedTopicCount={untouchedTopicCount}
            tags={tags}
            courseId={courseId}
            displayId={displayId}
            onStartQuiz={onStartQuiz}
            labels={{
                errorTitle: t("flashcard.quiz.quizStatsError"),
                retry: t("flashcard.quiz.retry"),
                emptyTitle: t("flashcard.quiz.quizStatsEmptyTitle"),
                emptyDescription: t("flashcard.quiz.quizStatsEmptyDescription"),
                emptyAction: t("flashcard.quiz.quizHistoryEmptyAction"),
                coverageZone: t("flashcard.quiz.quizStatsCoverageVsTargetLabel"),
                coverageVerdict: t("flashcard.quiz.quizStatsCoverageSentence", {
                    coverage: coveragePercent ?? 0,
                    remaining: untouchedTopicCount,
                    total: conceptCoverage?.total ?? 0,
                }),
                coverageSub: t("flashcard.quiz.quizStatsCoverageTargetCaption", { target: COVERAGE_TARGET }),
                coverageDrillCta: t("flashcard.quiz.quizStatsCoverageDrillCta", { count: untouchedTopicCount }),
                gapZone: t("flashcard.quiz.quizStatsGapLabel"),
                topicOftenWrong: t("flashcard.quiz.quizStatsTopicOftenWrong"),
                topicNeverTried: t("flashcard.quiz.quizStatsTopicNeverTried"),
                topicEmptyChip: t("flashcard.quiz.quizStatsTopicEmptyChip"),
                studyHeading: t("flashcard.review.stats.studyHeading"),
            }}
        />
    )
}

/**
 * Cloze (fill-in-the-blank) builder for the flashcard quick quiz — fully
 * offline, no AI. The blanks are read DIRECTLY from Anki-style `{{cN::…}}`
 * markers that the content author (via the mechanical marking pass) placed in
 * the answer prose, so there is NO fragile string-matching of a separate key-
 * term list against the text: the marker IS the blank, exactly where it sits.
 * A marker's own term IS that card's "keywords" now too (see
 * {@link extractMarkerTerms}) — the separate `:::chip` list was retired
 * 2026-07-12 (reviewer: "get rid of the free-points keyword") once every card had ≥1 marker,
 * so there was no longer a card left that needed it as a fallback source.
 * Distractors come from two
 * tiers: a marker's own curated near-synonyms when authored inline
 * (`{{c1::docker::k8s,vps}}`) are preferred, topped up with sibling cards' key
 * terms (same tag, then same deck) — mirroring how Duolingo builds its word
 * bank from the session's own vocabulary.
 */

/** One piece of a cloze sentence: literal text, a lightweight inline markdown
 *  span (`` `code` ``/`**bold**`/`*italic*`), or a numbered blank slot. */
export type ClozeSegment =
    | { kind: "text", text: string }
    | { kind: "code", text: string }
    | { kind: "bold", text: string }
    | { kind: "italic", text: string }
    | { kind: "blank", index: number }

/** A generated cloze question for one card. */
export interface ClozeQuestion {
    /** The sentence split into literal text + blank slots, in reading order. */
    segments: Array<ClozeSegment>
    /** The correct term for each blank, in blank order. */
    blanks: Array<string>
    /** Shuffled option chips: the correct terms plus sibling distractors. */
    bank: Array<string>
}

/** Options for {@link buildCloze}. */
export interface BuildClozeParams {
    /** Raw answer markdown (carrying `{{cN::…}}` markers). */
    answer: string
    /** Key terms of OTHER cards in the session — the distractor pool. */
    distractorPool: Array<string>
    /** Max blanks to open (extra markers are revealed as plain text). Default 3. */
    maxBlanks?: number
    /** How many wrong options to add beyond the correct terms. Default 2. */
    distractorCount?: number
}

/** Global cloze-marker matcher: `{{c1::term}}` or `{{c1::term::distractorA,distractorB}}`.
 *  Group 1 = the correct term. Group 2 (optional) = curated near-synonym
 *  distractors, comma-separated — an author-supplied confuser set for THIS
 *  blank specifically (reviewer, 2026-07-11: "docker" → "k8s, vps"), preferred over
 *  the generic sibling-card pool when present. */
const MARKER = /\{\{c\d+::([\s\S]*?)(?:::([\s\S]*?))?\}\}/g

/** A parsed marker with its span in the raw answer. */
interface Marker { start: number, end: number, inner: string, curatedDistractors: Array<string> }

/** Clean a term/segment for DISPLAY + matching: drop backticks, collapse whitespace, trim. */
const clean = (value: string): string => value.replace(/`/g, "").replace(/\s+/g, " ").trim()

/** Parses the optional `::distractorA,distractorB` group into cleaned, non-empty terms. */
const parseCuratedDistractors = (raw: string | undefined): Array<string> =>
    (raw ?? "")
        .split(",")
        .map((term) => clean(term))
        .filter((term) => term.length > 0)

/**
 * Extracts just the correct-answer terms of every `{{cN::term}}` marker in an
 * answer — used to seed a card's "keywords" (self-grading coverage + the
 * distractor pool offered to SIBLING cards) directly from the markers, so a
 * term never needs typing twice (once as a marker, once in `:::chip`).
 * @param answer - Raw answer markdown (may be empty/undefined).
 */
export const extractMarkerTerms = (answer: string | null | undefined): Array<string> => {
    if (!answer) {
        return []
    }
    const terms: Array<string> = []
    MARKER.lastIndex = 0
    for (let m = MARKER.exec(answer); m; m = MARKER.exec(answer)) {
        terms.push(clean(m[1]))
    }
    return terms
}

/** Sentence-start offsets (after `. ` / newline / `:::` directive fence). */
const sentenceStarts = (source: string): Array<number> => {
    const starts = [0]
    const re = /(?:[.!?]\s+|\n+|:::+[^\n]*\n?)/g
    for (let m = re.exec(source); m; m = re.exec(source)) {
        starts.push(m.index + m[0].length)
    }
    return starts
}

/** Fisher–Yates shuffle (new array). */
const shuffle = <T,>(input: Array<T>): Array<T> => {
    const array = [...input]
    for (let i = array.length - 1; i > 0; i -= 1) {
        const j = Math.floor(Math.random() * (i + 1))
        ;[array[i], array[j]] = [array[j], array[i]]
    }
    return array
}

/**
 * Builds a cloze question from a card's marked answer, or returns null when the
 * answer has no `{{cN::…}}` markers (the caller then falls back to a plain flip
 * + self-grade for that card).
 * @param params - See {@link BuildClozeParams}.
 */
export const buildCloze = (
    {
        answer,
        distractorPool,
        maxBlanks = 3,
        distractorCount = 2,
    }: BuildClozeParams,
): ClozeQuestion | null => {
    if (!answer) {
        return null
    }
    // collect every marker with its span
    const markers: Array<Marker> = []
    MARKER.lastIndex = 0
    for (let m = MARKER.exec(answer); m; m = MARKER.exec(answer)) {
        markers.push({
            start: m.index,
            end: m.index + m[0].length,
            inner: m[1],
            curatedDistractors: parseCuratedDistractors(m[2]),
        })
    }
    if (markers.length === 0) {
        return null
    }
    // which markers become BLANKS (cap) — the rest are revealed as plain text
    const blankSet = new Set(markers.slice(0, maxBlanks))

    // tight sentence window covering the markers we use (keeps the cloze short)
    const usedMarkers = [...blankSet]
    const firstStart = usedMarkers[0].start
    const lastEnd = usedMarkers[usedMarkers.length - 1].end
    const starts = sentenceStarts(answer)
    const winStart = [...starts].reverse().find((s) => s <= firstStart) ?? 0
    const winEnd = starts.find((s) => s > lastEnd) ?? answer.length

    // walk the window, splitting at each marker into text + blank/revealed segments
    const inWindow = markers
        .filter((marker) => marker.start >= winStart && marker.end <= winEnd)
        .sort((a, b) => a.start - b.start)
    const segments: Array<ClozeSegment> = []
    const blanks: Array<string> = []
    let cursor = winStart
    // splits on lightweight inline markdown spans instead of leaving them as raw
    // `*`/`` ` `` characters, so the rendered cloze sentence matches the same
    // emphasis the answer prose carries (reviewer, 2026-07-09: "the blank text
    // can have markdown too"). Checked in priority order per match position: code
    // (`` `x` ``) > bold (`**x**`) > italic (`*x*`) — `**` must be tried before
    // `*` or the italic branch would eat one asterisk of a bold pair.
    const inlineSpan = /`([^`]+)`|\*\*([^*]+)\*\*|\*([^*]+)\*/g
    // A code span in the source can straddle a `{{cN::…}}` marker (the marker
    // sits INSIDE the backtick pair) — since markers are cut out into their own
    // fragment before this scanner sees the surrounding text, each side only
    // ever has an ORPHAN backtick, which used to fall through as a literal `
    // character (reviewer, 2026-07-11 bug report). `openCode` carries "we're still
    // inside an unclosed code span" across fragment/marker boundaries so the
    // orphan backticks are consumed (never rendered) and both sides stay `code`.
    let openCode = false
    const pushText = (raw: string) => {
        let cursor2 = 0
        if (openCode) {
            const closeIndex = raw.indexOf("`")
            if (closeIndex === -1) {
                if (raw.length > 0) {
                    segments.push({ kind: "code", text: raw })
                }
                return
            }
            if (closeIndex > 0) {
                segments.push({ kind: "code", text: raw.slice(0, closeIndex) })
            }
            openCode = false
            cursor2 = closeIndex + 1
        }
        inlineSpan.lastIndex = cursor2
        for (let m = inlineSpan.exec(raw); m; m = inlineSpan.exec(raw)) {
            const before = raw.slice(cursor2, m.index)
            if (before.length > 0) {
                segments.push({ kind: "text", text: before })
            }
            if (m[1] !== undefined) {
                segments.push({ kind: "code", text: m[1] })
            } else if (m[2] !== undefined) {
                segments.push({ kind: "bold", text: m[2] })
            } else {
                segments.push({ kind: "italic", text: m[3] })
            }
            cursor2 = m.index + m[0].length
        }
        const rest = raw.slice(cursor2)
        const openIndex = rest.indexOf("`")
        if (openIndex === -1) {
            if (rest.length > 0) {
                segments.push({ kind: "text", text: rest })
            }
            return
        }
        // unmatched backtick — a code span opens here and continues past this fragment
        if (openIndex > 0) {
            segments.push({ kind: "text", text: rest.slice(0, openIndex) })
        }
        const codeContent = rest.slice(openIndex + 1)
        if (codeContent.length > 0) {
            segments.push({ kind: "code", text: codeContent })
        }
        openCode = true
    }
    for (const marker of inWindow) {
        pushText(answer.slice(cursor, marker.start))
        if (blankSet.has(marker)) {
            segments.push({ kind: "blank", index: blanks.length })
            blanks.push(clean(marker.inner))
        } else {
            // an extra marker beyond the cap → reveal it as plain text
            pushText(marker.inner)
        }
        cursor = marker.end
    }
    pushText(answer.slice(cursor, winEnd))

    if (blanks.length === 0) {
        return null
    }

    // word bank: correct terms + plausible distractors (drop dups / ones already
    // visible in the sentence). Curated per-marker distractors (author-supplied
    // near-synonyms, e.g. "docker" → "k8s, vps") are PREFERRED — they're a much
    // sharper confuser than a random sibling-card term — and only top up with
    // the generic sibling `distractorPool` when a blank has none / too few.
    const windowText = answer.slice(winStart, winEnd).toLowerCase()
    const seen = new Set(blanks.map((term) => term.toLowerCase()))
    const distractors: Array<string> = []
    const curatedPool = shuffle(usedMarkers.flatMap((marker) => marker.curatedDistractors))
    for (const pool of [curatedPool, shuffle(distractorPool)]) {
        for (const candidate of pool) {
            if (distractors.length >= distractorCount) {
                break
            }
            const term = clean(candidate)
            const key = term.toLowerCase()
            if (!term || seen.has(key) || windowText.includes(key)) {
                continue
            }
            seen.add(key)
            distractors.push(term)
        }
    }

    return {
        segments,
        blanks,
        bank: shuffle([...blanks, ...distractors]),
    }
}

