"use client"

import React, { useMemo } from "react"
import { Chip, Typography } from "@heroui/react"
import { BuildingsIcon, MapPinIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { pathConfig } from "@/resources/path"
import { isJobPostingExpired } from "@/modules/utils/careers/jobs"
import type { JobPostingEntity } from "@/modules/types/entities/job-posting"
import { WorkMode } from "@/modules/types/enums/work-mode"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** i18n key per {@link WorkMode} (reuses the existing profile labels). */
const WORK_MODE_LABEL_KEY: Record<WorkMode, string> = {
    [WorkMode.Remote]: "publicProfile.workMode.remote",
    [WorkMode.Hybrid]: "publicProfile.workMode.hybrid",
    [WorkMode.Onsite]: "publicProfile.workMode.onsite",
}

/** Props for {@link JobListRow}. */
export interface JobListRowProps {
    /** The job posting to render. */
    job: JobPostingEntity
}

/**
 * One row of the job board list — the company logo (via {@link IconTile}), title,
 * location + work-mode chip, salary range (or "negotiable"), and a relative
 * "posted N ago" timestamp. The whole row navigates to the posting's detail page
 * (a nav row, not a select-in-place row), so hover underlines the title rather
 * than filling the row.
 *
 * @param props - {@link JobListRowProps}
 */
export const JobListRow = ({ job }: JobListRowProps) => {
    const t = useTranslations()
    const locale = useLocale()

    const salaryLabel = useMemo(() => {
        if (job.salaryMin == null && job.salaryMax == null) {
            return t("jobs.list.row.salaryNegotiable")
        }
        const format = (value: number) => value.toLocaleString(locale)
        if (job.salaryMin != null && job.salaryMax != null) {
            return t("jobs.list.row.salaryRange", {
                min: format(job.salaryMin),
                max: format(job.salaryMax),
            })
        }
        const single = job.salaryMin ?? job.salaryMax
        return single != null ? format(single) : t("jobs.list.row.salaryNegotiable")
    }, [job.salaryMin, job.salaryMax, locale, t])

    const postedAgo = useMemo(
        () => getTimeAgoLabel(getTimeAgoMessage(job.createdAt), t),
        [job.createdAt, t],
    )

    const expired = isJobPostingExpired(job)

    const metaItems = [
        ...(expired ? [() => (
            <Chip size="sm" variant="soft" color="danger">
                <Chip.Label>{t("jobs.list.row.expired")}</Chip.Label>
            </Chip>
        )] : []),
        ...(job.location ? [() => (
            <StackH
                gap={2}
                principle="icon-text"
                explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                inline
                align="center"
                items={[
                    () => <MapPinIcon aria-hidden focusable="false" className="size-3" />,
                    () => <span className="text-xs text-muted">{job.location}</span>,
                ]}
            />
        )] : []),
        ...(job.workMode ? [() => (
            <Chip size="sm" variant="soft" color="default">
                <Chip.Label>{t(WORK_MODE_LABEL_KEY[job.workMode!])}</Chip.Label>
            </Chip>
        )] : []),
    ]

    return (
        <SurfaceListCardItem
            href={pathConfig().locale(locale).jobs(job.displayId).build()}
            hover="underline"
        >
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={[
                    () => (
                        <IconTile
                            icon={<BuildingsIcon aria-hidden focusable="false" />}
                            src={job.company.logoUrl}
                            alt={job.company.title}
                            tone="neutral"
                            size="sm"
                        />
                    ),
                    () => (
                        <StackV
                            gap={2}
                            principle="title-subtitle"
                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                            classNames={["min-w-0", "flex-1"]}
                            items={[
                                () => (
                                    <Typography type="body-sm" weight="medium" className="underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                                        {job.title}
                                    </Typography>
                                ),
                                () => (
                                    <Typography type="body-xs" color="muted" truncate>
                                        {job.company.title}
                                    </Typography>
                                ),
                                ...(metaItems.length > 0 ? [() => (
                                    <Cluster gap={3} principle="chip-row"
                                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                        items={metaItems}  />
                                )] : []),
                            ]}
                        />
                    ),
                    () => (
                        <StackV
                            gap={2}
                            principle="title-subtitle"
                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                            align="end"
                            classNames={["shrink-0"]}
                            items={[
                                () => (
                                    <Typography type="body-sm" weight="medium">
                                        {salaryLabel}
                                    </Typography>
                                ),
                                () => (
                                    <Typography type="body-xs" color="muted">
                                        {postedAgo}
                                    </Typography>
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        </SurfaceListCardItem>
    )
}

import React, { useState } from "react"
import type { ReactNode } from "react"
import { BriefcaseIcon, FunnelIcon, TrayIcon } from "@phosphor-icons/react"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Badge } from "@/components/atoms/display/Badge"
import { Button } from "@/components/atoms/buttons/Button"
import { Popover } from "@/components/atoms/overlay/Popover"
import { Typography } from "@/components/atoms/text/Typography"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Cluster } from "@/components/frames/Cluster"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { FlexWrapButtonRadio, type FlexWrapButtonRadioItem } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { Pagination } from "@/components/blocks/navigation/Pagination"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import type { JobPostingEntity } from "@/modules/types/entities/job-posting"
import { JobEmploymentType } from "@/modules/types/enums/job-employment-type"
import { WorkMode } from "@/modules/types/enums/work-mode"
import { JobListRow } from "./JobListRow"

/** Single-select work-mode filter value — `"all"` clears the filter. */
export type WorkModeFilterValue = "all" | WorkMode
/** Single-select employment-type filter value — `"all"` clears the filter. */
export type EmploymentTypeFilterValue = "all" | JobEmploymentType

/** How many placeholder rows the co-located skeleton shows while the first page loads. */
const SKELETON_ROW_COUNT = 6

/** All display text, already localized by the connected {@link import("./index").JobListPage}; a story passes i18n keys. */
export interface JobListLabels {
    pageTitle: string
    pageDescription: string
    postCta: string
    searchPlaceholder: string
    filterButtonAria: string
    workModeHeading: string
    workModeAria: string
    employmentTypeHeading: string
    employmentTypeAria: string
    clearFacets: string
    /** Already interpolated with the total count (e.g. "3 postings"). */
    found: string
    emptyPlatformTitle: string
    emptyPlatformDescription: string
    emptyPlatformCta: string
    emptyFilteredTitle: string
    emptyFilteredClearFilters: string
    errorTitle: string
    retry: string
}

/** Props for {@link _JobListPage} — presentational; all data resolved, no fetch/store/i18n. */
export interface JobListPageProps {
    /** First load, nothing in hand → the row list shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero matching postings → the empty branch. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retries the failed fetch. */
    onRetry?: () => void
    /** The current page of postings, already resolved. */
    items?: Array<JobPostingEntity>
    /** `true` → the board itself has zero postings (no filter applied); `false` → a filtered search matched nothing. */
    isPlatformEmpty?: boolean
    /** Clears search + every facet — the filtered-empty branch's retry action. */
    onClearFilters?: () => void
    /** Opens the "post a job" flow — the header CTA AND the platform-empty branch's action. */
    onPostJob: () => void

    /** Current search query (controlled). */
    search: string
    /** Fired with the new query on every keystroke. */
    onSearchChange: (value: string) => void
    /** Currently selected work-mode facet. */
    workModeFilter: WorkModeFilterValue
    onWorkModeFilterChange: (value: WorkModeFilterValue) => void
    /** Work-mode facet options, already localized. */
    workModeItems: Array<FlexWrapButtonRadioItem<WorkModeFilterValue>>
    /** Currently selected employment-type facet. */
    employmentTypeFilter: EmploymentTypeFilterValue
    onEmploymentTypeFilterChange: (value: EmploymentTypeFilterValue) => void
    /** Employment-type facet options, already localized. */
    employmentTypeItems: Array<FlexWrapButtonRadioItem<EmploymentTypeFilterValue>>
    /** Facets currently applied (0–2) — badges the filter trigger. */
    activeFacetCount: number
    /** Resets both facet rows without touching the search box. */
    onClearFacets: () => void

    /** 1-based current page. */
    page: number
    totalPages: number
    onPageChange: (page: number) => void

    labels: JobListLabels
}

/**
 * Loading placeholder for one job-posting row — mirrors {@link JobListRow}'s
 * IconTile + title/company/meta + salary/time shape so the list does not
 * collapse or jump when data resolves. Co-located right here (not a separate
 * hand-kept file) since `JobListRow` takes no `isSkeleton` prop of its own to
 * thread through (`loading-and-skeleton.md`).
 */
const JobListRowSkeleton = () => (
    <SurfaceListCardItem>
        <StackH
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="center"
            items={[
                () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                () => (
                    <StackV
                        gap={2}
                        principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        classNames={["min-w-0", "flex-1"]}
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="1/2" />,
                            () => <Skeleton.Typography type="body-xs" width="1/3" />,
                            () => (
                                <Cluster
                                    gap={3}
                                    principle="chip-row"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    items={[
                                        () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                        () => <Skeleton.Chip />,
                                    ]}
                                />
                            ),
                        ]}
                    />
                ),
                () => (
                    <StackV
                        gap={2}
                        principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        align="end"
                        classNames={["shrink-0"]}
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="full" className="w-16" />,
                            () => <Skeleton.Typography type="body-xs" width="full" className="w-12" />,
                        ]}
                    />
                ),
            ]}
        />
    </SurfaceListCardItem>
)

/**
 * The job board (`/jobs`) — the presentational half of {@link import("./index").JobListPage}. Search +
 * two single-select filter rows (work mode, employment type) behind a funnel popover drive a
 * paginated ROW LIST (not a card grid — a posting has too many attributes — title, company,
 * location, work mode, salary — to read comfortably in a tile; every real job board renders rows).
 * Public — works for anonymous viewers.
 *
 * The header + search/filter toolbar always render; only the row-list region below switches
 * error → (settled) empty → content, with `isSkeleton` threaded to every leaf that can mirror
 * itself (`loading-and-skeleton.md`). `JobListRow` (a sibling component owned outside this pass)
 * takes no `isSkeleton` prop, so the loading branch mirrors it minimally with the co-located
 * `JobListRowSkeleton` at the SAME position and the SAME row count — not a parallel tree.
 *
 * Two distinct empty states (per the brainstorm's cold-start marketplace note): a filtered search
 * with zero matches offers a "clear filters" affordance, while a genuinely empty board (no postings
 * at all, yet) becomes a two-sided funnel — "no listings yet — is your company hiring? post one
 * free" — instead of a dead end.
 *
 * @param props - {@link JobListPageProps}
 */
export const _JobListPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    items = [],
    isPlatformEmpty = false,
    onClearFilters,
    onPostJob,
    search,
    onSearchChange,
    workModeFilter,
    onWorkModeFilterChange,
    workModeItems,
    employmentTypeFilter,
    onEmploymentTypeFilterChange,
    employmentTypeItems,
    activeFacetCount,
    onClearFacets,
    page,
    totalPages,
    onPageChange,
    labels,
}: JobListPageProps) => {
    // funnel popover open state — purely visual, needs no server/store/session (split.md's own test)
    const [filterOpen, setFilterOpen] = useState(false)

    const emptyPlatformAction: ComponentTypeWithSkeleton = () => (
        <Button variant="tertiary" size="sm" label={labels.emptyPlatformCta} onPress={onPostJob} />
    )

    const filterPopoverContent = (
        <StackV gap={3} items={[
            () => (
                <StackV gap={2} items={[
                    () => <Typography size="xs" color="muted" text={labels.workModeHeading} />,
                    () => (
                        <FlexWrapButtonRadio<WorkModeFilterValue>
                            ariaLabel={labels.workModeAria}
                            value={workModeFilter}
                            onChange={onWorkModeFilterChange}
                            items={workModeItems}
                        />
                    ),
                ]} />
            ),
            () => (
                <StackV gap={2} items={[
                    () => <Typography size="xs" color="muted" text={labels.employmentTypeHeading} />,
                    () => (
                        <FlexWrapButtonRadio<EmploymentTypeFilterValue>
                            ariaLabel={labels.employmentTypeAria}
                            value={employmentTypeFilter}
                            onChange={onEmploymentTypeFilterChange}
                            items={employmentTypeItems}
                        />
                    ),
                ]} />
            ),
            ...(activeFacetCount > 0 ? [() => (
                <Button variant="danger-soft" size="sm" label={labels.clearFacets} onPress={onClearFacets} classNames={["self-start"]} />
            )] : []),
        ]} />
    )

    // toolbar: search + funnel popover on the left, the resolved count on the right —
    // always rendered, unaffected by the row-list region's own error/empty/content switch
    const toolbar = (
        <StackH gap={3} principle="flex-action" justify="between" align="center" at="sm"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            items={[
                () => (
                    <StackH gap={3} principle="flex-action" align="center" classNames={["min-w-0", "flex-1"]}
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => (
                                <SearchInput
                                    className="min-w-0 flex-1"
                                    value={search}
                                    onValueChange={onSearchChange}
                                    placeholder={labels.searchPlaceholder}
                                />
                            ),
                            () => (
                                <Badge count={activeFacetCount} color="accent" size="sm" placement="top-left">
                                    <Popover
                                        triggerLabel={<span className="sr-only">{labels.filterButtonAria}</span>}
                                        triggerIcon={FunnelIcon}
                                        triggerVariant="ghost"
                                        isOpen={filterOpen}
                                        onOpenChange={setFilterOpen}
                                        classNames={["shrink-0"]}
                                        content={filterPopoverContent}
                                    />
                                </Badge>
                            ),
                        ]} />
                ),
                () => <Typography size="sm" color="muted" classNames={["shrink-0"]} text={labels.found} />,
            ]} />
    )

    // row-list region — the ONLY part of this block that switches state; the header +
    // toolbar above always render regardless of error/loading/empty/content.
    let listRegion: ReactNode
    if (error) {
        listRegion = <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    } else if (!isSkeleton && isEmpty) {
        listRegion = isPlatformEmpty ? (
            <AsyncContentEmpty
                icon={BriefcaseIcon}
                title={labels.emptyPlatformTitle}
                description={labels.emptyPlatformDescription}
                action={emptyPlatformAction}
            />
        ) : (
            <AsyncContentEmpty
                icon={TrayIcon}
                title={labels.emptyFilteredTitle}
                onRetry={onClearFilters}
                retryLabel={labels.emptyFilteredClearFilters}
            />
        )
    } else {
        // rows — while shimmering, the SAME position holds SKELETON_ROW_COUNT placeholder
        // rows (JobListRow takes no isSkeleton prop, so the mirror is JobListRowSkeleton,
        // co-located here rather than a separate branch — see missingSkeletonSupport).
        listRegion = (
            <StackV gap={3} items={[
                () => (
                    <SurfaceListCard>
                        {isSkeleton
                            ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => (
                                <JobListRowSkeleton key={index} />
                            ))
                            : items.map((job) => <JobListRow key={job.id} job={job} />)}
                    </SurfaceListCard>
                ),
                // pager: left-aligned with the rows, hidden on a single page
                ...(totalPages > 1 ? [() => (
                    <Pagination
                        className="mt-0 justify-start"
                        currentPage={page}
                        totalPages={totalPages}
                        onPageChange={onPageChange}
                    />
                )] : []),
            ]} />
        )
    }

    const jobListBody = (
        <StackV gap={8} items={[
            () => (
                <PageHeader
                    title={labels.pageTitle}
                    description={labels.pageDescription}
                    actions={<Button variant="secondary" label={labels.postCta} onPress={onPostJob} />}
                />
            ),
            () => toolbar,
            () => listRegion,
        ]} />
    )

    return (
        <Container
            size="md"
            padding={6}
            body={() => jobListBody}
            identity={{ tier: "block", component: "JobListPage" }}
        />
    )
}

"use client"

import React from "react"
import { Input, Label, TextField } from "@heroui/react"
import { useTranslations } from "next-intl"
import type { UseFormSetValue } from "react-hook-form"
import type { SubmitJobPostingFormValues } from "@/hooks/rhf/useSubmitJobPostingForm"
import { JobApplyMethod } from "@/modules/types/enums/job-apply-method"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { StackV } from "@/components/frames/Stack"

/** Max length of a URL field. */
const URL_MAX = 2048

/** Props for {@link ApplyMethodSection}. */
export interface ApplyMethodSectionProps {
    applyMethod: JobApplyMethod
    applyUrl: string
    applyEmail: string
    /** Sets a single form field. */
    setValue: UseFormSetValue<SubmitJobPostingFormValues>
}

/**
 * "How to apply" section of the job-post form — a 2-option toggle between an
 * external application link and an email address, showing only the matching
 * input.
 *
 * @param props - {@link ApplyMethodSectionProps}
 */
export const ApplyMethodSection = ({
    applyMethod,
    applyUrl,
    applyEmail,
    setValue,
}: ApplyMethodSectionProps) => {
    const t = useTranslations()

    return (
        <SurfaceCard
            label={t("jobs.post.sections.applyMethod")}

            body={() => (
                <StackV gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    items={[
                        () => (
                            <TabsCard
                                variant="primary"
                                leftTabs={{
                                    selectedKey: applyMethod,
                                    ariaLabel: t("jobs.post.applyMethod.toggleAria"),
                                    onSelectionChange: (key) => setValue("applyMethod", String(key) as JobApplyMethod),
                                    items: [
                                        { key: JobApplyMethod.ExternalUrl, label: t("jobs.post.applyMethod.externalUrl") },
                                        { key: JobApplyMethod.Email, label: t("jobs.post.applyMethod.email") },
                                    ],
                                }}
                            />
                        ),
                        () => (applyMethod === JobApplyMethod.ExternalUrl ? (
                            <TextField variant="secondary">
                                <Label htmlFor="job-post-apply-url">{t("jobs.post.applyMethod.urlLabel")}</Label>
                                <Input
                                    id="job-post-apply-url"
                                    type="url"
                                    placeholder={t("jobs.post.applyMethod.urlPlaceholder")}
                                    maxLength={URL_MAX}
                                    value={applyUrl}
                                    onChange={(event) => setValue("applyUrl", event.target.value)}
                                />
                            </TextField>
                        ) : (
                            <TextField variant="secondary">
                                <Label htmlFor="job-post-apply-email">{t("jobs.post.applyMethod.emailLabel")}</Label>
                                <Input
                                    id="job-post-apply-email"
                                    type="email"
                                    placeholder={t("jobs.post.applyMethod.emailPlaceholder")}
                                    value={applyEmail}
                                    onChange={(event) => setValue("applyEmail", event.target.value)}
                                />
                            </TextField>
                        )),
                    ]} />
            )}
        />
    )
}

"use client"

import React, { useEffect, useState } from "react"
import { Button, Input, Label, TextField, Typography } from "@heroui/react"
import { XIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import type { UseFormSetValue } from "react-hook-form"
import { useQueryHeadhuntingCompanySuggestionsSwr } from "@/hooks/swr/api/graphql/queries/useQueryHeadhuntingCompanySuggestionsSwr"
import type { SubmitJobPostingFormValues } from "@/hooks/rhf/useSubmitJobPostingForm"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Debounce window (ms) before a typed search hits the suggestions backend. */
const SEARCH_DEBOUNCE_MS = 350
/** Max length of a new-company title (mirrors the `title` column cap used elsewhere). */
const COMPANY_TITLE_MAX = 255

/** Props for {@link CompanySection}. */
export interface CompanySectionProps {
    /** Chosen existing company id (empty = none picked yet). */
    companyId: string
    /** Chosen existing company's display label. */
    companyLabel: string
    /** New-company field values (used when no existing company is picked). */
    newCompanyTitle: string
    newCompanyLogoUrl: string
    newCompanyWebsiteUrl: string
    /** Sets a single form field. */
    setValue: UseFormSetValue<SubmitJobPostingFormValues>
}

/**
 * "Company" section of the job-post form: an ES-backed company typeahead to pick
 * an EXISTING {@link import("@/modules/types/entities/headhunting-company").HeadhuntingCompanyEntity},
 * or — when nothing is picked — a fallback set of fields to register a brand-new
 * company inline. Exactly one of the two paths feeds `submitJobPosting` (enforced
 * in {@link import("@/hooks/rhf/useSubmitJobPostingForm").useSubmitJobPostingForm}).
 *
 * @param props - {@link CompanySectionProps}
 */
export const CompanySection = ({
    companyId,
    companyLabel,
    newCompanyTitle,
    newCompanyLogoUrl,
    newCompanyWebsiteUrl,
    setValue,
}: CompanySectionProps) => {
    const t = useTranslations()

    const [query, setQuery] = useState("")
    const [debouncedQuery, setDebouncedQuery] = useState("")
    useEffect(() => {
        const handle = setTimeout(() => setDebouncedQuery(query), SEARCH_DEBOUNCE_MS)
        return () => clearTimeout(handle)
    }, [query])

    const { data: suggestionItems } = useQueryHeadhuntingCompanySuggestionsSwr(debouncedQuery)
    const suggestions = suggestionItems ?? []

    const hasPickedCompany = Boolean(companyId)

    return (
        <SurfaceCard
            label={t("jobs.post.sections.company")}

            body={() => (
                <StackV gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    items={[
                        () => (hasPickedCompany ? (
                            <Box principle="row-pad" className="rounded-2xl border border-default px-4 py-3"
                                explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                                <StackH gap={4} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    justify="between" align="center" items={[
                                        () => (
                                            <Typography type="body-sm" weight="medium">
                                                {companyLabel}
                                            </Typography>
                                        ),
                                        () => (
                                            <Button
                                                variant="tertiary"
                                                size="sm"
                                                onPress={() => {
                                                    setValue("companyId", "")
                                                    setValue("companyLabel", "")
                                                    setQuery("")
                                                }}
                                            >
                                                <XIcon aria-hidden focusable="false" className="size-4" />
                                                {t("jobs.post.company.change")}
                                            </Button>
                                        ),
                                    ]} />
                            </Box>
                        ) : (
                            <StackV gap={4} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    () => (
                                        <SearchInput
                                            value={query}
                                            onValueChange={setQuery}
                                            placeholder={t("jobs.post.company.searchPlaceholder")}
                                            suggestions={suggestions}
                                            onSelectSuggestion={(suggestion) => {
                                                setValue("companyId", suggestion.id)
                                                setValue("companyLabel", suggestion.label)
                                                setQuery("")
                                            }}
                                        />
                                    ),
                                    () => (
                                        <Typography type="body-xs" color="muted">
                                            {t("jobs.post.company.notFoundHint")}
                                        </Typography>
                                    ),
                                    () => (
                                        <Box principle="separator-dot" className="border-t border-default pt-3"
                                            explain="Places a middle-dot separator between short meta peers so the items read as one inline list.">
                                            <StackV gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                items={[
                                                    () => (
                                                        <TextField variant="secondary">
                                                            <Label htmlFor="job-post-new-company-title">
                                                                {t("jobs.post.company.newTitle")}
                                                            </Label>
                                                            <Input
                                                                id="job-post-new-company-title"
                                                                placeholder={t("jobs.post.company.newTitlePlaceholder")}
                                                                maxLength={COMPANY_TITLE_MAX}
                                                                value={newCompanyTitle}
                                                                onChange={(event) => setValue("newCompanyTitle", event.target.value)}
                                                            />
                                                        </TextField>
                                                    ),
                                                    () => (
                                                        <TextField variant="secondary">
                                                            <Label htmlFor="job-post-new-company-logo">
                                                                {t("jobs.post.company.newLogoUrl")}
                                                            </Label>
                                                            <Input
                                                                id="job-post-new-company-logo"
                                                                type="url"
                                                                placeholder={t("jobs.post.company.newLogoUrlPlaceholder")}
                                                                value={newCompanyLogoUrl}
                                                                onChange={(event) => setValue("newCompanyLogoUrl", event.target.value)}
                                                            />
                                                        </TextField>
                                                    ),
                                                    () => (
                                                        <TextField variant="secondary">
                                                            <Label htmlFor="job-post-new-company-website">
                                                                {t("jobs.post.company.newWebsiteUrl")}
                                                            </Label>
                                                            <Input
                                                                id="job-post-new-company-website"
                                                                type="url"
                                                                placeholder={t("jobs.post.company.newWebsiteUrlPlaceholder")}
                                                                value={newCompanyWebsiteUrl}
                                                                onChange={(event) => setValue("newCompanyWebsiteUrl", event.target.value)}
                                                            />
                                                        </TextField>
                                                    ),
                                                ]} />
                                        </Box>
                                    ),
                                ]} />
                        )),
                    ]} />
            )}
        />
    )
}

"use client"

import React from "react"
import {
    Input,
    Label,
    ListBox,
    Select,
    TextArea,
    TextField,
    Typography,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import type { UseFormSetValue } from "react-hook-form"
import type { SubmitJobPostingFormValues } from "@/hooks/rhf/useSubmitJobPostingForm"
import { JobEmploymentType } from "@/modules/types/enums/job-employment-type"
import { WorkMode } from "@/modules/types/enums/work-mode"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Grid } from "@/components/frames/Grid"
import { StackV } from "@/components/frames/Stack"

/** Max length of the job title. */
const TITLE_MAX = 255
/** Max length of the free-text location. */
const LOCATION_MAX = 100
/** Sentinel key for "no selection" in the employment-type / work-mode selects. */
const NONE_KEY = "none"

/** Employment-type options + their i18n label keys. */
const EMPLOYMENT_TYPE_OPTIONS = [
    { value: JobEmploymentType.Fulltime, labelKey: "jobs.employmentType.fulltime" },
    { value: JobEmploymentType.Parttime, labelKey: "jobs.employmentType.parttime" },
    { value: JobEmploymentType.Internship, labelKey: "jobs.employmentType.internship" },
    { value: JobEmploymentType.Contract, labelKey: "jobs.employmentType.contract" },
] as const

/** Work-mode options + their i18n label keys (reuses the existing profile labels). */
const WORK_MODE_OPTIONS = [
    { value: WorkMode.Remote, labelKey: "publicProfile.workMode.remote" },
    { value: WorkMode.Hybrid, labelKey: "publicProfile.workMode.hybrid" },
    { value: WorkMode.Onsite, labelKey: "publicProfile.workMode.onsite" },
] as const

/** Props for {@link PositionSection}. */
export interface PositionSectionProps {
    title: string
    employmentType: JobEmploymentType | ""
    workMode: WorkMode | ""
    location: string
    salaryMin: string
    salaryMax: string
    description: string
    requirements: string
    /** Sets a single form field. */
    setValue: UseFormSetValue<SubmitJobPostingFormValues>
}

/**
 * "Position" section of the job-post form — title, employment type,
 * work mode, location, salary range (blank + blank = negotiable), and the
 * markdown description / requirements.
 *
 * @param props - {@link PositionSectionProps}
 */
export const PositionSection = ({
    title,
    employmentType,
    workMode,
    location,
    salaryMin,
    salaryMax,
    description,
    requirements,
    setValue,
}: PositionSectionProps) => {
    const t = useTranslations()

    return (
        <SurfaceCard
            label={t("jobs.post.sections.position")}

            body={() => (
                <StackV gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    items={[
                        () => (
                            <TextField variant="secondary">
                                <Label htmlFor="job-post-title">{t("jobs.post.position.title")}</Label>
                                <Input
                                    id="job-post-title"
                                    placeholder={t("jobs.post.position.titlePlaceholder")}
                                    maxLength={TITLE_MAX}
                                    value={title}
                                    onChange={(event) => setValue("title", event.target.value)}
                                />
                            </TextField>
                        ),

                        () => (
                            <Grid columns={{ base: 1, sm: 2 }} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    {
                                        key: "employment-type",
                                        content: () => (
                                            <StackV gap={3} principle="label-field"
                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                items={[
                                                    () => <Label htmlFor="job-post-employment-type">{t("jobs.post.position.employmentType")}</Label>,
                                                    () => (
                                                        <Select.Root<{ id: string }, "single">
                                                            id="job-post-employment-type"
                                                            aria-label={t("jobs.post.position.employmentType")}
                                                            selectedKey={employmentType === "" ? NONE_KEY : employmentType}
                                                            onSelectionChange={(key) =>
                                                                setValue(
                                                                    "employmentType",
                                                                    key === NONE_KEY ? "" : (String(key) as JobEmploymentType),
                                                                )
                                                            }
                                                        >
                                                            <Select.Trigger aria-label={t("jobs.post.position.employmentType")}>
                                                                <Select.Value>
                                                                    {() => {
                                                                        const found = EMPLOYMENT_TYPE_OPTIONS.find(
                                                                            (option) => option.value === employmentType,
                                                                        )
                                                                        return (
                                                                            <Typography type="body-sm">
                                                                                {found ? t(found.labelKey) : t("jobs.post.position.employmentTypeNone")}
                                                                            </Typography>
                                                                        )
                                                                    }}
                                                                </Select.Value>
                                                                <Select.Indicator />
                                                            </Select.Trigger>
                                                            <Select.Popover>
                                                                <ListBox.Root aria-label={t("jobs.post.position.employmentType")}>
                                                                    <ListBox.Item id={NONE_KEY} textValue={t("jobs.post.position.employmentTypeNone")}>
                                                                        {t("jobs.post.position.employmentTypeNone")}
                                                                    </ListBox.Item>
                                                                    {EMPLOYMENT_TYPE_OPTIONS.map((option) => (
                                                                        <ListBox.Item key={option.value} id={option.value} textValue={t(option.labelKey)}>
                                                                            {t(option.labelKey)}
                                                                        </ListBox.Item>
                                                                    ))}
                                                                </ListBox.Root>
                                                            </Select.Popover>
                                                        </Select.Root>
                                                    ),
                                                ]} />
                                        ),
                                    },

                                    {
                                        key: "work-mode",
                                        content: () => (
                                            <StackV gap={3} principle="label-field"
                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                items={[
                                                    () => <Label htmlFor="job-post-work-mode">{t("jobs.post.position.workMode")}</Label>,
                                                    () => (
                                                        <Select.Root<{ id: string }, "single">
                                                            id="job-post-work-mode"
                                                            aria-label={t("jobs.post.position.workMode")}
                                                            selectedKey={workMode === "" ? NONE_KEY : workMode}
                                                            onSelectionChange={(key) =>
                                                                setValue("workMode", key === NONE_KEY ? "" : (String(key) as WorkMode))
                                                            }
                                                        >
                                                            <Select.Trigger aria-label={t("jobs.post.position.workMode")}>
                                                                <Select.Value>
                                                                    {() => {
                                                                        const found = WORK_MODE_OPTIONS.find(
                                                                            (option) => option.value === workMode,
                                                                        )
                                                                        return (
                                                                            <Typography type="body-sm">
                                                                                {found ? t(found.labelKey) : t("jobs.post.position.workModeNone")}
                                                                            </Typography>
                                                                        )
                                                                    }}
                                                                </Select.Value>
                                                                <Select.Indicator />
                                                            </Select.Trigger>
                                                            <Select.Popover>
                                                                <ListBox.Root aria-label={t("jobs.post.position.workMode")}>
                                                                    <ListBox.Item id={NONE_KEY} textValue={t("jobs.post.position.workModeNone")}>
                                                                        {t("jobs.post.position.workModeNone")}
                                                                    </ListBox.Item>
                                                                    {WORK_MODE_OPTIONS.map((option) => (
                                                                        <ListBox.Item key={option.value} id={option.value} textValue={t(option.labelKey)}>
                                                                            {t(option.labelKey)}
                                                                        </ListBox.Item>
                                                                    ))}
                                                                </ListBox.Root>
                                                            </Select.Popover>
                                                        </Select.Root>
                                                    ),
                                                ]} />
                                        ),
                                    },
                                ]} />
                        ),

                        () => (
                            <TextField variant="secondary">
                                <Label htmlFor="job-post-location">{t("jobs.post.position.location")}</Label>
                                <Input
                                    id="job-post-location"
                                    placeholder={t("jobs.post.position.locationPlaceholder")}
                                    maxLength={LOCATION_MAX}
                                    value={location}
                                    onChange={(event) => setValue("location", event.target.value)}
                                />
                            </TextField>
                        ),

                        () => (
                            <StackV gap={3} principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => (
                                        <Grid columns={{ base: 1, sm: 2 }} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={[
                                                {
                                                    key: "salary-min",
                                                    content: () => (
                                                        <TextField variant="secondary">
                                                            <Label htmlFor="job-post-salary-min">{t("jobs.post.position.salaryMin")}</Label>
                                                            <Input
                                                                id="job-post-salary-min"
                                                                type="number"
                                                                inputMode="numeric"
                                                                min={0}
                                                                placeholder={t("jobs.post.position.salaryPlaceholder")}
                                                                value={salaryMin}
                                                                onChange={(event) => setValue("salaryMin", event.target.value)}
                                                            />
                                                        </TextField>
                                                    ),
                                                },
                                                {
                                                    key: "salary-max",
                                                    content: () => (
                                                        <TextField variant="secondary">
                                                            <Label htmlFor="job-post-salary-max">{t("jobs.post.position.salaryMax")}</Label>
                                                            <Input
                                                                id="job-post-salary-max"
                                                                type="number"
                                                                inputMode="numeric"
                                                                min={0}
                                                                placeholder={t("jobs.post.position.salaryPlaceholder")}
                                                                value={salaryMax}
                                                                onChange={(event) => setValue("salaryMax", event.target.value)}
                                                            />
                                                        </TextField>
                                                    ),
                                                },
                                            ]} />
                                    ),
                                    () => (
                                        <Typography type="body-xs" color="muted">
                                            {t("jobs.post.position.salaryHint")}
                                        </Typography>
                                    ),
                                ]} />
                        ),

                        () => (
                            <TextField variant="secondary">
                                <Label htmlFor="job-post-description">{t("jobs.post.position.description")}</Label>
                                <TextArea
                                    id="job-post-description"
                                    rows={6}
                                    placeholder={t("jobs.post.position.descriptionPlaceholder")}
                                    className="resize-none"
                                    value={description}
                                    onChange={(event) => setValue("description", event.target.value)}
                                />
                            </TextField>
                        ),

                        () => (
                            <TextField variant="secondary">
                                <Label htmlFor="job-post-requirements">{t("jobs.post.position.requirements")}</Label>
                                <TextArea
                                    id="job-post-requirements"
                                    rows={5}
                                    placeholder={t("jobs.post.position.requirementsPlaceholder")}
                                    className="resize-none"
                                    value={requirements}
                                    onChange={(event) => setValue("requirements", event.target.value)}
                                />
                            </TextField>
                        ),
                    ]} />
            )}
        />
    )
}

"use client"

import React from "react"
import { Button, Typography } from "@heroui/react"
import { ArrowRightIcon, CheckCircleIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link SubmitSuccess}. */
export interface SubmitSuccessProps {
    /** Display id of the newly created posting, for the "view it" link. */
    jobDisplayId: string
}

/**
 * Persistent confirmation state shown after a successful `submitJobPosting` —
 * this is a full-page form (not a modal), so success is a screen the viewer can
 * read at their own pace, not a toast that disappears. Explains there is no
 * moderation queue (the posting is already live) and links onward to the new
 * listing or back to the board.
 *
 * @param props - {@link SubmitSuccessProps}
 */
export const SubmitSuccess = ({ jobDisplayId }: SubmitSuccessProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()

    return (
        <Box identity={{ tier: "page", component: "SubmitSuccess" }} principle="center-measure" className="mx-auto max-w-lg p-6 py-16 text-center"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
            <StackV gap={5} principle="group-boundary"
                explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                align="center" items={[
                    () => <CheckCircleIcon aria-hidden focusable="false" className="size-12 text-success-soft-foreground" />,
                    () => (
                        <Typography type="h4" weight="bold">
                            {t("jobs.post.success.title")}
                        </Typography>
                    ),
                    () => (
                        <Typography type="body-sm" color="muted">
                            {t("jobs.post.success.description")}
                        </Typography>
                    ),
                    () => (
                        <Box principle="push-end"
                            explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row."
                            className="mt-2">
                            <StackH gap={4} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                align="center" justify="center" at="sm" items={[
                                    () => (
                                        <Button
                                            variant="primary"
                                            onPress={() => router.push(pathConfig().locale(locale).jobs(jobDisplayId).build())}
                                        >
                                            {t("jobs.post.success.viewPosting")}
                                            <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                                        </Button>
                                    ),
                                    () => (
                                        <Button
                                            variant="secondary"
                                            onPress={() => router.push(pathConfig().locale(locale).jobs().build())}
                                        >
                                            {t("jobs.post.success.backToBoard")}
                                        </Button>
                                    ),
                                ]} />
                        </Box>
                    ),
                ]} />
        </Box>
    )
}

"use client"

import React, { useState } from "react"
import { Button, Spinner, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { CompanySection } from "./CompanySection"
import { PositionSection } from "./PositionSection"
import { ApplyMethodSection } from "./ApplyMethodSection"
import { SubmitSuccess } from "./SubmitSuccess"
import { useSubmitJobPostingForm } from "@/hooks/rhf/useSubmitJobPostingForm"
import { useAppSelector } from "@/redux/hooks"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link JobPostFormPage}. */
export type JobPostFormPageProps = Record<string, never>
/**
 * Public job-post form — `/jobs/post`. Any signed-in user can submit an opening;
 * it goes live immediately (no approval queue). Sections are grouped by MEANING
 * (company · position · how to apply), each an independent `LabeledCard` — not
 * one card per field. On success, replaces the form with a persistent
 * confirmation screen ({@link SubmitSuccess}) rather than a toast, since this is
 * a full page the viewer navigated to, not a modal.
 *
 * @param props - {@link JobPostFormPageProps}
 */
export const JobPostFormPage = () => {
    const t = useTranslations()
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const [submittedJobId, setSubmittedJobId] = useState<string | null>(null)

    const {
        watch,
        setValue,
        onSubmit,
        formState: { isSubmitting },
    } = useSubmitJobPostingForm({
        onSuccess: (jobPostingId) => setSubmittedJobId(jobPostingId),
    })

    const companyId = watch("companyId")
    const companyLabel = watch("companyLabel")
    const newCompanyTitle = watch("newCompanyTitle")
    const newCompanyLogoUrl = watch("newCompanyLogoUrl")
    const newCompanyWebsiteUrl = watch("newCompanyWebsiteUrl")
    const title = watch("title")
    const employmentType = watch("employmentType")
    const workMode = watch("workMode")
    const location = watch("location")
    const salaryMin = watch("salaryMin")
    const salaryMax = watch("salaryMax")
    const description = watch("description")
    const requirements = watch("requirements")
    const applyMethod = watch("applyMethod")
    const applyUrl = watch("applyUrl")
    const applyEmail = watch("applyEmail")

    if (submittedJobId) {
        return <SubmitSuccess jobDisplayId={submittedJobId} />
    }

    if (!authenticated) {
        return (
            <Box principle="center-measure"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
                className={"mx-auto max-w-2xl p-6 py-16 text-center"}>
                <StackV gap={3} principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    align="center" items={[
                        () => (
                            <Typography type="h5" weight="semibold" align="center">
                                {t("jobs.post.signedOut.title")}
                            </Typography>
                        ),
                        () => (
                            <Typography type="body-sm" color="muted" align="center">
                                {t("jobs.post.signedOut.description")}
                            </Typography>
                        ),
                    ]} />
            </Box>
        )
    }

    return (
        <Box principle="center-measure"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            className={"mx-auto max-w-2xl p-6"}>
            <StackV gap={7} principle="layout-split"
                explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                items={[
                    () => (
                        <PageHeader
                            title={t("jobs.post.title")}
                            description={t("jobs.post.description")}
                        />
                    ),
                    () => (
                        <form onSubmit={onSubmit}>
                            <StackV gap={6} principle="block-boundary"
                                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                items={[
                                    () => (
                                        <CompanySection
                                            companyId={companyId}
                                            companyLabel={companyLabel}
                                            newCompanyTitle={newCompanyTitle}
                                            newCompanyLogoUrl={newCompanyLogoUrl}
                                            newCompanyWebsiteUrl={newCompanyWebsiteUrl}
                                            setValue={setValue}
                                        />
                                    ),
                                    () => (
                                        <PositionSection
                                            title={title}
                                            employmentType={employmentType}
                                            workMode={workMode}
                                            location={location}
                                            salaryMin={salaryMin}
                                            salaryMax={salaryMax}
                                            description={description}
                                            requirements={requirements}
                                            setValue={setValue}
                                        />
                                    ),
                                    () => (
                                        <ApplyMethodSection
                                            applyMethod={applyMethod}
                                            applyUrl={applyUrl}
                                            applyEmail={applyEmail}
                                            setValue={setValue}
                                        />
                                    ),
                                    () => (
                                        <Button
                                            type="submit"
                                            variant="primary"
                                            size="lg"
                                            isDisabled={isSubmitting}
                                            isPending={isSubmitting}
                                        >
                                            {({ isPending }) => (
                                                <>
                                                    {isPending ? <Spinner color="current" size="sm" /> : null}
                                                    {t("jobs.post.submit")}
                                                </>
                                            )}
                                        </Button>
                                    ),
                                ]} />
                        </form>
                    ),
                ]} />
        </Box>
    )
}

import React from "react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { InfoTooltip } from "@/components/blocks/feedback/InfoTooltip"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { ProgressBar } from "@/components/atoms/display/Progress"
import { Container } from "@/components/frames/Container"
import { StackV, StackH } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import type { KpiKey } from "@/modules/api/graphql/queries/types/my-kpis"

/** Leading glyph a KPI row carries — matches `KPI_META`'s own `Icon` field shape. */
export type KpiRowIcon = React.ComponentType<{ className?: string }>

/** One quick-pick preset target button, already resolved to its disabled state. */
export interface KpiRowPreset {
    /** The preset's target value (e.g. `5`). */
    value: number
    /** `true` while a DIFFERENT preset (on this row or another) is mid-save. */
    isDisabled: boolean
}

/**
 * One weekly-KPI row, fully resolved by the connected {@link KpiPage}: icon + label,
 * current/target, its preset buttons, and its coin-reward claim state.
 */
export interface KpiRowData {
    /** The KPI key (matches BE `KpiKey`) — also the React key. */
    key: KpiKey
    /** Leading icon, decorative chrome (not data — shown regardless of load state). */
    icon: KpiRowIcon
    /** Already-translated row label. */
    label: string
    /** Current-week value. */
    current: number
    /** Effective target — the learner's custom goal, or a sensible default. */
    target: number
    /** Quick-pick target presets, each already carrying its disabled state. */
    presets: Array<KpiRowPreset>
    /** Persist a newly chosen preset target for this row. */
    onChoosePreset: (target: number) => void
    /** Already-translated "N coins" reward line; omitted → no coin-reward row (no target set server-side yet). */
    coinRewardText?: string
    /** `true` → the reward was already claimed this week. */
    claimed: boolean
    /** `true` → the reward is met and not yet claimed (shows the Claim button). */
    canClaim: boolean
    /** `true` while THIS row's claim mutation is in flight. */
    isClaiming: boolean
    /** `true` while a DIFFERENT row's claim mutation is in flight. */
    isClaimDisabled: boolean
    /** Claim this row's coin reward. */
    onClaim: () => void
}

/** All display text, already localized by the connected {@link KpiPage}; a story passes i18n keys. */
export interface KpiLabels {
    /** Page title, also the breadcrumb's current crumb and the info-tooltip heading. */
    title: string
    /** Info-tooltip explanation body for the title. */
    tooltipDescription: string
    /** Breadcrumb root ("Home") label. */
    homeLabel: string
    /** Full composite-score + reset-countdown sentence under the title. */
    description: string
    errorTitle: string
    retry: string
    /** Claim-button label, shared by every row. */
    claimLabel: string
    /** "Claimed" caption, shared by every row. */
    claimedLabel: string
}

/** Props for {@link _KpiPage} — presentational; all data resolved, no fetch/store/i18n. */
export interface KpiPageProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Truthy → the error message (beats loading). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Navigate to the dashboard (breadcrumb root). */
    onNavigateHome: () => void
    /** The six weekly-KPI rows, in display order. */
    rows: Array<KpiRowData>
    labels: KpiLabels
    /** Where this sits inside its parent. Appearance is not passable — it is already a prop. */
    classNames?: Array<AllowedClassName>
}

/**
 * One row's inner content — leading icon + label, current/target, the progress bar,
 * the quick-pick preset buttons, and the coin-reward claim line. `SurfaceCardList`
 * free-form `content` and `FlexWrapButtonRadio` carry no `isSkeleton` of their own
 * (`missingSkeletonSupport`), so the preset row is mirrored inline with `Skeleton.Button`
 * right where it sits rather than built as a second, hand-kept tree.
 */
const kpiRowBody = (row: KpiRowData, isSkeleton: boolean, labels: KpiLabels) => {
    const labelValueRow = () => (
        <StackH justify="between" gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                () => (
                    <StackH gap={3} principle="identity"
                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                        items={[
                            () => <row.icon className="size-5 shrink-0 text-foreground" />,
                            () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={row.label} />,
                        ]}
                    />
                ),
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? ["w-1/4"] : undefined}
                        text={`${row.current}/${row.target}`}
                    />
                ),
            ]}
        />
    )

    const presetRow = () => (
        isSkeleton ? (
            <StackH gap={3} principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                items={row.presets.map((preset) => () => (
                    <Skeleton.Button key={preset.value} width="w-16" />
                ))}
            />
        ) : (
            <FlexWrapButtonRadio
                ariaLabel={row.label}
                value={String(row.target)}
                onChange={(value) => row.onChoosePreset(Number(value))}
                items={row.presets.map((preset) => ({
                    value: String(preset.value),
                    content: preset.value,
                    isDisabled: preset.isDisabled,
                }))}
            />
        )
    )

    const coinRow = () => (
        <StackH justify="between" gap={3} principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            items={[
                () => (
                    <Typography
                        size="xs"
                        color={row.canClaim ? "accent-soft" : "muted"}
                        text={row.coinRewardText as string}
                    />
                ),
                ...(row.claimed
                    ? [() => <Typography size="xs" color="muted" text={labels.claimedLabel} />]
                    : row.canClaim
                        ? [() => (
                            <Button
                                variant="primary"
                                size="sm"
                                isPending={row.isClaiming}
                                isDisabled={row.isClaimDisabled}
                                onPress={row.onClaim}
                                label={labels.claimLabel}
                            />
                        )]
                        : []),
            ]}
        />
    )

    const rowItems = [
        labelValueRow,
        () => (
            <ProgressBar
                ariaLabel={row.label}
                value={row.current}
                max={row.target || 1}
                color="accent"
                size="sm"
                isSkeleton={isSkeleton}
            />
        ),
        presetRow,
        ...(!isSkeleton && row.coinRewardText ? [coinRow] : []),
    ]

    return <StackV gap={4} items={rowItems} />
}

/**
 * The `/kpi` editor page body — the presentational half of {@link KpiPage}: the
 * composite score header, then one joined row per weekly KPI (icon · label ·
 * current/target · progress · preset target buttons · coin-reward claim).
 * `PageHeader`/`ResponsiveBreadcrumb`/`InfoTooltip` carry no `isSkeleton` of their
 * own (`missingSkeletonSupport`), so the header zone is mirrored inline with
 * `Skeleton.*` right where it sits, rather than a separate hand-kept skeleton tree.
 * See `tiers/split.md` — the connected `index.tsx` owns the fetch, the mutations,
 * and i18n.
 *
 * @param props - {@link KpiPageProps}
 */
export const _KpiPage = ({
    isSkeleton = false,
    error,
    onRetry,
    onNavigateHome,
    rows,
    labels,
    classNames,
}: KpiPageProps) => {
    // error beats a stale loading flag (BLOCK-8) — the shared `AsyncContentError`
    // frame, not hand-written JSX (loading-and-skeleton.md §6).
    if (error) {
        return (
            <AsyncContentError
                title={labels.errorTitle}
                onRetry={onRetry}
                retryLabel={labels.retry}
            />
        )
    }

    const headerZone = () => (
        isSkeleton ? (
            <StackV gap={4} items={[
                () => <Skeleton.Breadcrumbs count={2} />,
                () => <Skeleton.Typography type="h3" width="1/3" />,
                () => <Skeleton.Typography type="body-sm" width="1/2" />,
            ]}
            />
        ) : (
            <PageHeader
                breadcrumb={(
                    <ResponsiveBreadcrumb
                        items={[
                            {
                                key: "home",
                                label: labels.homeLabel,
                                onPress: onNavigateHome,
                            },
                            {
                                key: "kpi",
                                label: labels.title,
                            },
                        ]}
                    />
                )}
                title={(
                    <InfoTooltip title={labels.title} description={labels.tooltipDescription}>
                        {labels.title}
                    </InfoTooltip>
                )}
                description={labels.description}
            />
        )
    )

    return (
        <Container
            identity={{ tier: "page", component: "KpiPage" }}
            size="sm"
            padding={6}
            isSkeleton={isSkeleton}
            classNames={classNames}
            body={() => (
                <StackV gap={7} items={[
                    headerZone,
                    () => {
                        const kpiItems: Array<SurfaceCardListItem> = rows.map((row) => ({
                            key: row.key,
                            content: () => kpiRowBody(row, isSkeleton, labels),
                        }))
                        return <SurfaceCardList items={kpiItems} />
                    },
                ]}
                />
            )}
        />
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import {
    KPI_META,
} from "@/modules/utils/kpi-meta"
import {
    DEFAULT_KPI_TARGETS,
} from "@/modules/utils/weekly-goals-map"
import { useQueryMyKpisSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyKpisSwr"
import { useMutateSetKpiTargetSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSetKpiTargetSwr"
import { useMutateClaimKpiRewardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateClaimKpiRewardSwr"
import type { KpiKey, QueryKpiItemData } from "@/modules/api/graphql/queries/types/my-kpis"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { _KpiPage, type KpiRowData } from "./component"

/**
 * Props for {@link KpiPage}. Only positioning — the route hands this nothing else, it
 * self-fetches. Renamed from the old `className: string` to the house
 * `classNames: Array<AllowedClassName>` convention every frame/atom already uses.
 */
export interface KpiPageProps {
    /** Where this sits inside its parent. Appearance is not passable — it is already a prop. */
    classNames?: Array<AllowedClassName>
}

/**
 * The `/kpi` editor page: the connected half of {@link _KpiPage}. Self-fetches the
 * weekly KPIs, owns the set-target + claim-reward mutations, resolves every
 * label (incl. interpolation), and hands them to the presentational `_KpiPage`.
 * See `tiers/split.md`.
 *
 * @param props - {@link KpiPageProps}
 */
export const KpiPage = ({
    classNames,
}: KpiPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { data, error, mutate } = useQueryMyKpisSwr()
    const { trigger: triggerSetTarget } = useMutateSetKpiTargetSwr()
    const { trigger: triggerClaimReward } = useMutateClaimKpiRewardSwr()
    const runGraphQL = useGraphQLWithToast()
    // the `${key}:${preset}` currently being saved, or null when idle
    const [savingKey, setSavingKey] = useState<string | null>(null)
    // the KPI key currently being claimed, or null when idle
    const [claimingKey, setClaimingKey] = useState<KpiKey | null>(null)

    /** Navigate to the DashboardPage (breadcrumb root). */
    const onNavigateHome = useCallback(
        () => router.push(pathConfig().locale(locale).build()),
        [router, locale],
    )

    /** Index the KPI items by key for O(1) lookup while rendering meta order. */
    const itemByKey = useMemo(
        () => {
            const map = new Map<KpiKey, QueryKpiItemData>()
            for (const item of data?.items ?? []) {
                map.set(item.key, item)
            }
            return map
        },
        [
            data,
        ],
    )

    /** Persist a chosen target for one KPI, then revalidate. */
    const onChoose = useCallback(
        async (key: KpiKey, target: number) => {
            setSavingKey(`${key}:${target}`)
            try {
                const ok = await runGraphQL(async () => {
                    const result = await triggerSetTarget({
                        key,
                        target,
                    })
                    const env = result?.data?.setKpiTarget
                    if (!env) {
                        throw new Error(t("DashboardPage.kpi.error"))
                    }
                    // returned envelope drives the success / error toast
                    return env
                })
                if (ok) {
                    await mutate()
                }
            } finally {
                setSavingKey(null)
            }
        },
        [
            triggerSetTarget,
            mutate,
            runGraphQL,
        ],
    )

    /** Claim one KPI's coin reward, then revalidate. */
    const onClaim = useCallback(
        async (key: KpiKey) => {
            setClaimingKey(key)
            try {
                const ok = await runGraphQL(async () => {
                    const result = await triggerClaimReward({
                        key,
                    })
                    const env = result?.data?.claimKpiReward
                    if (!env) {
                        throw new Error(t("DashboardPage.kpi.error"))
                    }
                    return env
                })
                if (ok) {
                    await mutate()
                }
            } finally {
                setClaimingKey(null)
            }
        },
        [
            triggerClaimReward,
            mutate,
            runGraphQL,
            t,
        ],
    )

    // days/hours left until the weekly reset — mirrors WeeklyBoard/WeeklyGoals
    const remaining = data ? Math.max(0, new Date(data.resetAt).getTime() - Date.now()) : 0
    const countdown = {
        days: Math.floor(remaining / 86_400_000),
        hours: Math.floor((remaining % 86_400_000) / 3_600_000),
    }

    // composite-score sentence (or the plain subtitle before any target is set) + the reset countdown
    const description = data
        ? (data.composite.total > 0
            ? t("DashboardPage.kpi.summary", {
                percent: data.composite.percent,
                completed: data.composite.completed,
                total: data.composite.total,
            })
            : t("DashboardPage.kpi.subtitle")) + ` · ${t("DashboardPage.kpi.resetIn", {
            days: countdown.days,
            hours: countdown.hours,
        })}`
        : ""

    // one resolved row per weekly KPI, meta order — presets carry their disabled
    // state pre-computed (a global save lock, matching the pre-split behaviour:
    // saving ANY preset on ANY row locks every OTHER preset everywhere).
    const rows: Array<KpiRowData> = KPI_META.map(({ key, Icon, labelKey, presets }) => {
        const item = itemByKey.get(key)
        const current = item?.current ?? 0
        // effective target = the learner's custom goal, or a sensible default
        // (mirrors the DashboardPage card — meter always runs, never sits empty waiting for config)
        const target = item?.target ?? DEFAULT_KPI_TARGETS[key]
        return {
            key,
            icon: Icon,
            label: t(`DashboardPage.kpi.labels.${labelKey}`),
            current,
            target,
            presets: presets.map((preset) => ({
                value: preset,
                isDisabled: savingKey !== null && savingKey !== `${key}:${preset}`,
            })),
            onChoosePreset: (chosenTarget: number) => {
                void onChoose(key, chosenTarget)
            },
            coinRewardText: item?.coinReward != null
                ? t("DashboardPage.kpi.coinReward", {
                    count: item.coinReward,
                })
                : undefined,
            claimed: item?.claimed ?? false,
            canClaim: item?.canClaim ?? false,
            isClaiming: claimingKey === key,
            isClaimDisabled: claimingKey !== null && claimingKey !== key,
            onClaim: () => {
                void onClaim(key)
            },
        }
    })

    return (
        <_KpiPage
            // first load with no cached data → skeleton; a first-load query error
            // shows the retryable error slot instead of a permanent skeleton
            isSkeleton={!data}
            error={!data ? error : undefined}
            onRetry={() => {
                void mutate()
            }}
            onNavigateHome={onNavigateHome}
            rows={rows}
            classNames={classNames}
            labels={{
                title: t("DashboardPage.kpi.title"),
                tooltipDescription: t("DashboardPage.kpi.help"),
                homeLabel: t("nav.home"),
                description,
                errorTitle: t("DashboardPage.loadError"),
                retry: t("DashboardPage.retry"),
                claimLabel: t("DashboardPage.kpi.claimReward"),
                claimedLabel: t("DashboardPage.kpi.claimed"),
            }}
        />
    )
}

"use client"

import React from "react"
import { Handle, type NodeProps, Position } from "@xyflow/react"
import { Button, Typography, cn } from "@heroui/react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { TRACK_CONFIG, NODE_DEGREE, bubbleRadius, type TrackKey } from "@/modules/utils/knowledge-graph-data"
import { LANDING_TRACK_TAG } from "@/modules/utils/landing-constants"

/** React Flow node-type id for a knowledge-graph concept. */
export const CONCEPT_NODE_TYPE = "concept" as const

/** Data carried on a concept node. */
export interface ConceptNodeData {
    label: string
    track: TrackKey
    /** Dim when another node is hovered and this one isn't connected to it. */
    dimmed?: boolean
    /** This node is the one whose popover is open. */
    selected?: boolean
    /** Open the flagship course that teaches this concept. */
    onOpenCourse?: (track: TrackKey) => void
    [key: string]: unknown
}

/** Centred, invisible handle — kept for layout/positioning only (no edges are drawn). */
const centreHandleClass = "!size-0 !min-w-0 !border-0 !bg-transparent"
const centreHandleStyle = { left: "50%", top: "50%", transform: "translate(-50%, -50%)" } as const

/**
 * A glowing concept BUBBLE — a translucent track-coloured circle sized by its degree
 * (hubs big, leaves small) + soft glow + colored ring, with the label CENTRED on it,
 * its font scaled by the same degree (hub labels read bigger). No connecting edges —
 * a pure constellation. When `selected`, a popover floats above with a one-line blurb
 * (i18n by node id) + an "Enter course" CTA.
 *
 * @param props - React Flow {@link NodeProps} carrying {@link ConceptNodeData}.
 */
export const ConceptNode = ({ id, data }: NodeProps) => {
    const { label, track, dimmed, selected, onOpenCourse } = data as ConceptNodeData
    const t = useTranslations()
    const cfg = TRACK_CONFIG[track]
    const degree = NODE_DEGREE[id] ?? 1
    const r = bubbleRadius(degree)
    const fontSize = Math.round(11 + degree * 0.8)
    return (
        <div
            className={cn("relative cursor-pointer transition-opacity duration-300", dimmed && "opacity-25")}
            style={{ width: r * 2, height: r * 2 }}
        >
            {/* bubble — diameter ∝ degree; translucent track fill + colored ring + soft glow */}
            <div
                className={cn("absolute inset-0 rounded-full border", cfg.ring, selected && "ring-2 ring-accent")}
                style={{
                    backgroundColor: `color-mix(in oklch, ${cfg.glow} 22%, transparent)`,
                    boxShadow: `0 0 ${Math.round(r * 0.9)}px -2px ${cfg.glow}`,
                }}
            >
                <Handle type="target" position={Position.Top} isConnectable={false} className={centreHandleClass} style={centreHandleStyle} />
                <Handle type="source" position={Position.Bottom} isConnectable={false} className={centreHandleClass} style={centreHandleStyle} />
            </div>
            {/* label centred ON the bubble; font scales with degree (may overflow small bubbles) */}
            <span
                className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 text-center font-medium whitespace-nowrap text-foreground"
                style={{ fontSize }}
            >
                {label}
            </span>

            {selected ? (
                <div
                    data-principle="cell-pad" className="nodrag nopan absolute bottom-full left-1/2 z-50 mb-2 w-60 -translate-x-1/2 cursor-default rounded-2xl border border-default bg-surface p-3 text-left"

                    onClick={(event) => event.stopPropagation()}
                >
                    <div data-principle="identity" className="mb-1 flex items-center gap-2">
                        <span aria-hidden className={cn("size-1.5 shrink-0 rounded-full", cfg.dot)} />
                        <span className="text-xs font-semibold text-foreground">{label}</span>
                        <span data-principle="push-end" className="ml-auto text-[10px] text-muted">{LANDING_TRACK_TAG[track]}</span>
                    </div>
                    <Typography type="body-xs" color="muted" className="whitespace-normal">
                        {t(`landing.treasure.graph.${id}`)}
                    </Typography>
                    <Button variant="primary" size="sm" className="mt-2" onPress={() => onOpenCourse?.(track)}>
                        {t("landing.courses.view")}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-3.5" />
                    </Button>
                </div>
            ) : null}
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useState } from "react"
import { motion, useReducedMotion } from "framer-motion"
import { ArrowsClockwiseIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"

/** How long the ring takes to fill before it auto-reshuffles the graph (ms). */
const PERIOD_MS = 10000
const RADIUS = 10
const CIRCUMFERENCE = 2 * Math.PI * RADIUS

/** Props for {@link ShuffleBeacon}. */
interface ShuffleBeaconProps {
    /** Re-shuffle (re-layout) the graph nodes. */
    onShuffle: () => void
}

/**
 * A DeFi-swap-style countdown beacon: a ring fills over {@link PERIOD_MS}; when full it
 * auto-reshuffles the graph (re-runs the force layout into a fresh arrangement), then
 * restarts. Clicking it reshuffles immediately + restarts the ring. Honours reduced-
 * motion (no auto-cadence; the manual tap still works). Sits in the graph's bottom-left.
 *
 * @param props - {@link ShuffleBeaconProps}
 */
export const ShuffleBeacon = ({ onShuffle }: ShuffleBeaconProps) => {
    const t = useTranslations()
    const reduce = useReducedMotion()
    // bump to restart the ring (auto-fire on cooldown, or manual tap)
    const [cycle, setCycle] = useState(0)

    useEffect(() => {
        if (reduce) {
            return
        }
        const id = setTimeout(() => {
            onShuffle()
            setCycle((value) => value + 1)
        }, PERIOD_MS)
        return () => clearTimeout(id)
    }, [cycle, onShuffle, reduce])

    const trigger = useCallback(() => {
        onShuffle()
        setCycle((value) => value + 1)
    }, [onShuffle])

    return (
        <button
            type="button"
            onClick={trigger}
            title={t("landing.treasure.beaconTap")}
            aria-label={t("landing.treasure.beaconTap")}
            data-principle="flex-action" className="nodrag nopan group flex cursor-pointer items-center gap-2 rounded-full border border-default bg-surface/80 py-2 pr-3 pl-2 text-xs text-muted backdrop-blur-sm transition-colors hover:text-foreground"
        >
            <span className="relative inline-flex size-6 items-center justify-center">
                <svg viewBox="0 0 26 26" className="size-6 -rotate-90">
                    <circle cx="13" cy="13" r={RADIUS} fill="none" stroke="var(--default)" strokeWidth="2.5" />
                    {reduce ? null : (
                        <motion.circle
                            key={cycle}
                            cx="13"
                            cy="13"
                            r={RADIUS}
                            fill="none"
                            stroke="var(--accent)"
                            strokeWidth="2.5"
                            strokeLinecap="round"
                            strokeDasharray={CIRCUMFERENCE}
                            initial={{ strokeDashoffset: CIRCUMFERENCE }}
                            animate={{ strokeDashoffset: 0 }}
                            transition={{ duration: PERIOD_MS / 1000, ease: "linear" }}
                        />
                    )}
                </svg>
                <ArrowsClockwiseIcon
                    aria-hidden
                    weight="bold"
                    className="absolute size-3 text-accent-soft-foreground transition-transform duration-300 group-hover:rotate-180"
                />
            </span>
            <span className="hidden @app-sm:inline">{t("landing.treasure.beaconLabel")}</span>
        </button>
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react"
import {
    Background,
    BackgroundVariant,
    type Edge,
    type Node,
    type NodeMouseHandler,
    type OnNodeDrag,
    Panel,
    ReactFlow,
    ReactFlowProvider,
    useEdgesState,
