"use client"

import React from "react"
import {
    Accordion,
    Button,
    Link,
    Typography,
} from "@heroui/react"
import {
    ArrowRightIcon,
    ArrowUpIcon,
    CaretRightIcon,
    CloudArrowUpIcon,
    CubeIcon,
    StackIcon,
    TreeStructureIcon,
    UserIcon,
} from "@phosphor-icons/react"
import { FaFacebook, FaGithub, FaLinkedin } from "react-icons/fa6"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import dynamic from "next/dynamic"
/** Hero architecture diagram in real 3D (WebGL/R3F). Client-only — never SSRs;
 * while the WebGL chunk loads, show a neutral sized skeleton (the old fallback
 * was a *different* SVG diagram → jarring swap to the 3D scene). */
const ArchitectureScene3D = dynamic(
    () => import("@/components/blocks/marketing/ArchitectureScene").then((m) => m.ArchitectureScene),
    {
        ssr: false,
        loading: () => (
            <div
                aria-hidden
                className="h-[440px] w-full animate-pulse rounded-3xl bg-default/20 @app-sm:h-[560px]"
            />
        ),
    },
)
import { pathConfig } from "@/resources/path"
import { FOUNDER_FACEBOOK, FOUNDER_GITHUB, FOUNDER_LINKEDIN } from "@/resources/contact"
import { StatStrip } from "./StatStrip"
import { TalentMarketplace } from "./TalentMarketplace"
import { LearnLoopScroll } from "./LearnLoopScroll"
import { KnowledgeGraph } from "./KnowledgeGraph"
import { KNOWLEDGE_NODES } from "@/modules/utils/knowledge-graph-data"
import {
    LANDING_COURSE_TRACKS,
    LANDING_FAQ_INDEXES,
    LANDING_FOUNDER_TRUTH_INDEXES,
    LANDING_HERO_KEYWORDS,
    LANDING_ROADMAP_TIERS,
    LANDING_TRACK_COURSE_SLUG,
} from "@/modules/utils/landing-constants"
import { HeroBanner } from "@/components/blocks/marketing/HeroBanner"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SectionHeading } from "@/components/blocks/marketing/SectionHeading"
import { TrackCard } from "@/components/blocks/marketing/TrackCard"
import { TruthList } from "@/components/blocks/marketing/TruthList"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Icon per featured course track. */
const COURSE_TRACK_ICONS: Record<string, React.ReactNode> = {
    fullstack: <StackIcon aria-hidden focusable="false" />,
    systemDesign: <TreeStructureIcon aria-hidden focusable="false" />,
    devops: <CloudArrowUpIcon aria-hidden focusable="false" />,
}

/** Metro line colour per track. */
const TRACK_LINE_COLOR: Record<string, "accent" | "success" | "warning"> = {
    fullstack: "accent",
    systemDesign: "success",
    devops: "warning",
}

/** Founder social proof links (brand-icon row in the founder beat). */
const FOUNDER_SOCIALS = [
    { key: "github", href: FOUNDER_GITHUB, icon: FaGithub, label: "GitHub" },
    { key: "linkedin", href: FOUNDER_LINKEDIN, icon: FaLinkedin, label: "LinkedIn" },
    { key: "facebook", href: FOUNDER_FACEBOOK, icon: FaFacebook, label: "Facebook" },
] as const

/** Props for {@link LandingPage}. */
export type LandingPageProps = Record<string, never>
/**
 * Public landing page. Show-don't-tell information architecture: hero → live
 * proof → the wedge (challenge + AI grading) → track ladder → founder beat →
 * recruiter proof → two-sided outcomes → course catalog (conversion) → FAQ →
 * closing CTA. Real data only (platform stats, open-to-work talent, courses);
 * narrative beats stay tight. Container reads SWR + i18n and composes blocks;
 * all styling lives in the blocks.
 *
 * @param props - optional className (placement only).
 */
export const LandingPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()

    /** Smooth-scroll to the embedded course catalog (the conversion surface). */
    const onSeeCourses = () => {
        document.getElementById("courses")?.scrollIntoView({ behavior: "smooth" })
    }
    const onLogin = () => router.push(pathConfig().locale(locale).authentication().build())

    // Back-to-top FAB — shows after scrolling past the first screen (scrollY > 600), click smooth-scrolls back to the top.
    const [showTop, setShowTop] = React.useState(false)
    React.useEffect(() => {
        const onScroll = () => setShowTop(window.scrollY > 600)
        window.addEventListener("scroll", onScroll, { passive: true })
        onScroll()
        return () => window.removeEventListener("scroll", onScroll)
    }, [])

    // HERO only fills the first fold (min-height = viewport − navbar, dvh prevents the mobile
    // URL bar from causing jumps, vertically centered). Other beats shrink to their content
    // (no min-h) → no more "half-empty screen", and rhythm is even via the root gap.
    const screen = "flex min-h-[calc(100dvh-4rem)] flex-col justify-center"

    return (
        <div>
            {/* Section-to-section rhythm: gap-16→20 (64–80px) between beats. ONLY the HERO is
                min-h-screen; other beats shrink to their content → this small gap is REAL
                whitespace, enough to separate sections without a short section (stats,
                learn-loop) drifting in the middle of a half-empty screen. */}
            <Box principle="center-measure" className="mx-auto flex max-w-6xl flex-col gap-16 px-4 pt-8 pb-16 @app-sm:px-6 @app-md:gap-20 @app-md:pb-20 @app-md:pt-10 @app-lg:px-8"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                {/* 1 — Hero */}
                <div className={screen}>
                    <HeroBanner
                        eyebrow={t("landing.hero.eyebrow")}
                        eyebrowIcon={<CubeIcon aria-hidden focusable="false" className="size-3" />}
                        headline={t.rich("landing.hero.headline", {
                            accent: (chunks) => <span className="text-accent-soft-foreground">{chunks}</span>,
                        })}
                        subline={t("landing.hero.subline")}
                        primary={(
                            <Button variant="primary" size="lg" onPress={onSeeCourses}>
                                {t("landing.hero.ctaPrimary")}
                                <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                            </Button>
                        )}
                        secondary={(
                            <Button variant="secondary" size="lg" onPress={onLogin}>
                                {t("landing.hero.ctaSecondary")}
                            </Button>
                        )}
                        keywords={LANDING_HERO_KEYWORDS}
                        keywordsLabel={t("landing.hero.solveWith")}
                        visual={(
                        // grounded StarCi backend topology in real 3D (R3F) — the System Design
                        // value prop made visible (no image; client-only, SVG fallback while loading).
                            <ArchitectureScene3D caption={t("landing.hero.diagramCaption")} />
                        )}
                    />
                </div>

                {/* 2 — Live proof strip + "transparent" header: frames REAL numbers (early,
                    small) as an honest signal instead of bragging. Header → strip = gap-16
                    (synced with other sections); spacing between beats is handled by the root gap. */}
                <div id="stats" className="flex scroll-mt-24 flex-col gap-16">
                    <SectionHeading
                        anchorId="stats"
                        eyebrow={t("landing.stats.eyebrow")}
                        title={t("landing.stats.title")}
                        intro={t("landing.stats.intro")}
                    />
                    <StatStrip />
                </div>

                {/* 3 — 4-step learn loop (read → grade → capstone → rank): scroll-pinned
                    scrollytelling (section pins, scroll → active step + visual must change;
                    scroll finishes → releases). Falls back to a static layout on
                    mobile / reduced-motion. */}
                <LearnLoopScroll />

                {/* 3 — Roadmap: 3 flagship tracks. Each card = identity (icon/module/tag/title/desc)
                    + tier path (foundation → application) + "Enter course" → the real course. Merged
                    from 2 old sections (Courses + Roadmap) since track = course → avoids rendering
                    the same 3 tracks twice. */}
                <section id="courses" className="flex scroll-mt-24 flex-col gap-12">
                    <SectionHeading
                        anchorId="courses"
                        eyebrow={t("landing.courses.eyebrow")}
                        title={t("landing.courses.title")}
                        intro={t("landing.courses.intro")}
                    />
                    {/* "Three roadmaps · one mindset": each track = 1 self-contained card (identity +
                        a VERTICAL 4-tier path foundation→application + "Enter course" → the real
                        course). 3 cards side by side to read + compare; the same 4-tier structure
                        = "one mindset". */}
                    <Box principle="block-boundary" className="grid grid-cols-1 gap-6 @app-md:grid-cols-3"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups.">
                        {LANDING_COURSE_TRACKS.map((key) => (
                            <TrackCard
                                key={key}
                                icon={COURSE_TRACK_ICONS[key]}
                                title={t(`landing.courses.items.${key}.title`)}
                                meta={`${t(`landing.courses.items.${key}.modules`)} · ${t(`landing.courses.items.${key}.systems`)}`}
                                color={TRACK_LINE_COLOR[key]}
                                tiers={LANDING_ROADMAP_TIERS[key]}
                                viewLabel={t("landing.courses.view")}
                                onView={() => router.push(pathConfig().locale(locale).course(LANDING_TRACK_COURSE_SLUG[key]).build())}
                            />
                        ))}
                    </Box>
                </section>

                {/* Skill map — SPLIT: "flex your skills" copy (left) + knowledge graph contained
                    (right). The graph is NO LONGER full-bleed (no more "sprawling everywhere") but
                    keeps the interactive wow factor. */}
                <section id="treasure" className="scroll-mt-24">
                    <div className="grid grid-cols-1 items-center gap-10 @app-lg:grid-cols-[0.85fr_1.15fr] @app-lg:gap-12">
                        {/* LEFT — flex copy: heading + editorial stat + interconnection line + CTA */}
                        <StackV gap={6} principle="block-boundary"
                            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                            items={[
                                () => (
                                    <SectionHeading
                                        anchorId="treasure"
                                        align="start"
                                        eyebrow={t("landing.treasure.eyebrow")}
                                        title={t("landing.treasure.title")}
                                        intro={t("landing.treasure.intro")}
                                    />
                                ),
                                () => (
                                    <StackH gap={6} principle="block-boundary"
                                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                        items={[
                                            () => (
                                                <div className="flex flex-col">
                                                    <span className="text-3xl font-medium tracking-tight text-foreground @app-sm:text-4xl">
                                                        {KNOWLEDGE_NODES.length}
                                                    </span>
                                                    <Typography type="body-xs" color="muted">
                                                        {t("landing.treasure.statConcepts")}
                                                    </Typography>
                                                </div>
                                            ),
                                            () => <span aria-hidden className="h-10 w-px bg-default" />,
                                            () => (
                                                <div className="flex flex-col">
                                                    <span className="text-3xl font-medium tracking-tight text-foreground @app-sm:text-4xl">
                                                        {LANDING_COURSE_TRACKS.length}
                                                    </span>
                                                    <Typography type="body-xs" color="muted">
                                                        {t("landing.treasure.statTracks")}
                                                    </Typography>
                                                </div>
                                            ),
                                        ]} />
                                ),
                                () => (
                                    <Typography type="body-sm" color="muted">
                                        {t("landing.treasure.interconnect")}
                                    </Typography>
                                ),
                                () => (
                                    <Button variant="primary" size="lg" onPress={onSeeCourses} className="self-start">
                                        {t("landing.treasure.cta")}
                                        <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                                    </Button>
                                ),
                            ]} />
                        {/* RIGHT — knowledge graph contained: ~38 REAL concepts (nodes) linked by
                            builds-on + cross-track relations (d3-force live, drag/zoom). Node colour
                            follows its track, click → the course containing it. "Interconnected
                            knowledge" (Qdrant vibe, @xyflow). */}
                        <KnowledgeGraph />
                    </div>
                </section>

                {/* 5 — Founder beat */}
                <section id="founder" className="flex scroll-mt-24 flex-col gap-12">
                    <SectionHeading
                        anchorId="founder"
                        eyebrow={t("landing.founder.eyebrow")}
                        title={t("landing.founder.title")}
                        intro={t("landing.founder.thesis")}
                    />
                    {/* the uncomfortable truths are the hero; the founder recedes to a
                        byline (who's saying this), each truth anchored to a real mechanism */}
                    <TruthList
                        items={LANDING_FOUNDER_TRUTH_INDEXES.map((index) => ({
                            truth: t(`landing.founder.truth${index}`),
                            fix: t(`landing.founder.fix${index}`),
                        }))}
                        byline={(
                            <>
                                <IconTile
                                    size="sm"
                                    tone="accent"
                                    src="/landing/founder.jpg"
                                    alt={t("landing.founder.name")}
                                    icon={<UserIcon aria-hidden focusable="false" />}
                                />
                                <StackV gap={3} principle="sibling-stack" classNames={["min-w-0"]}
                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={[
                                        () => (
                                            <Typography type="body-sm" weight="semibold">
                                                {t("landing.founder.name")}
                                            </Typography>
                                        ),
                                        () => (
                                            <Typography type="body-xs" color="muted">
                                                {t("landing.founder.titles")}
                                            </Typography>
                                        ),
                                    ]} />
                                <div data-principle="content-row" className="flex items-center gap-3 @app-sm:ml-auto">
                                    {/* social proof — brand icons (GitHub · LinkedIn · Facebook) */}
                                    {FOUNDER_SOCIALS.map(({ key, href, icon: Icon, label }) => (
                                        <Link
                                            key={key}
                                            href={href}
                                            target="_blank"
                                            aria-label={label}
                                            className="text-muted transition-colors hover:text-accent-soft-foreground"
                                        >
                                            <Icon aria-hidden className="size-4" />
                                        </Link>
                                    ))}
                                    {/* blog = "go read + judge the quality yourself" CTA */}
                                    <Link href={pathConfig().locale(locale).blog().build()} data-principle="flex-action" className="inline-flex items-center gap-2 text-accent-soft-foreground">
                                        {t("landing.founder.blog")}
                                        <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                                    </Link>
                                </div>
                            </>
                        )}
                    />
                </section>

                {/* 6 — Two-sided talent marketplace (engineer outcome + recruiter browse, product-led) */}
                <TalentMarketplace />

                {/* 9 — FAQ */}
                <section id="faq" className="flex scroll-mt-24 flex-col gap-12">
                    <SectionHeading
                        anchorId="faq"
                        eyebrow={t("landing.faq.eyebrow")}
                        title={t("landing.faq.title")}
                    />
                    <Accordion variant="surface">
                        {LANDING_FAQ_INDEXES.map((index) => (
                            <Accordion.Item key={index} aria-label={t(`landing.faq.q${index}`)}>
                                <Accordion.Heading>
                                    <Accordion.Trigger>
                                        <Typography type="body-sm" weight="medium">
                                            {t(`landing.faq.q${index}`)}
                                        </Typography>
                                    </Accordion.Trigger>
                                </Accordion.Heading>
                                <Accordion.Panel>
                                    <Accordion.Body>
                                        <Typography type="body-sm" color="muted">
                                            {t(`landing.faq.a${index}`)}
                                        </Typography>
                                    </Accordion.Body>
                                </Accordion.Panel>
                            </Accordion.Item>
                        ))}
                    </Accordion>
                </section>

                {/* 10 — Closing CTA */}
                <StackV as="section" align="center" gap={6} principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV align="center" gap={4} principle="card-caption"
                                explain="Holds caption text under card media so the caption stays attached to the image above it."
                                items={[
                                    () => (
                                        <Typography.Heading level={2} weight="bold" align="center" className="max-w-2xl">
                                            {t("landing.closing.title")}
                                        </Typography.Heading>
                                    ),
                                    () => (
                                        <Typography type="body" color="muted" align="center" className="max-w-xl">
                                            {t("landing.closing.subtitle")}
                                        </Typography>
                                    ),
                                ]} />
                        ),
                        () => (
                            <Button variant="primary" size="lg" onPress={onSeeCourses}>
                                {t("landing.closing.cta")}
                                <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />
                            </Button>
                        ),
                    ]} />
            </Box>

            {/* Back-to-top FAB — floats bottom-right (primary accent), shows after scrolling past the first screen */}
            {showTop ? (
                <Button
                    isIconOnly
                    variant="primary"
                    aria-label={t("landing.backToTop")}
                    onPress={() => window.scrollTo({ top: 0, behavior: "smooth" })}
                    className="fixed bottom-6 right-[calc(var(--app-rail-w,0px)+1.5rem)] z-40 size-12 rounded-full shadow-lg"
                >
                    <ArrowUpIcon aria-hidden focusable="false" className="size-5" />
                </Button>
            ) : null}
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import Link from "next/link"
import {
    TrophyIcon,
} from "@phosphor-icons/react"
import {
    AsyncContentEmpty,
} from "@/components/composites/async/AsyncContent"
import {
    Typography,
} from "@/components/atoms/text/Typography"
import {
    Box,
} from "@/components/frames/Box"
import {
    StackV,
    StackH,
} from "@/components/frames/Stack"
import {
    Skeleton,
} from "@/components/blocks/skeleton/Skeleton"
import {
    UserCell,
} from "@/components/composites/lists/UserCell"
import {
    StandingHeroCard,
    type StandingHeroProgress,
} from "@/components/blocks/dashboard/StandingHeroCard"
import {
    Podium,
} from "@/components/blocks/dashboard/Podium"
import {
    IconTile,
} from "@/components/blocks/identity/IconTile"
import {
    SurfaceCardList,
    type SurfaceCardListItem,
} from "@/components/composites/cards/SurfaceCard"
import {
    FollowButton,
} from "@/components/blocks/community/FollowButton"
import {
    Confetti,
} from "@/components/blocks/dashboard/Confetti"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** How many placeholder rank-4+ rows the co-located skeleton shows. */
const SKELETON_ROW_COUNT = 6

/** One top-3 podium finisher, already resolved (points formatted, "mine" decided). */
export interface GlobalBoardPodiumEntry {
    rank: number
    username: string | null
    avatar: string | null
    /** Already-translated points label, e.g. "1420 XP". */
    pointsLabel: string
    /** True when this finisher is the viewer — ring-accent avatar + accent name (`Podium`'s own contract). */
    isMe: boolean
}

/**
 * One rank-4+ row, already resolved: display name already carries the — · You"
 * suffix when it's the viewer's own row (matches the connected file's old
 * string composition), follow state resolved from the connected file's sets.
 */
export interface GlobalBoardRow {
    key: string
    rank: number
    isMine: boolean
    /** Already composed with the — · You" suffix when {@link GlobalBoardRow.isMine}. */
    displayName: string
    avatar: string | null
    profileHref: string
    /** Already-translated points label, e.g. "1420 XP". */
    pointsLabel: string
    following: boolean
    isPending: boolean
    onToggleFollow: () => void
}

/** The viewer's own pinned row, appended after an ellipsis when they sit below the fetched slice. */
export interface GlobalBoardSelfRow {
    rank: number
    /** Already composed with the — · You" suffix (matches the connected file's old string composition). */
    displayName: string
    avatar: string | null
    /** Already-translated points label. */
    pointsLabel: string
}

/** Props for {@link _GlobalBoard} — presentational; all data resolved, no fetch/store/i18n. */
export interface GlobalBoardProps extends WithClassNames<undefined> {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no ranked entries → the empty message (funnel to courses). */
    isEmpty?: boolean

    /** Rank-driven badge art for the standing hero (`rankBadgeIcon`) — already a built node (block API). */
    rankBadge?: ReactNode
    /** e.g. "Rank #9 platform-wide". */
    rankLabel?: string
    /** e.g. "1420 XP". */
    pointsMeta?: string
    /** Goal-gradient meter toward the next rank; omitted when the viewer is already #1 or has no baseline. */
    progress?: StandingHeroProgress
    /** North-star CTA label — funnels to courses. Shown on the hero and (as the retry action) on the empty state. */
    climbCtaLabel: string
    onClimb: () => void

    /** Top-3 finishers for the podium. */
    podiumEntries?: Array<GlobalBoardPodiumEntry>
    /** "You" suffix label for the podium's own finisher. */
    meLabel: string

    /** Rank 4+ rows. Shown whenever there's more than the podium, or the viewer sits below it. */
    rows?: Array<GlobalBoardRow>
    /** Whether the rank-4+ section renders at all (mirrors the connected file's old gate). */
    showRows?: boolean
    /** Pinned self-row appended after an ellipsis when the viewer sits below the fetched slice. */
    selfRow?: GlobalBoardSelfRow
    /** "{count} more" between the fetched slice and the pinned self-row; omitted when there's no gap. */
    hiddenBetweenLabel?: string

    /** Bumped to fire a confetti burst on a top-3 platform finish. */
    celebrateKey?: number

    emptyTitle: string
    emptyDescription: string
}

/**
 * The global (all-users) leaderboard — presentational half of {@link import("./index").GlobalBoard}.
 * Same shell as the weekly board: a {@link StandingHeroCard} of the viewer's platform-wide standing,
 * the top-3 {@link Podium}, then rank 4+ as a followable {@link SurfaceCardList}. `isSkeleton`
 * threads down to every leaf; `StandingHeroCard`/`Podium`/`IconTile`/`SurfaceCardList`/`FollowButton`/
 * `UserCell` take no `isSkeleton` of their own (`missingSkeletonSupport`), so each is mirrored in
 * place with `Skeleton.*` at the exact position it renders, instead of a parallel skeleton tree. See
 * `tiers/split.md` — the connected `index.tsx` owns the fetch, the follow mutation, and every label.
 *
 * @param props - {@link GlobalBoardProps}
 */
export const _GlobalBoard = ({
    className,
    isSkeleton = false,
    isEmpty = false,
    rankBadge,
    rankLabel,
    pointsMeta,
    progress,
    climbCtaLabel,
    onClimb,
    podiumEntries = [],
    meLabel,
    rows = [],
    showRows = false,
    selfRow,
    hiddenBetweenLabel,
    celebrateKey = 0,
    emptyTitle,
    emptyDescription,
}: GlobalBoardProps) => {
    // settled, nothing to rank yet → funnel to courses (BLOCK-8: error/loading beat empty; this
    // component has no distinct error state — an SWR error settles with `!data`, which the
    // connected file already folds into `isEmpty`, exactly like the retired `AsyncContent` did).
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                icon={TrophyIcon}
                title={emptyTitle}
                description={emptyDescription}
                onRetry={onClimb}
                retryLabel={climbCtaLabel}
            />
        )
    }

    const podiumRows = isSkeleton
        ? [false, true, false]
        : podiumEntries.slice(0, 3).map((entry) => entry.rank === 1)
    const skeletonRows = Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => index)

    // `StackV`'s own `classNames` is the closed positioning-only allowlist (ATOM-4 vocabulary),
    // not a free-form passthrough — an incoming placement `className` from the caller needs the
    // frame tier's escape hatch (`Box`), which is the ONLY frame that takes a raw string.
    return (
        <Box className={className}>
            <StackV
                gap={6}
                principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                identity={{ tier: "block", component: "GlobalBoard" }}
                items={[
                    // celebrate a top-3 platform finish — only meaningful once real data has settled
                    ...(!isSkeleton ? [() => <Confetti fireKey={celebrateKey} />] : []),

                    // ── your platform-wide standing ── `StandingHeroCard` has no `isSkeleton` of its
                    // own (missingSkeletonSupport): mirrored in place with `Skeleton.*`, same box.
                    () => (isSkeleton ? (
                        <Box principle="card-padding" className="rounded-3xl bg-surface p-4 shadow-surface"
                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <StackV gap={5} principle="group-boundary"
                                explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                items={[
                                    () => (
                                        <StackH gap={5} principle="group-boundary"
                                            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                            align="center" items={[
                                                () => <Skeleton className="size-10 shrink-0 rounded-2xl" />,
                                                () => (
                                                    <StackV gap={2} principle="title-subtitle"
                                                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                        classNames={["min-w-0", "flex-1"]} items={[
                                                            () => <Skeleton.Typography type="h6" width="1/2" />,
                                                            () => <Skeleton.Typography type="body-sm" width="1/3" />,
                                                        ]} />
                                                ),
                                            ]} />
                                    ),
                                    () => (
                                        <StackV gap={2} principle="title-subtitle"
                                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                                            items={[
                                                () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                                () => <Skeleton.ProgressBar />,
                                            ]} />
                                    ),
                                    () => <Skeleton className="h-10 w-40 rounded-full" />,
                                ]} />
                        </Box>
                    ) : (
                        <StandingHeroCard
                            badge={rankBadge ? <IconTile icon={rankBadge} tone="neutral" size="sm" /> : undefined}
                            rankLabel={rankLabel}
                            meta={pointsMeta}
                            progress={progress}
                            ctaLabel={climbCtaLabel}
                            onCta={onClimb}
                        />
                    )),

                    // ── the winners' dais ── `Podium` has no `isSkeleton` of its own
                    // (missingSkeletonSupport): mirrored in place, champion centered + raised.
                    () => (isSkeleton ? (
                        <StackH gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            align="end" justify="center" items={podiumRows.map((isChampion) => () => (
                                <StackV gap={2} principle="title-subtitle"
                                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                                    align="center" items={[
                                        () => <Skeleton className={isChampion ? "size-14 shrink-0 rounded-full" : "size-12 shrink-0 rounded-full"} />,
                                        () => (
                                            <StackV gap={2} principle="title-subtitle"
                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                align="center" classNames={["w-full"]} items={[
                                                    () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                                    () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                                ]} />
                                        ),
                                        () => (
                                            <Box className={isChampion
                                                ? "h-16 w-20 rounded-t-2xl rounded-b-none"
                                                : "h-10 w-20 rounded-t-2xl rounded-b-none"}
                                            >
                                                <Skeleton className="h-full w-full rounded-t-2xl rounded-b-none" />
                                            </Box>
                                        ),
                                    ]} />
                            ))} />
                    ) : (
                        <Podium
                            meLabel={meLabel}
                            entries={podiumEntries.map((entry) => ({
                                rank: entry.rank,
                                username: entry.username,
                                avatar: entry.avatar,
                                pointsLabel: entry.pointsLabel,
                                isMe: entry.isMe,
                            }))}
                        />
                    )),

                    // ── rank 4+ ── a followable list; `SurfaceCardList`/`FollowButton`/`UserCell`
                    // have no `isSkeleton` of their own (missingSkeletonSupport): each row is
                    // mirrored in place with `Skeleton.UserCell` + bare bars, same row shape.
                    ...(isSkeleton || showRows ? [() => {
                        const listItems: Array<SurfaceCardListItem> = isSkeleton
                            ? skeletonRows.map((row) => ({
                                key: `skeleton-${row}`,
                                content: () => (
                                    <StackH gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        align="center" items={[
                                            () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
                                            () => <Skeleton.UserCell className="min-w-0 flex-1" withHandle={false} />,
                                            () => <Skeleton className="h-3 w-10 shrink-0 rounded-sm" />,
                                        ]} />
                                ),
                            }))
                            : [
                                ...rows.map((row) => ({
                                    key: row.key,
                                    content: () => (
                                        <StackH gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            align="center" items={[
                                                () => (
                                                    <Box className="w-6 shrink-0">
                                                        <Typography
                                                            size="xs"
                                                            align="end"
                                                            color={row.isMine ? "accent" : "muted"}
                                                            weight={row.isMine ? "semibold" : undefined}
                                                            text={String(row.rank)}
                                                        />
                                                    </Box>
                                                ),
                                                () => (
                                                    <Link
                                                        href={row.profileHref}
                                                        className="flex min-w-0 flex-1 items-center text-foreground no-underline transition-opacity hover:opacity-60"
                                                    >
                                                        <UserCell username={row.displayName} avatar={row.avatar} />
                                                    </Link>
                                                ),
                                                () => (
                                                    <Typography
                                                        size="sm"
                                                        color={row.isMine ? "accent" : "muted"}
                                                        weight={row.isMine ? "semibold" : undefined}
                                                        classNames={["shrink-0"]}
                                                        text={row.pointsLabel}
                                                    />
                                                ),
                                                ...(!row.isMine ? [() => (
                                                    <FollowButton
                                                        quiet
                                                        following={row.following}
                                                        isPending={row.isPending}
                                                        onToggle={row.onToggleFollow}
                                                    />
                                                )] : []),
                                            ]} />
                                    ),
                                })),
                                // viewer below the fetched slice → ellipsis + pinned self-row
                                ...(selfRow
                                    ? [
                                        {
                                            key: "hidden-between",
                                            content: () => (
                                                <Box principle="control-pad" className="-m-3 bg-surface-secondary px-3 py-2 text-xs text-muted"
                                                    explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                                                    <StackH gap={3} principle="sibling-stack"
                                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                        align="center" justify="center" items={[
                                                            () => <span className="text-base leading-none tracking-widest">⋯</span>,
                                                            ...(hiddenBetweenLabel ? [() => <Typography size="xs" color="muted" text={hiddenBetweenLabel} />] : []),
                                                        ]} />
                                                </Box>
                                            ),
                                        },
                                        {
                                            key: "self-row",
                                            content: () => (
                                                <StackH gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    align="center" items={[
                                                        () => (
                                                            <Box className="w-6 shrink-0">
                                                                <Typography size="xs" align="end" color="accent" weight="semibold" text={String(selfRow.rank)} />
                                                            </Box>
                                                        ),
                                                        () => (
                                                            <Box className="min-w-0 flex-1">
                                                                <UserCell username={selfRow.displayName} avatar={selfRow.avatar} />
                                                            </Box>
                                                        ),
                                                        () => (
                                                            <Typography size="sm" color="accent" weight="semibold" classNames={["shrink-0"]} text={selfRow.pointsLabel} />
                                                        ),
                                                    ]} />
                                            ),
                                        },
                                    ]
                                    : []),
                            ]

                        return <SurfaceCardList items={listItems} />
                    }] : []),
                ]}
            />
        </Box>
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useRef,
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import {
    fromGlobalId,
} from "@/modules/utils/globalId"
import {
    rankBadgeIcon,
} from "@/components/blocks/dashboard/rankBadge"
import { useQueryGlobalLeaderboardSwr } from "@/hooks/swr/api/graphql/queries/useQueryGlobalLeaderboardSwr"
import { useMutateSetFollowSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSetFollowSwr"
import { useAppSelector } from "@/redux/hooks"
import { _GlobalBoard } from "./component"

/** Props for {@link GlobalBoard}. */
export type GlobalBoardProps = Record<string, never>
/**
 * The global (all-users) leaderboard — the CONNECTED half of {@link import("./component")._GlobalBoard}.
 * Fetches the leaderboard, owns the follow mutation (rows stay presentational), computes the
 * first-load skeleton flag + the settled-empty flag, resolves every label, and hands the fully
 * resolved shape to the presentational component. See `tiers/split.md`.
 *
 * @param props - {@link GlobalBoardProps}
 */
export const GlobalBoard = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { data, isLoading } = useQueryGlobalLeaderboardSwr()
    const me = useAppSelector((state) => state.user.user)
    // owns the follow mutation; presentational rows only fire the resolved handler
    const { trigger: triggerSetFollow } = useMutateSetFollowSwr()
    // globalIds the viewer follows from this board (optimistic) + in-flight set
    const [followed, setFollowed] = useState<Set<string>>(new Set())
    const [pending, setPending] = useState<Set<string>>(new Set())

    /** Whether an entry belongs to the viewer (best-effort username match). */
    const isMine = (username: string | null) => Boolean(me?.username) && username === me?.username

    /**
     * Toggle follow/unfollow for a user. The board exposes each user as an OPAQUE
     * global id, but `setFollow` wants the raw `users.id` — decode it first. Flips
     * the row optimistically on success. (Same pattern as `TopLearners`.)
     */
    const onToggleFollow = useCallback(
        async (globalId: string) => {
            const rawId = fromGlobalId(globalId)?.id ?? globalId
            const currentlyFollowing = followed.has(globalId)
            setPending((current) => new Set(current).add(globalId))
            try {
                const result = await triggerSetFollow({
                    userId: rawId,
                    follow: !currentlyFollowing,
                })
                if (result?.data?.setFollow?.success) {
                    setFollowed((current) => {
                        const next = new Set(current)
                        if (currentlyFollowing) {
                            next.delete(globalId)
                        } else {
                            next.add(globalId)
                        }
                        return next
                    })
                }
            } finally {
                setPending((current) => {
                    const next = new Set(current)
                    next.delete(globalId)
                    return next
                })
            }
        },
        [followed, triggerSetFollow],
    )

    /** Funnel to courses — climb the leaderboard by learning (the north-star CTA). */
    const onClimb = () => router.push(pathConfig().locale(locale).course().build())

    // the person directly above me — for the goal-gradient meter (FE-computed,
    // only when that rank is present in the fetched top slice).
    const above = data ? data.entries.find((entry) => entry.rank === data.myRank - 1) : undefined
    const pointsToNext = above ? Math.max(0, above.points - (data?.myPoints ?? 0) + 1) : 0
    // the viewer sits below the fetched top slice → pin a self-row at the bottom
    const viewerInList = data ? data.entries.some((entry) => isMine(entry.username)) : false
    const hiddenBetween = data ? Math.max(0, data.myRank - data.entries.length - 1) : 0

    // celebrate a top-3 platform finish with a confetti burst on tab entry
    const isTop = Boolean(data) && (data?.myRank ?? 99) <= 3
    const [celebrateKey, setCelebrateKey] = useState(0)
    const celebratedRef = useRef(false)
    useEffect(
        () => {
            if (isTop && !celebratedRef.current) {
                celebratedRef.current = true
                setCelebrateKey((key) => key + 1)
            }
        },
        [isTop],
    )

    return (
        <_GlobalBoard
            // first load, nothing in hand → shimmer; settled (data OR a resolved error, which
            // SWR also clears `isLoading` for) stops it (loading-and-skeleton.md §2). Same
            // formula the retired `AsyncContent` used (`isLoading={isLoading && !data}`).
            isSkeleton={isLoading && !data}
            // settled with nothing to rank — also the branch a fetch error falls into, exactly
            // like the retired `AsyncContent` (it never had a distinct error branch either).
            isEmpty={!data || data.entries.length === 0}
            rankBadge={data ? rankBadgeIcon(data.myRank) : undefined}
            rankLabel={data ? t("dashboard.league.globalRankLine", { rank: data.myRank }) : undefined}
            pointsMeta={data ? t("dashboard.league.points", { count: data.myPoints }) : undefined}
            progress={data && above && data.myRank > 1 ? {
                ratio: data.myPoints / Math.max(1, above.points),
                label: t("dashboard.league.pointsToNext", {
                    points: pointsToNext,
                    rank: data.myRank - 1,
                }),
            } : undefined}
            climbCtaLabel={t("dashboard.league.climbCta")}
            onClimb={onClimb}
            meLabel={t("dashboard.league.you")}
            podiumEntries={data ? data.entries.slice(0, 3).map((entry) => ({
                rank: entry.rank,
                username: entry.username,
                avatar: entry.avatar,
                pointsLabel: t("dashboard.league.points", { count: entry.points }),
                isMe: isMine(entry.username),
            })) : undefined}
            rows={data ? data.entries.slice(3).map((entry) => {
                const mine = isMine(entry.username)
                return {
                    key: entry.userGlobalId,
                    rank: entry.rank,
                    isMine: mine,
                    displayName: mine ? `${entry.username} · ${t("dashboard.league.you")}` : (entry.username ?? ""),
                    avatar: entry.avatar,
                    profileHref: pathConfig().locale(locale).profile(entry.username ?? undefined).build(),
                    pointsLabel: t("dashboard.league.points", { count: entry.points }),
                    following: followed.has(entry.userGlobalId),
                    isPending: pending.has(entry.userGlobalId),
                    onToggleFollow: () => void onToggleFollow(entry.userGlobalId),
                }
            }) : undefined}
            showRows={data ? (data.entries.length > 3 || !viewerInList) : false}
            selfRow={data && !viewerInList ? {
                rank: data.myRank,
                displayName: `${me?.username ?? ""} · ${t("dashboard.league.you")}`,
                avatar: me?.avatar ?? null,
                pointsLabel: t("dashboard.league.points", { count: data.myPoints }),
            } : undefined}
            hiddenBetweenLabel={hiddenBetween > 0 ? t("dashboard.league.othersCount", { count: hiddenBetween }) : undefined}
            celebrateKey={celebrateKey}
            emptyTitle={t("dashboard.community.topLearners.noLeadersTitle")}
            emptyDescription={t("dashboard.community.topLearners.noLeadersDescription")}
        />
    )
}

import React from "react"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { StandingHeroCard } from "@/components/blocks/dashboard/StandingHeroCard"
import { Podium, type PodiumEntry } from "@/components/blocks/dashboard/Podium"
import { rankBadgeIcon } from "@/components/blocks/dashboard/rankBadge"
import { Confetti } from "@/components/blocks/dashboard/Confetti"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { UserCell } from "@/components/composites/lists/UserCell"
import { RankDeltaCaret } from "@/components/blocks/profile/RankDeltaCaret"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackV, StackH } from "@/components/frames/Stack"

/** Number of placeholder cohort rows (rank 4+) shown while the board shimmers. */
const SKELETON_ROW_COUNT = 6

/** "Your standing" hero — already resolved (i18n interpolated) by the connected `WeeklyBoard`. */
export interface WeeklyBoardHero {
    /** 1-based rank, drives the {@link rankBadgeIcon} art. */
    rank: number
    /** Primary line, e.g. "Rank #1 · Bronze" (already translated + interpolated). */
    rankLabel: string
    /** Secondary meta line — points · reset countdown (already translated + interpolated). */
    meta: string
    /** Optional goal-gradient meter toward the promotion cutoff. */
    progress?: {
        /** Fill ratio, `0..1`. */
        ratio: number
        /** Muted line above the meter (already translated + interpolated). */
        label: string
    }
}

/** One top-3 podium finisher — see {@link PodiumEntry}. */
export type WeeklyBoardPodiumEntry = PodiumEntry

/** One rank 4+ cohort row, already resolved by the connected `WeeklyBoard`. */
export interface WeeklyBoardRowEntry {
    /** Stable row identity. */
    userGlobalId: string
    /** 1-based rank. */
    rank: number
    /** True when this row is the viewer's own. */
    mine: boolean
    /** Resolved, locale-aware link to this user's public profile. */
    profileHref: string
    /** Display username — the viewer's own row already carries the "· you" suffix. */
    displayUsername: string
    /** Avatar URL, or `null` for the generated fallback. */
    avatar: string | null
    /** Pre-formatted points label (already translated). */
    pointsLabel: string
    /** Weekly rank movement (`>0` climbed, `<0` dropped, `0`/`null` unchanged/no baseline). */
    rankDelta: number | null
}

/** All display text, already localized by the connected `WeeklyBoard`; a story passes i18n keys. */
export interface WeeklyBoardLabels {
    /** Nothing to show until the viewer is placed in a cohort — funnel-to-courses title. */
    emptyTitle: string
    /** Funnel-to-courses supporting line under {@link WeeklyBoardLabels.emptyTitle}. */
    emptyDescription: string
    /** North-star CTA — shown both on the hero and as the empty-state retry action. */
    climbCta: string
    /** "you" suffix appended to the viewer's own podium finisher. */
    you: string
    /** Promote-zone legend line (already interpolated with the cohort's promote count). */
    legendPromote: string
    /** Demote-zone legend line (already interpolated with the cohort's demote count). */
    legendDemote: string
}

/** Props for {@link _WeeklyBoard} — presentational; all data resolved, no fetch/store/i18n. */
export interface WeeklyBoardProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no cohort placement → the empty message (funnel to courses). */
    isEmpty?: boolean
    /** The viewer's own standing hero — omitted when the viewer isn't placed in the loaded cohort. */
    hero?: WeeklyBoardHero
    /** Top-3 finishers, best → worst. */
    podiumEntries?: ReadonlyArray<WeeklyBoardPodiumEntry>
    /** Rank 4+ rows — the runners the podium can't hold. */
    rows?: ReadonlyArray<WeeklyBoardRowEntry>
    /** Bumped to fire a top-3 confetti burst (owned by the connected file's one-shot effect). */
    celebrateKey?: number
    /** North-star funnel — both the hero CTA and the empty-state retry action. */
    onClimb: () => void
    labels: WeeklyBoardLabels
    className?: string
}

/**
 * Loading placeholder for the "your standing" hero — mirrors {@link StandingHeroCard}'s shape
 * (badge · rank/meta lines · goal meter · CTA) since the block has no `isSkeleton` of its own.
 */
const HeroSkeleton = () => (
    <Box principle="card-padding" className="rounded-3xl bg-surface p-4 shadow-surface"
        explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
        <StackV gap={5} principle="group-boundary"
            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
            items={[
                () => (
                    <StackH gap={5} principle="group-boundary"
                        explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            () => <Skeleton className="size-10 shrink-0 rounded-2xl" />,
                            () => <StackV gap={2} principle="title-subtitle"
                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                classNames={["min-w-0", "flex-1"]} items={[
                                    () => <Skeleton.Typography type="h6" width="1/2" />,
                                    () => <Skeleton.Typography type="body-sm" width="1/3" />,
                                ]} />,
                        ]} />
                ),
                () => (
                    <StackV gap={2} principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        items={[
                            () => <Skeleton.Typography type="body-xs" width="1/3" />,
                            () => <Skeleton.ProgressBar />,
                        ]} />
                ),
                () => <Skeleton className="h-10 w-40 rounded-full" />,
            ]} />
    </Box>
)

/**
 * Loading placeholder for the top-3 dais — mirrors {@link Podium}'s shape (champion centered +
 * raised) since the block has no `isSkeleton` of its own.
 */
const PodiumSkeleton = () => (
    <StackH gap={4} principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        justify="center" items={[false, true, false].map((isChampion) => () => (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center" items={[
                    () => <Skeleton className={isChampion ? "size-14 shrink-0 rounded-full" : "size-12 shrink-0 rounded-full"} />,
                    // The podium column's fixed width is not a member of the closed AllowedClassName
                    // union, so it sits on Box — the frame tier's sanctioned escape hatch — rather than
                    // widening that union for one skeleton.
                    () => <Box className="w-20"><StackV gap={2} principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        align="center" items={[
                            () => <Skeleton.Typography type="body-sm" width="3/4" />,
                            () => <Skeleton.Typography type="body-xs" width="1/2" />,
                        ]} /></Box>,
                    () => <Skeleton className={isChampion ? "h-16 w-20 rounded-t-2xl rounded-b-none" : "h-10 w-20 rounded-t-2xl rounded-b-none"} />,
                ]} />
        ))} />
)

/** Loading placeholder for one rank 4+ row — mirrors the [rank · avatar · name · points · caret] shape. */
const RowSkeleton = () => (
    <StackH gap={4} principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        items={[
            () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
            () => <Skeleton.Avatar size="sm" />,
            () => <Skeleton.Typography type="body-sm" width="1/3" className="min-w-0 flex-1" />,
            () => <Skeleton className="h-3 w-8 shrink-0 rounded-sm" />,
            () => <Skeleton className="h-4 w-8 shrink-0 rounded-sm" />,
        ]} />
)

/** One resolved rank 4+ row: rank cell · profile-linked user cell · points · movement caret. */
interface RowProps {
    row: WeeklyBoardRowEntry
}

const Row = ({ row }: RowProps) => (
    <StackH gap={4} principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        items={[
            () => (
                <Box as="span" className="w-6 shrink-0 text-right">
                    <Typography size="xs" color={row.mine ? "accent" : "muted"} weight={row.mine ? "semibold" : undefined} text={String(row.rank)} />
                </Box>
            ),
            () => (
                <Box className="min-w-0 flex-1">
                    <UserCell username={row.displayUsername} avatar={row.avatar} isOwnRow={row.mine } />
                </Box>
            ),
            () => (
                <Typography size="sm" color={row.mine ? "accent" : "muted"} weight={row.mine ? "semibold" : undefined} classNames={["shrink-0"]} text={row.pointsLabel} />
            ),
            () => <RankDeltaCaret delta={row.rankDelta} className="w-8 shrink-0 justify-end" />,
        ]} />
)

/**
 * `_WeeklyBoard` — the presentational half of {@link import("./index").WeeklyBoard}: the full
 * weekly-league board shell shared with the global board — a {@link StandingHeroCard} of the
 * viewer's own standing, the top-3 {@link Podium}, the promote/demote legend, then rank 4+ in a
 * {@link SurfaceCardList}. Renders ONE tree with `isSkeleton` threaded to every leaf that supports
 * it; the sub-blocks that don't ({@link StandingHeroCard}, {@link Podium}, {@link SurfaceCardList},
 * {@link UserCell}, {@link RankDeltaCaret}) are mirrored in place with `Skeleton.*` at the exact
 * site they render, so the shimmer stays co-located instead of a hand-kept parallel tree
 * (`loading-and-skeleton.md`). See `tiers/split.md` — the connected `index.tsx` owns the fetch,
 * the async decisions, and every interpolated string.
 *
 * @param props - {@link WeeklyBoardProps}
 */
export const _WeeklyBoard = ({
    isSkeleton = false,
    isEmpty = false,
    hero,
    podiumEntries = [],
    rows = [],
    celebrateKey = 0,
    onClimb,
    labels,
    className,
}: WeeklyBoardProps) => {
    // empty only once settled — a first-load skeleton always wins over a structurally-empty isEmpty.
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                onRetry={onClimb}
                retryLabel={labels.climbCta}
            />
        )
    }

    const showHero = isSkeleton || Boolean(hero)
    const showPodium = isSkeleton || podiumEntries.length > 0
    const showRows = isSkeleton || rows.length > 0

    const listItems: Array<SurfaceCardListItem> = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
            key: `pending-${index}`,
            content: () => <RowSkeleton />,
        }))
        : rows.map((row) => ({
            key: row.userGlobalId,
            href: row.profileHref,
            withVerdict: {
                enable: (row.rankDelta ?? 0) !== 0,
                variant: (row.rankDelta ?? 0) > 0 ? "success" : "danger",
            },
            content: () => <Row row={row} />,
        }))

    return (
        <Box className={className} identity={{ tier: "block", component: "WeeklyBoard" }}>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => <Confetti fireKey={celebrateKey} />,

                    // your standing hero — rank-driven badge · rank/meta · goal meter · CTA
                    ...(showHero ? [() => (
                        isSkeleton || !hero
                            ? <HeroSkeleton />
                            : (
                                <StandingHeroCard
                                    badge={<IconTile icon={rankBadgeIcon(hero.rank)} tone="neutral" size="sm" />}
                                    rankLabel={hero.rankLabel}
                                    meta={hero.meta}
                                    progress={hero.progress}
                                    ctaLabel={labels.climbCta}
                                    onCta={onClimb}
                                />
                            )
                    )] : []),

                    // the winners' dais — top-3 (viewer's own column ringed)
                    ...(showPodium ? [() => (
                        isSkeleton
                            ? <PodiumSkeleton />
                            : <Podium meLabel={labels.you} entries={[...podiumEntries]} />
                    )] : []),

                    // promote / demote legend
                    () => (
                        <StackH gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <StackH gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => <Box as="span" className="size-2 shrink-0 rounded-full bg-success" />,
                                            () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.legendPromote} />,
                                        ]} />
                                ),
                                () => (
                                    <StackH gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => <Box as="span" className="size-2 shrink-0 rounded-full bg-danger" />,
                                            () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.legendDemote} />,
                                        ]} />
                                ),
                            ]} />
                    ),

                    // rank 4+ — the runners the podium can't hold; zone edge-markers via `withVerdict`
                    ...(showRows ? [() => <SurfaceCardList items={listItems} />] : []),
                ]} />
        </Box>
    )
}

"use client"

import React, {
    useEffect,
    useMemo,
    useRef,
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    _WeeklyBoard,
    type WeeklyBoardHero,
    type WeeklyBoardPodiumEntry,
    type WeeklyBoardRowEntry,
} from "./component"
import { useQueryMyLeagueSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyLeagueSwr"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"

/** Props for {@link WeeklyBoard}. */
export type WeeklyBoardProps = Record<string, never>
/**
 * The full weekly-league board — one shell shared with the global board:
 * a {@link import("./component").WeeklyBoardHero} of the viewer's own standing (rank-driven
 * badge · goal-gradient meter · climb CTA), the top-3 podium (the viewer's own column ringed
 * when they're a finisher), the promote/demote legend, then rank 4+ (zone edge-markers + the
 * rank-movement caret). Self-fetches its leaf query; empty (not placed in a cohort) funnels to
 * courses.
 *
 * The CONNECTED half: it owns the fetch, computes `isSkeleton` from the first-load formula and
 * `isEmpty` from the resolved data, derives every domain value (countdown, the viewer's own
 * standing, the promotion goal-gradient, the one-shot podium-finish celebration), resolves every
 * translated string, and hands it all to the presentational `_WeeklyBoard`
 * (`tiers/split.md`).
 *
 * @param props - optional className for the root element.
 */
export const WeeklyBoard = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // `error` is intentionally not read: the original `AsyncContent` usage never wired an
    // error/errorContent pair, so a settled fetch error falls through into the empty branch
    // exactly as it did before this split (`!data` makes `isEmpty` true) — see `apiChanged`
    // in the retirement report for this deliberate call.
    const { data, isLoading } = useQueryMyLeagueSwr()
    const me = useAppSelector((state) => state.user.user)

    /** Hours/days left until the weekly reset (computed from `weekEndAt`). */
    const countdown = useMemo(
        () => {
            if (!data) {
                return null
            }
            const remaining = Math.max(0, new Date(data.weekEndAt).getTime() - Date.now())
            return {
                days: Math.floor(remaining / 86_400_000),
                hours: Math.floor((remaining % 86_400_000) / 3_600_000),
            }
        },
        [data],
    )

    const total = data?.entries.length ?? 0

    /** Whether an entry belongs to the viewer (best-effort username match). */
    const isMine = (username: string | null) => Boolean(me?.username) && username === me?.username

    // the viewer's own standing + goal-gradient toward the promotion cutoff (all
    // computed FE from data already fetched — no BE change).
    const myEntry = data && me?.username
        ? data.entries.find((entry) => entry.username === me.username)
        : undefined
    const myPercent = myEntry ? Math.max(1, Math.ceil((myEntry.rank / total) * 100)) : null
    const promoteCutoff = data ? data.entries[data.promoteCount - 1] : undefined
    const inPromote = myEntry ? myEntry.rank <= (data?.promoteCount ?? 0) : false
    const pointsToPromote = myEntry && promoteCutoff && !inPromote
        ? Math.max(0, promoteCutoff.weekPoints - myEntry.weekPoints + 1)
        : 0

    /** Funnel to courses — climb the league by learning (the north-star CTA). */
    const onClimb = () => router.push(pathConfig().locale(locale).course().build())

    // celebrate a top-3 finish with a confetti burst when the viewer lands here
    // (the board remounts on tab switch → fires once per visit to a podium tab).
    const isTop = Boolean(myEntry) && (myEntry?.rank ?? 99) <= 3
    const [celebrateKey, setCelebrateKey] = useState(0)
    const celebratedRef = useRef(false)
    useEffect(
        () => {
            if (isTop && !celebratedRef.current) {
                celebratedRef.current = true
                setCelebrateKey((key) => key + 1)
            }
        },
        [isTop],
    )

    const youLabel = t("dashboard.league.you")

    const hero: WeeklyBoardHero | undefined = myEntry && myPercent !== null ? {
        rank: myEntry.rank,
        rankLabel: t("dashboard.myProfile.rankLine", {
            rank: myEntry.rank,
            percent: myPercent,
        }),
        meta: `${t("dashboard.league.points", { count: myEntry.weekPoints })}${countdown
            ? ` · ${t("dashboard.league.resetIn", { days: countdown.days, hours: countdown.hours })}`
            : ""}`,
        progress: !inPromote && promoteCutoff ? {
            ratio: myEntry.weekPoints / Math.max(1, promoteCutoff.weekPoints),
            label: t("dashboard.league.pointsToPromote", { points: pointsToPromote }),
        } : undefined,
    } : undefined

    // top-3 finishers — pointsLabel is i18n, so it's resolved here (not in the presentational half).
    const podiumEntries: Array<WeeklyBoardPodiumEntry> = (data?.entries ?? []).slice(0, 3).map((entry) => ({
        rank: entry.rank,
        username: entry.username,
        avatar: entry.avatar,
        pointsLabel: t("dashboard.league.points", { count: entry.weekPoints }),
        isMe: isMine(entry.username),
        rankDelta: entry.rankDelta,
    }))

    // rank 4+ — the runners the podium can't hold.
    const rows: Array<WeeklyBoardRowEntry> = (data?.entries ?? []).slice(3).map((entry) => {
        const mine = isMine(entry.username)
        return {
            userGlobalId: entry.userGlobalId,
            rank: entry.rank,
            mine,
            profileHref: pathConfig().locale(locale).profile(entry.username ?? undefined).build(),
            displayUsername: mine ? `${entry.username} · ${youLabel}` : (entry.username ?? ""),
            avatar: entry.avatar,
            pointsLabel: t("dashboard.league.points", { count: entry.weekPoints }),
            rankDelta: entry.rankDelta,
        }
    })

    return (
        <_WeeklyBoard
            // first load, nothing in hand → shimmer (unchanged formula, loading-and-skeleton.md)
            isSkeleton={isLoading && !data}
            // nothing to show until the viewer is placed in a cohort → funnel to courses
            isEmpty={!data || data.entries.length === 0}
            hero={hero}
            podiumEntries={podiumEntries}
            rows={rows}
            celebrateKey={celebrateKey}
            onClimb={onClimb}
            labels={{
                emptyTitle: t("dashboard.league.emptyTitle"),
                emptyDescription: t("dashboard.league.emptyDescription"),
                climbCta: t("dashboard.league.climbCta"),
                you: youLabel,
                legendPromote: t("dashboard.league.promote", { count: data?.promoteCount ?? 0 }),
                legendDemote: t("dashboard.league.demote", { count: data?.demoteCount ?? 0 }),
            }}
        />
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    Button,
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    BookOpenIcon,
    FlagIcon,
    PuzzlePieceIcon,
} from "@phosphor-icons/react"
import {
    formatDateTime,
    getTimeAgoLabel,
    getTimeAgoMessage,
} from "@/modules/dayjs"
import { toDifficulty } from "@/modules/utils/difficulty"
import { CourseLearningEventType } from "@/modules/api/graphql/queries/types/course-learning-history"
import type { CourseLearningHistoryItemData } from "@/modules/api/graphql/queries/types/course-learning-history"
import { useQueryCourseLearningHistorySwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseLearningHistorySwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { ListRow } from "@/components/blocks/lists/ListRow"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link CourseDayTimeline}. */
export interface CourseDayTimelineProps {
    /** Selected course RELAY GLOBAL ID (the `?course=` value, passed to the query). */
    courseGlobalId: string
    /** Lower-cased trimmed search query; filters events by label, client-side. */
    query: string
}

/** Event-type → entity icon (phosphor `*Icon`) shown as the row's leading tile. */
const EVENT_ICON: Record<CourseLearningEventType, typeof BookOpenIcon> = {
    [CourseLearningEventType.LessonRead]: BookOpenIcon,
    [CourseLearningEventType.ChallengePassed]: PuzzlePieceIcon,
    [CourseLearningEventType.MilestonePassed]: FlagIcon,
}

/** Event-type → IconTile tone. */
const EVENT_TONE = {
    [CourseLearningEventType.LessonRead]: "accent",
    [CourseLearningEventType.ChallengePassed]: "success",
    [CourseLearningEventType.MilestonePassed]: "warning",
} as const

/** A day bucket of learning events under a relative day header. */
interface DayGroup {
    /** Stable key (start-of-day ms as string). */
    key: string
    /** Header label ("Today" / "Yesterday" / a formatted date). */
    label: string
    /** Events in this day, newest first. */
    items: Array<CourseLearningHistoryItemData>
}

/** Start-of-day epoch ms for a date (local). */
const startOfDayMs = (date: Date): number =>
    new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime()

/**
 * "By day" view — the viewer's per-course learning journal: every
 * `lessonRead` / `challengePassed` / `milestonePassed` event, newest first,
 * grouped under relative day headers (Today / Yesterday / localized date). Each
 * row is an entity-icon tile + the label + a module/type subtitle + an optional
 * {@link DifficultyChip} + a relative timestamp. Drives its own cursor-paginated
 * SWR (load more) and filters by the shared search query, client-side. Every
 * data state goes through {@link AsyncContent}; empties center.
 *
 * @param props - {@link CourseDayTimelineProps}
 */
export const CourseDayTimeline = ({
    courseGlobalId,
    query}: CourseDayTimelineProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const {
        data,
        size,
        setSize,
        isLoading,
        isValidating,
        error,
        mutate,
    } = useQueryCourseLearningHistorySwr(courseGlobalId)

    // flatten every loaded page into one newest-first list
    const items = useMemo(
        () => (data ?? []).flatMap((page) => page.items),
        [data],
    )
    const hasMore = Boolean(data && data.length > 0 && data[data.length - 1].nextCursor !== null)
    const isLoadingMore = isValidating && Boolean(data) && size > 0

    // search filters loaded events by label, client-side
    const filtered = useMemo(
        () => (query ? items.filter((item) => item.label.toLowerCase().includes(query)) : items),
        [items, query],
    )

    // bucket the filtered events by local day
    const dayGroups = useMemo<Array<DayGroup>>(
        () => {
            const now = new Date()
            const todayMs = startOfDayMs(now)
            const dayMs = 86_400_000
            const groups: Array<DayGroup> = []
            for (const item of filtered) {
                const at = new Date(item.at)
                const dayMsValue = startOfDayMs(at)
                let label: string
                if (dayMsValue === todayMs) {
                    label = t("profileSettings.learning.day.today")
                } else if (dayMsValue === todayMs - dayMs) {
                    label = t("profileSettings.learning.day.yesterday")
                } else {
                    label = at.toLocaleDateString(locale, {
                        day: "numeric",
                        month: "long",
                        year: "numeric",
                    })
                }
                const key = String(dayMsValue)
                const last = groups[groups.length - 1]
                if (last && last.key === key) {
                    last.items.push(item)
                } else {
                    groups.push({ key, label, items: [item] })
                }
            }
            return groups
        },
        [
            filtered,
            locale,
            t,
        ],
    )

    return (
        <div>
            <AsyncContent
                isLoading={isLoading && items.length === 0}
                skeleton={(
                    <StackV gap={6} principle="block-boundary" explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups." items={[0, 1].map(() => () => (
                        <StackV
                            gap={4}
                            principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                () => <Skeleton.ListRow withTrailing />,
                                () => <Skeleton.ListRow withTrailing />,
                                () => <Skeleton.ListRow withTrailing />,
                            ]}
                        />
                    ))} />
                )}
                isEmpty={items.length === 0}
                emptyContent={{
                    title: t("profileSettings.learning.day.empty"),
                    description: t("profileSettings.learning.day.emptyHint"),
                }}
                error={items.length === 0 ? error : undefined}
                errorContent={{
                    title: t("profileSettings.learning.outline.error"),
                    onRetry: () => { void mutate() },
                    retryLabel: t("profileSettings.learning.loadMore"),
                }}
            >
                {filtered.length === 0 ? (
                // loaded but the current search matches no event
                    <AsyncContentEmpty title={t("profileSettings.learning.day.noMatch")} />
                ) : (
                    <StackV
                        gap={6}
                        principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            ...dayGroups.map((group) => () => (
                                <StackV
                                    gap={4}
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={[
                                        () => (
                                            <Typography type="body-xs" color="muted" weight="medium">
                                                {group.label}
                                            </Typography>
                                        ),
                                        () => (
                                            <StackV
                                                gap={3}
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={group.items.map((item) => () => {
                                                    const Icon = EVENT_ICON[item.type]
                                                    const relative = getTimeAgoLabel(getTimeAgoMessage(item.at), t)
                                                    const subtitle = item.moduleTitle
                                                        ?? t(`profileSettings.learning.day.eventType.${item.type}`)
                                                    return (
                                                        <ListRow
                                                            leading={(
                                                                <IconTile
                                                                    size="sm"
                                                                    tone={EVENT_TONE[item.type]}
                                                                    icon={<Icon aria-hidden focusable="false" />}
                                                                />
                                                            )}
                                                            title={item.label}
                                                            subtitle={subtitle}
                                                            meta={(
                                                                <>
                                                                    {item.difficulty ? (
                                                                        <DifficultyChip difficulty={toDifficulty(item.difficulty)} />
                                                                    ) : null}
                                                                    <Typography type="body-xs" color="muted">
                                                                        <span title={formatDateTime(item.at, locale)}>{relative}</span>
                                                                    </Typography>
                                                                </>
                                                            )}
                                                        />
                                                    )
                                                })}
                                            />
                                        ),
                                    ]}
                                />
                            )),
                            ...(hasMore ? [() => (
                                <div className="flex justify-center">
                                    <Button
                                        variant="secondary"
                                        size="sm"
                                        isPending={isLoadingMore}
                                        onPress={() => setSize(size + 1)}
                                    >
                                        {t("profileSettings.learning.loadMore")}
                                    </Button>
                                </div>
                            )] : []),
                        ]}
                    />
                )}
            </AsyncContent>
        </div>
    )
}

"use client"

import React, {
    useState,
} from "react"
import {
    Input,
    Link,
    TextField,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    ArrowLeftIcon,
    BookOpenIcon,
    FlagIcon,
    ListBulletsIcon,
} from "@phosphor-icons/react"
import {
    CourseTrialChip,
} from "@/components/blocks/course/CourseTrialChip"
import {
    useSelectedCourse,
} from "@/hooks/useSelectedCourse"
import {
    CourseOutline,
} from "../CourseOutline"
import {
    CourseMilestoneOutline,
} from "../CourseMilestoneOutline"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"
import { useQueryMyCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCoursesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { fromGlobalId } from "@/modules/utils/globalId"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Detail view tabs: course content vs the personal-project capstone. */
type DetailTab = "contents" | "personalProject"

/** Segment colour per course progress dimension. */
const DIM_COLOR: Record<string, string> = {
    content: "var(--accent)",
    challenge: "var(--success)",
    milestone: "var(--warning)",
}

/**
 * Per-course detail. A sticky course header ({@link IconTile} + title +
 * completion % + {@link SegmentBar} + a meta line of lessons / challenges /
 * milestones), a client search over the active tab, and a two-tab toggle — both
 * tabs render an accordion-card off the SAME `myCourseOutline` payload:
 *
 *   - "Contents" (default): the {@link CourseOutline} module → lesson →
 *     challenge tree with read flags.
 *   - "Personal Project": the {@link CourseMilestoneOutline}
 *     milestone → task tree with a roll-up completion status per milestone.
 *
 * Reads the selected course globalId from `?course=` (decoded to the raw id for
 * the shared outline query in each tab).
 */
export const CourseDetail = () => {
    const t = useTranslations()
    const { selectedCourse, setSelectedCourse } = useSelectedCourse()
    const [tab, setTab] = useState<DetailTab>("contents")
    const [search, setSearch] = useState("")

    // decode the selected course globalId (CourseEntity:<id>) → raw id for the outline query
    const rawCourseId = selectedCourse ? fromGlobalId(selectedCourse)?.id ?? null : null
    const outlineSwr = useQueryMyCourseOutlineSwr(rawCourseId)
    const outline = outlineSwr.data
    // the outline payload has no cover; reuse the (cached) course list to show the real
    // course logo in the header IconTile, like the hub list does — falls back to the book icon.
    const coursesSwr = useQueryMyCoursesSwr()
    const selectedCourseItem = (coursesSwr.data ?? [])
        .find((course) => course.globalId === selectedCourse)
    const courseThumbnailUrl = selectedCourseItem?.thumbnailUrl
    const query = search.trim().toLowerCase()

    const progress = outline?.progress
    const headerDims = progress
        ? [
            { key: "content", completed: progress.lessonsRead, total: progress.lessonsTotal },
            { key: "challenge", completed: progress.challengesCompleted, total: progress.challengesTotal },
            { key: "milestone", completed: progress.tasksCompleted, total: progress.tasksTotal },
        ]
        : []
    const headerTotal = headerDims.reduce((acc, dim) => acc + dim.total, 0)

    return (
        <StackV
            gap={6}
            principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major course-detail sections rather than nested section groups."
            items={[
                () => (
                    <Link onPress={() => { setSelectedCourse(null) }} className="text-sm text-muted">
                        <StackH
                            inline
                            gap={3}
                            principle="identity"
                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                            align="center"
                            items={[
                                () => <ArrowLeftIcon aria-hidden focusable="false" className="size-5" />,
                                () => <>{t("profileSettings.learning.history.title")}</>,
                            ]}
                        />
                    </Link>
                ),
                () => (
                    /* sticky course header — title + progress + meta */
                    <Box principle="row-pad" className="sticky top-16 z-30 -mx-4 bg-background px-4 py-3"
                        explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                        <StackV gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <AsyncContent
                                        isLoading={outlineSwr.data === null || outlineSwr.data === undefined ? !outlineSwr.error : false}
                                        skeleton={(
                                            <StackH gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                align="center" items={[
                                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                    () => (
                                                        <StackV gap={3} principle="sibling-stack"
                                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                            classNames={["min-w-0", "flex-1"]} items={[
                                                                () => <Skeleton.Typography type="h4" width="1/2" />,
                                                                () => <Skeleton.ProgressBar />,
                                                            ]} />
                                                    ),
                                                ]} />
                                        )}
                                        isEmpty={!outline}
                                        emptyContent={{ title: t("profileSettings.learning.outline.empty") }}
                                        error={!outlineSwr.data ? outlineSwr.error : undefined}
                                        errorContent={{
                                            title: t("profileSettings.learning.outline.error"),
                                            onRetry: () => { void outlineSwr.mutate() },
                                            retryLabel: t("profileSettings.learning.loadMore"),
                                        }}
                                    >
                                        {outline && progress ? (
                                            <StackH gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                align="center" items={[
                                                    () => <IconTile size="sm" src={courseThumbnailUrl} icon={<BookOpenIcon aria-hidden focusable="false" />} />,
                                                    () => (
                                                        <StackV gap={3} principle="sibling-stack"
                                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                            classNames={["min-w-0", "flex-1"]} items={[
                                                                () => (
                                                                    <StackH gap={3} principle="value-row"
                                                                        explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                                        justify="between" align="center" items={[
                                                                            () => (
                                                                                <Typography type="h5" weight="bold" truncate className="min-w-0 flex-1">
                                                                                    {outline.course.title}
                                                                                </Typography>
                                                                            ),
                                                                            () => (selectedCourseItem ? <CourseTrialChip isEnrolled={selectedCourseItem.isEnrolled} /> : null),
                                                                            () => (
                                                                                <Typography type="body-xs" color="muted">
                                                                                    {`${progress.completionPercent}%`}
                                                                                </Typography>
                                                                            ),
                                                                        ]} />
                                                                ),
                                                                () => (
                                                                    <SegmentBar
                                                                        max={headerTotal || 1}
                                                                        hideLegend
                                                                        ariaLabel={`${outline.course.title} · ${progress.completionPercent}%`}
                                                                        segments={headerDims.map((dim) => ({
                                                                            key: dim.key,
                                                                            label: t(`dashboard.courseProgress.${dim.key}`),
