/** Props for {@link LearningHistoryPage}. */
export type LearningHistoryPageProps = Record<string, never>
/** Number of placeholder course cards shown while the hub loads. */
const SKELETON_COURSE_COUNT = 3

/** Hub-search appears only once the list has at least this many courses. */
const SEARCH_MIN_COURSES = 4

/** Segment colour per course progress dimension. */
const DIM_COLOR: Record<string, string> = {
    content: "var(--accent)",
    challenge: "var(--success)",
    milestone: "var(--warning)",
}

/**
 * Learning history (brainstorm direction A / H1). The HUB lists every joined
 * course as a hinh-2 card — an {@link IconTile}, the title + overall completion %,
 * and a {@link SegmentBar} folding the three dimensions (content / challenge /
 * milestone) into one honest bar — each a press target opening that course's
 * detail (written into `?course=`). A client search filters the cards by title,
 * shown only when there are several courses. When a course is selected, the
 * {@link CourseDetail} view (day timeline + chapter outline) replaces the grid.
 *
 * @param props - optional root className (placement only).
 */
export const LearningHistoryPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { selectedCourse, setSelectedCourse } = useSelectedCourse()
    const [search, setSearch] = useState("")
    const coursesSwr = useQueryMyCoursesSwr()
    const courses = useMemo(() => coursesSwr.data ?? [], [coursesSwr.data])

    // search filters the loaded courses by title, client-side
    const query = search.trim().toLowerCase()
    const filtered = useMemo(
        () => (query
            ? courses.filter((course) => course.label.toLowerCase().includes(query))
            : courses),
        [courses, query],
    )

    // a selected course → show its detail (day timeline + chapter outline)
    if (selectedCourse) {
        return <CourseDetail />
    }

    return (
        <div className={"flex flex-col gap-10"}>
            <PageHeader
                breadcrumb={<SettingsBreadcrumb current={t("profileSettings.learning.history.title")} />}
                title={t("profileSettings.learning.history.title")}
                description={t("profileSettings.learning.history.subtitle")}
            />
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                // search — only worth showing once there are several courses
                    () => (courses.length >= SEARCH_MIN_COURSES ? (
                        <TextField variant="secondary">
                            <Input
                                aria-label={t("profileSettings.learning.history.searchCourses")}
                                placeholder={t("profileSettings.learning.history.searchCourses")}
                                value={search}
                                onChange={(event) => setSearch(event.target.value)}
                            />
                        </TextField>
                    ) : null),

                    () => {
                        const skeletonItems: Array<SurfaceCardListItem> = Array.from(
                            { length: SKELETON_COURSE_COUNT },
                            (_unused, row) => ({
                                key: `skeleton-${row}`,
                                content: () => (
                                    <StackH gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        align="center" items={[
                                            () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                            () => (
                                                <StackV gap={3} principle="sibling-stack"
                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                    classNames={["min-w-0", "flex-1"]} items={[
                                                        () => (
                                                            <StackH gap={3} principle="value-row"
                                                                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                                justify="between" align="center" items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                    () => <Skeleton className="h-3 w-8 rounded" />,
                                                                ]} />
                                                        ),
                                                        () => <Skeleton.ProgressBar />,
                                                    ]} />
                                            ),
                                        ]} />
                                ),
                            }),
                        )

                        const courseItems: Array<SurfaceCardListItem> = filtered.map((course) => {
                            const dims = [
                                { key: "content", completed: course.contentCompleted, total: course.contentTotal },
                                { key: "challenge", completed: course.challengeCompleted, total: course.challengeTotal },
                                { key: "milestone", completed: course.completed, total: course.total },
                            ]
                            const totalTasks = dims.reduce((acc, dim) => acc + dim.total, 0)
                            return {
                                key: course.globalId,
                                onPress: () => { setSelectedCourse(course.globalId) },
                                hover: "underline" as const,
                                content: () => (
                                    <StackH gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        align="center" items={[
                                            () => <IconTile size="sm" src={course.thumbnailUrl} icon={<BookOpenIcon aria-hidden focusable="false" />} />,
                                            () => (
                                                <StackV gap={3} principle="sibling-stack"
                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                    classNames={["min-w-0", "flex-1"]} items={[
                                                        () => (
                                                            <StackH gap={3} principle="value-row"
                                                                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                                justify="between" align="center" items={[
                                                                    () => (
                                                                        <Typography type="body-sm" weight="semibold" truncate className="min-w-0 flex-1 underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                                                                            {course.label}
                                                                        </Typography>
                                                                    ),
                                                                    () => <CourseTrialChip isEnrolled={course.isEnrolled} />,
                                                                    () => (
                                                                        <Typography type="body-xs" color="muted">
                                                                            {`${course.completionPercent}%`}
                                                                        </Typography>
                                                                    ),
                                                                ]} />
                                                        ),
                                                        () => (
                                                            <SegmentBar
                                                                max={totalTasks || 1}
                                                                ariaLabel={`${course.label} · ${course.completionPercent}%`}
                                                                segments={dims.map((dim) => ({
                                                                    key: dim.key,
                                                                    label: t(`dashboard.courseProgress.${dim.key}`),
                                                                    value: dim.completed,
                                                                    color: DIM_COLOR[dim.key],
                                                                }))}
                                                            />
                                                        ),
                                                    ]} />
                                            ),
                                        ]} />
                                ),
                            }
                        })

                        return (
                            <AsyncContent
                                isLoading={!coursesSwr.data && !coursesSwr.error}
                                skeleton={<SurfaceCardList items={skeletonItems} />}
                                isEmpty={courses.length === 0}
                                emptyContent={{
                                    title: t("profileSettings.learning.history.coursesEmpty"),
                                    description: t("profileSettings.learning.history.coursesEmptyHint"),
                                    onRetry: () => { router.push(pathConfig().locale(locale).course().build()) },
                                    retryLabel: t("profileSettings.learning.history.explore"),
                                }}
                                error={!coursesSwr.data ? coursesSwr.error : undefined}
                                errorContent={{
                                    title: t("profileSettings.learning.outline.error"),
                                    onRetry: () => { void coursesSwr.mutate() },
                                    retryLabel: t("profileSettings.learning.loadMore"),
                                }}
                            >
                                {filtered.length === 0 ? (
                                    <AsyncContentEmpty title={t("profileSettings.learning.history.noMatch")} />
                                ) : (
                                    <SurfaceCardList items={courseItems} />
                                )}
                            </AsyncContent>
                        )
                    },
                ]} />
        </div>
    )
}

"use client"

import React from "react"
import {
    Breadcrumbs,
    Button,
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import {
    PRIVACY_LAST_UPDATED,
    PRIVACY_POLICY,
    TERMS_LAST_UPDATED,
    TERMS_OF_SERVICE,
} from "@/resources/legal"
import type {
    LegalSection,
} from "@/resources/legal"
import { PageContainer } from "@/components/blocks/layout/PageContainer"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Which legal document this page renders. */
export type LegalKind = "terms" | "privacy"

/** Props for {@link LegalPage}. */
export interface LegalPageProps {
    /** Selects the legal document (and its `legal.*` header copy) to render. */
    kind: LegalKind
}

/** Props for the in-page {@link Section} renderer. */
interface SectionProps {
    /** One numbered legal section from the structured document. */
    section: LegalSection
}

/**
 * Renders one numbered section: heading + body paragraphs + an optional bullet
 * list whose items may carry a bold lead label. Plain Typography — no markdown.
 */
const Section = ({ section }: SectionProps) => {
    const sectionItems = [
        () => <Typography.Heading level={4} weight="semibold">{section.heading}</Typography.Heading>,
        ...(section.paragraphs?.map((paragraph) => () => (
            <Typography key={paragraph} type="body" color="muted" className="leading-relaxed">
                {paragraph}
            </Typography>
        )) ?? []),
        ...(section.items
            ? [() => (
                <ul data-principle="sibling-stack" className="flex flex-col gap-2">
                    {section.items!.map((item) => (
                        <li key={item.label ?? item.text} data-principle="icon-text" className="flex gap-2">
                            <span className="mt-2 size-1.5 shrink-0 rounded-full bg-default-400" aria-hidden />
                            <Typography type="body" color="muted" className="leading-relaxed">
                                {item.label ? (
                                    <span className="font-semibold text-foreground">{`${item.label} `}</span>
                                ) : null}
                                {item.text}
                            </Typography>
                        </li>
                    ))}
                </ul>
            )]
            : []),
    ]
    return (
        <StackV as="section" gap={4} items={sectionItems} />
    )
}

/**
 * Shared legal document page (`/terms`, `/privacy`): a 3-tier reading column —
 * breadcrumb → `PageHeader` (title + description + last-updated) → the document
 * rendered NATIVELY from structured content (numbered sections of paragraphs and
 * bullet lists) with Typography. No markdown. Document picked by `kind` + the
 * active locale (falls back to `vi`); copy lives in `legal/content/{privacy,terms}.ts`.
 *
 * @param props - {@link LegalPageProps}
 */
export const LegalPage = ({ kind }: LegalPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const docs = kind === "privacy" ? PRIVACY_POLICY : TERMS_OF_SERVICE
    const doc = docs[locale] ?? docs.vi
    const lastUpdatedIso = kind === "privacy" ? PRIVACY_LAST_UPDATED : TERMS_LAST_UPDATED
    // local-midnight parse avoids a timezone day-shift; localized long date
    const lastUpdated = new Date(`${lastUpdatedIso}T00:00:00`).toLocaleDateString(
        locale === "vi" ? "vi-VN" : "en-GB",
        { day: "numeric", month: "long", year: "numeric" },
    )

    const docItems = [
        () => (
            <Typography type="body" className="leading-relaxed">
                {doc.intro}
            </Typography>
        ),
        ...doc.sections.map((section) => () => (
            <Section key={section.heading} section={section} />
        )),
    ]

    return (
        <PageContainer>
            <Box principle="center-measure" className="mx-auto max-w-3xl"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                <StackV gap={7} principle="layout-split"
                    explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        () => (
                            <PageHeader
                                breadcrumb={(
                                    <Breadcrumbs>
                                        <Breadcrumbs.Item onPress={() => router.push(pathConfig().locale().build())}>
                                            {t("nav.home")}
                                        </Breadcrumbs.Item>
                                        <Breadcrumbs.Item>
                                            {t(`legal.${kind}.title`)}
                                        </Breadcrumbs.Item>
                                    </Breadcrumbs>
                                )}
                                title={t(`legal.${kind}.title`)}
                                description={t(`legal.${kind}.description`)}
                                meta={(
                                    <Typography type="body-xs" color="muted">
                                        {t("legal.lastUpdated", { date: lastUpdated })}
                                    </Typography>
                                )}
                            />
                        ),
                        () => <StackV gap={7} principle="layout-split"
                            explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                            items={docItems} />,
                        () => (
                            <Button
                                variant="tertiary"
                                size="sm"
                                className="self-start"
                                onPress={() => router.push(pathConfig().locale().course().build())}
                            >
                                {`${t("cart.browseCourses")} →`}
                            </Button>
                        ),
                    ]} />
            </Box>
        </PageContainer>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Button,
    Card,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { CheckListCard, CheckListItem } from "@/components/blocks/cards/CheckListCard"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Community membership feature container.
 *
 * A single-product purchase surface ($5/month equivalent): premium tech blog,
 * private community, course discount, recruitment exposure. Opening the shared
 * payment overlay with {@link PaymentFlow.Membership} lets the user pick a
 * gateway, which then runs `purchaseMembership` + redirects to checkout.
 * Mounted by the `/profile/membership` route. `"use client"` because it reads
 * the payment overlay singleton and routes.
 */
export const MembershipPage = () => {
    const t = useTranslations()
    // shared payment modal — opening it with the membership flow runs the purchase
    const { open: openPaymentModal } = usePaymentOverlayState()


    /** Perk rows shown under the price — each is a translated benefit line. */
    const perks = useMemo(
        () => [
            t("membership.perks.blog"),
            t("membership.perks.community"),
            t("membership.perks.discount"),
            t("membership.perks.recruitment"),
        ],
        [
            t,
        ],
    )

    /** Open the shared payment modal for the membership flow. */
    const onSubscribe = useCallback(
        () => {
            // hand the membership flow to the modal — it creates the checkout
            // with whichever payment method the user picks, then redirects
            openPaymentModal({
                flow: PaymentFlow.Membership,
            })
        },
        [
            openPaymentModal,
        ],
    )

    const cardItems = [
        () => (
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={[
                    () => (
                        <Typography type="h5" weight="semibold">
                            {t("membership.card.title")}
                        </Typography>
                    ),
                    () => (
                        <Typography type="body-sm" color="muted">
                            {t("membership.card.desc")}
                        </Typography>
                    ),
                ]}
            />
        ),
        () => (
            <div className="flex flex-col gap-0">
                <StackH
                    gap={3}
                    align="end"
                    principle="value-row"
                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                    items={[
                        () => (
                            <Typography type="h3" weight="bold">
                                {t("membership.price")}
                            </Typography>
                        ),
                        () => (
                            <Typography type="body-sm" color="muted" className="pb-1">
                                {t("membership.priceHint")}
                            </Typography>
                        ),
                    ]}
                />
                <Typography type="body-xs" color="muted">
                    {t("membership.priceApprox")}
                </Typography>
            </div>
        ),
        () => (
            <CheckListCard>
                {perks.map((perk) => (
                    <CheckListItem key={perk}>
                        <Typography type="body-sm">{perk}</Typography>
                    </CheckListItem>
                ))}
            </CheckListCard>
        ),
        () => (
            <Button
                variant="primary"
                fullWidth
                onPress={onSubscribe}
            >
                {t("membership.cta")}
            </Button>
        ),
    ]

    return (
        <Box identity={{ tier: "page", component: "MembershipPage" }} principle="center-measure" className="mx-auto max-w-2xl"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
            <Box principle="page-pad" className="p-6"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                <div className="flex flex-col gap-10">
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("membership.title")} />}
                        title={t("membership.title")}
                        description={t("membership.subtitle")}
                    />
                    <Card className="flex flex-col">
                        <Card.Content>
                            <StackV gap={6} items={cardItems} />
                        </Card.Content>
                    </Card>
                </div>
            </Box>
        </Box>
    )
}

import React from "react"
import { MapTrifoldIcon } from "@phosphor-icons/react"
import { MindMapRail, type MindMapRailItem, type MindMapRailTier } from "@/components/blocks/learn/MindMapRail"
import { MindMapContinueButton } from "@/components/blocks/learn/MindMapContinueButton"
import { MindMapFullscreenButton, type MindMapFullscreenButtonAriaLabels } from "@/components/blocks/learn/MindMapFullscreenButton"
import { Legend, type LegendItem } from "@/components/composites/stats/Legend"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { type ComponentTypeWithSkeleton, type SkeletonProps } from "@/components/frames/_slot"
import { ResizableRail } from "@/components/behaviors/ResizableRail"
import { StackH, StackV } from "@/components/frames/Stack"
import { Stage } from "@/components/frames/Stage"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { FillAvailable } from "@/components/frames/FillAvailable"
import type { CallerIdentity } from "@/components/frames/_identity"

/**
 * SCREEN — `_MindMapPage`: the course keyword graph, in its two real shapes.
 * See the component's own file header for the full function list and the two
 * corrections against the planner's proposed tree (`MindMapBackButton` and
 * `FloatingActionButton` are both absent, on purpose).
 *
 * The graph engine arrives as the `canvas` slot. This screen lays out the rail,
 * the floating chrome and the empty state; it does not know ReactFlow exists.
 *
 * FIVE LEAVES, by STRUCTURE — `workspace` and `standalone` are different
 * compositions (not one shape with a variant flag flipping paint), so each
 * gets its own leaves; `Empty` and `Loading` each lose or swap real nodes
 * (rail's shimmer vs. its populated list; the three floating blocks present
 * vs. absent), which is a structural change, not a data condition of one leaf.
 *
 * PRESENTATIONAL — every input arrives as a prop; the connected `index.tsx`
 * owns the fetch, the rail's filter state, and every `t()` call (`split.md`).
 *
 * Emits its own identity (`data-tier="page"` / `data-component="MindMapPage"`)
 * unconditionally on its root, same as `_ModulePage`/`_ContentPage` — see
 * `split.md`'s "Identity is data-tier + data-component" section.
 *
 * The viewport-relative full-bleed height, the canvas's floating-chrome
 * anchoring, and the rail's scroll region are all composed on `Stage` /
 * `ScrollArea` (`@/components/frames/Stage`, `@/components/frames/ScrollArea`)
 * — the two frames the vocabulary gap this screen flagged in a previous pass
 * was built to close. No raw `className` shape remains on this page.
 */

/** Which shape of the mind map this screen renders — see the file header. */
export type MindMapVariant = "workspace" | "standalone"

/** Props for {@link MindMapPage}. */
export interface MindMapPageProps {
    /** Which shape to render — see the file header for how the two differ. */
    variant: MindMapVariant

    // ── `workspace`: the `MindMapRail` search pane ──
    /** Current search text (controlled). Ignored outside `workspace`. */
    query: string
    /** Fired on every keystroke in the rail's search field. */
    onQuery: (query: string) => void
    /** Current popularity-tier filter. */
    tier: MindMapRailTier
    /** Fired with the tier the reader picked in the rail's funnel popover. */
    onTier: (tier: MindMapRailTier) => void
    /** The current query+tier's matching keywords, in display order. */
    items: Array<MindMapRailItem>
    /** Which result is currently focused on the canvas, if any. */
    selectedId?: string
    /** Fired with a result's id when its rail row is pressed. */
    onPick: (id: string) => void
    /** `true` → the rail's own query/tier fetch is in flight (independent of `isSkeleton`). */
    isRailLoading?: boolean
    /** Accessible name for the rail's search field. */
    railAriaLabel: string
    /** Accessible name for the rail's tier filter group. */
    railTierAriaLabel: string
    /** Accessible name for the rail's drag-to-resize handle. */
    railResizeAriaLabel: string

    // ── `standalone`: floating chrome over the canvas ──
    /** Href of the viewer's next unread lesson/challenge, or `null` when none resolves. Ignored outside `standalone`. */
    resumeHref?: string | null
    /** `true` → the viewer has read everything the map has to offer. */
    allContentDone?: boolean
    /** Fired on a resume press. */
    onResume?: () => void
    /** Accessible name for the resume action. */
    continueAriaLabel?: string
    /** Legend entries — colour swatch + label, e.g. done/in-progress/not-started/locked/current. */
    legendItems?: Array<LegendItem>
    /** Fired on every press of the zoom-in button. */
    onZoomIn?: () => void
    /** Fired on every press of the zoom-out button. */
    onZoomOut?: () => void
    /** Fired on every press of the fullscreen toggle. */
    onToggleFullscreen?: () => void
    /** `true` → canvas is currently fullscreen. */
    isFullscreen?: boolean
    /** Per-button accessible names for the zoom/fullscreen rail. */
    fullscreenAriaLabels?: MindMapFullscreenButtonAriaLabels

    // ── shared ──
    /** `true` → every block that can mirror itself does; the canvas gap swaps to its loading wording. */
    isSkeleton?: boolean
    /** `true` → the course has no authored map/modules yet. `workspace`-ONLY — see the file header. */
    isEmpty?: boolean

    /**
     * The graph itself, mounted by the caller. A screen composes; it does not own a
     * rendering engine — and an earlier pass left a literal placeholder here instead
     * of a slot, which meant wiring this screen would have shipped a mind-map page
     * with no map in it.
     */
    canvas: ComponentTypeWithSkeleton
    /**
     * The empty state's one way forward — browse the course's modules instead.
     * Omit → the empty state states the fact and offers nothing, which is right
     * only when there is nowhere useful to send the reader.
     */
    onBrowseModules?: () => void
    /** Every word the whole-screen empty state says — resolved by the connected half. */
    labels: MindMapPageLabels
}

/** All display text this screen owns, already localized by the connected half. */
export interface MindMapPageLabels {
    /** Heading when the course has no authored map yet. */
    emptyTitle: string
    /** Body when the course has no authored map yet. */
    emptyDescription: string
    /** Label on the empty state's way forward, paired with {@link MindMapPageProps.onBrowseModules}. */
    emptyCta: string
}

/** localStorage key + bounds the real workspace persists the rail width under. */
const RAIL_STORAGE_KEY = "mindmap-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 264
const RAIL_MAX_WIDTH = 520

/** This screen's own identity — handed down to whichever `Stage` is the root, per branch, instead of a wrapping div (BLOCK-2). See `_identity.ts`. */
const MIND_MAP_PAGE_IDENTITY: CallerIdentity = { tier: "page", component: "MindMapPage" }

/**
 * `workspace` empty state — the course has no authored map yet. Replaces the
 * ENTIRE spine, same "one frame + one composite, each badging itself" shape
 * `CourseContents`/`ModulePage` already established for this exact case. The
 * viewport-relative full-bleed height is `Stage`'s `fill="viewport"` — the
 * same shape the real spine below uses for the same reason.
 */
const MindMapWorkspaceEmpty = ({ labels, onBrowseModules }: MindMapWorkspaceEmptyProps) => (
    <Stage
        fill="viewport"
        identity={MIND_MAP_PAGE_IDENTITY}
        canvas={() => (
            <StackV
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={[() => (
                    <AsyncContentEmpty

                        icon={MapTrifoldIcon}
                        title={labels.emptyTitle}
                        description={labels.emptyDescription}
                        onRetry={onBrowseModules}
                        retryLabel={labels.emptyCta}
                    />
                )]}
            />
        )}
    />
)

/**
 * The mind-map screen, in its two shapes. See the file header for the function
 * list, the two corrections against the planner's proposed tree, and the
 * canvas gap.
 *
 * @param props - {@link MindMapPageProps}
 */
const _MindMapPage = ({
    variant,
    query,
    onQuery,
    tier,
    onTier,
    items,
    selectedId,
    onPick,
    isRailLoading = false,
    railAriaLabel,
    railTierAriaLabel,
    railResizeAriaLabel,
    resumeHref = null,
    allContentDone = false,
    onResume,
    continueAriaLabel = "",
    legendItems = [],
    onZoomIn = () => {},
    onZoomOut = () => {},
    onToggleFullscreen = () => {},
    isFullscreen = false,
    fullscreenAriaLabels = { zoomIn: "", zoomOut: "", toggleFullscreen: "" },
    isSkeleton = false,
    isEmpty = false,
    canvas: Canvas,
    onBrowseModules,
    labels,
}: MindMapPageProps) => {
    // Built as a thunk, called only for the non-empty branch below — mirrors
    // `_ModulePage`'s `spine(isSkeleton)`, so the empty branch never pays for
    // building a tree it will not render.
    const workspace = () => {
        const railSection = (
            <MindMapRail

                query={query}
                onQuery={onQuery}
                tier={tier}
                onTier={onTier}
                items={items}
                selectedId={selectedId}
                onPick={onPick}
                isLoading={isRailLoading}
                ariaLabel={railAriaLabel}
                tierAriaLabel={railTierAriaLabel}
                isSkeleton={isSkeleton}

            />
        )

        // The canvas region's floating chrome — in the real app these render as the
        // SAME ReactFlow engine's own Panel children. Only present (`standalone`,
        // resting) — `Stage` skips a slot entirely when it is `undefined`.
        const showOverlays = variant === "standalone" && !isSkeleton

        const topCenterSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <MindMapContinueButton

                            resumeHref={resumeHref}
                            allContentDone={allContentDone}
                            onResume={onResume}
                            continueAriaLabel={continueAriaLabel}
                            isSkeleton={isSkeleton}
                        />
                    )]}
                />
            )
            : undefined

        const bottomStartSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    gap={1}
                    isSkeleton={isSkeleton}
                    items={[() => <Legend items={legendItems} />]}
                />
            )
            : undefined

        const bottomEndSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    gap={1}
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <MindMapFullscreenButton

                            onZoomIn={onZoomIn}
                            onZoomOut={onZoomOut}
                            onToggleFullscreen={onToggleFullscreen}
                            isFullscreen={isFullscreen}
                            ariaLabels={fullscreenAriaLabels}
                            isSkeleton={isSkeleton}
                        />
                    )]}
                />
            )
            : undefined

        // The canvas region: the out-of-reach engine's gap, plus (standalone only) the
        // floating chrome that in the real app renders as the SAME engine's own Panel
        // children. `Stage` owns the positioning context and the three floating anchors —
        // no page-level `relative`/`absolute` left.
        const canvasStage = (
            <FillAvailable
                at="base"
                explain="Canvas stage consumes remaining workspace width beside the resizable rail — not a fixed-size peer."
                body={() => (
                    <Stage
                        canvas={Canvas}
                        topCenter={topCenterSlot}
                        bottomStart={bottomStartSlot}
                        bottomEnd={bottomEndSlot}
                        isSkeleton={isSkeleton}
                    />
                )}
            />
        )

        const workspaceRail = (
            <ResizableRail
                storageKey={RAIL_STORAGE_KEY}
                defaultWidth={RAIL_DEFAULT_WIDTH}
                minWidth={RAIL_MIN_WIDTH}
                maxWidth={RAIL_MAX_WIDTH}
                ariaLabel={railResizeAriaLabel}
                handleSide="right"
                className="h-full shrink-0 border-r border-default"

            >
                <ScrollArea
                    axis="y"
                    isSkeleton={isSkeleton}
                    body={({ isSkeleton }: SkeletonProps) => (
                        <StackV
                            principle="page-pad"
                            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                            isSkeleton={isSkeleton}
                            items={[() => railSection]}
                        />
                    )}
                />
            </ResizableRail>
        )

        const workspaceSections = (
            <>
                {variant === "workspace" ? workspaceRail : null}
                {canvasStage}
            </>
        )

        // The viewport-relative full-bleed height — the shell's own chrome height
        // subtracted — is `Stage`'s `fill="viewport"`; the rail + canvas row is its
        // `canvas` slot (a stage need not be a literal drawing surface — see the
        // frame's own file header for why this is the shape it names).
        return (
            <Stage
                fill="viewport"
                isSkeleton={isSkeleton}
                identity={MIND_MAP_PAGE_IDENTITY}
                canvas={({ isSkeleton }: SkeletonProps) => (
                    <StackH gap={1} isSkeleton={isSkeleton} items={[() => workspaceSections]} />
                )}
            />
        )
    }

    return variant === "workspace" && isEmpty
        ? <MindMapWorkspaceEmpty labels={labels} onBrowseModules={onBrowseModules} />
        : workspace()
}

export { _MindMapPage }

type MindMapWorkspaceEmptyProps = {
    labels: MindMapPageLabels
    onBrowseModules?: () => void
}

"use client"

import React, { useCallback, useMemo, useState } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryCourseMindMapSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseMindMapSwr"
import { useQueryCourseSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseSwr"
import type { CourseMindMapNodeData } from "@/modules/api/graphql/queries/types"
import { tierAllows } from "@/modules/utils/mind-map"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { ConceptMap } from "@/components/blocks/learn/ConceptMap"
import { MindMapCanvas } from "@/components/blocks/learn/ConceptMap/MindMapCanvas"
import type {
    MindMapPopularity,
    MindMapRailItem,
    MindMapRailTier,
} from "@/components/blocks/learn/MindMapRail"
import { Stage } from "@/components/frames/Stage"
import { _MindMapPage, type MindMapVariant } from "./component"

/**
 * The graph carries popularity as a free-form string; the rail names a closed set.
 * Anything else (or nothing) reads as "no tier", which is what structural nodes are.
 */
const toPopularity = (value: string | null | undefined): MindMapPopularity =>
    value === "high" || value === "medium" || value === "low" ? value : null

/** Props for {@link MindMapPage}. */
export interface MindMapPageProps {
    /**
     * Which shape to render. `workspace` is the learn-shell third column (rail
     * beside the graph); `standalone` is the full-bleed map with floating chrome.
     */
    variant?: MindMapVariant
}

/**
 * `MindMapPage` — the CONNECTED half of the course keyword graph. Owns the
 * course fetch (a hard refresh straight into this route has no other loader, so
 * the graph would otherwise stay empty), the map fetch, and the search + tier +
 * selection state that drives BOTH panes: the rail lists the matching keywords,
 * the canvas hides the non-matches. Selecting a keyword — from a canvas node OR
 * a rail row — recentres the map on it and opens its drawer.
 *
 * The filter is a plain in-memory pass over the loaded tree, not a query: the
 * whole graph is already in hand, so typing has to feel instant.
 *
 * @param props - {@link MindMapPageProps}
 */
export const MindMapPage = ({ variant = "workspace" }: MindMapPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const course = useAppSelector((state) => state.course.entity)
    const displayId = useAppSelector((state) => state.course.displayId)
    const { isLoading: isCourseLoading, error: courseError, mutate: reloadCourse } = useQueryCourseSwr()
    const { data, isLoading: isMapLoading } = useQueryCourseMindMapSwr(displayId ?? null)

    const [query, setQuery] = useState("")
    const [tier, setTier] = useState<MindMapRailTier>("all")
    const [selectedId, setSelectedId] = useState<string | null>(null)

    // The rail's result list: concept keywords clearing the tier floor and (while
    // typing) the substring, each carrying its ancestor breadcrumb for context.
    const items = useMemo<Array<MindMapRailItem>>(
        () => {
            if (!data) {
                return []
            }
            const value = query.trim().toLowerCase()
            const nodeById = new Map(data.nodes.map((node) => [node.id, node]))
            const parentOf = new Map(data.edges.map((edge) => [edge.target, edge.source]))
            const labelOf = (id: string) =>
                String((nodeById.get(id)?.data as unknown as CourseMindMapNodeData | undefined)?.label ?? "")
            const breadcrumb = (id: string) => {
                const parts: Array<string> = []
                let cursor = parentOf.get(id)
                while (cursor) {
                    const ancestor = nodeById.get(cursor)
                    if (!ancestor || ancestor.type === "course") {
                        break
                    }
                    parts.unshift(labelOf(cursor))
                    cursor = parentOf.get(cursor)
                }
                return parts.join(" › ")
            }
            return data.nodes
                .filter((node) => {
                    if (node.type !== "concept") {
                        return false
                    }
                    const nodeData = node.data as unknown as CourseMindMapNodeData
                    return tierAllows(nodeData.popularity, tier)
                        && (!value || String(nodeData.label).toLowerCase().includes(value))
                })
                .map((node) => {
                    const nodeData = node.data as unknown as CourseMindMapNodeData
                    return {
                        id: node.id,
                        label: String(nodeData.label),
                        popularity: toPopularity(nodeData.popularity),
                        breadcrumb: breadcrumb(node.id),
                    }
                })
        },
        [data, query, tier],
    )

    const onPick = useCallback((id: string) => setSelectedId(id), [])

    /** The empty state's funnel: an unauthored map still has modules worth reading. */
    const onBrowseModules = useCallback(
        () => {
            if (!displayId) {
                return
            }
            router.push(pathConfig().locale(locale).course(displayId).learn().content().build())
        },
        [displayId, locale, router],
    )

    // The graph itself — the screen mounts it, and knows nothing about it beyond
    // "something fills the canvas".
    const Canvas = useCallback(
        () => {
            // `standalone` draws the MODULE graph (progress + floating chrome); `workspace`
            // draws the KEYWORD graph beside the rail. Two different maps, one slot.
            if (variant === "standalone") {
                return <MindMapCanvas />
            }
            return data
                ? (
                    <ConceptMap
                        data={data}
                        query={query}
                        tier={tier}
                        selectedId={selectedId}
                        onSelectId={setSelectedId}
                    />
                )
                : null
        },
        [data, query, selectedId, tier, variant],
    )

    // error beats a stale loading flag (BLOCK-8); the course fetch is the one that
    // can fail loudly here, so it replaces the whole viewport rather than leaving
    // an empty canvas the reader would read as "this course has no map".
    if (courseError && !course) {
        return (
            <Stage
                identity={{ tier: "page", component: "MindMapPage" }}
                fill="viewport"
                canvas={() => (
                    <AsyncContentError
                        title={t("courseLanding.errorTitle")}
                        onRetry={() => { void reloadCourse() }}
                        retryLabel={t("courseLanding.retry")}
                    />
                )}
            />
        )
    }

    const isSkeleton = (isCourseLoading && !course) || (isMapLoading && !data)

    return (
        <_MindMapPage
            variant={variant}
            query={query}
            onQuery={setQuery}
            tier={tier}
            onTier={setTier}
            items={items}
            selectedId={selectedId ?? undefined}
            onPick={onPick}
            railAriaLabel={t("mindMap.toolbar.searchAria")}
            railTierAriaLabel={t("mindMap.toolbar.tierAria")}
            railResizeAriaLabel={t("mindMap.rail.resizeAria")}
            canvas={Canvas}
            isSkeleton={isSkeleton}
            // settled with a map that has no nodes → the course has nothing authored yet
            isEmpty={!isMapLoading && (!data || data.nodes.length === 0)}
            onBrowseModules={displayId ? onBrowseModules : undefined}
            labels={{
                emptyTitle: t("mindMap.emptyTitle"),
                emptyDescription: t("mindMap.emptyDescription"),
                emptyCta: t("mindMap.emptyCta"),
            }}
        />
    )
}

