"use client"

import React, { useCallback, useEffect, useRef, useState } from "react"
import { Handle, type Node, type NodeProps, Position, useReactFlow } from "@xyflow/react"
import { cn } from "@heroui/react"

/** React Flow node type id for the mock-interview diagram's single box node. */
export const MOCK_INTERVIEW_BOX_NODE_TYPE = "mockInterviewBox" as const

/** Data carried on a {@link MockInterviewBoxNode} — just its editable label. */
export type MockInterviewBoxNodeData = {
    /** Current label text shown on the box. */
    label: string
}

/** React Flow node type for the mock-interview diagram's box node. */
export type MockInterviewBoxNode = Node<MockInterviewBoxNodeData, typeof MOCK_INTERVIEW_BOX_NODE_TYPE>

/**
 * The diagram's only node shape: a simple rectangular labeled box. Double-click
 * enters inline rename (a plain `<input>`); `Enter` or blur commits the new label
 * back onto the node's `data.label` via `useReactFlow().updateNodeData`. Exposes a
 * connectable handle on every side so the candidate can drag an arrow from any edge
 * of the box to any edge of another box.
 *
 * @param props - React Flow `NodeProps` for `mockInterviewBox` nodes.
 */
export const BoxNode = ({ id, data, selected }: NodeProps<MockInterviewBoxNode>) => {
    const { updateNodeData } = useReactFlow()
    const [isEditing, setIsEditing] = useState(false)
    const [draft, setDraft] = useState(data.label)
    const inputRef = useRef<HTMLInputElement>(null)

    // keep the draft in sync if the label changes from outside while not editing
    useEffect(() => {
        if (!isEditing) {
            setDraft(data.label)
        }
    }, [data.label, isEditing])

    useEffect(() => {
        if (isEditing) {
            inputRef.current?.focus()
            inputRef.current?.select()
        }
    }, [isEditing])

    const commit = useCallback(() => {
        const next = draft.trim()
        updateNodeData(id, { label: next.length > 0 ? next : data.label })
        setIsEditing(false)
    }, [draft, id, data.label, updateNodeData])

    const onKeyDown = useCallback(
        (event: React.KeyboardEvent<HTMLInputElement>) => {
            if (event.key === "Enter") {
                event.preventDefault()
                commit()
            } else if (event.key === "Escape") {
                event.preventDefault()
                setDraft(data.label)
                setIsEditing(false)
            }
        },
        [commit, data.label],
    )

    const onContainerKeyDown = useCallback(
        (event: React.KeyboardEvent<HTMLDivElement>) => {
            if (!isEditing && (event.key === "Enter" || event.key === " ")) {
                event.preventDefault()
                setIsEditing(true)
            }
        },
        [isEditing],
    )

    return (
        // eslint-disable-next-line jsx-a11y/no-static-element-interactions -- react-flow node container; double-click/Enter-to-rename is keyboard-reachable via tabIndex + onKeyDown, role is intentionally dropped in edit mode so the inner input owns focus
        <div
            className={cn(
                "relative flex min-h-[56px] min-w-[140px] items-center justify-center rounded-xl border bg-surface px-4 py-2 text-center shadow-sm transition-colors",
                selected ? "border-accent ring-2 ring-accent/40" : "border-divider",
            )}
            onDoubleClick={() => setIsEditing(true)}
            onKeyDown={onContainerKeyDown}
            role={isEditing ? undefined : "button"}
            tabIndex={isEditing ? -1 : 0}
            aria-label={isEditing ? undefined : `${data.label}. Press Enter to rename.`}
        >
            <Handle className="opacity-0" position={Position.Top} type="target" />
            <Handle className="opacity-0" position={Position.Top} id="top-source" type="source" />
            <Handle className="opacity-0" position={Position.Right} type="source" />
            <Handle className="opacity-0" position={Position.Right} id="right-target" type="target" />
            <Handle className="opacity-0" position={Position.Bottom} type="target" />
            <Handle className="opacity-0" position={Position.Bottom} id="bottom-source" type="source" />
            <Handle className="opacity-0" position={Position.Left} type="source" />
            <Handle className="opacity-0" position={Position.Left} id="left-target" type="target" />

            {isEditing ? (
                <input
                    ref={inputRef}
                    className="nodrag w-full bg-transparent text-center text-sm text-foreground outline-none"
                    onBlur={commit}
                    onChange={(event) => setDraft(event.target.value)}
                    onKeyDown={onKeyDown}
                    value={draft}
                />
            ) : (
                <span className="max-w-full break-words text-sm text-foreground">{data.label}</span>
            )}
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useRef } from "react"
import {
    addEdge,
    Background,
    BackgroundVariant,
    type Connection,
    Controls,
    type Edge,
    ReactFlow,
    ReactFlowProvider,
    useEdgesState,
    useNodesState,
} from "@xyflow/react"
import { Button, cn } from "@heroui/react"
import { PlusIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"
import { BoxNode, MOCK_INTERVIEW_BOX_NODE_TYPE, type MockInterviewBoxNode } from "./BoxNode"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** A single box on the diagram, simplified to the fields a parent actually needs. */
export interface MockInterviewDiagramNodeSnapshot {
    /** Box id. */
    id: string
    /** Box's current label text. */
    label: string
}

/** A single arrow on the diagram, simplified to the fields a parent actually needs. */
export interface MockInterviewDiagramEdgeSnapshot {
    /** Id of the box the arrow starts from. */
    source: string
    /** Id of the box the arrow points to. */
    target: string
}

/** Props for the {@link MockInterviewDiagram} block. */
export interface MockInterviewDiagramProps extends WithClassNames<undefined> {
    /**
     * Fired whenever the boxes or arrows change (add/move/rename/connect/delete),
     * with a plain-object snapshot of the current diagram — not the internal
     * `@xyflow/react` node/edge objects — so a parent can grab the latest state
     * without importing xyflow types.
     */
    onChange?: (
        nodes: Array<MockInterviewDiagramNodeSnapshot>,
        edges: Array<MockInterviewDiagramEdgeSnapshot>,
    ) => void
}

/** Node type map registered on the canvas — a single rectangular labeled box. */
const NODE_TYPES = { [MOCK_INTERVIEW_BOX_NODE_TYPE]: BoxNode }

/** Starting box so the canvas never opens fully empty. */
const INITIAL_NODES: Array<MockInterviewBoxNode> = [
    {
        id: "box-1",
        type: MOCK_INTERVIEW_BOX_NODE_TYPE,
        position: { x: 0, y: 0 },
        data: { label: "New box" },
    },
]

const INITIAL_EDGES: Array<Edge> = []

/** Horizontal/vertical offset applied to each newly added box so they don't stack exactly. */
const NEW_BOX_OFFSET = 40

let nextBoxId = 2

/**
 * The interactive canvas rendered inside {@link MockInterviewDiagram} — split out
 * so it can freely use `@xyflow/react` hooks (`useNodesState`, `useEdgesState`)
 * under a `ReactFlowProvider`.
 */
const MockInterviewDiagramCanvas = ({ className, onChange }: MockInterviewDiagramProps) => {
    const t = useTranslations()
    const [nodes, setNodes, onNodesChange] = useNodesState<MockInterviewBoxNode>(INITIAL_NODES)
    const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>(INITIAL_EDGES)
    /** Position of the most recently added box, so the next one offsets from it (not the origin). */
    const lastAddedPositionRef = useRef(INITIAL_NODES[0]?.position ?? { x: 0, y: 0 })

    const onConnect = useCallback(
        (connection: Connection) => setEdges((current) => addEdge(connection, current)),
        [setEdges],
    )

    const addBox = useCallback(() => {
        const position = {
            x: lastAddedPositionRef.current.x + NEW_BOX_OFFSET,
            y: lastAddedPositionRef.current.y + NEW_BOX_OFFSET,
        }
        lastAddedPositionRef.current = position

        const newNode: MockInterviewBoxNode = {
            id: `box-${nextBoxId++}`,
            type: MOCK_INTERVIEW_BOX_NODE_TYPE,
            position,
            data: { label: t("mockInterview.diagram.newBoxLabel") },
        }
        setNodes((current) => [...current, newNode])
    }, [setNodes, t])

    // notify the parent with a plain-object snapshot whenever boxes or arrows change
    useEffect(() => {
        onChange?.(
            nodes.map((node) => ({ id: node.id, label: node.data.label })),
            edges.map((edge) => ({ source: edge.source, target: edge.target })),
        )
    }, [nodes, edges, onChange])

    const nodeTypes = useMemo(() => NODE_TYPES, [])

    return (
        <div className={cn("relative flex h-full w-full flex-col overflow-hidden rounded-xl", className)}>
            <Box principle="control-pad" className="border-b border-divider bg-surface px-3 py-2"
                explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                <StackH
                    gap={3}
                    principle="flex-action"
                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                    justify="between"
                    classNames={["w-full"]}
                    items={[
                        () => (
                            <span className="text-sm font-medium text-foreground">{t("mockInterview.diagram.title")}</span>
                        ),
                        () => (
                            <Button onPress={addBox} size="sm" variant="secondary">
                                <PlusIcon aria-hidden className="size-4" focusable="false" />
                                {t("mockInterview.diagram.addBox")}
                            </Button>
                        ),
                    ]}
                />
            </Box>
            <div className="relative min-h-0 flex-1">
                <ReactFlow
                    aria-label={t("mockInterview.diagram.canvasAria")}
                    className="text-foreground"
                    deleteKeyCode={["Backspace", "Delete"]}
                    edges={edges}
                    fitView
                    fitViewOptions={{ padding: 0.3 }}
                    maxZoom={2}
                    minZoom={0.3}
                    nodeTypes={nodeTypes}
                    nodes={nodes}
                    onConnect={onConnect}
                    onEdgesChange={onEdgesChange}
                    onNodesChange={onNodesChange}
                    proOptions={{ hideAttribution: true }}
                >
                    <Background gap={16} variant={BackgroundVariant.Dots} />
                    <Controls showFitView showInteractive={false} showZoom />
                </ReactFlow>
            </div>
        </div>
    )
}

/**
 * A minimal, self-contained editable box-and-arrow canvas for a mock-interview
 * candidate to sketch a system on. Backed by `@xyflow/react`: add a box from the
 * toolbar, drag it anywhere, double-click a box to rename its label inline, drag
 * from one box's edge to another to draw an arrow between them, select a box or
 * arrow and press `Backspace`/`Delete` to remove it, and pan/zoom the canvas
 * freely. Deliberately minimal — a single box shape, no auto-layout, no
 * grouping/subflows, no persistence, no undo/redo, no export.
 *
 * Wraps the canvas in a `ReactFlowProvider` so its custom node (which reads
 * `useReactFlow()` to commit inline-rename edits) always has store context, even
 * if this block is ever composed with other `@xyflow/react` trees on the page.
 *
 * @param props - {@link MockInterviewDiagramProps}
 */
export const MockInterviewDiagram = (props: MockInterviewDiagramProps) => {
    return (
        <ReactFlowProvider>
            <MockInterviewDiagramCanvas {...props} />
        </ReactFlowProvider>
    )
}

/** Plain node snapshot consumed by {@link serializeMockInterviewDiagram}. */
export interface MockInterviewDiagramSerializeNode {
    /** Node id (matches the `source`/`target` ids on edges). */
    id: string
    /** Node's current label text. */
    label: string
}

/** Plain edge snapshot consumed by {@link serializeMockInterviewDiagram}. */
export interface MockInterviewDiagramSerializeEdge {
    /** Id of the node this edge starts from. */
    source: string
    /** Id of the node this edge points to. */
    target: string
}

/**
 * Renders a diagram snapshot (plain nodes/edges — no `@xyflow/react` dependency)
 * into a short, human-readable plain-text block suitable for appending to a
 * chat/grading transcript: one `- {label}` line per box, followed by one
 * `{sourceLabel} -> {targetLabel}` line per arrow, with edge endpoints resolved
 * back to their node labels. Edges referencing an unknown node id fall back to
 * the raw id so nothing silently disappears. Returns `""` when there are no nodes.
 *
 * @param nodes - Boxes on the diagram.
 * @param edges - Arrows connecting boxes, by node id.
 * @returns A short plain-text description of the diagram, or `""` when empty.
 */
export const serializeMockInterviewDiagram = (
    nodes: Array<MockInterviewDiagramSerializeNode>,
    edges: Array<MockInterviewDiagramSerializeEdge>,
): string => {
    if (nodes.length === 0) {
        return ""
    }

    const labelById = new Map(nodes.map((node) => [node.id, node.label]))
    const resolveLabel = (id: string) => labelById.get(id) ?? id

    const nodeLines = nodes.map((node) => `- ${node.label}`)
    const edgeLines = edges.map((edge) => `${resolveLabel(edge.source)} -> ${resolveLabel(edge.target)}`)

    return [...nodeLines, ...edgeLines].join("\n")
}

