/** Props for {@link NotificationsPage}. */
export type NotificationsPageProps = Record<string, never>
/** Page size for the notification center's pager (bigger than the bell's popover page). */
const PAGE_SIZE = 20

/** The "All" tab has no `type` filter — a dedicated key distinct from any real
 *  {@link NotificationType} so it round-trips through the tab strip cleanly. */
const ALL_TAB = "all"

/** One filter tab: 1:1 with a real {@link NotificationType} (plus the "All"
 *  catch-all) — every type stays reachable, nothing is silently grouped away. */
type TabKey = typeof ALL_TAB | NotificationType

/** Icon per {@link NotificationType} — mirrors the motif each type's action carries
 *  elsewhere in the app (challenge = puzzle piece, streak = flame, …). */
const TYPE_ICONS: Record<NotificationType, ReactNode> = {
    [NotificationType.System]: <BellIcon aria-hidden focusable="false" />,
    [NotificationType.ChallengeGraded]: <PuzzlePieceIcon aria-hidden focusable="false" />,
    [NotificationType.CodingGraded]: <CodeIcon aria-hidden focusable="false" />,
    [NotificationType.MilestoneGraded]: <FlagIcon aria-hidden focusable="false" />,
    [NotificationType.NewFollower]: <UserPlusIcon aria-hidden focusable="false" />,
    [NotificationType.CommentReply]: <ChatCircleIcon aria-hidden focusable="false" />,
    [NotificationType.CommunityReply]: <UsersThreeIcon aria-hidden focusable="false" />,
    [NotificationType.SubscriptionGranted]: <SparkleIcon aria-hidden focusable="false" />,
    [NotificationType.Announcement]: <MegaphoneIcon aria-hidden focusable="false" />,
    [NotificationType.StreakMilestone]: <FlameIcon aria-hidden focusable="false" />,
}

/**
 * "Notification Center" — the full notification feed the bell's "View all"
 * deep-links into. Same query/mutations/deep-link resolution as
 * `NotificationBell` (`components/features/navbar/Navbar/NotificationBell`),
 * just with type filter tabs + a bigger offset-paginated page instead of the
 * popover's fixed recent slice. `"use client"` for the SWR hook, tab/page state,
 * and navigation.
 * @param props - optional root class name
 */
export const NotificationsPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const runGraphQL = useGraphQLWithToast()

    const [tab, setTab] = useState<TabKey>(ALL_TAB)
    const [page, setPage] = useState(1)

    const type = tab === ALL_TAB ? undefined : tab
    const offset = (page - 1) * PAGE_SIZE
    const { data, isLoading, error, mutate } = useQueryMyNotificationsSwr({
        limit: PAGE_SIZE,
        offset,
        type,
    })

    const items = data?.items ?? []
    const total = data?.total ?? 0
    const unreadCount = data?.unreadCount ?? 0
    const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE))

    /** Locale-aware relative-time formatter for the item timestamps — same
     *  formatting rule as the bell. */
    const relativeFormat = useMemo(
        () => new Intl.RelativeTimeFormat(locale, { numeric: "auto" }),
        [locale],
    )

    const formatRelative = useCallback(
        (iso: string): string => {
            const diffMs = new Date(iso).getTime() - Date.now()
            const diffMin = Math.round(diffMs / 60_000)
            const absMin = Math.abs(diffMin)
            if (absMin < 60) {
                return relativeFormat.format(diffMin, "minute")
            }
            const diffHour = Math.round(diffMin / 60)
            if (Math.abs(diffHour) < 24) {
                return relativeFormat.format(diffHour, "hour")
            }
            const diffDay = Math.round(diffHour / 24)
            return relativeFormat.format(diffDay, "day")
        },
        [relativeFormat],
    )

    /** Switching tabs re-queries from the first page — a filtered set may have
     *  fewer pages than the one the viewer was on. */
    const onSelectTab = useCallback((key: Key) => {
        setTab(String(key) as TabKey)
        setPage(1)
    }, [])

    /** Mark a single notification read and navigate to its resolved target —
     *  identical flow to the bell's `onPressItem`, sharing the same helper. */
    const onPressItem = useCallback(
        async (notification: QueryNotificationData) => {
            if (!notification.isRead) {
                await runGraphQL(
                    async () => {
                        const env = await mutateMarkNotificationAsRead({
                            request: { notificationId: notification.id },
                        })
                        return env.data!.markNotificationAsRead
                    },
                    { showSuccessToast: false, showErrorToast: false },
                )
                await mutate()
            }
            const { target } = notification
            if (!target) {
                return
            }
            const path = await resolveNotificationTargetPath(target)
            if (path) {
                router.push(`/${locale}${path}`)
            }
        },
        [locale, mutate, router, runGraphQL],
    )

    const onMarkAllRead = useCallback(
        async () => {
            await runGraphQL(
                async () => {
                    const env = await mutateMarkAllNotificationsAsRead({
                        request: undefined,
                    })
                    return env.data!.markAllNotificationsAsRead
                },
                { showSuccessToast: false, showErrorToast: true },
            )
            await mutate()
        },
        [mutate, runGraphQL],
    )

    const goToCourses = () => router.push(pathConfig().locale(locale).course().build())

    return (
        <Box identity={{ tier: "page", component: "NotificationsPage" }} principle="center-measure" className={"mx-auto max-w-3xl p-6"}
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
        >
            <StackV gap={7} principle="layout-split"
                explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                items={[
                    () => (
                        <PageHeader
                            breadcrumb={(
                                <ResponsiveBreadcrumb
                                    items={[
                                        {
                                            key: "home",
                                            label: t("nav.home"),
                                            onPress: () => router.push(pathConfig().locale(locale).build()),
                                        },
                                        {
                                            key: "notifications",
                                            label: t("notifications.title"),
                                        },
                                    ]}
                                />
                            )}
                            title={t("notifications.title")}
                            description={t("notifications.description")}
                            actions={unreadCount > 0 ? (
                                <Button
                                    variant="secondary"
                                    size="sm"
                                    onPress={onMarkAllRead}
                                >
                                    <CheckDoubleIcon className="size-4" aria-hidden focusable="false" />
                                    {t("notifications.markAllRead")}
                                </Button>
                            ) : undefined}
                        />
                    ),

                    () => (
                        <StackV gap={6} principle="block-boundary"
                            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                            items={[
                                () => (
                                    <TabsCard
                                        leftTabs={{
                                            items: [
                                                { key: ALL_TAB, label: t("notifications.tabs.all") },
                                                {
                                                    key: NotificationType.CommentReply,
                                                    label: t("notifications.tabs.commentReply"),
                                                    icon: <ChatCircleIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.CommunityReply,
                                                    label: t("notifications.tabs.communityReply"),
                                                    icon: <UsersThreeIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.MilestoneGraded,
                                                    label: t("notifications.tabs.milestoneGraded"),
                                                    icon: <FlagIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.ChallengeGraded,
                                                    label: t("notifications.tabs.challengeGraded"),
                                                    icon: <PuzzlePieceIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.CodingGraded,
                                                    label: t("notifications.tabs.codingGraded"),
                                                    icon: <CodeIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.NewFollower,
                                                    label: t("notifications.tabs.newFollower"),
                                                    icon: <UserPlusIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.SubscriptionGranted,
                                                    label: t("notifications.tabs.subscriptionGranted"),
                                                    icon: <SparkleIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.StreakMilestone,
                                                    label: t("notifications.tabs.streakMilestone"),
                                                    icon: <FlameIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.Announcement,
                                                    label: t("notifications.tabs.announcement"),
                                                    icon: <MegaphoneIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                                {
                                                    key: NotificationType.System,
                                                    label: t("notifications.tabs.system"),
                                                    icon: <BellIcon className="size-4" aria-hidden focusable="false" />,
                                                },
                                            ],
                                            selectedKey: tab,
                                            ariaLabel: t("notifications.tabsAria"),
                                            onSelectionChange: onSelectTab,
                                        }}
                                        className="overflow-x-auto"
                                    />
                                ),

                                () => (
                                    <AsyncContent
                                        isLoading={isLoading && !data}
                                        skeleton={(
                                            <SurfaceCardList
                                                items={[0, 1, 2, 3, 4].map((row) => ({
                                                    key: `skeleton-${row}`,
                                                    content: () => (
                                                        <Box principle="row-pad" className="px-4 py-4"
                                                            explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                                                            <StackH gap={4} principle="content-row" align="center"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                items={[
                                                                    () => <Skeleton className="size-9 shrink-0 rounded-full" />,
                                                                    () => (
                                                                        <StackV gap={3} principle="sibling-stack" classNames={["flex-1"]}
                                                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                            items={[
                                                                                () => <Skeleton className="h-4 w-2/3 rounded-medium" />,
                                                                                () => <Skeleton className="h-3 w-1/3 rounded-medium" />,
                                                                            ]} />
                                                                    ),
                                                                ]} />
                                                        </Box>
                                                    ),
                                                }))}
                                            />
                                        )}
                                        error={error}
                                        errorContent={{
                                            title: t("notifications.loadError"),
                                            onRetry: () => { void mutate() },
                                            retryLabel: t("notifications.retry"),
                                        }}
                                    >
                                        {items.length === 0 ? (
                                        // `EmptyState` intentionally omits its own frame — wrap it in `<Card>` to
                                        // match the shape of the list card when there is data (`components/card.md` §2).
                                            <Card>
                                                <CardContent>
                                                    <EmptyState
                                                        icon={BellIcon}
                                                        title={tab === ALL_TAB ? t("notifications.empty") : t("notifications.emptyFiltered")}
                                                        action={() => tab === ALL_TAB ? (
                                                        // Genuinely platform-empty (never had any notification) — the CTA must be
                                                        // a primary funnel invitation, not a quiet secondary one (canon §Conversion).
                                                            <Button size="sm" variant="primary" onPress={goToCourses}>
                                                                {t("notifications.emptyCta")}
                                                                <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                                                            </Button>
                                                        ) : (
                                                        // Filtered-empty (a filtered tab that's empty) — the CTA must go back to
                                                        // viewing everything (clear the filter), not push out to the course page
                                                        // (canon §State-matrix: 2 different reasons for empty → 2 CTAs with different meaning).
                                                            <Button size="sm" variant="secondary" onPress={() => onSelectTab(ALL_TAB)}>
                                                                {t("notifications.clearFilters")}
                                                            </Button>
                                                        )}
                                                    />
                                                </CardContent>
                                            </Card>
                                        ) : (
                                            <StackV gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                items={[
                                                    () => {
                                                        const notificationItems: Array<SurfaceCardListItem> = items.map((notification) => ({
                                                            key: notification.id,
                                                            leading: () => (
                                                                <span
                                                                    className={cn(
                                                                        "flex size-9 shrink-0 items-center justify-center rounded-full [&>svg]:size-4",
                                                                        notification.isRead
                                                                            ? "bg-default text-muted"
                                                                            : "bg-accent-soft text-accent-soft-foreground",
                                                                    )}
                                                                >
                                                                    {TYPE_ICONS[notification.type]}
                                                                </span>
                                                            ),
                                                            title: t(
                                                                notification.title.key,
                                                                notification.title.params ?? undefined,
                                                            ),
                                                            subtitle: notification.body
                                                                ? t(
                                                                    notification.body.key,
                                                                    notification.body.params ?? undefined,
                                                                )
                                                                : undefined,
                                                            meta: () => (
                                                                <Typography type="body-xs" color="muted" className="whitespace-nowrap">
                                                                    {formatRelative(notification.createdAt)}
                                                                </Typography>
                                                            ),
                                                            // unread dot: `title` is plain text; unread signal rides trailing
                                                            // (already echoed by the leading badge's accent tint).
                                                            trailing: !notification.isRead ? () => (
                                                                <CircleIcon
                                                                    weight="fill"
                                                                    aria-hidden
                                                                    focusable="false"
                                                                    className="size-1.5 shrink-0 text-accent-soft-foreground"
                                                                />
                                                            ) : undefined,
                                                            onPress: () => { void onPressItem(notification) },
                                                        }))
                                                        return <SurfaceCardList items={notificationItems} />
                                                    },

                                                    () => (totalPages > 1 ? (
                                                        <StackH gap={4} principle="content-row" justify="between" align="center"
                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                            items={[
                                                                () => (
                                                                    <Typography type="body-xs" color="muted">
                                                                        {t("notifications.pageInfo", {
                                                                            from: offset + 1,
                                                                            to: Math.min(offset + PAGE_SIZE, total),
                                                                            total,
                                                                        })}
                                                                    </Typography>
                                                                ),
                                                                () => (
                                                                    <StackH gap={3} principle="flex-action" align="center"
                                                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                                        items={[
                                                                            () => (
                                                                                <Button
                                                                                    variant="secondary"
                                                                                    size="sm"
                                                                                    isDisabled={page <= 1}
                                                                                    onPress={() => setPage((current) => Math.max(1, current - 1))}
                                                                                >
                                                                                    {t("common.pagination.previous")}
                                                                                </Button>
                                                                            ),
                                                                            () => (
                                                                                <Button
                                                                                    variant="secondary"
                                                                                    size="sm"
                                                                                    isDisabled={page >= totalPages}
                                                                                    onPress={() => setPage((current) => Math.min(totalPages, current + 1))}
                                                                                >
                                                                                    {t("common.pagination.next")}
                                                                                </Button>
                                                                            ),
                                                                        ]} />
                                                                ),
                                                            ]} />
                                                    ) : null),
                                                ]} />
                                        )}
                                    </AsyncContent>
                                ),
                            ]} />
                    ),
                ]} />
        </Box>
    )
}

"use client"

import React, { useEffect } from "react"
import { Button, Spinner, Typography } from "@heroui/react"
import { useRouter, useSearchParams } from "next/navigation"
import { useLocale, useTranslations } from "next-intl"
import { pathConfig } from "@/resources/path"

import { OauthAction } from "@/modules/types/enums/oauth-action"
import { OAUTH_ACTION_MESSAGE_KEY_MAP } from "@/modules/utils/oauth-action-message"
import { Spacer } from "@/components/blocks/layout/Spacer"
import { SessionStorage } from "@/modules/storage/session/storage"
import { SessionStorageId } from "@/modules/storage/session/enums/id"
import { type SessionStoragePostLoginRedirect } from "@/modules/storage/session/types/post-login-redirect"
import { StackV } from "@/components/frames/Stack"

export * from "@/modules/types/enums/oauth-action"

/** Props for {@link OauthRedirectPage}. */
export interface OauthRedirectPageProps {
    /**
     * The OAuth lifecycle step this redirect page represents — selects the i18n
     * message shown under the spinner. The redirect destination (locale home)
     * and delay are identical for every step.
     */
    action: OauthAction
}

/**
 * OAuth redirect landing — shown after a Keycloak provider hand-off
 * (login / logout / generic authenticate). Waits ~1s, then sends the user to
 * the locale home. Presentational shell + the redirect effect.
 *
 * `"use client"`: relies on `useRouter`, `useEffect` and `useLocale`.
 */
export const OauthRedirectPage = ({ action}: OauthRedirectPageProps) => {
    const router = useRouter()
    const locale = useLocale()
    const t = useTranslations()
    const searchParams = useSearchParams()

    // Keycloak (and the OAuth2 spec) hands back a failed/cancelled round-trip on the
    // redirect_uri as `?error=...` (e.g. `access_denied`), never establishing a session.
    // Detect it BEFORE redirecting so we don't drop the user home wearing success chrome.
    const hasOauthError = Boolean(searchParams.get("error"))

    // Hold the user briefly so the Keycloak session settles, then continue on: a sign-in
    // started from the `/login` guard stashed where the visitor was headed (query params
    // don't survive the IdP round-trip); anything else (logout, generic authenticate) goes home.
    // setTimeout (not `sleep().then()`) so the pending redirect is cancelled via cleanup if
    // this page unmounts within the delay — `sleep()`'s promise can't be cancelled.
    useEffect(() => {
        // a failed/cancelled hand-off never authenticated the user — render the failure
        // state instead of forwarding them on as if signed in.
        if (hasOauthError) {
            return
        }
        const handle = setTimeout(() => {
            let target: string | undefined
            if (action === OauthAction.Login) {
                const stashed = SessionStorage.getItem<SessionStoragePostLoginRedirect>(
                    SessionStorageId.PostLoginRedirect,
                )
                target = stashed?.target
                SessionStorage.removeItem(SessionStorageId.PostLoginRedirect)
            }
            router.push(target ?? pathConfig().locale(locale).build())
        }, 1000)

        return () => clearTimeout(handle)
    }, [action, locale, router, hasOauthError])

    if (hasOauthError) {
        const errorItems = [
            () => (
                <Typography type="h5" weight="semibold" align="center">
                    {t("auth.oauth.failedTitle")}
                </Typography>
            ),
            () => (
                <Typography type="body-sm" color="muted" align="center">
                    {t("auth.oauth.failedDescription")}
                </Typography>
            ),
            () => <Spacer y={3} />,
            () => (
                <Button
                    variant="primary"
                    onPress={() => router.replace(pathConfig().locale(locale).login().build())}
                >
                    {t("auth.oauth.retry")}
                </Button>
            ),
        ]
        return (
            <div className={"flex min-h-[60vh] flex-col items-center justify-center"}>
                <div className="max-w-sm text-center">
                    <StackV
                        gap={3}
                        align="center"
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={errorItems}
                    />
                </div>
            </div>
        )
    }

    const loadingItems = [
        () => (
            <Spinner
                color="accent"
                size="lg"
            />
        ),
        () => <Spacer y={3} />,
        () => (
            <div className="text-sm">
                {t(OAUTH_ACTION_MESSAGE_KEY_MAP[action])}
            </div>
        ),
    ]

    return (
        <div className={"flex min-h-[60vh] flex-col items-center justify-center"}>
            <StackV gap={3} align="center" principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={loadingItems}  />
        </div>
    )
}

import { InputText } from "@/components/atoms/forms"
import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { CaretRightIcon, GearSixIcon, SparkleIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Breadcrumbs, type BreadcrumbItem } from "@/components/atoms/navigation/Breadcrumbs"
import { Chip } from "@/components/atoms/chips/Chip"

import { Typography } from "@/components/atoms/text/Typography"
import {
    SurfaceCard,
    SurfaceCardAccordion,
    type SurfaceCardAccordionItem,
} from "@/components/composites/cards/SurfaceCard"
import { Callout } from "@/components/composites/feedback/Callout"
import { ListRow } from "@/components/composites/lists/List"
import { PageHeader } from "@/components/composites/layout/Page"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { SplitWorkspace } from "@/components/frames/SplitWorkspace"
import {
    ContentRelatedList,
    type ContentRelatedItem,
} from "@/components/blocks/learn/ContentRelatedList"
import {
    SubmissionScoreCard,
    type AiModelCategory,
} from "@/components/blocks/learn/SubmissionScoreCard"

/**
 * `PersonalProjectTaskPage` — the screen to solve one personal-project task. A
 * screen owns a list of functions. Split workspace: a reading column that swaps
 * per task (task identity, the locked-preview banner, the authored brief or the
 * legacy rubric/implementation guides, and related lessons) beside a
 * persistent, sticky act column (repo URL, the settings-drawer trigger,
 * evaluate/secondary actions, and the latest graded result). Two columns
 * composed with `SplitWorkspace`: a `min-w-0 flex-1` reading column beside a
 * `shrink-0 w-[360px]` sticky aside, stacked on mobile/tablet →
 * `@app-xl:flex-row` on desktop. The grading-settings drawer content is not
 * built — `onOpenSettings` is a chrome trigger only.
 *
 * PRESENTATIONAL — every input arrives as a prop; this twin owns no data of
 * its own, so `index.tsx` IS the presentational file (no separate connected
 * wrapper, no `component.tsx` split) — mirrors `MindMapPage`'s convention.
 *
 * Emits its own identity (`data-tier="page"` / `data-component="PersonalProjectTaskPage"`)
 * unconditionally, handed down to the root `Container` via its `identity` prop
 * (see `frames/_identity.ts`) rather than drawn on a wrapper `div` of its own
 * (`tiers/block.md` BLOCK-2: a page never draws a shape of its own) — same as
 * `split.md`'s "Identity is data-tier + data-component" section. The
 * breadcrumb sits in a `StackH inline` (shrink-to-content sizing) rather
 * than a raw `div`.
 */

/** One personal-project schema-v1 evaluation criterion — the legacy rubric row. */
export interface PersonalProjectTaskLegacyCriterionItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** The criterion sentence itself. */
    text: string
    /** Points this criterion is worth. */
    score: number
    /** Optional grading hint, markdown. Omit → the panel shows a plain "no hint" line. */
    hint?: string
}

/** One legacy per-language implementation guide (schema-v1 tasks with no authored brief). */
export interface PersonalProjectTaskLegacyCodeImplementationItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** Target language label, e.g. "TypeScript". */
    lang: string
    /** How to approach the task in this language, markdown. */
    guide: string
    /** A worked example, markdown. */
    example: string
}

/** The task identity this screen reads about. */
export interface PersonalProjectTaskPageTask {
    /** Task title. */
    title: string
    /** One-paragraph summary of what the task asks for. */
    description?: string
}

/** The schema-v2 authored brief for this task. */
export interface PersonalProjectTaskPageBrief {
    /** The brief itself, markdown, already resolved to the active language/locale. */
    body: string
}

/** Cost/quality tier + model byline data for a graded submission — see {@link SubmissionScoreCard}. */
export interface PersonalProjectSubmissionResult {
    /** Points earned on the latest graded attempt. */
    score: number
    /** Points the attempt was scored out of. */
    maxScore?: number
    /** Whether this score cleared the pass bar. */
    isPassing: boolean
    /** The pass bar itself, in points. */
    passScore?: number
    /** A short line of grader feedback. */
    shortFeedback?: string
    /** The model that produced this grade. */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
    /** Relative time since grading, already localized. */
    timeAgo?: string
}

/** Everything the persistent, sticky act column needs — the project-level submission loop. */
export interface PersonalProjectTaskSubmissionPanelProps {
    /** The GitHub repo URL as typed so far. */
    repoUrl: string
    /** Fired as the learner types the repo URL. */
    onRepoUrlChange: (value: string) => void
    /** Validation message for the repo URL field. Set → the field shows invalid. */
    repoUrlError?: string
    /** Grading language summary shown in the settings row, e.g. "TypeScript". */
    settingsLangLabel: string
    /** Grading branch summary shown in the settings row, e.g. "main". */
    settingsBranch: string
    /** Fired when the settings summary row is pressed — chrome trigger only, see file header. */
    onOpenSettings: () => void
    /** Fired to submit the current repo for AI evaluation. */
    onEvaluate: () => void
    /** `true` → the evaluate CTA shows its own spinner and blocks further presses. */
    isEvaluatePending?: boolean
    /** `true` → the evaluate CTA is disabled (the caller's own combined business rule — locked, syncing, …). */
    isEvaluateDisabled?: boolean
    /** `true` → at least one attempt exists, so the secondary actions unlock and the CTA reads "Re-evaluate". */
    hasAttempts?: boolean
    /** Fired to open the full feedback/result page. */
    onOpenFeedbackDetails: () => void
    /** Fired to open the attempts history drawer. */
    onOpenAttempts: () => void
    /** The latest graded attempt. Present → the score card renders; omit → nothing has been graded yet. */
    result?: PersonalProjectSubmissionResult
}

/** Props for {@link PersonalProjectTaskPage}. */
export interface PersonalProjectTaskPageProps {
    /** Breadcrumb trail as DATA — `PageHeader` builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<BreadcrumbItem>
    /** The task being read/solved. */
    task: PersonalProjectTaskPageTask
    /**
     * `true` → this task is not yet unlocked for the learner (previewing ahead
     * of their current milestone position). Shows the warning banner; nothing
     * else in the reading column changes shape.
     */
    isLocked?: boolean
    /** The schema-v2 authored brief. */
    brief: PersonalProjectTaskPageBrief
    /** Schema-v1 legacy rubric — only present on tasks with no authored brief. */
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    /** Schema-v1 legacy per-language implementation guides — only present alongside {@link legacyCriteria}. */
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    /** Lessons related to this task's subject, auto-derived by the caller from its title/description. */
    relatedItems: Array<ContentRelatedItem>
    /** Section label for {@link relatedItems}, e.g. "You might want to read". */
    relatedLabel: string
    /** Everything the persistent, sticky act column needs. */
    submissionPanelProps: PersonalProjectTaskSubmissionPanelProps
    /**
     * `true` → every part that can mirror itself does. Flows down into the
     * reading column's composed parts and the act column's fields/buttons/score
     * card (§12c) rather than a parallel skeleton tree built here.
     */
    isSkeleton?: boolean
}

/** Skeleton placeholder count for the legacy accordions while real data hasn't landed yet. */
const LEGACY_SKELETON_ROWS = 2

/** `ListRow.leading` for the grading-settings summary row — a gear icon, hidden while skeleton. */
const SettingsLeading = ({ isSkeleton }: SkeletonProps) =>
    isSkeleton ? null : <GearSixIcon aria-hidden focusable="false" className="size-4" />

/** `ListRow.trailing` for the grading-settings summary row — the disclosure chevron. */
const SettingsChevron = () => <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />

/** One markdown body at the `compact` measure the legacy accordion panels use. */
const legacyMarkdown = (body: string) => (
    <MarkdownContent source={body} measure="compact" />
)

/** One legacy code-implementation accordion panel body: guide, then a worked example. */
const legacyCodeBody = (item: PersonalProjectTaskLegacyCodeImplementationItem) => {
    const guideSection = (
        <>
            <Typography size="xs" weight="medium" color="muted" text="Guide" />
            {legacyMarkdown(item.guide)}
        </>
    )
    const exampleSection = (
        <>
            <Typography size="xs" weight="medium" color="muted" text="Example" />
            {legacyMarkdown(item.example)}
        </>
    )
    return (
        <StackV
            gap={4}

            items={[
                () => <StackV gap={2} items={[() => guideSection]} />,
                () => <StackV gap={2} items={[() => exampleSection]} />,
            ]}
        />
    )
}

/**
 * The reading column: task identity (`PageHeader`) + the locked banner + the
 * brief itself + the legacy rubric/implementation guides + related lessons.
 * A private render helper (see file header for why this is not a separate
 * storied component), not an anatomy node of its own.
 */
const readingColumn = (props: {
    breadcrumbItems?: Array<BreadcrumbItem>
    task: PersonalProjectTaskPageTask
    isLocked: boolean
    brief: PersonalProjectTaskPageBrief
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    relatedItems: Array<ContentRelatedItem>
    relatedLabel: string
    isSkeleton: boolean
}) => {
    const {
        breadcrumbItems,
        task,
        isLocked,
        brief,
        legacyCriteria,
        legacyCodeImplementations,
        relatedItems,
        relatedLabel,
        isSkeleton,
    } = props

    const hasLegacyCriteria = (legacyCriteria?.length ?? 0) > 0
    const hasLegacyCode = (legacyCodeImplementations?.length ?? 0) > 0
    const showLegacy = isSkeleton || hasLegacyCriteria || hasLegacyCode
    // Schema-v2 tasks always carry an authored brief; schema-v1 (legacy) tasks
    // hand this screen an empty `body` and rely on the legacy section instead
    // (mirrors `src`'s `TaskBrief` self-hiding when `briefs.length === 0`).
    const showBrief = isSkeleton || brief.body.trim().length > 0

    const criteriaItems: Array<SurfaceCardAccordionItem> = hasLegacyCriteria
        ? (legacyCriteria ?? []).map((item, index) => ({
            id: item.key,
            title: `${index + 1}. ${item.text}`,
            titleEnd: () => <Chip tone="accent" text={`${item.score} points`} />,
            body: () => (
                item.hint
                    ? legacyMarkdown(item.hint)
                    : <Typography size="sm" color="muted"
                        isItalic text="No grading hint yet" />
            ),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `criteria-skeleton-${index}`, title: "", body: () => null }))
            : []

    const codeItems: Array<SurfaceCardAccordionItem> = hasLegacyCode
        ? (legacyCodeImplementations ?? []).map((item) => ({
            id: item.key,
            title: item.lang,
            body: () => legacyCodeBody(item),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `code-skeleton-${index}`, title: "", body: () => null }))
            : []

    const legacyAccordions = (
        <>
            {hasLegacyCriteria || isSkeleton ? (
                <SurfaceCardAccordion
                    variant="nested"
                    items={criteriaItems}
                    allowsMultipleExpanded
                    isSkeleton={isSkeleton}


                />
            ) : null}
            {hasLegacyCode || isSkeleton ? (
                <SurfaceCardAccordion
                    variant="nested"
                    items={codeItems}
                    allowsMultipleExpanded
                    isSkeleton={isSkeleton}


                />
            ) : null}
        </>
    )

    const readingSections = (
        <>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton || breadcrumbItems?.length ? (
                        <StackH
                            inline
                            gap={1}
                            body={() => (
                                <Breadcrumbs collapseOnMobile collapseFrom={4} items={breadcrumbItems ?? []} isSkeleton={isSkeleton} />
                            )}
                        />
                    ) : undefined
                }
                title={task.title}
                description={task.description}
            />

            {!isSkeleton && isLocked ? (
                <Callout
                    status="warning"
                    title="Preview of a task not yet unlocked"
                    description="You need to finish the current task before you can work on this one."

                />
            ) : null}

            {showBrief ? (
                <SurfaceCard
                    label="Guide"
                    isSkeleton={isSkeleton}

                    body={() => <MarkdownContent source={brief.body} />}
                />
            ) : null}

            {showLegacy ? (
                <SurfaceCard
                    label="Evaluation criteria (legacy)"
                    isSkeleton={isSkeleton}

                    body={() => <StackV gap={6} items={[() => legacyAccordions]} />}
                />
            ) : null}

            <ContentRelatedList
                label={relatedLabel}
                items={relatedItems}
                isSkeleton={isSkeleton}

            />
        </>
    )

    return <StackV gap={7} isSkeleton={isSkeleton} items={[() => readingSections]} />
}

/**
 * The persistent, sticky act column: repo URL + settings summary trigger +
 * evaluate/secondary actions + the latest graded result. A private render
 * helper (see file header), not an anatomy node of its own.
 */
const submissionPanel = (props: {
    panel: PersonalProjectTaskSubmissionPanelProps
    isSkeleton: boolean
}) => {
    const { panel, isSkeleton } = props
    const hasAttempts = panel.hasAttempts ?? false

    const evaluateActions = (
        <>
            <Button
                label={hasAttempts ? "Re-evaluate" : "Evaluate"}
                prefixIcon={SparkleIcon}
                onPress={panel.onEvaluate}
                isPending={panel.isEvaluatePending}
                isDisabled={panel.isEvaluateDisabled}
                isSkeleton={isSkeleton}

            />
            <Button
                label="View feedback"
                variant="tertiary"
                onPress={panel.onOpenFeedbackDetails}
                isDisabled={!hasAttempts}
                isSkeleton={isSkeleton}

            />
            <Button
                label="View submission history"
                variant="tertiary"
                onPress={panel.onOpenAttempts}
                isDisabled={!hasAttempts}
                isSkeleton={isSkeleton}

            />
        </>
    )

    const githubFields = (
        <>
            <InputText
                label="GitHub repo URL"
                value={panel.repoUrl}
                onValueChange={panel.onRepoUrlChange}
                errorMessage={panel.repoUrlError}
                placeholder="https://github.com/…"
                ariaLabel="GitHub repo URL"
                isSkeleton={isSkeleton}

            />
            <div>
                <ListRow
                    leading={SettingsLeading}
                    title="Grading settings"
                    meta={() => <Typography size="sm" color="muted" text={`${panel.settingsLangLabel} · ${panel.settingsBranch}`} />}
                    trailing={SettingsChevron}
                    onPress={panel.onOpenSettings}
                    isSkeleton={isSkeleton}

                />
            </div>
            <StackH gap={3} at="sm" principle="flex-action" isSkeleton={isSkeleton} items={[() => evaluateActions]}
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            />
        </>
    )

    const panelSections = (
        <>
            <SurfaceCard
                label="Project GitHub"
                isSkeleton={isSkeleton}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => githubFields]} />}
            />

            {isSkeleton || panel.result != null ? (
                <SubmissionScoreCard
                    label="Latest grading result"
                    score={panel.result?.score ?? 0}
                    maxScore={panel.result?.maxScore}
                    isPassing={panel.result?.isPassing ?? true}
                    passScore={panel.result?.passScore}
                    shortFeedback={panel.result?.shortFeedback}
                    gradedByModel={panel.result?.gradedByModel}
                    modelCategory={panel.result?.modelCategory}
                    timeAgo={panel.result?.timeAgo}
                    isSkeleton={isSkeleton}


                />
            ) : null}
        </>
    )

    return <StackV gap={6} isSkeleton={isSkeleton} items={[() => panelSections]} />
}

/**
 * The personal-project task solve screen. See the file header for the function
 * list, the reuse map, and the two-column layout's known limits.
 *
 * @param props - {@link PersonalProjectTaskPageProps}
 */
const PersonalProjectTaskPage = ({
    breadcrumbItems,
    task,
    isLocked = false,
    brief,
    legacyCriteria,
    legacyCodeImplementations,
    relatedItems,
    relatedLabel,
    submissionPanelProps,
    isSkeleton = false,
}: PersonalProjectTaskPageProps) => (
    <Container
        identity={{ tier: "page", component: "PersonalProjectTaskPage" }}
        size="xl"
        padding={6}
        body={() => (
            <SplitWorkspace

                main={() => readingColumn({
                    breadcrumbItems,
                    task,
                    isLocked,
                    brief,
                    legacyCriteria,
                    legacyCodeImplementations,
                    relatedItems,
                    relatedLabel,
                    isSkeleton,
                })}
                aside={() => submissionPanel({ panel: submissionPanelProps, isSkeleton })}
            />
        )}
    />
)

export { PersonalProjectTaskPage }

"use client"

import React, { useEffect } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useParams, useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import { usePlaygroundSessionContext } from "@/components/providers/PlaygroundSessionProvider"
import { PlaygroundCliSession } from "@/components/blocks/learn/PlaygroundCliSession"
import { PlaygroundRagSession } from "@/components/blocks/learn/PlaygroundRagSession"
import { Typography } from "@/components/atoms/text/Typography"
import { Stage } from "@/components/frames/Stage"

/**
 * `PlaygroundSessionPage` — the 20-step work surface. `slug === "rag"` swaps the
 * CLI Terminal/Resources workspace for the on-device RAG widget; both are blocks,
 * and choosing between them is this screen's one structural decision.
 *
 * GUARDED: a session with no paired machine is a dead surface — that is the whole
 * reason Setup is its own route — so an unpaired visit (a deep link, or a refresh
 * that minted a fresh session) is sent back to Setup. A machine that paired and
 * then DROPPED stays here (`everConnected`) and gets the reconnect strip instead.
 */
export const PlaygroundSessionPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // Course from the URL, NOT the store — see the Setup screen for why.
    const params = useParams()
    const courseDisplayId = String(params.courseId ?? "")
    const { slug, isRag, playground, isLoading, byomState, everConnected } = usePlaygroundSessionContext()

    const setupPath = pathConfig().locale(locale).course(courseDisplayId).learn().playground(slug).build()

    useEffect(() => {
        if (isLoading || !playground) {
            return
        }
        if (!byomState.connected && !everConnected) {
            router.replace(setupPath)
        }
    }, [isLoading, playground, byomState.connected, everConnected, router, setupPath])

    if (isLoading || !playground) {
        return (
            <Stage
                fill="viewport"
                identity={{ tier: "page", component: "PlaygroundSessionPage" }}
                canvas={() => <Typography size="sm" color="muted" text={t("common.loading")} />}
            />
        )
    }

    return isRag ? <PlaygroundRagSession /> : <PlaygroundCliSession />
}

"use client"

import React from "react"
import useSWR from "swr"
import { useTranslations } from "next-intl"
import { useAppSelector } from "@/redux/hooks"
import { queryCodingLeaderboard } from "@/modules/api/graphql/queries/query-coding-leaderboard"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { StackH } from "@/components/frames/Stack"

/** Max ranked users to pull for the board (backend caps this too). */
const LEADERBOARD_LIMIT = 50

/** Placeholder rows shown while the board loads. */
const SKELETON_ROWS = 6

/** One ranked entry as returned by `codingLeaderboard`. */
interface LeaderboardEntry {
    userId: string
    username: string
    solvedCount: number
}

/** Props for {@link LeaderboardRow}. */
interface LeaderboardRowProps {
    /** 1-based position on the board. */
    rank: number
    /** The ranked user. Absent only while {@link LeaderboardRowProps.isSkeleton}. */
    entry?: LeaderboardEntry
    /** Tints the signed-in viewer's own row. */
    isViewer?: boolean
    /** Already-translated "N solved" metric. */
    solvedLabel?: string
    /** Already-translated "you" chip label. */
    youLabel?: string
    /** First load → this row rests. Its resting state lives here, beside the loaded one. */
    isSkeleton?: boolean
}

/**
 * One board row: rank · avatar + name · the solved metric. ONE description of the
 * shape, resting or loaded, so the two cannot drift (`loading-and-skeleton.md`).
 *
 * @param props - {@link LeaderboardRowProps}
 */
const LeaderboardRow = ({ rank, entry, isViewer = false, solvedLabel, youLabel, isSkeleton = false }: LeaderboardRowProps) => (
    <Box className={!isSkeleton && isViewer ? "-m-3 bg-accent-soft p-3" : undefined}>
        <StackH
            gap={4}
            align="center"
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                // the rank column is a fixed gutter so every name starts on the same line
                () => (
                    <Box className="w-6 shrink-0">
                        <Typography
                            size="sm"
                            weight="semibold"
                            color="muted"
                            align="center"
                            isSkeleton={isSkeleton}
                            text={String(rank)}
                        />
                    </Box>
                ),
                () => (isSkeleton
                    ? <Skeleton.Avatar size="sm" />
                    : (
                        <FillAvailable
                            at="base"
                            explain="Name cell takes remaining row width beside rank and metric — not a fixed peer column."
                            body={() => (
                                <UserCell
                                    username={entry?.username ?? ""}
                                    size="sm"
                                    trailing={isViewer ? () => <Chip tone="accent" text={youLabel} /> : undefined}
                                />
                            )}
                        />
                    )),
                ...(isSkeleton ? [() => (
                    <FillAvailable
                        at="base"
                        explain="Skeleton name placeholder takes remaining row width beside rank and metric."
                        body={() => <Typography size="sm" isSkeleton />}
                    />
                )] : []),
                // the ranking metric — distinct problems solved (NOT points)
                () => (
                    <Typography
                        size="sm"
                        weight="semibold"
                        color="accent-soft"
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? ["w-1/4"] : undefined}
                        text={solvedLabel}
                    />
                ),
            ]}
        />
    </Box>
)

/**
 * The GLOBAL coding leaderboard — every user ranked by **distinct problems solved**
 * (`solvedCount`, the exact axis the backend `codingLeaderboard` orders on; NOT
 * points — those are a different currency). A single capped reading column:
 * rank · avatar · name · "N solved", with the signed-in viewer's row accent-tinted.
 * The viewer's own standing (rank / percentile / points) lives in the ProgressCockpit
 * above this on the page, so the board itself is just the list. **No podium** —
 * coding is a pure ranked list. Self-contained: it reads the viewer id from the store
 * and drives its own SWR.
 */
export const CodingLeaderboard = () => {
    const t = useTranslations()
    // viewer identity highlights their own row
    const viewerId = useAppSelector((state) => state.user.user?.id) ?? null

    const { data, isLoading, error, mutate } = useSWR(
        ["coding-leaderboard", LEADERBOARD_LIMIT],
        async () => {
            const response = await queryCodingLeaderboard({
                request: { limit: LEADERBOARD_LIMIT },
            })
            return response.data?.codingLeaderboard.data ?? []
        },
    )

    const entries = data ?? []
    const isSkeleton = isLoading && !data

    // error beats a stale loading flag; empty only once settled (BLOCK-8 order).
    if (error) {
        return (
            <AsyncContentError
                title={t("PracticeHubPage.leaderboard.error")}
                onRetry={() => { void mutate() }}
                retryLabel={t("PracticeHubPage.retry")}
            />
        )
    }
    if (!isSkeleton && entries.length === 0) {
        return <AsyncContentEmpty title={t("PracticeHubPage.leaderboard.empty")} />
    }

    const listItems: Array<SurfaceCardListItem> = isSkeleton
        ? Array.from({ length: SKELETON_ROWS }, (_row, index) => ({
            key: `skeleton-${index}`,
            content: () => <LeaderboardRow rank={index + 1} isSkeleton />,
        }))
        : entries.map((entry, index) => ({
            key: entry.userId,
            content: () => (
                <LeaderboardRow
                    rank={index + 1}
                    entry={entry}
                    isViewer={!!viewerId && entry.userId === viewerId}
                    solvedLabel={t("PracticeHubPage.leaderboard.solved", { count: entry.solvedCount })}
                    youLabel={t("PracticeHubPage.leaderboard.you")}
                />
            ),
        }))

    return (
        // the board keeps a capped reading measure — a width no closed union carries
        <Box className="mx-auto w-full max-w-2xl" principle="center-measure"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
        >
            <SurfaceCardList
                identity={{ tier: "block", component: "CodingLeaderboard" }}
                items={listItems}
            />
        </Box>
    )
}

"use client"

import React from "react"
import { Button, Label, ListBox, SearchField, Select, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import {
    RowsIcon,
    SquaresFourIcon,
} from "@phosphor-icons/react"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { StackH, StackV } from "@/components/frames/Stack"
import { usePracticeFilters } from "@/hooks/usePracticeFilters"
import {
    CODING_DIFFICULTY_META,
    DIFFICULTY_FILTERS,
    SORT_KEYS,
    STATUS_FILTERS,
} from "@/modules/utils/practice-hub"
import type {
    DifficultyFilter,
    SortKey,
    StatusFilter,
} from "@/modules/types/practice-hub"

/** Props for {@link PracticeFilters}. */
export type PracticeFiltersProps = Record<string, never>
/**
 * The PracticeHubPage catalog filter bar — a title search box plus difficulty / status
 * filter chips (HeroUI Buttons, secondary when active / ghost when not), a sort
 * `Select`, and a group-by-domain toggle. The topic (domain) filter lives in the
 * {@link import("../PracticeRail").PracticeRail} sidebar, not here. Reads + writes
 * the URL-backed filter state itself ({@link usePracticeFilters}); composes blocks
 * + HeroUI only.
 *
 * @param props - optional className for the root element.
 */
export const PracticeFilters = () => {
    const t = useTranslations()
    const { filters, setFilters } = usePracticeFilters()

    return (
        <div className={"flex flex-col gap-4"}>
            {/* title search — client-side filter over loaded problems */}
            <SearchField
                aria-label={t("PracticeHubPage.filters.searchPlaceholder")}
                value={filters.q}
                onChange={(value) => setFilters({ q: value })}
            >
                <Label className="sr-only">{t("PracticeHubPage.filters.searchPlaceholder")}</Label>
                <SearchField.Group>
                    <SearchField.SearchIcon />
                    <SearchField.Input placeholder={t("PracticeHubPage.filters.searchPlaceholder")} />
                    <SearchField.ClearButton />
                </SearchField.Group>
            </SearchField>

            {/* difficulty + status chip groups */}
            <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <FlexWrapButtonRadio
                            ariaLabel={t("PracticeHubPage.filters.difficultyAria")}
                            value={filters.difficulty}
                            onChange={(value) => setFilters({ difficulty: value as DifficultyFilter })}
                            items={DIFFICULTY_FILTERS.map((value) => ({
                                value,
                                content: value === "all"
                                    ? t("PracticeHubPage.filters.allDifficulties")
                                    : t(CODING_DIFFICULTY_META[value].labelKey),
                            }))}
                        />
                    ),
                    () => (
                        <FlexWrapButtonRadio
                            ariaLabel={t("PracticeHubPage.filters.statusAria")}
                            value={filters.status}
                            onChange={(value) => setFilters({ status: value as StatusFilter })}
                            items={STATUS_FILTERS.map((value) => ({
                                value,
                                content: t(`PracticeHubPage.filters.status.${value}`),
                            }))}
                        />
                    ),
                ]} />

            {/* sort dropdown + group toggle */}
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => <Label className="sr-only">{t("PracticeHubPage.filters.sortAria")}</Label>,
                                () => (
                                    <Select.Root<{ id: string }, "single">
                                        aria-label={t("PracticeHubPage.filters.sortAria")}
                                        selectedKey={filters.sort}
                                        onSelectionChange={(key) => setFilters({ sort: String(key) as SortKey })}
                                    >
                                        <Select.Trigger aria-label={t("PracticeHubPage.filters.sortAria")} className="w-fit min-w-40">
                                            <Select.Value>
                                                {() => (
                                                    <Typography type="body-sm">
                                                        {t(`PracticeHubPage.filters.sort.${filters.sort}`)}
                                                    </Typography>
                                                )}
                                            </Select.Value>
                                            <Select.Indicator />
                                        </Select.Trigger>
                                        <Select.Popover>
                                            <ListBox.Root aria-label={t("PracticeHubPage.filters.sortAria")}>
                                                {SORT_KEYS.map((value) => (
                                                    <ListBox.Item
                                                        key={value}
                                                        id={value}
                                                        textValue={t(`PracticeHubPage.filters.sort.${value}`)}
                                                    >
                                                        {t(`PracticeHubPage.filters.sort.${value}`)}
                                                    </ListBox.Item>
                                                ))}
                                            </ListBox.Root>
                                        </Select.Popover>
                                    </Select.Root>
                                ),
                            ]} />
                    ),
                    () => (
                        <Button
                            size="sm"
                            variant={filters.group ? "secondary" : "ghost"}
                            aria-pressed={filters.group}
                            onPress={() => setFilters({ group: !filters.group })}
                        >
                            {filters.group ? (
                                <SquaresFourIcon aria-hidden focusable="false" className="size-5" />
                            ) : (
                                <RowsIcon aria-hidden focusable="false" className="size-5" />
                            )}
                            {filters.group
                                ? t("PracticeHubPage.filters.grouped")
                                : t("PracticeHubPage.filters.flat")}
                        </Button>
                    ),
                ]} />
        </div>
    )
}

"use client"

import React from "react"
import { Button, ScrollShadow } from "@heroui/react"
import {
    ListChecksIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { CODING_DOMAIN_ORDER } from "@/modules/api/graphql/queries/types/coding"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { StackH } from "@/components/frames/Stack"
import { usePracticeView } from "@/hooks/usePracticeView"
import { usePracticeFilters } from "@/hooks/usePracticeFilters"
import type { PracticeView } from "@/hooks/usePracticeView"
import type { DomainFilter } from "@/modules/types/practice-hub"

/** Props for {@link PracticeMobileNav}. */
export type PracticeMobileNavProps = Record<string, never>
/** All topic options for the mobile chip row: "all" + the canonical domain order. */
const MOBILE_TOPICS: ReadonlyArray<DomainFilter> = ["all", ...CODING_DOMAIN_ORDER]

/**
 * Mobile counterpart of {@link import("..").PracticeRail}: the docs-style rail
 * hides below `lg`, so the mode switch + topic filter fold into scrollable chip
 * rows above the work pane (the master-detail mobile pattern). Reads/writes the
 * same URL state as the rail ({@link usePracticeView} + {@link usePracticeFilters}),
 * so the two stay in lockstep. Topics show only in Problems mode.
 *
 * @param props - {@link PracticeMobileNavProps}
 */
export const PracticeMobileNav = () => {
    const t = useTranslations()
    const { view, setView } = usePracticeView()
    const { filters, setFilters } = usePracticeFilters()

    return (
        <div className={"flex flex-col gap-3 @app-lg:hidden"}>
            {/* mode switch — mirrors the desktop rail's TabsCard (see PracticeRail) */}
            <TabsCard
                variant="primary"
                leftTabs={{
                    selectedKey: view,
                    ariaLabel: t("PracticeHubPage.rail.modeAria"),
                    onSelectionChange: (key) => setView(String(key) as PracticeView),
                    items: [
                        {
                            key: "problems",
                            label: (
                                <StackH gap={3} principle="flex-action" as="span"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    items={[
                                        () => <ListChecksIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                        () => <>{t("PracticeHubPage.tabs.problems")}</>,
                                    ]} />
                            ),
                        },
                        {
                            key: "leaderboard",
                            label: (
                                <StackH gap={3} principle="flex-action" as="span"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    items={[
                                        () => <TrophyIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                        () => <>{t("PracticeHubPage.tabs.leaderboard")}</>,
                                    ]} />
                            ),
                        },
