                }}
            />

            {/* topic chips — problems mode only */}
            {view === "problems" ? (
                <ScrollShadow
                    orientation="horizontal"
                    hideScrollBar
                    className="overflow-x-auto"
                >
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={MOBILE_TOPICS.map((domain) => (
                            () => (
                                <Button
                                    size="sm"
                                    variant={filters.domain === domain ? "secondary" : "ghost"}
                                    aria-pressed={filters.domain === domain}
                                    className="shrink-0"
                                    onPress={() => setFilters({ domain })}
                                >
                                    {domain === "all"
                                        ? t("PracticeHubPage.filters.allDomains")
                                        : t(`codingPractice.domain.${domain}`)}
                                </Button>
                            )
                        ))}
                    />
                </ScrollShadow>
            ) : null}
        </div>
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import {
    Input,
    Label,
    ListBox,
    ScrollShadow,
    TextField,
    Typography,
} from "@heroui/react"
import {
    ListChecksIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { CODING_DOMAIN_ORDER } from "@/modules/api/graphql/queries/types/coding"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { usePracticeView } from "@/hooks/usePracticeView"
import { usePracticeFilters } from "@/hooks/usePracticeFilters"
import type { PracticeView } from "@/hooks/usePracticeView"
import type { DomainFilter } from "@/modules/types/practice-hub"

/**
 * The PracticeHubPage LEFT RAIL — the same docs-style sidebar as the flashcards /
 * content-map rail (a pinned header over a scroll region, full rail height). A
 * mode switch (Problems / Leaderboard) above the course-domain topics as a
 * searchable nav list. The mode drives the URL view ({@link usePracticeView}); the
 * chosen topic drives the catalog domain filter ({@link usePracticeFilters}), so
 * the rail and the work pane share one source of truth. Topics show only in
 * Problems mode (the leaderboard is topic-agnostic). Placed in the rail column by
 * the page shell; reads/writes URL state directly (no data props).
 */
export const PracticeRail = () => {
    const t = useTranslations()
    const { view, setView } = usePracticeView()
    const { filters, setFilters } = usePracticeFilters()
    const [query, setQuery] = useState("")

    /** Resolve a topic's display label ("All topics" or a domain name). */
    const topicLabel = (domain: DomainFilter): string =>
        domain === "all"
            ? t("PracticeHubPage.filters.allDomains")
            : t(`codingPractice.domain.${domain}`)

    // the topic rows: "all" + the canonical domain order, narrowed by the search box
    const topics = useMemo<Array<DomainFilter>>(() => {
        const all: Array<DomainFilter> = ["all", ...CODING_DOMAIN_ORDER]
        const normalized = query.trim().toLowerCase()
        if (!normalized) {
            return all
        }
        return all.filter((domain) => topicLabel(domain).toLowerCase().includes(normalized))
    }, [query, t])

    return (
        <div className="relative flex min-h-0 min-w-0 flex-col gap-3 p-6">
            {/* pinned header: mode switch + topic search */}
            <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <TabsCard
                            variant="primary"
                            leftTabs={{
                                selectedKey: view,
                                ariaLabel: t("PracticeHubPage.rail.modeAria"),
                                onSelectionChange: (key) => setView(String(key) as PracticeView),
                                items: [
                                    {
                                        key: "problems",
                                        label: (
                                            <StackH gap={3} principle="flex-action" as="span"
                                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                items={[
                                                    () => <ListChecksIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                                    () => <>{t("PracticeHubPage.tabs.problems")}</>,
                                                ]} />
                                        ),
                                    },
                                    {
                                        key: "leaderboard",
                                        label: (
                                            <StackH gap={3} principle="flex-action" as="span"
                                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                items={[
                                                    () => <TrophyIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                                    () => <>{t("PracticeHubPage.tabs.leaderboard")}</>,
                                                ]} />
                                        ),
                                    },
                                ],
                            }}
                        />
                    ),
                    () => view === "problems" ? (
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => <Label className="px-1 text-xs text-muted" data-principle="control-pad">{t("PracticeHubPage.rail.topicsLabel")}</Label>,
                                () => (
                                    <TextField>
                                        <Input
                                            type="search"
                                            aria-label={t("PracticeHubPage.rail.searchTopic")}
                                            placeholder={t("PracticeHubPage.rail.searchTopic")}
                                            value={query}
                                            onChange={(event) => setQuery(event.target.value)}
                                        />
                                    </TextField>
                                ),
                            ]} />
                    ) : null,
                ]} />

            {/* scroll region: the topic nav list (problems mode only) */}
            {view === "problems" ? (
                <ScrollShadow
                    hideScrollBar
                    className="-mx-1 min-h-0 min-w-0 flex-1 overflow-y-auto px-1" data-principle="control-pad"
                >
                    {topics.length === 0 ? (
                        <Box principle="control-pad" className="px-3 py-2"
                            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                            <Typography type="body-sm" color="muted">
                                {t("PracticeHubPage.rail.searchTopicEmpty", { query: query.trim() })}
                            </Typography>
                        </Box>
                    ) : (
                        <ListBox
                            aria-label={t("PracticeHubPage.rail.topicsAria")}
                            selectionMode="single"
                            disallowEmptySelection
                            selectedKeys={[filters.domain]}
                            onSelectionChange={(keys) => {
                                // controlled single-select → filter the catalog by the chosen topic
                                const key = [...keys][0]
                                if (typeof key === "string") {
                                    setFilters({ domain: key as DomainFilter })
                                }
                            }}
                            className="gap-1 p-0" data-principle="title-subtitle"
                        >
                            {topics.map((domain) => (
                                <ListBox.Item
                                    key={domain}
                                    id={domain}
                                    textValue={topicLabel(domain)}
                                    className="cursor-pointer rounded-2xl px-3 py-2 text-foreground data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft data-[selected=true]:text-accent-soft-foreground" data-principle="control-pad"
                                >
                                    <Typography type="body-sm" className="min-w-0 flex-1 truncate text-inherit">
                                        {topicLabel(domain)}
                                    </Typography>
                                </ListBox.Item>
                            ))}
                        </ListBox>
                    )}
                </ScrollShadow>
            ) : null}
        </div>
    )
}

"use client"

import React from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import {
    CheckCircleIcon,
    CircleHalfIcon,
    CircleIcon,
} from "@phosphor-icons/react"
import { CODING_DIFFICULTY_META } from "@/modules/utils/practice-hub"
import type { ProblemStatus } from "@/modules/types/practice-hub"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import type { CodingProblem } from "@/modules/api/graphql/queries/types/coding"
import { StackH, StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/** Props for {@link ProblemRow}. A list-item, so it accepts its data as props. */
export interface ProblemRowProps {
    /** The problem to render. */
    problem: CodingProblem
    /** The viewer's solve status for this problem (drives the status icon). */
    status: ProblemStatus
}

/** Status icon + colour + aria-label key per {@link ProblemStatus}. */
const STATUS_META: Record<
    ProblemStatus,
    { Icon: typeof CircleIcon; className: string; labelKey: string }
> = {
    solved: {
        Icon: CheckCircleIcon,
        className: "text-success-soft-foreground",
        labelKey: "PracticeHubPage.row.status.solved",
    },
    attempted: {
        Icon: CircleHalfIcon,
        className: "text-warning-soft-foreground",
        labelKey: "PracticeHubPage.row.status.attempted",
    },
    unsolved: {
        Icon: CircleIcon,
        className: "text-muted",
        labelKey: "PracticeHubPage.row.status.unsolved",
    },
}

/**
 * One catalog row: a prominent status icon (✓ solved / ◐ attempted / ○ unsolved),
 * the problem title (underlines on hover) navigating into the solve page, a
 * difficulty {@link StatusChip}, a domain chip, and the point value — with topic
 * tags shown secondary below. Renders as a {@link SurfaceListCardItem} (the WHOLE
 * row is the single nav link — `hover="underline"` per the go-there row style) so
 * it joins its siblings inside the parent {@link SurfaceListCard}, not a
 * hand-rolled bordered div. Styling lives in the blocks, this only places them.
 *
 * @param props - {@link ProblemRowProps}.
 */
export const ProblemRow = ({
    problem,
    status}: ProblemRowProps) => {
    const t = useTranslations()
    const statusMeta = STATUS_META[status]
    const StatusIcon = statusMeta.Icon
    const difficultyMeta = CODING_DIFFICULTY_META[problem.difficulty]

    return (
        <SurfaceListCardItem
            href={`/PracticeHubPage/${problem.slug}`}
            hover="underline"
        >
            <StackH gap={4} align="center" principle="content-row" classNames={["min-w-0"]}
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StatusIcon
                            weight={status === "unsolved" ? "regular" : "fill"}
                            aria-label={t(statusMeta.labelKey)}
                            className={cn("size-5 shrink-0", statusMeta.className)}
                        />
                    ),
                    () => (
                        <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => (
                                    <Typography
                                        type="body-sm"
                                        weight="medium"
                                        truncate
                                        className="w-fit underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline"
                                    >
                                        {problem.title}
                                    </Typography>
                                ),
                                ...(problem.tags.length > 0 ? [
                                    () => (
                                        <Box principle="chip-row" className="flex flex-wrap items-center gap-2"
                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column.">
                                            {problem.tags.slice(0, 4).map((tag) => (
                                                <Typography key={tag} type="body-xs" color="muted">
                                                    {tag}
                                                </Typography>
                                            ))}
                                            {problem.tags.length > 4 ? (
                                                <Typography
                                                    type="body-xs"
                                                    color="muted"
                                                    title={problem.tags.slice(4).join(", ")}
                                                >
                                                    {t("PracticeHubPage.row.moreTags", {
                                                        count: problem.tags.length - 4,
                                                    })}
                                                </Typography>
                                            ) : null}
                                        </Box>
                                    ),
                                ] : []),
                            ]} />
                    ),
                    () => (
                        <Box principle="push-end" className="ml-auto flex shrink-0 items-center gap-2"
                            explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                            <StatusChip tone={difficultyMeta.tone}>
                                {t(difficultyMeta.labelKey)}
                            </StatusChip>
                            <StatusChip tone="neutral">
                                {t(`codingPractice.domain.${problem.domain}`)}
                            </StatusChip>
                            <Typography type="body-xs" color="muted">
                                {t("codingPractice.points", { points: problem.points })}
                            </Typography>
                        </Box>
                    ),
                ]} />
        </SurfaceListCardItem>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import { Chip, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { usePracticeFilters } from "@/hooks/usePracticeFilters"
import { useCodingProblemsSwr } from "@/hooks/useCodingProblemsSwr"
import { useMyCodingProgressSwr } from "@/hooks/useMyCodingProgressSwr"
import {
    deriveStatus,
    filterProblems,
    sortProblems,
} from "@/modules/utils/practice-hub"
import { ProblemRow } from "./ProblemRow"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { CODING_DOMAIN_ORDER, type CodingDomain, type CodingProblem } from "@/modules/api/graphql/queries/types/coding"
import { StackH, StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/** Props for {@link ProblemCatalog}. */
export type ProblemCatalogProps = Record<string, never>
/** One rendered domain section: the domain plus its (already sorted) problems. */
interface CatalogGroup {
    /** The domain this section groups. */
    domain: CodingDomain
    /** Problems under the domain, in the active sort order. */
    problems: Array<CodingProblem>
}

/**
 * The PracticeHubPage problem list. Loads the whole catalog + the viewer's progress,
 * overlays per-problem status, applies the URL-backed client filters / search /
 * sort, then renders either domain-grouped sections (LeetCode topic style) or a
 * flat sorted list per the group toggle. Every fetch goes through
 * {@link AsyncContent} (loading skeleton, filter-aware empty, retry on error).
 * Composes blocks + the {@link ProblemRow} list-item.
 *
 * @param props - optional className for the root element.
 */
export const ProblemCatalog = () => {
    const t = useTranslations()
    const { filters, isFiltered, clearFilters } = usePracticeFilters()

    const {
        data: problems,
        isLoading,
        error,
        mutate,
    } = useCodingProblemsSwr()
    // progress overlay — drives row status + the status filter (anonymous → null)
    const { data: progress } = useMyCodingProgressSwr()

    // apply client filters then sort the survivors
    const filtered = useMemo(
        () => sortProblems(filterProblems(problems ?? [], progress, filters), filters.sort),
        [problems, progress, filters],
    )

    // group the filtered+sorted problems by domain, in canonical domain order
    const groups = useMemo<Array<CatalogGroup>>(() => {
        const byDomain = new Map<CodingDomain, Array<CodingProblem>>()
        filtered.forEach((problem) => {
            const bucket = byDomain.get(problem.domain) ?? []
            bucket.push(problem)
            byDomain.set(problem.domain, bucket)
        })
        return CODING_DOMAIN_ORDER
            .filter((domain) => byDomain.has(domain))
            .map((domain) => ({ domain, problems: byDomain.get(domain) ?? [] }))
    }, [filtered])

    return (
        <AsyncContent
            isLoading={isLoading && !problems}
            // intentionally flat regardless of `filters.group` — real layout can be
            // N domain-header sections when grouped, but we keep the skeleton a
            // simple 5-row approximation rather than pre-guessing group shape
            skeleton={(
                <SurfaceListCard>
                    {[0, 1, 2, 3, 4].map((row) => (
                        <SurfaceListCardItem key={row}>
                            <StackH gap={4} align="center" principle="content-row" classNames={["min-w-0"]}
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    () => <Skeleton className="size-5 shrink-0 rounded-full" />,
                                    () => (
                                        <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                () => (
                                                    <Box principle="chip-row" className="flex flex-wrap items-center gap-2"
                                                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column.">
                                                        <Skeleton.Typography type="body-xs" width="1/4" />
                                                        <Skeleton.Typography type="body-xs" width="1/4" />
                                                    </Box>
                                                ),
                                            ]} />
                                    ),
                                    () => (
                                        <Box principle="push-end" className="ml-auto flex shrink-0 items-center gap-2"
                                            explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                            <Skeleton.Chip />
                                            <Skeleton.Chip />
                                            <Skeleton.Typography type="body-xs" width="1/4" className="w-10" />
                                        </Box>
                                    ),
                                ]} />
                        </SurfaceListCardItem>
                    ))}
                </SurfaceListCard>
            )}
            isEmpty={filtered.length === 0}
            emptyContent={isFiltered
                ? {
                    title: t("PracticeHubPage.catalog.noMatch"),
                    onRetry: clearFilters,
                    retryLabel: t("PracticeHubPage.catalog.clearFilters"),
                }
                : { title: t("codingPractice.empty"), description: t("codingPractice.emptyHint") }}
            error={error}
            errorContent={{
                title: t("PracticeHubPage.catalog.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("PracticeHubPage.retry"),
            }}
        >
            {filters.group ? (
                <div className={"flex flex-col gap-6"}>
                    {groups.map((group) => (
                        <StackV key={group.domain} gap={3} principle="sibling-stack" as="section"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => (
                                    <StackH gap={3} principle="flex-action"
                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                        items={[
                                            () => (
                                                <Typography type="h5" weight="semibold">
                                                    {t(`codingPractice.domain.${group.domain}`)}
                                                </Typography>
                                            ),
                                            () => (
                                                <Chip size="sm" variant="soft" color="default">
                                                    <Chip.Label>{group.problems.length}</Chip.Label>
                                                </Chip>
                                            ),
                                        ]} />
                                ),
                                () => (
                                    <SurfaceListCard>
                                        {group.problems.map((problem) => (
                                            <ProblemRow
                                                key={problem.id}
                                                problem={problem}
                                                status={deriveStatus(problem.id, progress)}
                                            />
                                        ))}
                                    </SurfaceListCard>
                                ),
                            ]} />
                    ))}
                </div>
            ) : (
                <SurfaceListCard>
                    {filtered.map((problem) => (
                        <ProblemRow
                            key={problem.id}
                            problem={problem}
                            status={deriveStatus(problem.id, progress)}
                        />
                    ))}
                </SurfaceListCard>
            )}
        </AsyncContent>
    )
}

"use client"

import React from "react"
import { Label } from "@heroui/react"
import { useTranslations } from "next-intl"
import { CODING_DIFFICULTY_META } from "@/modules/utils/practice-hub"
import { useQueryUserCodingProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingProgressSwr"
import { useQueryUserCodingRankSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingRankSwr"
import { useQueryUserCodingSkillsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingSkillsSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { MetricCard } from "@/components/composites/stats/MetricCard"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { useAppSelector } from "@/redux/hooks"
import { CodingDifficulty } from "@/modules/api/graphql/queries/types/coding"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link ProgressCockpit}. */
export type ProgressCockpitProps = Record<string, never>
/** Difficulty order for the distribution SegmentBar (easy → hard). */
const COCKPIT_DIFFICULTY: ReadonlyArray<CodingDifficulty> = [
    CodingDifficulty.Easy,
    CodingDifficulty.Medium,
    CodingDifficulty.Hard,
]

/**
 * The PracticeHubPage cockpit — the signed-in user's coding standing at a glance, built
 * from the SAME blocks as the profile Coding tab: a {@link MetricCard} row
 * (solved · points · rank · percentile, the last two hidden when unranked) over a
 * difficulty {@link SegmentBar} (easy/medium/hard solved counts, coding 3-tone
 * scale). Self-contained: reads the signed-in user id from the store and drives
 * its own SWR. Hides entirely for anonymous viewers (no user id → empty cockpit).
 *
 * @param props - optional className for the root element.
 */
export const ProgressCockpit = () => {
    const t = useTranslations()
    // signed-in user id — the rank/skills queries key off it (null when anonymous)
    const userId = useAppSelector((state) => state.user.user?.id) ?? null

    const {
        data: progress,
        isLoading,
        error,
        mutate,
    } = useQueryUserCodingProgressSwr(userId)
    const skillsSwr = useQueryUserCodingSkillsSwr(userId)
    const standingSwr = useQueryUserCodingRankSwr(userId)
    const skills = skillsSwr.data
    const standing = standingSwr.data

    const solved = progress?.solvedProblemIds.length ?? 0
    // `totalPoints` is the user's whole spendable Coin balance, NOT a coding-only
    // figure — the `coding` leaderboard ranks on distinct problems solved instead
    // (points are a different currency). Labelled "Coin" via `metric.points`.
    const totalPoints = progress?.totalPoints ?? 0

    // 2026-07-12: `skills`/`standing` fire alongside `progress` but the outer
    // skeleton only watches `progress` — while they're still in flight, rank/
    // percentile stat cards and the whole difficulty bar used to be silently
    // absent, then pop in a beat after the "solved"/"points" cards had already
    // rendered. Gate each dependent section on its OWN pending state instead of
    // just omitting it.
    const standingPending = standingSwr.isLoading && !standing

    // headline metric row; rank + percentile hide when the user is unranked
    const stats: Array<{ key: string; value: string | null }> = [
        { key: "solved", value: String(solved) },
        { key: "points", value: String(totalPoints) },
    ]
    if (standingPending) {
        stats.push({ key: "rank", value: null }, { key: "percentile", value: null })
    } else {
        if (standing?.rank != null) {
            stats.push({ key: "rank", value: `#${standing.rank}` })
        }
        if (standing?.percentile != null) {
            stats.push({ key: "percentile", value: `${standing.percentile}%` })
        }
    }

    // difficulty distribution (easy→hard), coloured by the coding 3-tone scale
    const skillsPending = skillsSwr.isLoading && !skills
    const solvedByDifficulty = new Map((skills?.byDifficulty ?? []).map((item) => [item.key, item.solved]))
    const difficultySegments = COCKPIT_DIFFICULTY
        .filter((difficulty) => (solvedByDifficulty.get(difficulty) ?? 0) > 0)
        .map((difficulty) => ({
            key: difficulty,
            label: t(CODING_DIFFICULTY_META[difficulty].labelKey),
            value: solvedByDifficulty.get(difficulty) ?? 0,
            color: CODING_DIFFICULTY_META[difficulty].color,
        }))

    // anonymous viewers never fire the queries (key disabled) — bail out
    // instead of `isLoading`/`!userId` feeding `isFirstLoad` forever.
    if (!userId) return null

    // first load in flight only when no progress has resolved yet
    const isFirstLoad = !progress && isLoading

    return (
        <AsyncContent
            isLoading={isFirstLoad}
            skeleton={(
                <div className={"flex flex-col gap-6"}>
                    {/* metric row — solved · points · rank · percentile */}
                    <Box principle="content-row" className="grid grid-cols-2 gap-3 @app-sm:grid-cols-4"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title.">
                        {[0, 1, 2, 3].map((index) => (
                            <Skeleton key={index} className="h-24 w-full rounded-2xl" />
                        ))}
                    </Box>
                    {/* difficulty distribution bar */}
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="1/4" />,
                            () => <Skeleton.SegmentBar legendItems={3} />,
                        ]} />
                </div>
            )}
            error={error}
            errorContent={{
                title: t("PracticeHubPage.cockpit.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("PracticeHubPage.retry"),
            }}
        >
            <div className={"flex flex-col gap-6"}>
                {/* headline metric row — pending rank/percentile cards skeleton in place */}
                <Box principle="content-row" className="grid grid-cols-2 gap-3 @app-sm:grid-cols-4"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title.">
                    {stats.map((stat) => (
                        stat.value === null ? (
                            <Skeleton key={stat.key} className="h-24 w-full rounded-2xl" />
                        ) : (
                            <MetricCard
                                key={stat.key}
                                value={stat.value}
                                label={t(`PracticeHubPage.cockpit.metric.${stat.key}`)}
                            />
                        )
                    ))}
                </Box>

                {/* difficulty distribution — skeleton while resolving, hidden once
                    resolved with nothing solved yet, real bar otherwise */}
                {skillsPending ? (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => <Skeleton.Typography type="body-sm" width="1/4" />,
                            () => <Skeleton.SegmentBar legendItems={3} />,
                        ]} />
                ) : difficultySegments.length > 0 ? (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => <Label>{t("PracticeHubPage.cockpit.byDifficulty")}</Label>,
                            () => (
                                <SegmentBar
                                    ariaLabel={t("PracticeHubPage.cockpit.byDifficulty")}
                                    segments={difficultySegments}
                                />
                            ),
                        ]} />
                ) : null}
            </div>
        </AsyncContent>
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResizableRail } from "@/components/blocks/layout/ResizableRail"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { pathConfig } from "@/resources/path"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { PracticeRail } from "./PracticeRail"
import { PracticeMobileNav } from "./PracticeRail/PracticeMobileNav"
import { ProgressCockpit } from "./ProgressCockpit"
import { PracticeFilters } from "./PracticeFilters"
import { ProblemCatalog } from "./ProblemCatalog"
import { CodingLeaderboard } from "./CodingLeaderboard"
import { usePracticeView } from "@/hooks/usePracticeView"

/**
 * `/PracticeHubPage` — the LeetCode-style coding-PracticeHubPage page, laid out docs-style: a
 * persistent left {@link PracticeRail} (the mode switch Problems ⇄ Leaderboard +
 * the course-domain topics as a nav list) beside a padded work pane. The rail and
 * the pane share one source of truth through the URL (the {@link usePracticeView}
 * mode + the {@link PracticeFilters} topic), so navigation is shareable. Below
 * `lg` the rail folds into the in-pane {@link PracticeMobileNav} chip rows.
 *
 * The pane stacks: a {@link PageHeader}, the {@link ProgressCockpit} (the viewer's
 * solve standing, shown for BOTH views), then the active view — **Problems** (the
 * {@link PracticeFilters} bar + {@link ProblemCatalog}) or the global
 * **Leaderboard** ({@link CodingLeaderboard}). Pure composition — each child reads
 * its own SWR / URL state; this root only places them and owns the shell.
 */
export const PracticeHubPage = () => {
    const t = useTranslations()
    const router = useRouter()
    const { view } = usePracticeView()

    return (
        // single column on mobile/tablet; rail + content side-by-side from lg up
        <div className="flex w-full flex-col items-start @app-lg:flex-row">
            {/* docs-style left rail — sticks under the navbar, viewport-tall, drag-resizable */}
            <ResizableRail
                className="hidden shrink-0 @app-lg:sticky @app-lg:top-16 @app-lg:flex @app-lg:h-[calc(100dvh-4rem)] @app-lg:flex-col @app-lg:self-start"
                storageKey="starci.PracticeHubPage.rail.width"
                defaultWidth={300}
                minWidth={256}
                maxWidth={420}
                ariaLabel={t("PracticeHubPage.rail.modeAria")}
            >
                <FillAvailable at="lg" body={() => <PracticeRail />} />
            </ResizableRail>

            {/* content column — owns the canonical p-6 reading padding */}
            <Box principle="page-pad" className="min-h-0 min-w-0 flex-1 p-6"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                <Box principle="center-measure" className="mx-auto flex max-w-5xl flex-col gap-10"
                    explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                    <PageHeader
                        breadcrumb={(
                            <ResponsiveBreadcrumb
                                items={[
                                    {
                                        key: "home",
                                        label: t("nav.home"),
                                        onPress: () => router.push(pathConfig().locale().build()),
                                    },
                                    {
                                        key: "current",
                                        label: t("codingPractice.title"),
                                    },
                                ]}
                            />
                        )}
                        title={t("codingPractice.title")}
                        description={t("codingPractice.subtitle")}
                    />

                    <StackV principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => <PracticeMobileNav />,
                            () => <ProgressCockpit />,
                            () => (view === "problems" ? (
                                <>
                                    <Box principle="pill-pad" className="sticky top-16 z-40 bg-background py-2"
                                        explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                                        <PracticeFilters />
                                    </Box>
                                    <ProblemCatalog />
                                </>
                            ) : (
                                <CodingLeaderboard />
                            )),
                        ]} />
                </Box>
            </Box>
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    useState,
    useRef,
} from "react"
import useSWR from "swr"
import Editor from "@monaco-editor/react"
import {
    Button,
    Tabs,
    Typography,
} from "@heroui/react"
import { ArrowCounterClockwiseIcon, PlayIcon, MagnifyingGlassIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useTheme } from "next-themes"
import { useParams, useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { AIProcessingText } from "@/components/blocks/learn/AIProcessingText"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { StatusChip, type StatusChipTone } from "@/components/blocks/chips/StatusChip"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"
import { StatGridCard } from "@/components/composites/stats/StatGridCard"
import { IOExampleCard } from "@/components/blocks/code/IOExampleCard"
import { CodeConsole } from "@/components/blocks/code/CodeConsole"
import { TestCaseResultGrid, type TestCaseResult } from "@/components/blocks/code/TestCaseResultGrid"
import { PracticeProblemSkeleton } from "./PracticeProblemSkeleton"
import { queryCodingProblem } from "@/modules/api/graphql/queries/query-coding-problem"
import { queryCodingProblemHint } from "@/modules/api/graphql/queries/query-coding-problem-hint"
import { queryMyCodingSubmissions } from "@/modules/api/graphql/queries/query-my-coding-submissions"
import { mutateSubmitCodingSolution } from "@/modules/api/graphql/mutations/mutation-submit-coding-solution"
import { mutateRevealCodingSolution } from "@/modules/api/graphql/mutations/mutation-reveal-coding-solution"
import {
    CodingDifficulty,
    CodingLanguage,
    CodingVerdict,
    parsePerCaseResults,
    type CodingProblem,
    type CodingProblemSolution,
    type CodingSubmission,
} from "@/modules/api/graphql/queries/types/coding"
import { useJobNotificationsSocketIo } from "@/hooks/socketio/useJobNotificationsSocketIo"
import { PublicationEvent } from "@/hooks/socketio/enums/publication-event"
import { JobCategory } from "@/modules/types/enums/job-category"
import { JobStatus } from "@/modules/types/enums/job-status"
import { useAppSelector } from "@/redux/hooks"
import { StackH, StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { Box } from "@/components/frames/Box"

/** Props for {@link PracticeProblemPage}. */
export type PracticeProblemPageProps = Record<string, never>

/** Seniority level i18n key per difficulty (easy=junior, medium=mid, hard=senior). */
const LEVEL_KEY: Record<CodingDifficulty, string> = {
    [CodingDifficulty.Easy]: "junior",
    [CodingDifficulty.Medium]: "mid",
    [CodingDifficulty.Hard]: "senior",
}

/** Difficulty → chip tone (mirrors the list-card difficulty palette). */
const DIFFICULTY_TONE: Record<CodingDifficulty, StatusChipTone> = {
    [CodingDifficulty.Easy]: "success",
    [CodingDifficulty.Medium]: "warning",
    [CodingDifficulty.Hard]: "danger",
}

/** Map a coding language to its Monaco editor language id. */
const MONACO_LANGUAGE: Record<CodingLanguage, string> = {
    [CodingLanguage.Python]: "python",
    [CodingLanguage.JavaScript]: "javascript",
    [CodingLanguage.TypeScript]: "typescript",
    [CodingLanguage.Java]: "java",
    [CodingLanguage.Cpp]: "cpp",
}

/** Chip tone per verdict (accepted = success, terminal failures = danger). */
const VERDICT_TONE: Record<CodingVerdict, StatusChipTone> = {
    [CodingVerdict.Accepted]: "success",
    [CodingVerdict.WrongAnswer]: "danger",
    [CodingVerdict.TimeLimitExceeded]: "danger",
    [CodingVerdict.MemoryLimitExceeded]: "danger",
    [CodingVerdict.RuntimeError]: "danger",
    [CodingVerdict.CompileError]: "danger",
    [CodingVerdict.InternalError]: "warning",
    [CodingVerdict.Pending]: "neutral",
    [CodingVerdict.Judging]: "neutral",
}

/** Left-pane tab ids. */
type LeftTab = "description" | "solution" | "submissions"
/** Console (right-pane bottom) tab ids. */
type ConsoleTab = "testcase" | "result"

/** Terminal job statuses — judging has finished (success or failure). */
const isTerminalStatus = (status: JobStatus | undefined): boolean =>
    status === JobStatus.Completed || status === JobStatus.Failed

/**
 * Coding-problem detail + editor — a full-bleed 2-pane IDE (`/practice/[slug]`).
 * LEFT = tabbed reading column (`ExtendedTabs`: Description / Solution / Submissions);
 * RIGHT = Monaco editor over a `CodeConsole` (Test case / Result) whose result
 * tab renders the judged PER-CASE outcome (`TestCaseResultGrid` off the API's
 * `perCaseResults`) plus runtime/memory stats. The submit → async-judge →
 * realtime-verdict flow (SWR + `/job_notifications` socket + anti-cheat
 * telemetry) is unchanged from the prior build; only the shell is new.
 */
export const PracticeProblemPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const params = useParams()
    const slug = String(params.slug ?? "")
    const { theme } = useTheme()
    const socket = useJobNotificationsSocketIo()

    const [language, setLanguage] = useState<CodingLanguage>(CodingLanguage.Python)
    const [code, setCode] = useState<string>("")
    const [pendingJobId, setPendingJobId] = useState<string | null>(null)
    const [submitting, setSubmitting] = useState(false)
    const [leftTab, setLeftTab] = useState<LeftTab>("description")
    const [consoleTab, setConsoleTab] = useState<ConsoleTab>("testcase")
    // Live job status mirrored from Redux — the global /job_notifications lifecycle
    // dispatches every subscribed job's status into socketIo.jobStatusByJobId, the same
    // single source the challenge panel reads (no per-component EventEmitter listener).
    const pendingJobMessage = useAppSelector((state) =>
        (pendingJobId ? state.socketIo.jobStatusByJobId[pendingJobId] : undefined))
    const pendingJobStatus = pendingJobMessage?.data?.status
    const pendingJobError = pendingJobMessage?.data?.error
    const [showHint, setShowHint] = useState(false)
    const [showSolution, setShowSolution] = useState(false)
    // reference solutions arrive ONLY from the gated reveal mutation (never the
    // problem detail read) — held here once the learner reveals them
    const [revealedSolutions, setRevealedSolutions] = useState<Array<CodingProblemSolution>>([])
    const [solutionLanguage, setSolutionLanguage] = useState<CodingLanguage>(CodingLanguage.Python)
    const [touchedLanguages, setTouchedLanguages] = useState<Set<CodingLanguage>>(new Set())

    const telemetryRef = useRef({
        pasteCount: 0,
        pasteSizeMax: 0,
        keystrokeCount: 0,
        tabBlurCount: 0,
        timeOpen: Date.now(),
    })

    // Reset telemetry when the slug changes (user selects a new problem)
    useEffect(() => {
        telemetryRef.current = {
            pasteCount: 0,
            pasteSizeMax: 0,
            keystrokeCount: 0,
            tabBlurCount: 0,
            timeOpen: Date.now(),
        }
    }, [slug])

    // Track when window loses focus (user switching browser tabs/windows)
    useEffect(() => {
        const onBlur = () => {
            telemetryRef.current.tabBlurCount += 1
        }
        window.addEventListener("blur", onBlur)
        return () => window.removeEventListener("blur", onBlur)
    }, [])

    const {
        data: problem,
        isLoading,
        error: problemError,
        mutate: mutateProblem,
    } = useSWR<CodingProblem | null>(
        ["coding-problem", slug],
        async () => {
            const response = await queryCodingProblem({ request: { slug } })
            return response.data?.codingProblem.data ?? null
        },
    )

    const { data: hint } = useSWR<string | null>(
        ["coding-problem-hint", slug],
        async () => {
            const response = await queryCodingProblemHint({ request: { slug } })
            return response.data?.codingProblemHint.data?.hint ?? null
        },
    )

    const { data: submissionsData, mutate: mutateSubmissions } = useSWR(
        ["my-coding-submissions", slug],
        async () => {
            const response = await queryMyCodingSubmissions({
                request: { slug, page: 1, limit: 20 },
            })
            return response.data?.myCodingSubmissions.data ?? null
        },
    )

    const starterByLanguage = useMemo(() => {
        const map = new Map<CodingLanguage, string>()
        problem?.starterCodes?.forEach((starter) => map.set(starter.language, starter.code))
        return map
    }, [problem?.starterCodes])

    const languages = useMemo<Array<CodingLanguage>>(() => {
        const withStarter = problem?.starterCodes?.map((starter) => starter.language) ?? []
        return withStarter.length > 0 ? withStarter : Object.values(CodingLanguage)
    }, [problem?.starterCodes])

    useEffect(() => {
        if (languages.length > 0 && !languages.includes(language)) {
            setLanguage(languages[0])
        }
    }, [languages, language])

    useEffect(() => {
        if (!touchedLanguages.has(language)) {
            setCode(starterByLanguage.get(language) ?? "")
        }
    }, [language, starterByLanguage, touchedLanguages])

    const latestSubmission = useMemo<CodingSubmission | undefined>(
        () => submissionsData?.submissions[0],
        [submissionsData?.submissions],
    )

    // decode the judged per-case outcome (input/expected/got for samples) — the
    // data the API always returned but the old UI threw away.
    const resultCases = useMemo<Array<TestCaseResult>>(
        () => parsePerCaseResults(latestSubmission?.perCaseResults ?? null).map((perCase) => ({
            key: String(perCase.orderIndex),
            label: t("codingPractice.caseLabel", { index: perCase.orderIndex }),
            passed: perCase.verdict === CodingVerdict.Accepted,
            isSample: perCase.isSample,
            input: perCase.input,
            expectedOutput: perCase.expectedOutput,
            got: perCase.stdout,
        })),
        [latestSubmission?.perCaseResults, t],
    )

    // reference solution code keyed by language (revealed in the "answer" panel)
    const solutionByLanguage = useMemo(() => {
        const map = new Map<CodingLanguage, string>()
        revealedSolutions.forEach((solution) => map.set(solution.language, solution.code))
        return map
    }, [revealedSolutions])

    // languages that actually ship a reference solution
    const solutionLanguages = useMemo<Array<CodingLanguage>>(
        () => revealedSolutions.map((solution) => solution.language),
        [revealedSolutions],
    )

    // keep the solution language switcher pinned to an available language
    useEffect(() => {
        if (solutionLanguages.length > 0 && !solutionLanguages.includes(solutionLanguage)) {
            setSolutionLanguage(solutionLanguages[0])
        }
    }, [solutionLanguages, solutionLanguage])

    /** Back to the practice catalog. */
    const onBack = useCallback(
        () => router.push(pathConfig().locale(locale).practice().build()),
        [router, locale],
    )

    /** Reset the editor to the language's starter code (drops local edits). */
    const onResetCode = useCallback(() => {
        setCode(starterByLanguage.get(language) ?? "")
        setTouchedLanguages((prev) => {
            const next = new Set(prev)
            next.delete(language)
            return next
        })
    }, [language, starterByLanguage])

    // toggle the answer panel; revealing it forfeits the problem's points, so
    // confirm first and record the reveal server-side (best-effort)
    const onToggleSolution = useCallback(async () => {
        if (showSolution) {
            setShowSolution(false)
            return
        }
        if (!window.confirm(t("codingPractice.revealConfirm"))) {
            return
        }
        try {
            // the gated reveal mutation both records the forfeit AND returns the
            // reference solutions — the only path by which they reach the client
            const response = await mutateRevealCodingSolution({ request: { slug } })
            setRevealedSolutions(response.data?.revealCodingSolution.data?.solutions ?? [])
            setShowSolution(true)
        } catch {
            // reveal failed (network/auth) — keep the answer panel closed
        }
    }, [showSolution, slug, t])

    const onSubmit = useCallback(async () => {
        setSubmitting(true)
        setConsoleTab("result")
        try {
            const timeOpenToSubmitMs = Date.now() - telemetryRef.current.timeOpen
            const response = await mutateSubmitCodingSolution({
                request: {
                    slug,
                    language,
                    sourceCode: code,
                    telemetry: {
                        pasteCount: telemetryRef.current.pasteCount,
                        pasteSizeMax: telemetryRef.current.pasteSizeMax,
                        keystrokeCount: telemetryRef.current.keystrokeCount,
                        tabBlurCount: telemetryRef.current.tabBlurCount,
                        timeOpenToSubmitMs,
                    },
                },
            })
            const jobId = response.data?.submitCodingSolution.data?.jobId
            if (!jobId) return
            // Subscribe to the job room BEFORE the refetch so an early socket push is
            // never missed (race-free, like challenge). Status comes from Redux.
            setPendingJobId(jobId)
            socket.emit(PublicationEvent.SubscribeJobNotification, {
                data: { jobId },
                locale,
            })
            void mutateSubmissions()
        } finally {
            setSubmitting(false)
        }
    }, [slug, language, code, mutateSubmissions, socket, locale])

    // When the watched job reaches a terminal status (from Redux), refetch the
    // submissions (verdict now persisted) and stop watching.
    useEffect(() => {
        if (pendingJobId && isTerminalStatus(pendingJobStatus)) {
            void mutateSubmissions()
            setPendingJobId(null)
        }
    }, [pendingJobId, pendingJobStatus, mutateSubmissions])

    const judging = pendingJobId !== null

    // first load in flight → skeleton
    if (isLoading) {
        return <PracticeProblemSkeleton />
    }

    // load resolved with no problem: either a network/GraphQL error (`problemError`)
    // or the BE's uniform 404 for an unknown/disabled slug (fetcher yields `null`).
    // Distinguish the two, and never leave the skeleton spinning forever.
    if (!problem) {
        return (
            <div className="flex h-[calc(100vh-4rem)] flex-col">
                <Box principle="page-pad" className="flex flex-col border-b border-default px-6 py-3"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    <BackLink target={t("codingPractice.title")} onPress={onBack} />
                </Box>
                <Box principle="page-pad" className="flex min-h-0 flex-1 items-center justify-center px-6"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    {problemError ? (
                        <AsyncContentError
                            title={t("codingPractice.detailError")}
                            description={t("codingPractice.detailErrorHint")}
                            onRetry={() => { void mutateProblem() }}
                            retryLabel={t("common.retry")}
                        />
                    ) : (
                        <EmptyState
                            icon={MagnifyingGlassIcon}
                            title={t("codingPractice.notFound")}
                            description={t("codingPractice.notFoundHint")}
                            action={() => (
                                <Button variant="primary" size="sm" onPress={onBack}>
                                    {t("codingPractice.backToPractice")}
                                </Button>
                            )}
                        />
                    )}
                </Box>
            </div>
        )
    }

    const samples = problem.testcases ?? []
    const memoryMb = problem.memoryLimitKb ? Math.round(problem.memoryLimitKb / 1024) : null

    /** LEFT: problem statement, samples, hint. */
    const descriptionPanel = (
        <StackV gap={6} principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            items={[
                () => (
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => (
                                <StackH gap={3} principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    items={[
                                        () => <Typography type="h4" weight="bold">{problem.title}</Typography>,
                                        () => (
                                            <StatusChip tone={DIFFICULTY_TONE[problem.difficulty]}>
                                                {t(`codingPractice.level.${LEVEL_KEY[problem.difficulty]}`)}
                                            </StatusChip>
                                        ),
                                    ]} />
                            ),
                            () => (
                                <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted">
                                    <span>{t("codingPractice.points", { points: problem.points })}</span>
                                    {problem.timeLimitMs ? <span>· {t("codingPractice.timeLimit", { ms: problem.timeLimitMs })}</span> : null}
                                    {memoryMb ? <span>· {t("codingPractice.memoryLimit", { mb: memoryMb })}</span> : null}
                                    {problem.tags.map((tag) => <span key={tag}>· {tag}</span>)}
                                </div>
                            ),
                        ]} />
                ),
                () => <MarkdownContent markdown={problem.statement ?? ""} />,
                ...(samples.length > 0 ? [
                    () => (
                        <StackV gap={4} principle="card-caption"
                            explain="Holds caption text under card media so the caption stays attached to the image above it."
                            items={[
                                () => <hr className="border-default" />,
                                () => <p className="font-semibold">{t("codingPractice.samples")}</p>,
                                ...samples.map((testcase, index) => () => (
                                    <IOExampleCard
                                        key={testcase.id}
                                        rows={[
                                            { key: "in", label: `${t("codingPractice.example")} ${index + 1} · ${t("codingPractice.input")}`, value: testcase.input },
                                            { key: "out", label: t("codingPractice.output"), value: testcase.expectedOutput },
                                        ]}
                                    />
                                )),
                            ]} />
                    ),
                ] : []),
                ...(hint ? [
                    () => (
                        <StackV gap={4} principle="card-caption"
                            explain="Holds caption text under card media so the caption stays attached to the image above it."
                            items={[
                                () => <hr className="border-default" />,
                                () => (
                                    <StackH gap={3} principle="flex-action" justify="between"
                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                        items={[
                                            () => <p className="font-semibold">{t("codingPractice.hintTitle")}</p>,
                                            () => (
                                                <Button size="sm" variant="secondary" onPress={() => setShowHint((prev) => !prev)}>
                                                    {showHint ? t("codingPractice.hideHint") : t("codingPractice.showHint")}
                                                </Button>
                                            ),
                                        ]} />
                                ),
                                ...(showHint ? [() => <MarkdownContent markdown={hint} />] : []),
                            ]} />
                    ),
                ] : []),
            ]} />
    )

    /** LEFT: reveal-gated reference solution, one tab per language. */
    const solutionPanel = (
        <StackV gap={4} principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => (
                    <StackH gap={3} principle="flex-action" justify="between"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => <p className="font-semibold">{t("codingPractice.solutionTitle")}</p>,
                            () => (
                                <Button size="sm" variant="secondary" onPress={onToggleSolution}>
                                    {showSolution ? t("codingPractice.hideSolution") : t("codingPractice.showSolution")}
                                </Button>
                            ),
                        ]} />
                ),
                () => showSolution && solutionLanguages.length > 0 ? (
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => (
                                <Cluster gap={3} principle="flex-action" explain="Groups action controls on one horizontal peer row so they share a single hit baseline." items={solutionLanguages.map((option) => () => (
                                    <Button
                                        key={option}
                                        size="sm"
                                        variant={solutionLanguage === option ? "primary" : "secondary"}
                                        onPress={() => setSolutionLanguage(option)}
                                    >
                                        {t(`codingPractice.language.${option}`)}
                                    </Button>
                                ))} />
                            ),
                            () => (
                                <MarkdownContent
                                    markdown={`\`\`\`${MONACO_LANGUAGE[solutionLanguage]}\n${
                                        solutionByLanguage.get(solutionLanguage) ?? ""
                                    }\n\`\`\``}
                                />
                            ),
                        ]} />
                ) : (
                    <Typography type="body-sm" color="muted">
                        {t("codingPractice.solutionLocked")}
                    </Typography>
                ),
            ]} />
    )

    /** LEFT: the learner's prior submissions for this problem. */
    const submissionItems: Array<SurfaceCardListItem> = (submissionsData?.submissions ?? []).map(
        (submission: CodingSubmission) => ({
            key: submission.id,
            title: new Date(submission.createdAt).toLocaleString(),
            meta: () => (
                <>
                    <Typography type="body-xs" color="muted">
                        {t(`codingPractice.language.${submission.language}`)}
                    </Typography>
                    <StatusChip tone={VERDICT_TONE[submission.verdict]}>
                        {t(`codingPractice.verdict.${submission.verdict}`)}
                    </StatusChip>
                </>
            ),
        }),
    )
    const submissionsPanel = submissionItems.length > 0 ? (
        <SurfaceCardList items={submissionItems} />
    ) : (
        <EmptyState title={t("codingPractice.historyEmpty")} />
    )

    /** CONSOLE: sample testcases (pre-run reference). */
    const testcaseTab = samples.length > 0 ? (
        <StackV gap={4} principle="card-caption" explain="Holds caption text under card media so the caption stays attached to the image above it." items={samples.map((testcase, index) => () => (
            <IOExampleCard
                key={testcase.id}
                rows={[
                    { key: "in", label: `${t("codingPractice.example")} ${index + 1} · ${t("codingPractice.input")}`, value: testcase.input },
                    { key: "out", label: t("codingPractice.output"), value: testcase.expectedOutput },
                ]}
            />
        ))} />
    ) : (
        <Typography type="body-sm" color="muted">{t("codingPractice.noSamples")}</Typography>
    )

    /** CONSOLE: live judging / verdict + per-case grid + stats. */
    const resultTab = judging && pendingJobStatus ? (
        <AIProcessingText
            jobCategory={JobCategory.JudgeCoding}
            jobStatus={pendingJobStatus}
            error={pendingJobError}
        />
    ) : latestSubmission ? (
        <StackV gap={5} principle="group-boundary"
            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
            items={[
                () => (
                    <Cluster gap={4} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={[
                            () => (
                                <StatusChip tone={VERDICT_TONE[latestSubmission.verdict]}>
                                    {t(`codingPractice.verdict.${latestSubmission.verdict}`)}
                                </StatusChip>
                            ),
                            () => (
                                <Typography type="body-sm" color="muted">
                                    {t("codingPractice.passed")}: {latestSubmission.passedCount}/{latestSubmission.totalCount}
                                </Typography>
                            ),
                        ]} />
                ),
                () => (
                    <StatGridCard
                        items={[
                            {
                                key: "passed",
                                content: () => (
                                    <div className="flex flex-col gap-0">
                                        <span className="text-lg font-bold">{latestSubmission.passedCount}/{latestSubmission.totalCount}</span>
                                        <span className="text-xs text-muted">{t("codingPractice.statPassed")}</span>
                                    </div>
                                ),
                            },
                            {
                                key: "runtime",
                                content: () => (
                                    <div className="flex flex-col gap-0">
                                        <span className="text-lg font-bold">{latestSubmission.runtimeMs ?? "—"}<span className="text-xs"> ms</span></span>
                                        <span className="text-xs text-muted">{t("codingPractice.statRuntime")}</span>
                                    </div>
                                ),
                            },
                            {
                                key: "memory",
                                content: () => (
                                    <div className="flex flex-col gap-0">
                                        <span className="text-lg font-bold">{latestSubmission.memoryKb ?? "—"}<span className="text-xs"> KB</span></span>
                                        <span className="text-xs text-muted">{t("codingPractice.statMemory")}</span>
                                    </div>
                                ),
                            },
                        ]}
                    />
                ),
                ...(resultCases.length > 0 ? [
                    () => (
                        <TestCaseResultGrid
                            cases={resultCases}
                            labels={{
                                input: t("codingPractice.input"),
                                expected: t("codingPractice.expected"),
                                got: t("codingPractice.got"),
                                hidden: t("codingPractice.hiddenCase"),
                            }}
                        />
                    ),
                ] : []),
                ...(latestSubmission.compileOutput ? [
                    () => (
                        <pre data-principle="cell-pad" className="whitespace-pre-wrap rounded-2xl bg-danger-soft p-3 text-xs text-danger-soft-foreground">
                            {latestSubmission.compileOutput}
                        </pre>
                    ),
                ] : []),
            ]} />
    ) : (
        <Typography type="body-sm" color="muted">{t("codingPractice.resultEmpty")}</Typography>
    )

    return (
        // full-bleed 2-pane IDE: left reading column | right editor + console
        <div className="grid h-[calc(100vh-4rem)] grid-cols-1 @app-lg:grid-cols-2">

            {/* ── LEFT: tabbed reading column ── */}
            <div className="flex min-h-0 flex-col overflow-hidden border-r border-default">
                <Box principle="page-pad" className="flex flex-col border-b border-default px-6 py-3"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    <StackV gap={4} principle="card-caption"
                        explain="Holds caption text under card media so the caption stays attached to the image above it."
                        items={[
                            () => <BackLink target={t("codingPractice.title")} onPress={onBack} />,
                            () => (
                                <ExtendedTabs
                                    selectedKey={leftTab}
                                    onSelectionChange={(key) => setLeftTab(key as LeftTab)}
                                >
                                    <Tabs.ListContainer>
                                        <Tabs.List aria-label={problem.title}>
                                            <Tabs.Tab id="description">
                                                {t("codingPractice.tabDescription")}
                                                <Tabs.Indicator />
                                            </Tabs.Tab>
                                            <Tabs.Tab id="solution">
                                                {t("codingPractice.tabSolution")}
                                                <Tabs.Indicator />
                                            </Tabs.Tab>
                                            <Tabs.Tab id="submissions">
                                                {t("codingPractice.tabSubmissions")}
                                                <Tabs.Indicator />
                                            </Tabs.Tab>
                                        </Tabs.List>
                                    </Tabs.ListContainer>
                                </ExtendedTabs>
                            ),
                        ]} />
                </Box>
                <Box principle="page-pad" className="min-h-0 flex-1 overflow-auto px-6 py-5"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
                    {leftTab === "description" && descriptionPanel}
                    {leftTab === "solution" && solutionPanel}
                    {leftTab === "submissions" && submissionsPanel}
                </Box>
            </div>

            {/* ── RIGHT: editor + console ── */}
            <div className="flex min-h-0 flex-col overflow-hidden">
                {/* language selector + reset */}
                <Box principle="pill-pad" className="flex flex-wrap items-center justify-between border-b border-default px-4 py-2"
                    explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                    <Cluster gap={3} principle="flex-action" explain="Groups action controls on one horizontal peer row so they share a single hit baseline." items={languages.map((option) => () => (
                        <Button
                            key={option}
                            size="sm"
                            variant={language === option ? "primary" : "secondary"}
                            onPress={() => setLanguage(option)}
                        >
                            {t(`codingPractice.language.${option}`)}
                        </Button>
                    ))} />
                    <Button size="sm" variant="tertiary" onPress={onResetCode}>
                        <ArrowCounterClockwiseIcon className="size-4" aria-hidden focusable="false" />
                        {t("codingPractice.resetCode")}
                    </Button>
                </Box>

                {/* Monaco editor */}
                <div className="min-h-0 flex-1">
                    <Editor
                        height="100%"
                        language={MONACO_LANGUAGE[language]}
                        theme={theme === "dark" ? "vs-dark" : "light"}
                        value={code}
                        onChange={(value) => {
                            setCode(value ?? "")
                            setTouchedLanguages((prev) => new Set(prev).add(language))
                        }}
                        onMount={(editor) => {
                            editor.getDomNode()?.querySelector("textarea")?.setAttribute("spellcheck", "false")
                            editor.onDidPaste((e) => {
                                const model = editor.getModel()
                                const pastedText = model ? model.getValueInRange(e.range) : ""
                                const size = pastedText.length
                                telemetryRef.current.pasteCount += 1
                                telemetryRef.current.pasteSizeMax = Math.max(
                                    telemetryRef.current.pasteSizeMax,
                                    size
                                )
                            })
                            editor.onKeyDown(() => {
                                telemetryRef.current.keystrokeCount += 1
                            })
                            editor.onDidBlurEditorText(() => {
                                telemetryRef.current.tabBlurCount += 1
                            })
                        }}
                        options={{
                            minimap: { enabled: false },
                            fontSize: 14,
                            scrollBeyondLastLine: false,
                            padding: { top: 12, bottom: 12 },
                            bracketPairColorization: { enabled: true },
                            cursorBlinking: "smooth",
                            smoothScrolling: true,
                        }}
                    />
                </div>

                {/* bottom console — Test case / Result + Run/Submit bar */}
                <CodeConsole
                    className="h-[42%]"
                    ariaLabel={t("codingPractice.consoleLabel")}
                    selectedTab={consoleTab}
                    onSelectTab={(key) => setConsoleTab(key as ConsoleTab)}
                    tabs={[
                        { key: "testcase", label: t("codingPractice.tabTestcase"), content: testcaseTab },
                        { key: "result", label: t("codingPractice.tabResult"), content: resultTab },
                    ]}
                    hint={t("codingPractice.runVsSubmit")}
                    actions={(
                        <>
                            {/* "Run on sample" needs a dedicated judge-sample endpoint on the BE —
                                doesn't exist yet, so it's left disabled (the console hint explains it) instead of silently dropping it. */}
                            <Button
                                size="sm"
                                variant="secondary"
                                isDisabled
                            >
                                <PlayIcon className="size-4" aria-hidden focusable="false" />
                                {t("codingPractice.run")}
                            </Button>
                            <Button
                                size="sm"
                                variant="primary"
                                isPending={submitting || judging}
                                isDisabled={code.trim().length === 0}
                                onPress={onSubmit}
                            >
                                {judging ? t("codingPractice.judging") : t("codingPractice.submit")}
                            </Button>
                        </>
                    )}
                />
            </div>
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useState } from "react"
import {
    Button,
    Label,
    Spinner,
    Switch,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setUser } from "@/redux/slices/user"
import { useMutateUpdateProfileSwr } from "@/hooks/swr/api/graphql/mutations/useMutateUpdateProfileSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { StackH, StackV } from "@/components/frames/Stack"
import type { SectionVisibility } from "@/modules/types/entities/user"

/**
 * The four gateable profile sections + their reused tab labels (Overview + CV are
 * never gated here). Each row toggles `sectionVisibility.<key>`; the label reuses
 * the existing `publicProfile.tabs.*` keys so it always matches the tab it hides.
 */
const SECTION_VISIBILITY_OPTIONS = [
    { key: "projects", labelKey: "publicProfile.tabs.projects", descKey: "profileEdit.sectionVisibilityDesc.projects" },
    { key: "challenges", labelKey: "publicProfile.tabs.challenges", descKey: "profileEdit.sectionVisibilityDesc.challenges" },
    { key: "skills", labelKey: "publicProfile.tabs.skills", descKey: "profileEdit.sectionVisibilityDesc.skills" },
    { key: "activity", labelKey: "publicProfile.tabs.activity", descKey: "profileEdit.sectionVisibilityDesc.activity" },
] as const

/** Seed the per-section visibility from the redux user (absent flags default to visible). */
const seedSectionVisibility = (
    visibility: SectionVisibility | undefined,
): SectionVisibility => ({
    projects: visibility?.projects ?? true,
    challenges: visibility?.challenges ?? true,
    skills: visibility?.skills ?? true,
    activity: visibility?.activity ?? true,
})

/**
 * Privacy settings feature container.
 *
 * The profile-VISIBILITY controls — "Lock profile" (lock) + the per-section
 * "Profile visibility" group — moved out of the edit-profile form into their own
 * settings page. Owns a small local form state seeded from the redux user; on save
 * it persists ONLY `{ profileLocked, sectionVisibility }` via `updateProfile` and
 * pushes the fresh user into redux. Mounted by `/profile/settings/privacy`.
 */
export const PrivacySettingsPage = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const user = useAppSelector((state) => state.user.user)

    const runGraphQL = useGraphQLWithToast()
    const updateProfileSwr = useMutateUpdateProfileSwr()

    // small local form state (this page only touches two fields, no RHF needed)
    const [profileLocked, setProfileLocked] = useState<boolean>(user?.profileLocked ?? false)
    const [sectionVisibility, setSectionVisibility] = useState<SectionVisibility>(
        seedSectionVisibility(user?.sectionVisibility),
    )
    const [isSubmitting, setIsSubmitting] = useState(false)

    // re-seed when the redux user changes (mirrors RHF `values` reinit)
    useEffect(() => {
        if (!user) {
            return
        }
        setProfileLocked(user.profileLocked ?? false)
        setSectionVisibility(seedSectionVisibility(user.sectionVisibility))
    }, [user])

    /** Persist ONLY the visibility fields, then push the fresh user into redux. */
    const onSubmit = useCallback(async () => {
        setIsSubmitting(true)
        await runGraphQL(
            async () => {
                const result = await updateProfileSwr.trigger({
                    profileLocked,
                    sectionVisibility,
                })
                const env = result?.data?.updateProfile
                if (!env) {
                    throw new Error(t("profileEdit.error"))
                }
                if (env.success && env.data) {
                    dispatch(setUser(env.data))
                }
                return env
            },
            {
                showErrorToast: true,
                showSuccessToast: true,
            },
        )
        setIsSubmitting(false)
    }, [runGraphQL, updateProfileSwr, profileLocked, sectionVisibility, dispatch, t])

    // signed-out guard
    if (!user) {
        return (
            <div className="flex flex-col items-center py-12">
                <StackV
                    gap={3}
                    align="center"
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    items={[
                        () => (
                            <Typography type="h5" weight="semibold" align="center">
                                {t("profile.signedOut.title")}
                            </Typography>
                        ),
                        () => (
                            <Typography type="body-sm" color="muted" align="center">
                                {t("profile.signedOut.desc")}
                            </Typography>
                        ),
                    ]}
                />
            </div>
        )
    }

    const lockRow = () => (
        <div className="my-2">
            <StackH
                gap={4}
                align="start"
                justify="between"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <div className="flex flex-col gap-0">
                            <Label htmlFor="profile-locked">{t("profileEdit.lockProfile")}</Label>
                            <Typography type="body-xs" color="muted">
                                {t("profileEdit.lockProfileHint")}
                            </Typography>
                        </div>
                    ),
                    () => (
                        <Switch
                            className="shrink-0"
                            isSelected={profileLocked}
                            onChange={(selected) => setProfileLocked(selected)}
                            aria-label={t("profileEdit.lockProfile")}
                        >
                            <Switch.Content>
                                <Switch.Control>
                                    <Switch.Thumb />
                                </Switch.Control>
                            </Switch.Content>
                        </Switch>
                    ),
                ]}
            />
        </div>
    )

    const sectionRows = SECTION_VISIBILITY_OPTIONS.map((option) => () => (
        <div key={option.key} className="my-2">
            <StackH
                gap={4}
                align="start"
                justify="between"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <div className="flex min-w-0 flex-col gap-0">
                            <Label htmlFor={`profile-section-${option.key}`}>
                                {t(option.labelKey)}
                            </Label>
                            <Typography type="body-xs" color="muted">
                                {t(option.descKey)}
                            </Typography>
                        </div>
                    ),
                    () => (
                        <Switch
                            className="shrink-0"
                            isSelected={sectionVisibility[option.key]}
                            isDisabled={profileLocked}
                            onChange={(selected) => setSectionVisibility((prev) => ({
                                ...prev,
                                [option.key]: selected,
                            }))}
                            aria-label={t(option.labelKey)}
                        >
                            <Switch.Content>
                                <Switch.Control>
                                    <Switch.Thumb />
                                </Switch.Control>
                            </Switch.Content>
                        </Switch>
                    ),
                ]}
            />
        </div>
    ))

    const sectionGroupItems = [
        () => (
            <div className="flex flex-col gap-0">
                <Label htmlFor="profile-section-visibility">
                    {t("profileEdit.sectionVisibility")}
                </Label>
                <Typography type="body-xs" color="muted">
                    {profileLocked
                        ? t("profileEdit.sectionVisibilityLockedHint")
                        : t("profileEdit.sectionVisibilityHint")}
                </Typography>
            </div>
        ),
        () => (
            <div
                id="profile-section-visibility"
                className={profileLocked ? "pointer-events-none opacity-50" : undefined}
            >
                <StackV gap={4} items={sectionRows} />
            </div>
        ),
    ]

    const formItems = [
        lockRow,
        () => (
            <div aria-disabled={profileLocked}>
                <StackV gap={6} items={sectionGroupItems} />
            </div>
        ),
        () => (
            <Button
                variant="primary"
                size="lg"
                className="h-12 self-end text-base"
                isDisabled={isSubmitting}
                isPending={isSubmitting}
                onPress={() => onSubmit()}
            >
                {({ isPending }) => (
                    <>
                        {isPending ? (
                            <Spinner
                                color="current"
                                size="sm"
                            />
                        ) : null}
                        {t("profileEdit.save")}
                    </>
                )}
            </Button>
        ),
    ]

    return (
        <StackV gap={7} principle="layout-split"
            explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
            items={[
                () => (
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("profileSettings.privacy.title")} />}
                        title={t("profileSettings.privacy.title")}
                        description={t("profileSettings.privacy.description")}
                    />
                ),
                () => <StackV gap={6} items={formItems} />,
            ]} />
    )
}

"use client"

import React from "react"
import {
    Label,
    Tooltip,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { useQueryUserAchievementsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserAchievementsSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { MascotBadge } from "@/components/blocks/profile/MascotBadge"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import { getRank } from "@/modules/utils/rank"

/** One labelled achievement bucket: a group key plus the badge slugs it holds. */
interface AchievementGroup {
    /** i18n key identifying the group (e.g. `learning`, `skills`). */
    key: string
    /** Badge slugs displayed under this group, in order. */
    slugs: ReadonlyArray<string>
}

/**
 * Achievement wall layout: each badge slug bucketed into a labelled group, in
 * display order. Slugs not listed here fall into a trailing "other" group, so
 * adding a badge never silently drops it.
 */
const ACHIEVEMENT_GROUPS: ReadonlyArray<AchievementGroup> = [
    {
        key: "learning",
        slugs: [
            "baby-duckling",
            "blazing-fox",
            "crowned-owl",
            "polyglot-parrot",
        ],
    },
    {
        key: "skills",
        slugs: [
            "sword-shark",
            "bug-hunting-chameleon",
            "brainy-octopus",
        ],
    },
    {
        key: "community",
        slugs: [
            "guiding-elephant",
            "busy-bee",
            "champion-lion",
        ],
    },
    {
        key: "course",
        slugs: [
            "architect-rhino",
            "fullstack-monkey",
            "devops-wolf",
        ],
    },
]

/** Props for {@link ProfileAchievements}. */
export type ProfileAchievementsProps = WithClassNames<undefined>

/**
 * Achievements tab of the public profile — the profile owner's badge wall. Earned
 * badges show in full colour; locked ones are dimmed with progress toward the
 * threshold. Self-contained container: reads the target user id from the route
 * and drives its own SWR. Mirrors the dashboard achievements grid but for any
 * user (not just the viewer). Badge art comes from MinIO (`iconKey`), falling
 * back to a medal placeholder.
 *
 * @param props - optional className for the root element.
 */
export const ProfileAchievements = () => {
    const t = useTranslations()
    // route carries the username; resolve it to the entity id the achievements
    // query keys off (the profile fetch is SWR-deduped with the parent + tabs)
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserAchievementsSwr(userId)

    const items = data ?? []

    const renderItem = (item: (typeof items)[number]) => {
        // earned → rank (coloured by its ring) · rarity %; locked → progress
        const { labelKey, ring } = getRank(item.earned, item.tierReached)
        const rankLabel = labelKey ? t(labelKey) : null
        // shared meta line: rank in its ring colour + rarity muted, or locked progress
        const meta = item.earned && rankLabel ? (
            <StackH gap={3} items={[
                () => (
                    <Typography type="body-xs" weight="medium" style={{ color: ring }}>
                        {rankLabel}
                    </Typography>
                ),
                ...(item.rarityPercent != null
                    ? [() => (
                        <Typography type="body-xs" color="muted">
                            · {item.rarityPercent}%
                        </Typography>
                    )]
                    : []),
            ]} />
        ) : (
            <Typography type="body-xs" color="muted">
                {item.currentValue}/{item.threshold}
            </Typography>
        )
        return (
            <Tooltip
                key={item.slug}
                delay={200}
            >
                <Tooltip.Trigger>
                    <div className="max-w-32 min-w-0 cursor-default text-center">
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            align="center" items={[
                                () => (
                                    <MascotBadge
                                        objectKey={item.iconKey}
                                        name={item.name}
                                        earned={item.earned}
                                        tierReached={item.tierReached}
                                        size={48}
                                    />
                                ),
                                () => (
                                    <Typography type="body-xs" truncate className="w-full">
                                        {item.name}
                                    </Typography>
                                ),
                                () => meta,
                            ]} />
                    </div>
                </Tooltip.Trigger>
                <Tooltip.Content
                    placement="top"
                    showArrow
                    className="max-w-[240px]"
                >
                    <Tooltip.Arrow />
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        align="center" items={[
                            () => (
                                <MascotBadge
                                    objectKey={item.iconKey}
                                    name={item.name}
                                    earned={item.earned}
                                    tierReached={item.tierReached}
                                    size={56}
                                />
                            ),
                            () => (
                                <Typography type="body-sm" weight="semibold">
                                    {item.name}
                                </Typography>
                            ),
                            () => (
                                <Typography type="body-xs" color="muted">
                                    {item.description}
                                </Typography>
                            ),
                            () => meta,
                        ]} />
                </Tooltip.Content>
            </Tooltip>
        )
    }

    // earned badges first (then higher tier, then closer-to-earning) so the flex
    // leads and locked/grey badges sink to the back of each group
    const byFlex = (
        a: (typeof items)[number],
        b: (typeof items)[number],
    ): number => {
        if (a.earned !== b.earned) {
            return a.earned ? -1 : 1
        }
        const aTier = a.tierReached ?? 0
        const bTier = b.tierReached ?? 0
        if (aTier !== bTier) {
            return bTier - aTier
        }
        // both locked → the one nearer its threshold ranks first
        const aProgress = a.threshold > 0 ? a.currentValue / a.threshold : 0
        const bProgress = b.threshold > 0 ? b.currentValue / b.threshold : 0
        return bProgress - aProgress
    }

    // bucket the wall into labelled groups (display order), with a trailing
    // "other" group catching any slug not assigned above
    const assigned = new Set(ACHIEVEMENT_GROUPS.flatMap((group) => group.slugs))
    const groups = ACHIEVEMENT_GROUPS
        .map((group) => ({
            key: group.key,
            items: items.filter((item) => group.slugs.includes(item.slug)).sort(byFlex),
        }))
        .filter((group) => group.items.length > 0)
    const other = items.filter((item) => !assigned.has(item.slug)).sort(byFlex)
    if (other.length > 0) {
        groups.push({
            key: "other",
            items: other,
        })
    }

    return (
        <LabeledCard

            label={t("publicProfile.tabs.achievements")}
        >
            <AsyncContent
                isLoading={(isLoading || !userId) && items.length === 0}
                skeleton={
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={
                            [0, 1].map(() => () => (
                                <StackV gap={4} items={[
                                    () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                    () => (
                                        <Cluster gap={5} principle="group-boundary"
                                            explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                            items={
                                                [0, 1, 2, 3].map(() => () => (
                                                    <div className="w-24 text-center">
                                                        <StackV gap={3} principle="sibling-stack"
                                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                            align="center" items={[
                                                                () => <Skeleton className="size-12 rounded-full" />,
                                                                () => <Skeleton.Typography type="body-xs" width="3/4" />,
                                                                () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                                            ]} />
                                                    </div>
                                                ))
                                            } />
                                    ),
                                ]} />
                            ))
                        } />
                }
                isEmpty={items.length === 0}
                emptyContent={{
                    title: t("publicProfile.achievementsEmpty"),
                }}
                error={error}
                errorContent={{
                    title: t("publicProfile.loadError"),
                    onRetry: () => mutate(),
                    retryLabel: t("publicProfile.loadErrorRetry"),
                }}
            >
                <StackV gap={6} principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={
                        groups.map((group) => () => (
                            <StackV gap={4} items={[
                                () => (
                                    <Label>
                                        {t(`publicProfile.achievementGroups.${group.key}`)}
                                    </Label>
                                ),
                                () => (
                                    <Cluster gap={5} principle="group-boundary"
                                        explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                        items={
                                            group.items.map((item) => () => renderItem(item))
                                        } />
                                ),
                            ]} />
                        ))
                    } />
            </AsyncContent>
        </LabeledCard>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Button,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { queryResolveRoute } from "@/modules/api/graphql/queries/query-resolve-route"
import type { ReactionType } from "@/modules/api/graphql/queries/types/discussion"
import { useQueryUserFeedSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserFeedSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useMutateReactActivitySwr } from "@/hooks/swr/api/graphql/mutations/useMutateReactActivitySwr"
import { useAppSelector } from "@/redux/hooks"
import { ActivityFeed } from "@/components/blocks/feed/ActivityFeed"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { StackH, StackV } from "@/components/frames/Stack"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"

/** Props for {@link ProfileActivity}. */
export type ProfileActivityProps = WithClassNames<undefined>

/**
 * Activity-tab section — the profile owner's timeline, rendered by the shared
 * {@link ActivityFeed} block (avatar + activity-type badge · actor·action·target
 * sentence · relative time, grouped by day, milestone roll-up, never-blank target).
 * This feature owns the fetch (infinite SWR), the "load more" pager, the section
 * card + states, and the route resolver it hands the block. Self-hides when empty.
 *
 * @param props - optional className (placement only).
 */
export const ProfileActivity = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const {
        data,
        size,
        setSize,
        isLoading,
        isValidating,
        error,
        mutate,
    } = useQueryUserFeedSwr(userId)
    const { trigger: reactActivity } = useMutateReactActivitySwr()

    /** React to a timeline activity, then revalidate. Own items are read-only
     * (server sets `isMine` → the feed suppresses the picker), so this only ever
     * fires when viewing someone else's profile. */
    const onReact = useCallback(
        async (activityId: string, type: ReactionType | null) => {
            await reactActivity({ activityId, type })
            await mutate()
        },
        [
            reactActivity,
            mutate,
        ],
    )

    // flatten every loaded page into a single newest-first item list
    const items = useMemo(
        () => (data ?? []).flatMap((page) => page.items),
        [data],
    )
    const hasMore = Boolean(data && data.length > 0 && data[data.length - 1].nextCursor !== null)
    const isLoadingMore = isValidating && Boolean(data) && size > 0

    /** Resolve an entity's route via the index, then navigate (no-op if unroutable). */
    const onResolve = useCallback(
        (globalId: string | null | undefined): (() => void) | undefined => {
            if (!globalId) {
                return undefined
            }
            return () => {
                void (async () => {
                    const response = await queryResolveRoute({ request: { globalId } })
                    const path = response.data?.resolveRoute?.data?.path
                    if (path) {
                        router.push(`/${locale}${path}`)
                    }
                })()
            }
        },
        [
            locale,
            router,
        ],
    )

    return (
        <LabeledCard

            label={t("publicProfile.recentActivity")}
        >
            <AsyncContent
                isLoading={(isLoading || !userId) && items.length === 0}
                skeleton={(
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={
                            [0, 1].map(() => () => (
                                <StackV gap={4} items={[
                                    () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                    () => (
                                        <SurfaceListCard bordered>
                                            {[0, 1, 2].map((row) => (
                                                <SurfaceListCardItem key={row}>
                                                    <StackH gap={3} principle="identity"
                                                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                                        align="start" items={[
                                                            () => <Skeleton className="size-9 shrink-0 rounded-full" />,
                                                            () => (
                                                                <StackV gap={1} classNames={["flex-1"]} items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                                                    () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                                                ]} />
                                                            ),
                                                        ]} />
                                                </SurfaceListCardItem>
                                            ))}
                                        </SurfaceListCard>
                                    ),
                                ]} />
                            ))
                        } />
                )}
                isEmpty={items.length === 0}
                emptyContent={{
                    title: t("publicProfile.activityEmpty"),
                    description: t("publicProfile.activityEmptyHint"),
                }}
                error={items.length === 0 ? error : undefined}
                errorContent={{
                    title: t("publicProfile.loadError"),
                    onRetry: () => {
                        void mutate()
                    },
                    retryLabel: t("publicProfile.loadErrorRetry"),
                }}
            >
                <StackV gap={6} principle="block-boundary"
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <ActivityFeed
                                items={items}
                                onResolve={onResolve}
                                onReact={authenticated ? onReact : undefined}
                                bordered
                            />
                        ),
                        ...(hasMore
                            ? [() => (
                                <div className="flex justify-center">
                                    <Button
                                        variant="secondary"
                                        size="sm"
                                        isPending={isLoadingMore}
                                        onPress={() => setSize(size + 1)}
                                    >
                                        {t("publicProfile.loadMore")}
                                    </Button>
                                </div>
                            )]
                            : []),
                    ]} />
            </AsyncContent>
        </LabeledCard>
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import {
    Badge,
    Button,
    Popover,
    Typography,
    cn,
} from "@heroui/react"
import {
    FunnelIcon,
} from "@phosphor-icons/react"
import {
    useParams,
    useRouter,
} from "next/navigation"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    difficultyLevel,
} from "@/modules/utils/challenge-difficulty"
import { pathConfig } from "@/resources/path"
import { dayjs } from "@/modules/dayjs"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { LanguageChip } from "@/components/blocks/chips/LanguageChip"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Single-select difficulty filter value — `"all"` clears the filter. */
type DifficultyFilterValue = "all" | string
/** Single-select language filter value — `"all"` clears the filter. */
type LanguageFilterValue = "all" | string
/** Sort order for the submission list. */
type SortValue = "newest" | "score"

/**
 * Score → attention colour the eye catches fast: high green, mid yellow, low red.
 * @param score - the graded score (0–100).
 * @returns a `text-{token}` class for the score label.
 */
const scoreToneClass = (score: number): string => {
    if (score >= 90) {
        return "text-success-soft-foreground"
    }
    if (score >= 70) {
        return "text-warning-soft-foreground"
    }
    return "text-danger-soft-foreground"
}

/** Props for {@link ProfileChallengeManagePage}. */
export type ProfileChallengeManagePageProps = Record<string, never>
/**
 * `/profile/<u>/challenges/<courseSlug>` — the MANAGE tier of the 3-tier
 * challenges flow: search ONE course's passed-challenge submissions, with sort
 * (newest / highest score) and the difficulty/language facets tucked behind a
 * single FUNNEL popover next to the search box (keeps the toolbar one clean line).
 * Reads the course SLUG from the route, filters the profile owner's full
 * solved-challenges list down to it client-side (the list is already small
 * per-user; no server-side pagination needed here), then renders each match as
 * a nav row to the submission DETAIL page.
 *
 * @param props - optional className for the root element.
 */
export const ProfileChallengeManagePage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const params = useParams<{ courseId: string }>()
    const courseSlug = params?.courseId ? String(params.courseId) : null

    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserSolvedChallengesSwr(userId)

    const [search, setSearch] = useState("")
    const [filterOpen, setFilterOpen] = useState(false)
    const [difficultyFilter, setDifficultyFilter] = useState<DifficultyFilterValue>("all")
    const [languageFilter, setLanguageFilter] = useState<LanguageFilterValue>("all")
    const [sort, setSort] = useState<SortValue>("newest")

    const allChallenges = data ?? []
    // scope down to THIS course only — the manage page's whole reason to exist
    const courseChallenges = useMemo(
        () => allChallenges.filter((challenge) => challenge.courseSlug === courseSlug),
        [allChallenges, courseSlug],
    )
    const courseTitle = courseChallenges[0]?.courseTitle ?? null
    // how many of the two facet filters are narrowing right now (drives the funnel badge)
    const activeFacetCount = (difficultyFilter !== "all" ? 1 : 0) + (languageFilter !== "all" ? 1 : 0)
    const clearFacets = () => {
        setDifficultyFilter("all")
        setLanguageFilter("all")
    }

    // filter option pools — only difficulties/languages actually present in this course
    const difficultyOptions = useMemo(
        () => Array.from(new Set(courseChallenges.map((challenge) => challenge.difficulty).filter((value): value is string => Boolean(value)))),
        [courseChallenges],
    )
    const languageOptions = useMemo(
        () => Array.from(new Set(courseChallenges.map((challenge) => challenge.selectedLang).filter((value): value is string => Boolean(value)))),
        [courseChallenges],
    )

    const filtered = useMemo(() => {
        const query = search.trim().toLowerCase()
        const rows = courseChallenges.filter((challenge) => {
            if (query && !challenge.title.toLowerCase().includes(query)) {
                return false
            }
            if (difficultyFilter !== "all" && challenge.difficulty !== difficultyFilter) {
                return false
            }
            if (languageFilter !== "all" && challenge.selectedLang !== languageFilter) {
                return false
            }
            return true
        })
        const sorted = [...rows]
        if (sort === "score") {
            sorted.sort((a, b) => (b.score ?? -1) - (a.score ?? -1))
        } else {
            sorted.sort((a, b) => {
                const bTime = b.passedAt ? new Date(b.passedAt).getTime() : 0
                const aTime = a.passedAt ? new Date(a.passedAt).getTime() : 0
                return bTime - aTime
            })
        }
        return sorted
    }, [courseChallenges, search, difficultyFilter, languageFilter, sort])

    const hasActiveFilter = Boolean(search.trim() || difficultyFilter !== "all" || languageFilter !== "all")

    return (
        <div className={"mx-auto flex max-w-4xl flex-col gap-6"}>
            <PageHeader
                breadcrumb={(
                    <BackLink
                        target={t("publicProfile.challengesTab.repoHeading")}
                        onPress={() => router.push(pathConfig().locale(locale).profile(username ?? undefined).challenges().build())}
                    />
                )}
                title={courseTitle ?? t("publicProfile.challengesTab.manage.title")}
                description={t("publicProfile.challengesTab.manage.description")}
            />

            {/* search + a FUNNEL popover (difficulty/language facets) + sort, one row.
                Facets live behind the funnel so the toolbar stays a single clean line
                regardless of how many facet values exist. */}
            <Cluster gap={4} principle="content-row" justify="between" align="center" classNames={["w-full"]}
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StackH gap={4} principle="flex-action" classNames={["min-w-0", "flex-1"]}
                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            items={[
                                () => (
                                    <SearchInput
                                        className="min-w-0 flex-1"
                                        value={search}
                                        onValueChange={setSearch}
                                        placeholder={t("publicProfile.challengesTab.manage.searchPlaceholder")}
                                    />
                                ),
                                () => (
                                    <Popover isOpen={filterOpen} onOpenChange={setFilterOpen}>
                                        <Button
                                            isIconOnly
                                            variant="ghost"
                                            aria-label={t("publicProfile.challengesTab.manage.filterButton")}
                                            className="shrink-0"
                                        >
                                            {activeFacetCount > 0 ? (
                                                <Badge.Anchor>
                                                    <FunnelIcon className="size-5" />
                                                    <Badge size="sm" color="accent" placement="top-left">{activeFacetCount}</Badge>
                                                </Badge.Anchor>
                                            ) : (
                                                <FunnelIcon className="size-5" />
                                            )}
                                        </Button>
                                        <Popover.Content className="w-72">
                                            <Box principle="cell-pad" className="p-3"
                                                explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body.">
                                                <StackV gap={4} principle="group-boundary"
                                                    explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                                    items={[
                                                        () => (
                                                            <StackV gap={4} principle="label-field"
                                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                items={[
                                                                    () => <Typography type="body-xs" color="muted">{t("publicProfile.challengesTab.manage.sortHeading")}</Typography>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio<SortValue>
                                                                            ariaLabel={t("publicProfile.challengesTab.manage.sortAria")}
                                                                            value={sort}
                                                                            onChange={setSort}
                                                                            items={[
                                                                                { value: "newest", content: t("publicProfile.challengesTab.manage.sortNewest") },
                                                                                { value: "score", content: t("publicProfile.challengesTab.manage.sortScore") },
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                        ),
                                                        ...(difficultyOptions.length > 0 ? [() => (
                                                            <StackV gap={4} principle="label-field"
                                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                items={[
                                                                    () => <Typography type="body-xs" color="muted">{t("publicProfile.challengesTab.manage.difficultyHeading")}</Typography>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio<DifficultyFilterValue>
                                                                            ariaLabel={t("publicProfile.challengesTab.manage.difficultyFilterAria")}
                                                                            value={difficultyFilter}
                                                                            onChange={setDifficultyFilter}
                                                                            items={[
                                                                                { value: "all", content: t("publicProfile.challengesTab.manage.allDifficulties") },
                                                                                ...difficultyOptions.map((raw) => ({
                                                                                    value: raw,
                                                                                    content: <DifficultyChip difficulty={difficultyLevel(raw) ?? "beginner"} />,
                                                                                })),
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                        )] : []),
                                                        ...(languageOptions.length > 0 ? [() => (
                                                            <StackV gap={4} principle="label-field"
                                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                                items={[
                                                                    () => <Typography type="body-xs" color="muted">{t("publicProfile.challengesTab.manage.languageHeading")}</Typography>,
                                                                    () => (
                                                                        <FlexWrapButtonRadio<LanguageFilterValue>
                                                                            ariaLabel={t("publicProfile.challengesTab.manage.languageFilterAria")}
                                                                            value={languageFilter}
                                                                            onChange={setLanguageFilter}
                                                                            items={[
                                                                                { value: "all", content: t("publicProfile.challengesTab.manage.allLanguages") },
                                                                                ...languageOptions.map((lang) => ({
                                                                                    value: lang,
                                                                                    content: <LanguageChip language={lang} />,
                                                                                })),
                                                                            ]}
                                                                        />
                                                                    ),
                                                                ]} />
                                                        )] : []),
                                                        ...(activeFacetCount > 0 ? [() => (
                                                            <Button variant="danger-soft" size="sm" className="self-start" onPress={clearFacets}>
                                                                {t("publicProfile.challengesTab.manage.clearFilters")}
                                                            </Button>
                                                        )] : []),
                                                    ]} />
                                            </Box>
                                        </Popover.Content>
                                    </Popover>
                                ),
                            ]} />
                    ),
                    () => (
                        <Typography type="body-sm" color="muted" className="shrink-0">
                            {t("publicProfile.challengesTab.manage.found", { count: filtered.length })}
                        </Typography>
                    ),
                ]} />

            <AsyncContent
                isLoading={(isLoading || !userId) && courseChallenges.length === 0}
                skeleton={(
                    <SurfaceCardList
                        isSkeleton
                        items={[0, 1, 2].map((row) => ({
                            key: `manage-skel-${row}`,
                            content: () => (
                                <StackV gap={2} principle="title-subtitle"
                                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                                    items={[
                                        () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                        () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                    ]} />
                            ),
                        }))}
                    />
                )}
                isEmpty={filtered.length === 0}
                emptyContent={hasActiveFilter
                    ? {
                        title: t("publicProfile.challengesTab.manage.emptyFiltered"),
                        onRetry: () => {
                            setSearch("")
                            setDifficultyFilter("all")
                            setLanguageFilter("all")
                        },
                        retryLabel: t("jobs.list.emptyFiltered.clearFilters"),
                    }
                    : {
                        title: t("publicProfile.challengesTab.empty"),
                        description: t("publicProfile.challengesTab.emptyHint"),
                    }}
                error={courseChallenges.length === 0 ? error : undefined}
                errorContent={{
                    title: t("publicProfile.loadError"),
                    onRetry: () => { void mutate() },
                    retryLabel: t("publicProfile.loadErrorRetry"),
                }}
            >
                <SurfaceCardList
                    items={filtered.map((challenge, index) => {
                        const level = difficultyLevel(challenge.difficulty)
                        const passedAt = challenge.passedAt
                            ? dayjs(challenge.passedAt).locale(locale).format("hh:mm MMMM DD, YYYY")
                            : undefined
                        const selectedLang = challenge.selectedLang
                        const score = challenge.score
                        return {
                            key: challenge.id ?? `${challenge.submissionUrl}-${index}`,
                            hover: "underline" as const,
                            href: username && challenge.id
                                ? pathConfig().locale(locale).profile(username).challenges()
                                    .course(courseSlug ?? "").submission(challenge.id).build()
                                : undefined,
                            content: () => (
                                <StackH gap={4} principle="content-row" justify="between" align="center"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => (
                                            <StackV gap={2} principle="title-subtitle" classNames={["min-w-0", "flex-1"]}
                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                items={[
                                                    () => (
                                                        <Typography type="body-sm" weight="medium" truncate className="underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                                                            {challenge.title}
                                                        </Typography>
                                                    ),
                                                    () => (
                                                        <Cluster gap={3} principle="chip-row" align="center"
                                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                            items={[
                                                                ...(level ? [() => <DifficultyChip difficulty={level} />] : []),
                                                                ...(selectedLang ? [() => <LanguageChip language={selectedLang} />] : []),
                                                                ...(passedAt ? [() => (
                                                                    <Typography type="body-xs" color="muted">
                                                                        {passedAt}
                                                                    </Typography>
                                                                )] : []),
                                                            ]} />
                                                    ),
                                                ]} />
                                        ),
                                        ...(typeof score === "number" ? [() => (
                                            <Typography
                                                type="body-xs"
                                                weight="medium"
                                                className={cn("shrink-0", scoreToneClass(score))}
                                            >
                                                {t("publicProfile.challengesTab.score", { score })}
                                            </Typography>
                                        )] : []),
                                    ]} />
                            ),
                        } satisfies SurfaceCardListItem
                    })}
                />
            </AsyncContent>
        </div>
    )
}

"use client"

import React from "react"
import {
    Link,
    Typography,
    cn,
} from "@heroui/react"
import {
    useParams,
    useRouter,
} from "next/navigation"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    LinkIcon,
} from "@phosphor-icons/react"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    difficultyLevel,
} from "@/modules/utils/challenge-difficulty"
import { pathConfig } from "@/resources/path"
import { dayjs } from "@/modules/dayjs"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengeDetailSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengeDetailSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { LanguageChip } from "@/components/blocks/chips/LanguageChip"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Score → attention colour band (also used per-attempt in the attempts record). */
const scoreToneClass = (score: number): string => {
    if (score >= 90) {
        return "text-success-soft-foreground"
    }
    if (score >= 70) {
        return "text-warning-soft-foreground"
    }
    return "text-danger-soft-foreground"
}

/** Props for {@link ProfileChallengeSubmissionPage}. */
export type ProfileChallengeSubmissionPageProps = Record<string, never>
/**
 * `/profile/<u>/challenges/<courseSlug>/<submissionId>` — the DETAIL tier of
 * the 3-tier challenges flow: one passed submission's header (title, score,
 * difficulty, language, passed date), its submitted repo/docs link (the URL
 * itself, not a generic label), the attempts record (every graded try, newest
 * first), and the structured AI feedback rubric from the passing attempt — one
 * row per feedback item, accented by severity.
 *
 * @param props - optional className for the root element.
 */
export const ProfileChallengeSubmissionPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const params = useParams<{ courseId: string; submissionId: string }>()
    const courseSlug = params?.courseId ? String(params.courseId) : null
    const submissionId = params?.submissionId ? String(params.submissionId) : null

    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data: detail,
        isLoading,
        error,
        mutate,
    } = useQueryUserSolvedChallengeDetailSwr(userId, submissionId)

    const level = difficultyLevel(detail?.difficulty)
    const passedAt = detail?.passedAt
        ? dayjs(detail.passedAt).locale(locale).format("hh:mm MMMM DD, YYYY")
        : undefined
    const attempts = detail?.attempts ?? []

    return (
        <div className={"mx-auto flex max-w-4xl flex-col gap-6"}>
            <PageHeader
                breadcrumb={(
                    <BackLink
                        target={t("publicProfile.challengesTab.repoHeading")}
                        onPress={() => router.push(
                            username && courseSlug
                                ? pathConfig().locale(locale).profile(username).challenges().course(courseSlug).build()
                                : pathConfig().locale(locale).profile(username ?? undefined).challenges().build(),
                        )}
                    />
                )}
                title={detail?.title ?? t("publicProfile.challengesTab.detail.title")}
                meta={detail ? (
                    <Cluster gap={3} principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        align="center" items={[
                            ...(level ? [() => <DifficultyChip difficulty={level} />] : []),
                            ...(detail.selectedLang ? [() => {
                                const lang = detail.selectedLang as string
                                return <LanguageChip language={lang} />
                            }] : []),
                            ...(typeof detail.score === "number" ? [() => {
                                const score = detail.score as number
                                return (
                                    <Typography type="body-xs" weight="medium" className={scoreToneClass(score)}>
                                        {t("publicProfile.challengesTab.score", { score })}
                                    </Typography>
                                )
                            }] : []),
                            ...(passedAt ? [() => (
                                <Typography type="body-xs" color="muted">
                                    {passedAt}
                                </Typography>
                            )] : []),
                        ]} />
                ) : undefined}
            />

            <AsyncContent
                isLoading={isLoading && !detail}
                skeleton={(
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => <Skeleton className="h-6 w-1/2" />,
                            () => (
                                <SurfaceCardList
                                    isSkeleton
                                    items={[0, 1, 2].map((row) => ({
                                        key: `attempt-skel-${row}`,
                                        content: () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                    }))}
                                />
                            ),
                        ]} />
                )}
                isEmpty={!detail}
                emptyContent={{
                    title: t("publicProfile.challengesTab.detail.notFound"),
                }}
                error={!detail ? error : undefined}
                errorContent={{
                    title: t("publicProfile.loadError"),
                    onRetry: () => { void mutate() },
                    retryLabel: t("publicProfile.loadErrorRetry"),
                }}
            >
                {detail ? (
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => (
                                <StackV gap={1} principle="name-handle"
                                    explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                    items={[
                                        () => (
                                            <Typography type="body-xs" color="muted">
                                                {t("publicProfile.challengesTab.detail.repoLabel")}
                                            </Typography>
                                        ),
                                        () => (
                                            <Link
                                                href={detail.submissionUrl}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="w-fit min-w-0 max-w-full text-accent-soft-foreground underline underline-offset-4 decoration-[var(--separator-tertiary)]"
                                                aria-label={t("publicProfile.openRepo", { title: detail.title })}
                                            >
                                                <StackH gap={2} principle="icon-text"
                                                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                                    align="center" items={[
                                                        () => <LinkIcon aria-hidden focusable="false" className="size-5 shrink-0" />,
                                                        () => (
                                                            <Typography type="body-sm" truncate className="text-accent-soft-foreground">
                                                                {detail.submissionUrl}
                                                            </Typography>
                                                        ),
                                                    ]} />
                                            </Link>
                                        ),
                                    ]} />
                            ),
                            () => (
                                <SurfaceCardList
                                    label={t("publicProfile.challengesTab.detail.attemptsHeading")}
                                    emptyState={() => (
                                        <Typography type="body-sm" color="muted">
                                            {t("publicProfile.challengesTab.detail.noAttempts")}
                                        </Typography>
                                    )}
                                    items={attempts.map((attempt) => {
                                        const attemptProcessedAt = attempt.processedAt
                                            ? dayjs(attempt.processedAt).locale(locale).format("hh:mm MMMM DD, YYYY")
                                            : undefined
                                        const attemptScore = attempt.score
                                        return {
                                            key: String(attempt.attemptNumber),
                                            content: () => (
                                                <StackV gap={3} principle="sibling-stack"
                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                    items={[
                                                        () => (
                                                            <StackH gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                justify="between" align="center" items={[
                                                                    () => (
                                                                        <Typography type="body-sm" weight="medium">
                                                                            {t("publicProfile.challengesTab.detail.attemptLabel", { number: attempt.attemptNumber })}
                                                                        </Typography>
                                                                    ),
                                                                    ...(typeof attemptScore === "number" ? [() => (
                                                                        <Typography
                                                                            type="body-xs"
                                                                            weight="medium"
                                                                            className={cn("shrink-0", scoreToneClass(attemptScore))}
                                                                        >
                                                                            {t("publicProfile.challengesTab.score", { score: attemptScore })}
                                                                        </Typography>
                                                                    )] : []),
                                                                ]} />
                                                        ),
                                                        ...(attemptProcessedAt ? [() => (
                                                            <Typography type="body-xs" color="muted">
                                                                {attemptProcessedAt}
                                                            </Typography>
                                                        )] : []),
                                                        () => (
                                                            <Link
                                                                href={attempt.submissionUrl}
                                                                target="_blank"
                                                                rel="noopener noreferrer"
                                                                className="w-fit min-w-0 max-w-full text-accent-soft-foreground underline underline-offset-4 decoration-[var(--separator-tertiary)]"
                                                                aria-label={t("publicProfile.openRepo", { title: detail.title })}
                                                            >
                                                                <StackH gap={2} principle="icon-text"
                                                                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                                                    align="center" items={[
                                                                        () => <LinkIcon aria-hidden focusable="false" className="size-4 shrink-0" />,
                                                                        () => (
                                                                            <Typography type="body-xs" truncate className="text-accent-soft-foreground">
                                                                                {attempt.submissionUrl}
                                                                            </Typography>
                                                                        ),
                                                                    ]} />
                                                            </Link>
                                                        ),
                                                        ...(attempt.shortFeedback ? [() => (
                                                            <Typography type="body-xs" color="muted">
                                                                {attempt.shortFeedback}
                                                            </Typography>
                                                        )] : []),
                                                    ]} />
                                            ),
                                        } satisfies SurfaceCardListItem
                                    })}
                                />
                            ),
                        ]} />
                ) : null}
            </AsyncContent>
        </div>
    )
}

"use client"

import React from "react"
import {
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    PuzzlePieceIcon,
} from "@phosphor-icons/react"
import {
    buildDifficultySegments,
} from "@/modules/utils/challenge-difficulty"
import { pathConfig } from "@/resources/path"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { QueryUserSolvedChallengeItemData } from "@/modules/api/graphql/queries/types/user-solved-challenges"

/** Props for {@link ChallengeCourseRow}. */
export interface ChallengeCourseRowProps {
    /** Profile owner's username — routes the row to `.challenges().course(courseSlug)`. */
    username: string | null
    /** Course title for this group, or null for ungrouped (V1-legacy) rows. */
    courseTitle: string | null
    /** SEO-friendly slug of the course, or null when unresolved (V1-legacy) — the row is non-interactive without it. */
    courseSlug: string | null
    /** Solved-challenge rows under this course, in source order (list-item data). */
    items: Array<QueryUserSolvedChallengeItemData>
    /**
     * Total challenges in the course — makes the bar a PROGRESS bar (done coloured
     * by difficulty, the rest the empty track). Omit/0 → pure passed-mix (100% fill).
     */
    totalChallenges?: number
}

/**
 * One course group on the Challenges tab: a framed puzzle {@link IconTile}, the
 * course title, a 4-tone difficulty {@link SegmentBar} and a passed-count summary.
 * The WHOLE glance row is a nav link (row-as-link, hover underlines the title) to
 * the per-course MANAGE page (`.challenges().course(courseSlug)`) — search /
 * filter / sort of that course's submissions lives there, not inline here.
 *
 * @param props - {@link ChallengeCourseRowProps}
 */
export const ChallengeCourseRow = ({
    username,
    courseTitle,
    courseSlug,
    items,
    totalChallenges}: ChallengeCourseRowProps) => {
    const t = useTranslations()
    const locale = useLocale()

    const segments = buildDifficultySegments(items)
    const href = username && courseSlug
        ? pathConfig().locale(locale).profile(username).challenges().course(courseSlug).build()
        : undefined

    return (
        <SurfaceListCardItem
            href={href}
            hover="underline"
        >
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="start" items={[
                    () => (
                        <IconTile
                            size="sm"
                            icon={<PuzzlePieceIcon aria-hidden focusable="false" />}
                        />
                    ),
                    () => (
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            classNames={["min-w-0", "flex-1"]} items={[
                                () => (
                                    <Typography
                                        type="body-sm"
                                        weight="medium"
                                        truncate
                                        className={href ? "underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline" : undefined}
                                    >
                                        {courseTitle ?? t("publicProfile.challengesTab.ungrouped")}
                                    </Typography>
                                ),
                                () => (
                                    <SegmentBar
                                        hideLegend
                                        max={totalChallenges && totalChallenges > 0 ? totalChallenges : undefined}
                                        ariaLabel={t("publicProfile.challengesTab.submissionCount", { count: items.length })}
                                        segments={segments}
                                    />
                                ),
                                () => (
                                    <Typography type="body-xs" color="muted">
                                        {totalChallenges && totalChallenges > 0
                                            ? t("publicProfile.challengesTab.submissionProgress", { passed: items.length, total: totalChallenges })
                                            : t("publicProfile.challengesTab.submissionCount", { count: items.length })}
                                    </Typography>
                                ),
                            ]} />
                    ),
                ]} />
        </SurfaceListCardItem>
    )
}

"use client"

import React from "react"
import {
    Label,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    buildDifficultySegments,
} from "@/modules/utils/challenge-difficulty"
import {
    groupByCourse,
} from "@/modules/utils/group-challenges-by-course"
import {
    ChallengeCourseRow,
} from "./ChallengeCourseRow"
import { useQueryUserChallengeStrengthSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserChallengeStrengthSwr"
import { useQueryUserCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCoursesSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { StatRibbon } from "@/components/composites/stats/StatRibbon"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Props for {@link ProfileChallenges}. */
export type ProfileChallengesProps = Record<string, never>
/**
 * Challenges tab — the profile owner's graded-challenge proof of work. Leads with
 * a passed count + a 4-tone difficulty {@link SegmentBar} (easy→green /
 * medium→yellow / hard→red / insane→purple), then the submission list rendered as
 * Projects-tab-style rows: one collapsible {@link ChallengeCourseRow} per course
 * (its own difficulty bar + count), expanded on demand to reveal the repo links.
 * Self-contained: reads the username from the route, resolves it to the entity id,
 * and drives its own projection-backed SWR.
 *
 * @param props - optional className for the root element.
 */
export const ProfileChallenges = () => {
    const t = useTranslations()
    // route carries the username; resolve to the entity id the query keys off
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserSolvedChallengesSwr(userId)
    // difficulty-weighted challenge strength: global percentile + rank (null until passed)
    const { data: strength } = useQueryUserChallengeStrengthSwr(userId)
    // joined courses → total challenges per course (for the per-course progress bar)
    const { data: coursesData } = useQueryUserCoursesSwr(userId)
    const totalChallengesByCourse = new Map(
        (coursesData ?? []).map((course) => [course.label, course.challengeTotal]),
    )

    const challenges = data ?? []
    // difficulty distribution across all passed challenges (the headline bar)
    const difficultySegments = buildDifficultySegments(challenges)
    // language breadth: count per language, skipping rows with no language
    const langCounts = challenges.reduce<Record<string, number>>((acc, challenge) => {
        if (!challenge.selectedLang) {
            return acc
        }
        acc[challenge.selectedLang] = (acc[challenge.selectedLang] ?? 0) + 1
        return acc
    }, {})
    const langs = Object.entries(langCounts).sort((a, b) => b[1] - a[1])
    // submission list grouped by course (when the backend resolves titles)
    const groups = groupByCourse(challenges)

    // headline metric row (Coding-tab style): passed + XP + percentile + rank.
    // XP is the REAL ledger sum from the backend (NOT a FE sum of scores).
    const metricStats: Array<{ key: string; value: string }> = [
        { key: "passed", value: String(challenges.length) },
    ]
    if (strength?.xp != null) {
        metricStats.push({ key: "xp", value: String(strength.xp) })
    }
    if (strength?.percentile != null) {
        metricStats.push({ key: "percentile", value: `${strength.percentile}%` })
    }
    if (strength?.rank != null) {
        metricStats.push({ key: "rank", value: `#${strength.rank}` })
    }

    const rootClassNames: Array<AllowedClassName> = []


    return (
        <AsyncContent
            isLoading={(isLoading || !userId) && challenges.length === 0}
            skeleton={(
                <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => <Skeleton className="h-20 w-full rounded-2xl" />,
                            ]} />
                        ),
                        () => (
                            <SurfaceCardList
                                label={t("publicProfile.challengesTab.statsHeading")}
                                isSkeleton
                                items={[
                                    {
                                        key: "difficulty",
                                        content: () => <Skeleton.SegmentBar legendItems={4} />,
                                    },
                                    {
                                        key: "language",
                                        content: () => <Skeleton.SegmentBar legendItems={4} />,
                                    },
                                ]}
                            />
                        ),
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => (
                                    <SurfaceCardList
                                        isSkeleton
                                        items={[0, 1, 2].map((row) => ({
                                            key: `repo-skel-${row}`,
                                            content: () => (
                                                <StackH gap={4} principle="content-row" align="start"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                        () => (
                                                            <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                    () => <Skeleton.ProgressBar />,
                                                                    () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                                                ]} />
                                                        ),
                                                    ]} />
                                            ),
                                        }))}
                                    />
                                ),
                            ]} />
                        ),
                    ]} />
            )}
            isEmpty={challenges.length === 0}
            emptyContent={{
                title: t("publicProfile.challengesTab.empty"),
                description: t("publicProfile.challengesTab.emptyHint"),
            }}
            error={challenges.length === 0 ? error : undefined}
            errorContent={{
                title: t("publicProfile.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("publicProfile.loadErrorRetry"),
            }}
        >
            <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <LabeledCard label={t("publicProfile.challengesTab.metricsHeading")} frameless>
                            <StatRibbon
                                items={metricStats.map((stat) => ({
                                    key: stat.key,
                                    value: stat.value,
                                    label: t(`publicProfile.challengesTab.metric.${stat.key}`),
                                }))}
                            />
                        </LabeledCard>
                    ),
                    () => {
                        const statsItems: Array<SurfaceCardListItem> = [
                            ...(difficultySegments.length > 0
                                ? [{
                                    key: "difficulty",
                                    content: () => (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Label>{t("publicProfile.challengesTab.difficultyHeading")}</Label>,
                                                () => (
                                                    <SegmentBar
                                                        ariaLabel={t("publicProfile.challengesTab.difficultyHeading")}
                                                        segments={difficultySegments}
                                                    />
                                                ),
                                            ]} />
                                    ),
                                } satisfies SurfaceCardListItem]
                                : []),
                            ...(langs.length > 0
                                ? [{
                                    key: "language",
                                    content: () => (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Label>{t("publicProfile.challengesTab.languageHeading")}</Label>,
                                                () => (
                                                    <SegmentBar
                                                        ariaLabel={t("publicProfile.challengesTab.languageHeading")}
                                                        segments={langs.map(([lang, count]) => ({
                                                            key: lang,
                                                            label: getLanguageLabel(lang),
                                                            value: count,
                                                            color: getLanguageColor(lang),
                                                        }))}
                                                    />
                                                ),
                                            ]} />
                                    ),
                                } satisfies SurfaceCardListItem]
                                : []),
                        ]
                        return (
                            <SurfaceCardList
                                label={t("publicProfile.challengesTab.statsHeading")}
                                items={statsItems}
                            />
                        )
                    },
                    () => (
                        <LabeledCard
                            label={t("publicProfile.challengesTab.repoHeading")}
                            frameless
                        >
                            <SurfaceListCard>
                                {groups.map((group, groupIndex) => (
                                    <ChallengeCourseRow
                                        key={group.courseTitle ?? `__ungrouped-${groupIndex}`}
                                        username={username}
                                        courseTitle={group.courseTitle}
                                        courseSlug={group.courseSlug}
                                        items={group.items}
                                        totalChallenges={group.courseTitle
                                            ? totalChallengesByCourse.get(group.courseTitle)
                                            : undefined}
                                    />
                                ))}
                            </SurfaceListCard>
                        </LabeledCard>
                    ),
                ]} />
        </AsyncContent>
    )
}

