"use client"

import React from "react"
import {
    Typography,
} from "@heroui/react"
import {
    useParams,
    useRouter,
} from "next/navigation"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    CODING_DIFFICULTY_CHIP,
} from "@/modules/utils/coding-difficulty"
import { pathConfig } from "@/resources/path"
import { dayjs } from "@/modules/dayjs"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserCodingProblemDetailSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingProblemDetailSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { LanguageChip } from "@/components/blocks/chips/LanguageChip"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { Cluster } from "@/components/frames/Cluster"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"

/** Props for {@link ProfileCodingProblemPage}. */
export type ProfileCodingProblemPageProps = Record<string, never>
/**
 * `/profile/<u>/skills/<slug>` — the DETAIL tier of the skills (coding) flow: one
 * coding problem's statement (same read as the practice catalog, no ownership
 * check) plus the profile owner's accepted-submission summary for it — languages
 * used, verdict, passed/total testcases, first-solved date — or an empty note when
 * the owner hasn't solved it yet. Deliberately never shows source code (the BE
 * doesn't return it here). Self-contained: reads the username + slug from the
 * route, resolves the username to the entity id, and drives its own SWR.
 *
 * @param props - optional className for the root element.
 */
export const ProfileCodingProblemPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const params = useParams<{ slug: string }>()
    const slug = params?.slug ? String(params.slug) : null

    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data: detail,
        isLoading,
        error,
        mutate,
    } = useQueryUserCodingProblemDetailSwr(userId, slug)

    const problem = detail?.problem
    const submission = detail?.submission ?? null
    const difficulty = problem ? CODING_DIFFICULTY_CHIP[problem.difficulty] : undefined
    const solvedAt = submission?.firstSolvedAt
        ? dayjs(submission.firstSolvedAt).locale(locale).format("hh:mm MMMM DD, YYYY")
        : undefined

    const rootClassNames: Array<AllowedClassName> = []

    return (
        <Container identity={{ tier: "page", component: "ProfileCodingProblemPage" }} size="lg" padding={1} classNames={rootClassNames} body={() => (
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <PageHeader
                            breadcrumb={(
                                <BackLink
                                    target={t("publicProfile.coding.history")}
                                    onPress={() => router.push(pathConfig().locale(locale).profile(username ?? undefined).skills().build())}
                                />
                            )}
                            title={problem?.title ?? t("publicProfile.coding.detail.title")}
                            meta={problem ? (
                                <Cluster gap={3} principle="chip-row"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    items={[
                                        ...(difficulty
                                            ? [() => (
                                                <StatusChip tone={difficulty.tone}>
                                                    {t(difficulty.labelKey)}
                                                </StatusChip>
                                            )]
                                            : []),
                                        () => (
                                            <StatusChip tone="neutral">
                                                {t(`codingPractice.domain.${problem.domain}`)}
                                            </StatusChip>
                                        ),
                                    ]} />
                            ) : undefined}
                        />
                    ),
                    () => (
                        <AsyncContent
                            isLoading={isLoading && !detail}
                            skeleton={(
                                <StackV gap={6} principle="block-boundary"
                                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                    items={[
                                        () => <Skeleton className="h-6 w-1/2" />,
                                        () => <Skeleton className="h-40 w-full rounded-2xl" />,
                                        () => (
                                            <SurfaceCardList
                                                isSkeleton
                                                items={[0, 1, 2].map((row) => ({
                                                    key: `submission-skel-${row}`,
                                                    content: () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                                }))}
                                            />
                                        ),
                                    ]} />
                            )}
                            isEmpty={!problem}
                            emptyContent={{
                                title: t("publicProfile.coding.detail.notFound"),
                            }}
                            error={!problem ? error : undefined}
                            errorContent={{
                                title: t("publicProfile.loadError"),
                                onRetry: () => { void mutate() },
                                retryLabel: t("publicProfile.loadErrorRetry"),
                            }}
                        >
                            {problem ? (
                                <StackV gap={6} principle="block-boundary"
                                    explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                    items={[
                                        () => (
                                            <LabeledCard label={t("publicProfile.coding.detail.statementHeading")} frameless>
                                                <MarkdownContent markdown={problem.statement ?? ""} />
                                            </LabeledCard>
                                        ),
                                        ...(problem.tags.length > 0
                                            ? [() => (
                                                <Cluster gap={3} principle="chip-row"
                                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                    items={
                                                        problem.tags.map((tag) => (
                                                            () => (
                                                                <StatusChip key={tag} tone="neutral">
                                                                    {tag}
                                                                </StatusChip>
                                                            )
                                                        ))
                                                    } />
                                            )]
                                            : []),
                                        () => {
                                            const submissionItems: Array<SurfaceCardListItem> = submission
                                                ? [
                                                    {
                                                        key: "languages-verdict",
                                                        content: () => (
                                                            <Cluster gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                justify="between" items={[
                                                                    () => (
                                                                        <Cluster gap={3} principle="chip-row"
                                                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                                            items={
                                                                                submission.languages.map((language) => (
                                                                                    () => <LanguageChip key={language} language={language} />
                                                                                ))
                                                                            } />
                                                                    ),
                                                                    () => (
                                                                        <StatusChip tone="success">
                                                                            {t(`codingPractice.verdict.${submission.verdict}`)}
                                                                        </StatusChip>
                                                                    ),
                                                                ]} />
                                                        ),
                                                    },
                                                    {
                                                        key: "passed-date",
                                                        content: () => (
                                                            <StackH gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                justify="between" items={[
                                                                    () => (
                                                                        <Typography type="body-sm" color="muted">
                                                                            {t("publicProfile.coding.detail.passedOf", {
                                                                                passed: submission.passedCount,
                                                                                total: submission.totalCount,
                                                                            })}
                                                                        </Typography>
                                                                    ),
                                                                    ...(solvedAt
                                                                        ? [() => (
                                                                            <Typography type="body-xs" color="muted">
                                                                                {solvedAt}
                                                                            </Typography>
                                                                        )]
                                                                        : []),
                                                                ]} />
                                                        ),
                                                    },
                                                ]
                                                : []
                                            return (
                                                <SurfaceCardList
                                                    label={t("publicProfile.coding.detail.submissionHeading")}
                                                    emptyState={() => (
                                                        <Typography type="body-sm" color="muted">
                                                            {t("publicProfile.coding.detail.notSolved")}
                                                        </Typography>
                                                    )}
                                                    items={submissionItems}
                                                />
                                            )
                                        },
                                    ]} />
                            ) : null}
                        </AsyncContent>
                    ),
                ]} />
        )} />
    )
}

"use client"

import React from "react"
import { Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { buildDifficultySegments } from "@/modules/utils/challenge-difficulty"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengesSwr"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { StatPair } from "@/components/composites/stats/StatPair"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import type { SkeletonProps } from "@/components/frames/_slot"
import { StackV } from "@/components/frames/Stack"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Props for {@link OverviewChallengeSkills}. */
export interface OverviewChallengeSkillsProps {
    /** Section label, rendered outside the card (owned here, like every other self-contained section). */
    label: string
    /** Optional "see more" link on the label row. */
    onSeeMore?: () => void
    /** Text for the see-more link. */
    seeMoreLabel?: string
    /** Stretch the section (and its card) to fill the row's height. */
    fillHeight?: boolean
}

/**
 * Overview snapshot — skills proven by graded CHALLENGES, mirroring the "Skills
 * via Practice" card: a passed-count headline, the 4-tone DIFFICULTY
 * {@link SegmentBar}, then a language {@link SegmentBar} (brand legend, same as the
 * Challenges tab). A teaser only — the full submission list lives behind "See
 * more" in the Challenges tab. One labeled {@link SurfaceCardList} owns the
 * section header, empty/error, and `isSkeleton` (B37 class C collapse — no outer
 * `LabeledCard` frameless shell).
 *
 * @param props - {@link OverviewChallengeSkillsProps}
 */
export const OverviewChallengeSkills = ({ label, onSeeMore, seeMoreLabel, fillHeight }: OverviewChallengeSkillsProps) => {
    const t = useTranslations()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const { data, isLoading, error, mutate } = useQueryUserSolvedChallengesSwr(userId)

    const challenges = data ?? []
    // difficulty distribution across all passed challenges
    const difficultySegments = buildDifficultySegments(challenges)
    // language breadth: count per language, skipping rows with no language (V1-legacy)
    const langCounts = challenges.reduce<Record<string, number>>((acc, challenge) => {
        if (!challenge.selectedLang) {
            return acc
        }
        acc[challenge.selectedLang] = (acc[challenge.selectedLang] ?? 0) + 1
        return acc
    }, {})
    const langs = Object.entries(langCounts).sort((a, b) => b[1] - a[1])
    const isFirstLoad = (isLoading || !userId) && challenges.length === 0
    const showError = challenges.length === 0 && Boolean(error)

    const snapshotItems: Array<SurfaceCardListItem> = [{
        key: "snapshot",
        content: ({ isSkeleton: rowSkeleton }: SkeletonProps) => {
            const shimmer = rowSkeleton ?? isFirstLoad
            return (
                <StackV gap={4} items={[
                    () => (
                        shimmer
                            ? <StatPair isSkeleton />
                            : (
                                <StatPair
                                    value={String(challenges.length)}
                                    label={t("publicProfile.challengesCount")}
                                />
                            )
                    ),
                    ...(shimmer || difficultySegments.length > 0
                        ? [() => (
                            shimmer
                                ? (
                                    <SegmentBar
                                        isSkeleton
                                        ariaLabel={`${challenges.length} ${t("publicProfile.challengesCount")}`}
                                    />
                                )
                                : (
                                    <SegmentBar
                                        ariaLabel={`${challenges.length} ${t("publicProfile.challengesCount")}`}
                                        segments={difficultySegments}
                                    />
                                )
                        )]
                        : []),
                    ...(shimmer || langs.length > 0
                        ? [() => (
                            <StackV gap={3} principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => (
                                        <Typography type="body-xs" color="muted">
                                            {t("publicProfile.skillsSnapshot.languagesLabel")}
                                        </Typography>
                                    ),
                                    () => (
                                        shimmer
                                            ? (
                                                <SegmentBar
                                                    isSkeleton
                                                    ariaLabel={t("publicProfile.skillsSnapshot.languagesLabel")}
                                                />
                                            )
                                            : (
                                                <SegmentBar
                                                    ariaLabel={t("publicProfile.skillsSnapshot.languagesLabel")}
                                                    segments={langs.map(([lang, count]) => ({
                                                        key: lang,
                                                        label: getLanguageLabel(lang),
                                                        value: count,
                                                        color: getLanguageColor(lang),
                                                    }))}
                                                />
                                            )
                                    ),
                                ]} />
                        )]
                        : []),
                ]} />
            )
        },
    }]

    return (
        <SurfaceCardList
            label={label}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
            fillHeight={fillHeight}
            isSkeleton={isFirstLoad}
            error={showError ? error : undefined}
            errorState={() => (
                <AsyncContentError
                    title={t("publicProfile.loadError")}
                    onRetry={() => { void mutate() }}
                    retryLabel={t("publicProfile.loadErrorRetry")}
                />
            )}
            emptyState={() => (
                <AsyncContentEmpty title={t("publicProfile.skills.empty")} />
            )}
            items={isFirstLoad || challenges.length > 0 ? snapshotItems : []}
        />
    )
}

"use client"

import React from "react"
import { Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { useQueryUserCodingSkillsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingSkillsSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { StatPair } from "@/components/composites/stats/StatPair"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import type { SkeletonProps } from "@/components/frames/_slot"
import { StackV } from "@/components/frames/Stack"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Props for {@link OverviewCodeSkills}. */
export interface OverviewCodeSkillsProps {
    /** Section label, rendered outside the card (owned here, like every other self-contained section). */
    label: string
    /** Optional "see more" link on the label row. */
    onSeeMore?: () => void
    /** Text for the see-more link. */
    seeMoreLabel?: string
    /** Stretch the section (and its card) to fill the row's height. */
    fillHeight?: boolean
}

/** Capitalize the first character of a key for display. */
const capitalizeKey = (key: string): string =>
    key.charAt(0).toUpperCase() + key.slice(1)

/** Slice colour per difficulty bucket (semantic). */
const DIFF_COLOR: Record<string, string> = {
    easy: "var(--success)",
    medium: "var(--warning)",
    hard: "var(--danger)",
}

/**
 * Overview content — skills proven by solving CODE PROBLEMS (the practice judge):
 * total solved + difficulty depth chips + top-language chips with real counts.
 * One labeled {@link SurfaceCardList} owns the section header, empty/error, and
 * `isSkeleton` (B37 class C collapse — no outer `LabeledCard` frameless shell).
 * Counts are real, never relative-to-max, so 2 solves never looks like mastery.
 *
 * @param props - {@link OverviewCodeSkillsProps}
 */
export const OverviewCodeSkills = ({ label, onSeeMore, seeMoreLabel, fillHeight }: OverviewCodeSkillsProps) => {
    const t = useTranslations()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const { data, isLoading, error, mutate } = useQueryUserCodingSkillsSwr(userId)

    const byLanguage = data?.byLanguage ?? []
    const byDifficulty = data?.byDifficulty ?? []
    const totalSolved = byDifficulty.reduce((acc, d) => acc + d.solved, 0)
        || byLanguage.reduce((acc, l) => acc + l.solved, 0)
    const orderedLanguages = [...byLanguage].sort((a, b) => b.solved - a.solved)
    const isFirstLoad = (isLoading || !userId) && totalSolved === 0 && !data
    const showError = !data && error

    /** Localized label for a difficulty bucket; falls back to the capitalized key. */
    const diffLabel = (key: string): string => {
        const labels: Record<string, string> = {
            easy: t("publicProfile.skillsSnapshot.diffEasy"),
            medium: t("publicProfile.skillsSnapshot.diffMedium"),
            hard: t("publicProfile.skillsSnapshot.diffHard"),
        }
        return labels[key] ?? capitalizeKey(key)
    }

    const snapshotItems: Array<SurfaceCardListItem> = [{
        key: "snapshot",
        content: ({ isSkeleton: rowSkeleton }: SkeletonProps) => {
            const shimmer = rowSkeleton ?? isFirstLoad
            return (
                <StackV gap={4} items={[
                    () => (
                        shimmer
                            ? <StatPair isSkeleton />
                            : (
                                <StatPair
                                    value={String(totalSolved)}
                                    label={t("publicProfile.skillsSnapshot.solvedLabel")}
                                />
                            )
                    ),
                    () => (
                        shimmer
                            ? (
                                <SegmentBar
                                    isSkeleton
                                    ariaLabel={`${totalSolved} ${t("publicProfile.skillsSnapshot.solvedLabel")}`}
                                />
                            )
                            : (
                                <SegmentBar
                                    ariaLabel={`${totalSolved} ${t("publicProfile.skillsSnapshot.solvedLabel")}`}
                                    segments={byDifficulty.map((d) => ({
                                        key: d.key,
                                        label: diffLabel(d.key),
                                        value: d.solved,
                                        color: DIFF_COLOR[d.key],
                                    }))}
                                />
                            )
                    ),
                    ...(shimmer || orderedLanguages.length > 0
                        ? [() => (
                            <StackV gap={3} principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => (
                                        <Typography type="body-xs" color="muted">
                                            {t("publicProfile.skillsSnapshot.languagesLabel")}
                                        </Typography>
                                    ),
                                    () => (
                                        shimmer
                                            ? (
                                                <SegmentBar
                                                    isSkeleton
                                                    ariaLabel={t("publicProfile.skillsSnapshot.languagesLabel")}
                                                />
                                            )
                                            : (
                                                <SegmentBar
                                                    ariaLabel={t("publicProfile.skillsSnapshot.languagesLabel")}
                                                    segments={orderedLanguages.map((lang) => ({
                                                        key: lang.key,
                                                        label: getLanguageLabel(lang.key),
                                                        value: lang.solved,
                                                        color: getLanguageColor(lang.key),
                                                    }))}
                                                />
                                            )
                                    ),
                                ]} />
                        )]
                        : []),
                ]} />
            )
        },
    }]

    return (
        <SurfaceCardList
            label={label}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
            fillHeight={fillHeight}
            isSkeleton={isFirstLoad}
            error={showError ? error : undefined}
            errorState={() => (
                <AsyncContentError
                    title={t("publicProfile.loadError")}
                    onRetry={() => { void mutate() }}
                    retryLabel={t("publicProfile.loadErrorRetry")}
                />
            )}
            emptyState={() => (
                <AsyncContentEmpty
                    title={t("publicProfile.skills.empty")}
                    description={t("publicProfile.skills.emptyHint")}
                />
            )}
            items={isFirstLoad || totalSolved > 0 ? snapshotItems : []}
        />
    )
}

"use client"

import React, { useState } from "react"
import { FlameIcon as FireIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { ContributionCalendarView } from "@/components/blocks/profile/ContributionCalendarView"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { useQueryUserContributionCalendarSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserContributionCalendarSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserWeeklyStatsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserWeeklyStatsSwr"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Overview content — the contribution heatmap (GitHub-style) + the streak line
 * (current / longest). Content only (no card): the parent `LabeledCard` supplies
 * the frame.
 *
 * The calendar owns its own resting state, so there is no placeholder copy of its
 * shape here — only the streak line, which belongs to this block, shimmers on its
 * own (`loading-and-skeleton.md`).
 */
export const OverviewContributions = () => {
    const t = useTranslations()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null

    const [year, setYear] = useState(() => new Date().getFullYear())
    const { data, isLoading, error, mutate } = useQueryUserContributionCalendarSwr(userId, year)
    const { data: weekly } = useQueryUserWeeklyStatsSwr(userId)

    const days = data ?? []
    // first load, nothing in hand: no user resolved yet, or the calendar still in flight
    const isSkeleton = (isLoading || !userId) && days.length === 0

    // error beats a stale loading flag — but only a settled failure with nothing cached.
    if (error && days.length === 0) {
        return (
            <AsyncContentError
                title={t("publicProfile.loadError")}
                onRetry={() => { void mutate() }}
                retryLabel={t("publicProfile.loadErrorRetry")}
            />
        )
    }

    // Hoist streak items so the outer calendar|streak column is scanned as
    // gap-only (no nested align/principle leaking into the opening tag).
    const streakItems = [
        () => (
            <FireIcon
                aria-hidden
                focusable="false"
                className="size-5 text-accent-soft-foreground"
            />
        ),
        () => (
            <Typography
                size="sm"
                weight="medium"
                isSkeleton={isSkeleton}
                text={t("profile.streakLine", {
                    streak: weekly?.streak ?? 0,
                    longest: weekly?.longestStreak ?? 0,
                })}
            />
        ),
    ]

    return (
        <StackV
            identity={{ tier: "block", component: "OverviewContributions" }}
            gap={4}
            principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => (
                    <ContributionCalendarView
                        isSkeleton={isSkeleton}
                        days={days}
                        year={year}
                        onYearChange={setYear}
                    />
                ),
                // gap-only row: icon+text at house step 3 (8px); icon-text is step 2
                () => <StackH gap={3} items={streakItems} />,
            ]}
        />
    )
}

"use client"

import React from "react"
import { BookOpenIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useResolveRouteNavigation } from "@/components/blocks/entity/EntityToken/useResolveRouteNavigation"
import { CourseTrialChip } from "@/components/blocks/course/CourseTrialChip"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { CourseProgressBar } from "@/components/blocks/stats/CourseProgressBar"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import type { useQueryUserCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCoursesSwr"

/** One profile course-progress item (element of the `useQueryUserCoursesSwr` list). */
type CourseItem = NonNullable<ReturnType<typeof useQueryUserCoursesSwr>["data"]>[number]

/** Props for {@link CourseRow}. */
export interface CourseRowProps {
    /** One profile course-progress item. Absent only while {@link CourseRowProps.isSkeleton}. */
    item?: CourseItem
    /** Only the profile OWNER sees the "Trial" chip. */
    isOwnProfile?: boolean
    /**
     * First load, nothing in hand → this row shimmers in place. The resting state lives
     * HERE, beside the loaded one, so the two shapes cannot drift the way a placeholder
     * hand-kept in the list would (`loading-and-skeleton.md`).
     */
    isSkeleton?: boolean
}

/**
 * One profile course as a WHOLE-ROW clickable surface-list item — mirrors the
 * dashboard `MyCoursesProgress` CourseRow. Pressing anywhere resolves the course
 * route and navigates ({@link useResolveRouteNavigation} per row); the title
 * underlines on CARD hover with a foreground decoration — NOT a nested
 * `EntityToken`/`<Link>` (which hovers only on the label + draws an accent underline).
 *
 * @param props - {@link CourseRowProps}
 */
export const CourseRow = ({ item, isOwnProfile = false, isSkeleton = false }: CourseRowProps) => {
    const t = useTranslations()
    const { onPress, pending, routable } = useResolveRouteNavigation({ globalId: item?.globalId ?? "" })

    const dims = [
        { key: "content", completed: item?.contentCompleted ?? 0, total: item?.contentTotal ?? 0 },
        { key: "challenge", completed: item?.challengeCompleted ?? 0, total: item?.challengeTotal ?? 0 },
        { key: "milestone", completed: item?.completed ?? 0, total: item?.total ?? 0 },
    ]
    const totalTasks = dims.reduce((acc, d) => acc + d.total, 0)
    const doneTasks = dims.reduce((acc, d) => acc + d.completed, 0)
    const percent = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0

    const resting = isSkeleton || !item

    return (
        <SurfaceListCardItem
            onPress={resting ? undefined : onPress}
            isDisabled={resting || !routable || pending}
            hover="underline"
        >
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (resting
                        ? <Skeleton className="size-12 shrink-0 rounded-xl" />
                        : <IconTile size="sm" src={item.thumbnailUrl} icon={<BookOpenIcon aria-hidden focusable="false" />} />),
                    () => {
                        const titleRowItems = [
                            () => (
                                <Typography
                                    size="sm"
                                    weight="medium"
                                    truncate
                                    underlineOnGroupHover
                                    isSkeleton={resting}
                                    classNames={resting ? ["w-1/2"] : ["min-w-0", "flex-1"]}
                                    text={item?.label}
                                />
                            ),
                            ...(!resting && isOwnProfile
                                ? [() => <CourseTrialChip isEnrolled={item.isEnrolled} />]
                                : []),
                            () => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    isSkeleton={resting}
                                    classNames={resting ? ["w-fit"] : undefined}
                                    text={`${percent}%`}
                                />
                            ),
                        ]
                        return (
                            <StackV
                                gap={3}
                                principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                classNames={["min-w-0", "flex-1"]}
                                items={[
                                    () => (
                                        <StackH
                                            gap={3}
                                            principle="flex-action"
                                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                            justify="between"
                                            items={titleRowItems}
                                        />
                                    ),
                                    () => (resting
                                        ? <Skeleton.ProgressBar />
                                        : (
                                            <CourseProgressBar
                                                ariaLabel={`${item.label} · ${percent}%`}
                                                dims={dims.map((d) => ({
                                                    ...d,
                                                    label: t(`dashboard.courseProgress.${d.key}`),
                                                }))}
                                            />
                                        )),
                                ]}
                            />
                        )
                    },
                ]}
            />
        </SurfaceListCardItem>
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { CourseRow } from "./CourseRow"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { useQueryUserCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCoursesSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"
import { useAppSelector } from "@/redux/hooks"

/** Placeholder course rows shown while the list loads. */
const SKELETON_ROWS = 2

/** Props for {@link OverviewCourses}. */
export interface OverviewCoursesProps {
    /** Section label, rendered outside the card (owned here, like every other self-contained section). */
    label: string
    /** Optional "see more" link on the label row. */
    onSeeMore?: () => void
    /** Text for the see-more link. */
    seeMoreLabel?: string
}

/**
 * Overview content — courses the profile owner has joined. Each course is one
 * compact row: a course icon, the title + overall completion %, and a single
 * segmented bar that folds the three dimensions (content / challenge / milestone)
 * into one honest progress bar (filled to the real total, coloured by dimension).
 *
 * Owns its own `LabeledCard`, with `frameless` computed HERE (not hardcoded) so the
 * list — self-framed as a `SurfaceListCard` — skips the outer card, while the empty
 * and error states, which have no bounded surface of their own, still get one. The
 * placeholder rows are the SAME `CourseRow` resting, inside the SAME list, so no
 * second description of the row exists (`loading-and-skeleton.md`).
 *
 * @param props - {@link OverviewCoursesProps}
 */
export const OverviewCourses = ({ label, onSeeMore, seeMoreLabel }: OverviewCoursesProps) => {
    const t = useTranslations()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    // only the profile OWNER sees the "Free trial" chip — don't broadcast "hasn't paid"
    // for a course on someone else's public profile.
    const viewerId = useAppSelector((state) => state.user.user?.id)
    const isOwnProfile = Boolean(viewerId) && viewerId === userId
    const { data, isLoading, error, mutate } = useQueryUserCoursesSwr(userId)

    const courses = data ?? []
    const isSkeleton = (isLoading || !userId) && courses.length === 0
    // the list frames itself; every other state needs the card's own surface
    const hasCourses = !isSkeleton && !error && courses.length > 0

    // error beats a stale loading flag; empty only once settled (BLOCK-8 order).
    const body = () => {
        if (error && courses.length === 0) {
            return (
                <AsyncContentError
                    title={t("publicProfile.loadError")}
                    onRetry={() => { void mutate() }}
                    retryLabel={t("publicProfile.loadErrorRetry")}
                />
            )
        }
        if (!isSkeleton && courses.length === 0) {
            return <AsyncContentEmpty title={t("publicProfile.coursesEmpty")} />
        }
        return (
            <SurfaceListCard>
                {isSkeleton
                    ? Array.from({ length: SKELETON_ROWS }, (_row, index) => (
                        <CourseRow key={index} isSkeleton />
                    ))
                    : courses.map((item) => (
                        <CourseRow key={item.globalId} item={item} isOwnProfile={isOwnProfile} />
                    ))}
            </SurfaceListCard>
        )
    }

    return (
        <LabeledCard
            identity={{ tier: "block", component: "OverviewCourses" }}
            label={label}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
            frameless={hasCourses || isSkeleton}
        >
            {body()}
        </LabeledCard>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    useParams,
    useRouter,
} from "next/navigation"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    CheckCircleIcon,
    CircleIcon,
    RocketIcon,
    SealCheckIcon,
} from "@phosphor-icons/react"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import { pathConfig } from "@/resources/path"
import { useQueryUserCapstoneProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCapstoneProgressSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Score → attention colour the eye catches fast: high green, mid yellow, low red.
 * @param score - the graded score (0–100).
 * @returns a `text-{token}` class for the score label.
 */
const scoreToneClass = (score: number): string => {
    if (score >= 90) {
        return "text-success-soft-foreground"
    }
    if (score >= 70) {
        return "text-warning-soft-foreground"
    }
    return "text-danger-soft-foreground"
}

/** Props for {@link ProfileProjectRoadmapPage}. */
export type ProfileProjectRoadmapPageProps = Record<string, never>
/**
 * `/profile/<u>/projects/<courseGlobalId>` — the DETAIL tier of the projects
 * flow: the FULL milestone/task roadmap of ONE capstone course, no inline
 * expand cap (unlike the list's compact {@link import("../ProfileCapstone/ProjectCard").ProjectCard}
 * row). Reads the course id from the route, then filters the profile owner's
 * full `userCapstoneProgress` list down to it client-side — the same data the
 * list already fetched, per the BE recommendation (no dedicated detail query).
 *
 * @param props - optional className for the root element.
 */
export const ProfileProjectRoadmapPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const username = useProfileUsername()
    const params = useParams<{ courseId: string }>()
    const courseGlobalId = params?.courseId ? String(params.courseId) : null

    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data: projectsData,
        isLoading,
        error: projectsError,
        mutate: reloadProjects,
    } = useQueryUserCapstoneProgressSwr(userId)

    const projects = projectsData ?? []
    // scope down to THIS course only — the detail page's whole reason to exist
    const project = useMemo(
        () => projects.find((item) => item.courseGlobalId === courseGlobalId) ?? null,
        [projects, courseGlobalId],
    )

    // milestones ordered along the roadmap (defensive copy before sort)
    const milestones = useMemo(
        () => [...(project?.milestones ?? [])].sort((a, b) => a.position - b.position),
        [project],
    )

    const totalTasks = Math.max(project?.totalTasks ?? 0, 1)
    const percent = Math.round(((project?.completedTasks ?? 0) / totalTasks) * 100)
    const hasVerified = (project?.completedTasks ?? 0) > 0

    const resolvedLoading = (isLoading || !userId) && !projectsData
    // resolved (not loading, no error) but no match → "not found" empty state
    const notFound = !resolvedLoading && !projectsError && !project

    return (
        <div className={"mx-auto flex max-w-4xl flex-col gap-6"}>
            <PageHeader
                breadcrumb={(
                    <BackLink
                        target={t("publicProfile.capstone.roadmapBackToProjects")}
                        onPress={() => router.push(pathConfig().locale(locale).profile(username ?? undefined).projects().build())}
                    />
                )}
                title={project?.courseTitle ?? t("publicProfile.capstone.roadmapTitle")}
                meta={project ? (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={[
                            () => (
                                <StackH gap={3} principle="chip-row" align="center"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    items={[
                                        ...(hasVerified ? [() => (
                                            <StatusChip
                                                tone="success"
                                                icon={SealCheckIcon}
                                            >
                                                {t("pinnedProjects.verified")}
                                            </StatusChip>
                                        )] : []),
                                        () => (
                                            <Typography type="body-xs" color="muted">
                                                {t("publicProfile.capstone.roadmapSummary", {
                                                    completedMilestones: project.completedMilestones,
                                                    totalMilestones: project.totalMilestones,
                                                    completedTasks: project.completedTasks,
                                                    totalTasks: project.totalTasks,
                                                })}
                                            </Typography>
                                        ),
                                    ]} />
                            ),
                            () => (
                                <SegmentBar
                                    hideLegend
                                    max={totalTasks}
                                    ariaLabel={`${project.courseTitle} · ${percent}%`}
                                    segments={[
                                        {
                                            key: "verified",
                                            label: t("publicProfile.capstone.projectsHeading"),
                                            value: project.completedTasks,
                                            color: "var(--success)",
                                        },
                                    ]}
                                />
                            ),
                        ]} />
                ) : undefined}
            />

            <AsyncContent
                isLoading={resolvedLoading}
                skeleton={(
                    <SurfaceListCard>
                        {[0, 1].map((row) => (
                            <SurfaceListCardItem key={row}>
                                <StackH gap={4} principle="content-row" align="start"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={[
                                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                        () => (
                                            <StackV gap={4} principle="label-field" classNames={["min-w-0", "flex-1"]}
                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                items={[
                                                    () => <Skeleton.Typography type="body-sm" width="1/3" />,
                                                    () => <Skeleton.ProgressBar />,
                                                    () => <Skeleton.Typography type="body-xs" width="2/3" />,
                                                    () => (
                                                        <StackV gap={1} principle="name-handle"
                                                            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                            items={
                                                                [0, 1].map((task) => () => (
                                                                    <StackH key={task} gap={4} principle="content-row" align="center"
                                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                        items={[
                                                                            () => <Skeleton className="size-5 shrink-0 rounded-full" />,
                                                                            () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                        ]} />
                                                                ))
                                                            } />
                                                    ),
                                                ]} />
                                        ),
                                    ]} />
                            </SurfaceListCardItem>
                        ))}
                    </SurfaceListCard>
                )}
                isEmpty={notFound || (Boolean(project) && milestones.length === 0)}
                emptyContent={notFound
                    ? {
                        title: t("publicProfile.capstone.roadmapNotFound"),
                        description: t("publicProfile.capstone.roadmapNotFoundHint"),
                    }
                    : {
                        title: t("publicProfile.capstone.roadmapEmpty"),
                    }}
                error={projectsError}
                errorContent={{
                    title: t("publicProfile.capstone.loadErrorTitle"),
                    description: t("publicProfile.capstone.loadErrorDescription"),
                    onRetry: () => {
                        void reloadProjects()
                    },
                    retryLabel: t("publicProfile.capstone.loadErrorRetry"),
                }}
            >
                <SurfaceListCard>
                    {milestones.map((milestone, milestoneIndex) => (
                        <SurfaceListCardItem key={milestone.milestoneGlobalId ?? `${milestone.title}-${milestoneIndex}`}>
                            <StackH gap={4} principle="content-row" align="start"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                items={[
                                    () => (
                                        <IconTile
                                            size="sm"
                                            icon={<RocketIcon aria-hidden focusable="false" />}
                                        />
                                    ),
                                    () => (
                                        <StackV gap={4} principle="label-field" classNames={["min-w-0", "flex-1"]}
                                            explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                            items={[
                                                () => (
                                                    <ProgressMeter
                                                        label={milestone.title}
                                                        value={milestone.passedTasks}
                                                        max={Math.max(milestone.totalTasks, 1)}
                                                        showValue
                                                    />
                                                ),
                                                () => (
                                                    <Typography type="body-xs" color="muted">
                                                        {t("publicProfile.capstone.roadmapMilestoneProgress", {
                                                            completed: milestone.passedTasks,
                                                            total: milestone.totalTasks,
                                                        })}
                                                    </Typography>
                                                ),
                                                () => (
                                                    <StackV gap={1} principle="name-handle"
                                                        explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                        items={
                                                            milestone.tasks.map((task, taskIndex) => () => (
                                                                <div
                                                                    key={task.taskGlobalId ?? `${task.title}-${taskIndex}`}
                                                                    className={cn(
                                                                        taskIndex < milestone.tasks.length - 1 && "border-b border-default",
                                                                    )}
                                                                >
                                                                    <StackH
                                                                        gap={4}
                                                                        principle="content-row"
                                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                        align="center"
                                                                        items={[
                                                                            () => (
                                                                                task.passed ? (
                                                                                    <CheckCircleIcon aria-hidden focusable="false" className="size-5 shrink-0 text-success-soft-foreground" />
                                                                                ) : (
                                                                                    <CircleIcon aria-hidden focusable="false" className="size-5 shrink-0 text-muted-foreground" />
                                                                                )
                                                                            ),
                                                                            () => (
                                                                                <Typography
                                                                                    type="body-sm"
                                                                                    className={cn("min-w-0 flex-1 truncate", task.passed && "text-success-soft-foreground")}
                                                                                >
                                                                                    {task.title}
                                                                                </Typography>
                                                                            ),
                                                                            ...(task.passed ? [() => (
                                                                                <StackH gap={2} principle="separator-dot" classNames={["shrink-0"]}
                                                                                    explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                                                                                    items={[
                                                                                        () => (
                                                                                            <Typography
                                                                                                type="body-xs"
                                                                                                weight="medium"
                                                                                                className={scoreToneClass(task.score)}
                                                                                            >
                                                                                                {t("publicProfile.capstone.score", { score: task.score })}
                                                                                            </Typography>
                                                                                        ),
                                                                                        ...(task.passedAt ? [() => {
                                                                                            const passedAt = task.passedAt as string | number | Date
                                                                                            return (
                                                                                                <Typography type="body-xs" color="muted">
                                                                                                    {` · ${new Date(passedAt).toLocaleDateString(locale)}`}
                                                                                                </Typography>
                                                                                            )
                                                                                        }] : []),
                                                                                    ]} />
                                                                            )] : []),
                                                                        ]}
                                                                    />
                                                                </div>
                                                            ))
                                                        } />
                                                ),
                                            ]} />
                                    ),
                                ]} />
                        </SurfaceListCardItem>
                    ))}
                </SurfaceListCard>
            </AsyncContent>
        </div>
    )
}

"use client"

import React from "react"
import {
    useTranslations,
} from "next-intl"
import {
    RocketIcon,
    SealCheckIcon,
} from "@phosphor-icons/react"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Typography } from "@/components/atoms/text/Typography"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import type { QueryUserCapstoneCourseProgress } from "@/modules/api/graphql/queries/types/user-capstone-progress"

/** Props for {@link ProjectCard}. */
export interface ProjectCardProps {
    /** The single course capstone progress to showcase. Absent only while {@link ProjectCardProps.isSkeleton}. */
    project?: QueryUserCapstoneCourseProgress
    /**
     * First load, nothing in hand → this row shimmers in place. The resting state lives
     * HERE, beside the loaded one, so the two shapes cannot drift the way a placeholder
     * hand-kept in the list would (`loading-and-skeleton.md`).
     */
    isSkeleton?: boolean
}

/**
 * One personal-project capstone, rendered as a compact ROW (not a nested card —
 * the section's `LabeledCard` is the frame). Layout: a framed rocket
 * {@link IconTile}, the course title with a green "✓ Verified by StarCi" chip +
 * overall percent, a single honest {@link SegmentBar} whose green fill =
 * graded/verified tasks out of all tasks, and a milestone/task summary line.
 * Green (`success`) means "verified" throughout, per the profile spec.
 *
 * Purely presentational glance content — the parent
 * {@link import("../index").ProfileCapstone} wraps this in a `SurfaceListCardItem`
 * that is itself the nav LINK to `/profile/<u>/projects/<courseGlobalId>`,
 * `hover="underline"` — the title underlines on hover as the row's own go-there
 * affordance (row-as-link; ref `hover-style-matches-clickable-nature`).
 *
 * @param props - {@link ProjectCardProps}
 */
export const ProjectCard = ({
    project,
    isSkeleton = false,
}: ProjectCardProps) => {
    const t = useTranslations()

    const resting = isSkeleton || !project
    const totalTasks = Math.max(project?.totalTasks ?? 1, 1)
    const percent = Math.round(((project?.completedTasks ?? 0) / totalTasks) * 100)
    const hasVerified = (project?.completedTasks ?? 0) > 0

    return (
        <StackH identity={{ tier: "page", component: "ProjectCard" }}
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start"
            items={[
                () => (resting
                    ? <Skeleton className="size-12 shrink-0 rounded-xl" />
                    : <IconTile size="sm" icon={<RocketIcon aria-hidden focusable="false" />} />),
                () => (
                    <StackV
                        gap={3}
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        classNames={["min-w-0", "flex-1"]}
                        items={[
                            () => (
                                <StackH
                                    gap={3}
                                    principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    align="start"
                                    justify="between"
                                    items={[
                                        () => (
                                            <Cluster
                                                gap={3}
                                                principle="chip-row"
                                                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                classNames={["min-w-0"]}
                                                items={[
                                                    () => (
                                                        <Typography
                                                            size="sm"
                                                            weight="medium"
                                                            truncate
                                                            underlineOnGroupHover
                                                            isSkeleton={resting}
                                                            classNames={resting ? ["w-1/2"] : undefined}
                                                            text={project?.courseTitle}
                                                        />
                                                    ),
                                                    ...(resting
                                                        ? [() => <Skeleton.Chip />]
                                                        : hasVerified
                                                            ? [() => (
                                                                <StatusChip
                                                                    tone="success"
                                                                    icon={SealCheckIcon}
                                                                >
                                                                    {t("pinnedProjects.verified")}
                                                                </StatusChip>
                                                            )]
                                                            : []),
                                                ]}
                                            />
                                        ),
                                        () => (
                                            <Typography
                                                size="xs"
                                                color="muted"
                                                isSkeleton={resting}
                                                classNames={resting ? ["w-fit"] : undefined}
                                                text={`${percent}%`}
                                            />
                                        ),
                                    ]}
                                />
                            ),
                            () => (resting
                                ? <Skeleton.ProgressBar />
                                : (
                                    <SegmentBar
                                        hideLegend
                                        max={totalTasks}
                                        ariaLabel={`${project.courseTitle} · ${percent}%`}
                                        segments={[
                                            {
                                                key: "verified",
                                                label: t("publicProfile.capstone.projectsHeading"),
                                                value: project.completedTasks,
                                                color: "var(--success)",
                                            },
                                        ]}
                                    />
                                )),
                            () => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    isSkeleton={resting}
                                    classNames={resting ? ["w-2/3"] : undefined}
                                    text={project
                                        ? t("publicProfile.capstone.roadmapSummary", {
                                            completedMilestones: project.completedMilestones,
                                            totalMilestones: project.totalMilestones,
                                            completedTasks: project.completedTasks,
                                            totalTasks: project.totalTasks,
                                        })
                                        : undefined}
                                />
                            ),
                        ]}
                    />
                ),
            ]}
        />
    )
}

"use client"

import React from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    ProjectCard,
} from "./ProjectCard"
import { pathConfig } from "@/resources/path"
import { useQueryUserCapstoneProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCapstoneProgressSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import {
    SurfaceCardList,
    type SurfaceCardListItem,
} from "@/components/composites/cards/SurfaceCard"

/** Placeholder capstone rows shown while the projection loads. */
const SKELETON_ROWS = 3

/**
 * Projects tab — the profile owner's verified capstone work, framed as
 * "project = one narrative showcase per course". Each personal-project capstone
 * course is one compact {@link ProjectCard} ROW inside a single
 * {@link SurfaceCardList} (label + surface + rows owned together — Decision A),
 * separated by dividers. Self-contained container: reads username → entity id,
 * then drives its own projection-backed SWR.
 *
 * The placeholder rows are the SAME `ProjectCard` resting, in the SAME list, so the
 * row's shape has one description (`loading-and-skeleton.md`).
 */
export const ProfileCapstone = () => {
    const t = useTranslations()
    const locale = useLocale()
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data: projectsData,
        isLoading,
        error: projectsError,
        mutate: reloadProjects,
    } = useQueryUserCapstoneProgressSwr(userId)

    const projects = projectsData ?? []
    const isSkeleton = (isLoading || !userId) && !projectsData
    const loadError = projectsError && !projectsData ? projectsError : undefined

    // resolved-empty + no error → hide the whole section (sparse profiles stay clean).
    if (projectsData && projects.length === 0 && !projectsError) {
        return null
    }

    const items: ReadonlyArray<SurfaceCardListItem> = isSkeleton
        ? Array.from({ length: SKELETON_ROWS }, (_row, index) => ({
            key: `skeleton-${index}`,
            content: () => <ProjectCard isSkeleton />,
        }))
        : projects.map((project) => ({
            key: project.courseGlobalId,
            hover: "underline" as const,
            href: username
                ? pathConfig().locale(locale).profile(username).projects().course(project.courseGlobalId).build()
                : undefined,
            content: () => <ProjectCard project={project} />,
        }))

    return (
        <SurfaceCardList
            identity={{ tier: "block", component: "ProfileCapstone" }}
            label={t("publicProfile.capstone.projectsHeading")}
            items={items}
            isSkeleton={isSkeleton}
            error={loadError}
            errorState={() => (
                <AsyncContentError
                    title={t("publicProfile.capstone.loadErrorTitle")}
                    description={t("publicProfile.capstone.loadErrorDescription")}
                    onRetry={() => { void reloadProjects() }}
                    retryLabel={t("publicProfile.capstone.loadErrorRetry")}
                />
            )}
        />
    )
}

"use client"

import React from "react"
import {
    cn,
    Chip,
    Typography,
} from "@heroui/react"
import {
    ArrowSquareOutIcon,
    SealCheckIcon,
    GraduationCapIcon,
    CodeIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import type { QueryUserPinnedProjectItem } from "@/modules/api/graphql/queries/types/user-pinned-projects"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Tech-stack chips shown inline before collapsing the rest into a "+N" chip. */
const MAX_TECH_CHIPS = 3

/** Props for {@link PinnedProjectCard}. */
export interface PinnedProjectCardProps {
    /** The pinned project to render (list-item data prop — store can't index it). */
    pin: QueryUserPinnedProjectItem
}

/**
 * Display-only card for one pinned project (public-profile showcase, GitHub-pinned
 * style).
 *
 * @param props - {@link PinnedProjectCardProps}
 */
export const PinnedProjectCard = ({ pin}: PinnedProjectCardProps) => {
    const t = useTranslations()

    const isCourse = pin.type === "course"
    const TypeIcon = isCourse ? GraduationCapIcon : CodeIcon
    const title = pin.title ?? t("pinnedProjects.untitled")

    const tech = pin.techStack ?? []
    const visibleTech = tech.slice(0, MAX_TECH_CHIPS)
    const overflow = tech.length - visibleTech.length

    const chipItems = [
        ...visibleTech.map((techName) => (
            () => (
                <Chip key={techName} variant="soft" size="sm">
                    <Chip.Label>{techName}</Chip.Label>
                </Chip>
            )
        )),
        ...(overflow > 0
            ? [() => (
                <Chip variant="soft" size="sm">
                    <Chip.Label>{`+${overflow}`}</Chip.Label>
                </Chip>
            )]
            : []),
    ]

    const body = (
        <>
            <Box principle="card-padding" className="p-4"
                explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                <StackV gap={3} principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    items={[
                        () => (
                            <StackH gap={3} principle="flex-action" justify="between"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <span
                                            className={cn("inline-flex items-center rounded-full px-2 py-0 text-xs",
                                                isCourse
                                                    ? "bg-success-soft text-success-soft-foreground"
                                                    : "border border-default text-muted",
                                            )}
                                        >
                                            <StackH gap={2} principle="icon-text" inline
                                                explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                                items={[
                                                    () => <TypeIcon className="size-4" aria-hidden="true" focusable="false" />,
                                                    () => <span>{isCourse ? t("pinnedProjects.typeCapstone") : t("pinnedProjects.typeExternal")}</span>,
                                                ]} />
                                        </span>
                                    ),
                                    () => (
                                        <ArrowSquareOutIcon
                                            className="size-4 shrink-0 text-muted"
                                            aria-hidden="true"
                                            focusable="false"
                                        />
                                    ),
                                ]} />
                        ),
                        () => (
                            <Typography
                                type="body-sm"
                                weight="medium"
                                className="line-clamp-2 underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline"
                            >
                                {title}
                            </Typography>
                        ),
                        ...(pin.description
                            ? [() => (
                                <Typography type="body-xs" color="muted" className="line-clamp-1">
                                    {pin.description}
                                </Typography>
                            )]
                            : []),
                        ...(visibleTech.length > 0
                            ? [() => <Cluster gap={3} principle="chip-row" explain="Lets chips share one wrapping row so related tags stay together without stacking as a column." items={chipItems} />]
                            : []),
                    ]} />
            </Box>
            {pin.isVerified ? (
                <Box principle="pill-pad" className="border-t border-success/30 bg-success-soft px-4 py-2"
                    explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                    <StackH gap={3} items={[
                        () => (
                            <SealCheckIcon
                                className="size-4 shrink-0 text-success-soft-foreground"
                                aria-hidden="true"
                                focusable="false"
                            />
                        ),
                        () => (
                            <Typography type="body-xs" weight="medium" className="text-success-soft-foreground">
                                {t("pinnedProjects.verifiedByStarci")}
                            </Typography>
                        ),
                    ]} />
                </Box>
            ) : null}
        </>
    )

    const cardClassName = cn(
        "group flex flex-col overflow-hidden rounded-2xl border bg-surface",
        pin.isVerified ? "border-success/40" : "border-default")

    if (pin.url) {
        return (
            <a
                href={pin.url}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={t("pinnedProjects.openAria", { title })}
                className={cn(cardClassName, "cursor-pointer")}
            >
                {body}
            </a>
        )
    }

    return <div className={cardClassName}>{body}</div>
}

"use client"

import React from "react"
import { Link } from "@heroui/react"
import { useTranslations } from "next-intl"
import {
    PencilIcon,
} from "@phosphor-icons/react"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { PinnedProjectCard } from "./PinnedProjectCard"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { usePinnedProjectsOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useQueryUserPinnedProjectsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserPinnedProjectsSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useAppSelector } from "@/redux/hooks"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"

type ProfilePinnedActionProps = { label: string; onPress: () => void }

const ProfilePinnedAction = ({ label, onPress }: ProfilePinnedActionProps) => (
    <Link
        onPress={onPress}
        className="inline-flex shrink-0 cursor-pointer items-center text-sm text-accent-soft-foreground no-underline transition-opacity hover:opacity-60"
    >
        <StackH gap={2} principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            inline items={[
                () => <PencilIcon className="size-4" aria-hidden="true" focusable="false" />,
                () => <span>{label}</span>,
            ]} />
    </Link>
)

/** Props for {@link ProfilePinned}. */
export type ProfilePinnedProps = WithClassNames<undefined>

/**
 * Pinned projects card on the public profile — the user's hand-picked showcase
 * (verified course capstones + free-form external projects), GitHub-pinned-repos
 * style. Self-contained container: resolves the viewed user from the route, fetches
 * their pins via SWR, and renders one {@link PinnedProjectCard} per pin (verified
 * course pins get a "Verified by StarCi" chip; external pins link out).
 *
 * Owner-only: when the signed-in viewer owns this profile an "Add / manage"
 * action opens the manage modal (zustand overlay). Renders the empty state for
 * the owner (with an add CTA) but nothing at all for visitors with no pins, so a
 * stranger's profile stays clean.
 *
 * @param props - {@link ProfilePinnedProps}
 */
export const ProfilePinned = () => {
    const t = useTranslations()
    const username = useProfileUsername()
    const viewer = useAppSelector((state) => state.user.user)
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserPinnedProjectsSwr(userId)
    // manage modal (owner only) — open-state lives in the shared zustand overlay
    const { open: openManage } = usePinnedProjectsOverlayState()

    // viewing your own profile → show the add/manage affordance + owner empty state
    const isSelf = !!viewer && !!userId && viewer.id === userId
    const pins = data ?? []

    // visitor viewing a profile with no pins and nothing loading/erroring → hide the
    // whole section (clean profile). Owners always keep the card (header + add CTA).
    if (!isSelf && !isLoading && !error && pins.length === 0) {
        return null
    }

    // frameless ONLY once real pins render (each PinnedProjectCard self-frames);
    // while loading/empty(owner CTA)/erroring there is no bounded surface, so
    // LabeledCard's own Card must frame it — otherwise it renders bare on the page.
    const hasPins = !error && pins.length > 0

    return (
        <LabeledCard
            frameless={hasPins}
            label={t("pinnedProjects.heading")}
            action={isSelf && pins.length > 0
                ? () => <ProfilePinnedAction label={t("pinnedProjects.manage")} onPress={openManage} />
                : undefined}

        >
            <AsyncContent
                isLoading={isLoading && !data}
                skeleton={(
                    <Grid
                        principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        columns={{ base: 1, sm: 2 }}
                        items={[0, 1, 2, 3].map((index) => ({
                            key: `pin-skel-${index}`,
                            content: () => (
                                <Box principle="card-padding" className="rounded-2xl border border-default bg-surface p-4"
                                    explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                    <StackV gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => (
                                                <StackH gap={3} principle="flex-action"
                                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                    justify="between" items={[
                                                        () => <Skeleton.Chip />,
                                                        () => <Skeleton className="size-4 shrink-0 rounded" />,
                                                    ]} />
                                            ),
                                            () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                            () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                            () => (
                                                <Cluster gap={3} principle="chip-row"
                                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                    items={
                                                        [0, 1, 2].map((chip) => (
                                                            () => <Skeleton.Chip key={chip} />
                                                        ))
                                                    } />
                                            ),
                                        ]} />
                                </Box>
                            ),
                        }))}
                    />
                )}
                isEmpty={pins.length === 0}
                // owner sees an add CTA; a visitor sees nothing (clean profile)
                emptyContent={isSelf ? {
                    title: t("pinnedProjects.emptyOwnerTitle"),
                    description: t("pinnedProjects.emptyOwnerDescription"),
                    onRetry: openManage,
                    retryLabel: t("pinnedProjects.add"),
                } : undefined}
                error={error}
                errorContent={{
                    title: t("pinnedProjects.errorTitle"),
                    description: t("pinnedProjects.errorDescription"),
                    onRetry: () => mutate(),
                    retryLabel: t("pinnedProjects.retry"),
                }}
            >
                <Grid
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    columns={{ base: 1, sm: 2 }}
                    items={pins.map((pin) => ({
                        key: pin.id,
                        content: () => <PinnedProjectCard pin={pin} />,
                    }))}
                />
            </AsyncContent>
        </LabeledCard>
    )
}

"use client"

import React from "react"
